CREATE OR REPLACE 
PACKAGE BODY cra_contract
IS
   FUNCTION add_cra (
      p_currency        IN   INTEGER,
      p_opendate        IN   DATE,
      p_closedate       IN   DATE,
      p_annualintrest   IN   NUMBER,
      p_contractno      IN   VARCHAR2,
      p_personaltype    IN   INTEGER,
      p_clienttype      IN   INTEGER,
      p_branchid        IN   INTEGER
   )
      RETURN INTEGER
   IS
      RESULT    INTEGER;
      p_id      INTEGER;
      currdat   DATE;
   BEGIN
      SELECT pred_dat
        INTO currdat
        FROM sysdat;

      SELECT seg_cra_cont.NEXTVAL
        INTO p_id
        FROM DUAL;

      INSERT INTO cra_contracts
                  (ID, currency, annualinterest, opendate,
                   closedate, contractno, personaltype, clienttype,
                   branchid, type#, lastprocessdate, stopcalcdate,
                   calculationenabled
                  )
           VALUES (p_id, p_currency, p_annualintrest, p_opendate,
                   p_closedate, p_contractno, p_personaltype, p_clienttype,
                   p_branchid, 0, currdat, NULL,
                   1
                  )
        RETURNING ID
             INTO RESULT;

      RETURN RESULT;
   END;

   FUNCTION edit_cra (
      p_contractid      IN   INTEGER,
      p_currency        IN   INTEGER,
      p_opendate        IN   DATE,
      p_closedate       IN   DATE,
      p_annualintrest   IN   NUMBER,
      p_contractno      IN   VARCHAR2,
      p_personaltype    IN   INTEGER,
      p_clienttype      IN   INTEGER,
      p_branchid        IN   INTEGER
   )
      RETURN INTEGER
   IS
      RESULT   INTEGER;
   BEGIN
      UPDATE cra_contracts
         SET currency = p_currency,
             opendate = p_opendate,
             closedate = p_closedate,
             contractno = p_contractno,
             annualinterest = p_annualintrest,
             personaltype = p_personaltype,
             clienttype = p_clienttype,
             branchid = p_branchid
       WHERE ID = p_contractid;

      RETURN p_contractid;
   END;

   PROCEDURE add_craaccount (
      p_contractid      IN   INTEGER,
      p_contractaccid   IN   INTEGER,
      p_interestaccid   IN   INTEGER
   )
   IS
   BEGIN
      INSERT INTO cra_accounts
                  (id#, contractaccid, interestaccid
                  )
           VALUES (p_contractid, p_contractaccid, p_interestaccid
                  );
   END;

   PROCEDURE edit_craaccount (
      p_contractid      IN   INTEGER,
      p_contractaccid   IN   INTEGER,
      p_interestaccid   IN   INTEGER
   )
   IS
   BEGIN
      UPDATE cra_accounts
         SET contractaccid = p_contractaccid,
             interestaccid = p_interestaccid
       WHERE id# = p_contractid;
   END;

   PROCEDURE add_contract_state (p_contractid IN INTEGER)
   IS
      preddat   DATE;
   BEGIN
      SELECT pred_dat
        INTO preddat
        FROM sysdat;

      INSERT INTO cra_contract_state
                  (id#, facticaldebt, facticalinterestdebt,
                   stopcalculationdate, lastprocessdate, calculationenabled,
                   lastfacticaldebt
                  )
           VALUES (p_contractid, 0, 0,
                   NULL, preddat, 1,
                   0
                  );
   END;

   PROCEDURE add_cra_contracts (
      currency        IN   INTEGER,
      opendate        IN   DATE,
      closedate       IN   DATE,
      annualintrest   IN   NUMBER,
      contractno      IN   VARCHAR2,
      personaltype    IN   INTEGER,
      clienttype      IN   INTEGER,
      branchid        IN   INTEGER,
      contractaccid   IN   INTEGER,
      interestaccid   IN   INTEGER
   )
   IS
      RESULT   INTEGER;
   BEGIN
      RESULT :=
         add_cra (p_currency           => currency,
                  p_opendate           => opendate,
                  p_closedate          => closedate,
                  p_annualintrest      => annualintrest,
                  p_contractno         => contractno,
                  p_personaltype       => personaltype,
                  p_clienttype         => clienttype,
                  p_branchid           => branchid
                 );
      add_craaccount (p_contractid         => RESULT,
                      p_contractaccid      => contractaccid,
                      p_interestaccid      => interestaccid
                     );
      add_contract_state (p_contractid => RESULT);
      COMMIT WORK;
   EXCEPTION
      WHEN OTHERS
      THEN
         ROLLBACK WORK;
         RAISE;
   END;

   PROCEDURE edit_cra_contracts (
      contractid      IN   INTEGER,
      currency        IN   INTEGER,
      opendate        IN   DATE,
      closedate       IN   DATE,
      annualintrest   IN   NUMBER,
      contractno      IN   VARCHAR2,
      personaltype    IN   INTEGER,
      clienttype      IN   INTEGER,
      branchid        IN   INTEGER,
      contractaccid   IN   INTEGER,
      interestaccid   IN   INTEGER
   )
   IS
      RESULT   INTEGER;
   BEGIN
      RESULT :=
         edit_cra (p_contractid         => contractid,
                   p_currency           => currency,
                   p_opendate           => opendate,
                   p_closedate          => closedate,
                   p_annualintrest      => annualintrest,
                   p_contractno         => contractno,
                   p_personaltype       => personaltype,
                   p_clienttype         => clienttype,
                   p_branchid           => branchid
                  );
      edit_craaccount (p_contractid         => RESULT,
                       p_contractaccid      => contractaccid,
                       p_interestaccid      => interestaccid
                      );
      COMMIT WORK;
   EXCEPTION
      WHEN OTHERS
      THEN
         ROLLBACK WORK;
         RAISE;
   END;

   FUNCTION get_contractbalance (p_contractid IN INTEGER)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT ABS (ostat)
        INTO RESULT
        FROM tenostat
       WHERE acc_id = (SELECT contractaccid
                         FROM cra_accounts
                        WHERE id# = p_contractid);

      RETURN RESULT;
   END;

   FUNCTION get_accountbalance (p_id IN INTEGER)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT ABS (ostat)
        INTO RESULT
        FROM tenostat
       WHERE acc_id = p_id;

      RETURN RESULT;
   END;

   FUNCTION get_accountnumber (p_id IN INTEGER)
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (25);
   BEGIN
      SELECT acc_no
        INTO RESULT
        FROM ACCOUNT
       WHERE ID = p_id;

      RETURN RESULT;
   END;

   FUNCTION get_accountname (p_id IN INTEGER)
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (50);
   BEGIN
      SELECT NAME
        INTO RESULT
        FROM ACCOUNT
       WHERE ID = p_id;

      RETURN RESULT;
   END;

   PROCEDURE close_cont (p_contid IN INTEGER)
   IS
   BEGIN
      UPDATE cra_contracts
         SET type# = 1
       WHERE ID = p_contid;

      COMMIT;
   END;

   FUNCTION bankdaysbetween (firstdate IN DATE, lastdate IN DATE)
      RETURN INTEGER
   IS
      RESULT          INTEGER;
      currentmonth    DATE;
      MONTH           DATE    := firstdate;
      monthinterval   INTEGER;
      mounthindex     INTEGER;
      lastmonthday    INTEGER;
      bankyeardays    INTEGER := 360;
   BEGIN
      IF firstdate >= lastdate
      THEN
         RESULT := 0;
      ELSE
         RESULT := (lastdate - firstdate);

         IF bankyeardays > 360
         THEN
            RETURN RESULT;
         END IF;

         monthinterval := (lastdate - firstdate) / 30;

         FOR monthindex IN 0 .. monthinterval
         LOOP
            currentmonth := LAST_DAY (MONTH);
            lastmonthday := TO_NUMBER (TO_CHAR (currentmonth, 'DD'));

            IF (currentmonth <= lastdate) AND (currentmonth > firstdate)
            THEN
               IF lastmonthday = 31
               THEN
                  RESULT := RESULT - 1;
               END IF;

               IF lastmonthday = 28
               THEN
                  RESULT := RESULT + 2;
               END IF;

               IF lastmonthday = 29
               THEN
                  RESULT := RESULT + 1;
               END IF;
            END IF;

            MONTH := ADD_MONTHS (MONTH, 1);
         END LOOP;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION calcpercent (
      p_sum           IN   NUMBER,
      p_rate          IN   NUMBER,
      p_coefficient   IN   NUMBER,
      p_delimmer      IN   NUMBER DEFAULT 360
   )
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      RESULT := (p_sum * p_rate * p_coefficient) / (p_delimmer * 100);
      RETURN RESULT;
   END;

   PROCEDURE calcrapercent (p_contid IN INTEGER)
   IS
      CURSOR c_acc
      IS
         SELECT contractaccid, interestaccid
           FROM cra_accounts
          WHERE id# = p_contid;

      CURSOR c_cont
      IS
         SELECT currency, annualinterest, branchid, contractno
           FROM cra_contracts
          WHERE ID = p_contid;

      CURSOR c_rest (p_id IN INTEGER, p_dat IN DATE)
      IS
         SELECT ABS (ostat) AS rest
           FROM archost
          WHERE acc_id = p_id AND datdate = p_dat;

      CURSOR c_expint
      IS
         SELECT accid
           FROM sbcm_settings
          WHERE parentid =
                   (SELECT ID
                      FROM sbcm_movie_names
                     WHERE NAME = 'outComeAccForDeposit'
                       AND typeid = (SELECT clienttype
                                       FROM cra_contracts
                                      WHERE ID = p_contid))
          and currencyid = (select currency from cra_contracts where id= p_contid);                            

      CURSOR c_ostat (p_dat IN DATE, p_id IN INTEGER)
      IS
        SELECT   datdate, ABS (ostat) AS ostat
             FROM archost
            WHERE datdate > p_dat AND acc_id = p_id
         ORDER BY datdate;

      accinfo         c_acc%ROWTYPE;
      continfo        c_cont%ROWTYPE;
      ost             c_ostat%ROWTYPE;
      debitid         INTEGER;
      creditid        INTEGER;
      calcamt         NUMBER := 0;
      bankcurrdate    DATE;
      bankprevdate    DATE;
      dateinterval    NUMBER;
      prevrest        NUMBER;
      currrest        NUMBER;
      transactionid   NUMBER;
      checkdate       DATE;
      CH DATE;
      CH1 DATE;
      Accrest   number;
      
   BEGIN
      
      SELECT lastprocessdate
        INTO checkdate
        FROM cra_contracts
       WHERE ID = p_contid;

      SELECT tek_dat, pred_dat
        INTO bankcurrdate, bankprevdate
        FROM sysdat;

      IF checkdate >= bankcurrdate
      THEN
         raise_application_error (-20007, 'Фаизля? а?тыг щесабланыб!');
      END IF;

      OPEN c_expint;
      FETCH c_expint INTO debitid;
      CLOSE c_expint;

      IF debitid IS NULL
      THEN
         raise_application_error (-20007, 'DebitID is null');
      END IF;

      OPEN c_acc;
      FETCH c_acc INTO accinfo;
      CLOSE c_acc;
      creditid := accinfo.interestaccid;
      OPEN c_cont;
      FETCH c_cont INTO continfo;
      CLOSE c_cont;
      OPEN c_rest (accinfo.contractaccid, bankprevdate);
      FETCH c_rest INTO prevrest;
      CLOSE c_rest;
      OPEN c_rest (accinfo.contractaccid, bankcurrdate);
      FETCH c_rest INTO currrest;
      CLOSE c_rest;

     -- calcamt :=0;
     
     select abs(ostat) into Accrest
     from tenostat
     where acc_id = accinfo.contractaccid;
     
     if checkdates(bankcurrdate) then
        if to_char(bankcurrdate,'D') = 6 then
         calcamt :=
             calcpercent (p_sum              => Accrest,
                            p_rate             => continfo.annualinterest,
                            p_coefficient      => 3
                           );
        end if; 
      

        if to_char(bankcurrdate,'D') = 2 then
         calcamt :=
             calcpercent (p_sum              => Accrest,
                            p_rate             => continfo.annualinterest,
                            p_coefficient      => 1
                           );
        end if; 

        
      else  
      CH1:=checkdate;
      FOR ost IN c_ostat (checkdate, accinfo.contractaccid)
      LOOP
      
      
      SELECT MIN(DATDATE) INTO CH FROM ARCHOST
      WHERE DATDATE>CH1;
     
      dateinterval := CH-CH1-1;
      
      if dateinterval=0 then dateinterval :=1;
      
      
      end if;
       
       if dateinterval>1 then dateinterval :=dateinterval+1;
       end if;
       CH1:=CH;    
         calcamt :=
               NVL(calcamt,0)
             + calcpercent (p_sum              => NVL(ost.ostat,0),
                            p_rate             => continfo.annualinterest,
                            p_coefficient      => NVL(dateinterval,0)
                           );
      END LOOP;
      
      end if;
      
     --raise_application_error(-20007,'calcamt = '||calcamt);

      
      IF calcamt <> 0
      THEN
      --raise_application_error(-20007,'calcamt = '||creditid);
         transactionid :=
            sb_transaction.transaction_add (debitid              => debitid,
                                            creditid             => creditid,
                                            debitamount          => calcamt,
                                            creditamount         => NULL,
                                            lamount              => NULL,
                                            debitrate            => 0,
                                            creditrate           => 0,
                                            trname               =>    continfo.contractno||' '
                                                                   ||checkdate||' - '||bankcurrdate,
                                            flags                => 0,
                                            transactiondate      => bankcurrdate
                                           );
      END IF;

      UPDATE cra_contracts
         SET lastprocessdate = bankcurrdate
       WHERE ID = p_contid;
     COMMIT;
     
   END;

   FUNCTION getlastprocessdate (p_id IN INTEGER)
      RETURN DATE
   IS
      RESULT   DATE;
   BEGIN
      SELECT lastprocessdate
        INTO RESULT
        FROM cra_contracts
       WHERE ID = p_id;

      RETURN RESULT;
   END;

   FUNCTION iscalculationenabled (p_id IN INTEGER)
      RETURN BOOLEAN
   IS
      RESULT   BOOLEAN;
      r        NUMBER;
   BEGIN
      SELECT calculationenabled
        INTO r
        FROM cra_contracts
       WHERE ID = p_id;

      RESULT := NVL (r, 0) = 1;
      RETURN RESULT;
   END;

   FUNCTION checkcontractstate (contractid IN cra_contracts.ID%TYPE)
      RETURN INTEGER
   IS
      lastprocessdate   DATE;
      currentdate       DATE;
      RESULT            INTEGER := -9;
      currdat           DATE; -- S_OK
   BEGIN
      SELECT tek_dat
        INTO currdat
        FROM sysdat;

      currentdate := currdat;
      lastprocessdate := getlastprocessdate (contractid);

      IF NOT iscalculationenabled (contractid)
      THEN
         RESULT := -11;
      ELSIF lastprocessdate = currentdate
      THEN
         RESULT := -10; --S_Disabled
      END IF;

      RETURN RESULT;
   END;

   PROCEDURE calcenableddisabled (p_id IN INTEGER)
   IS
      checkcalc   INTEGER;
   BEGIN
      SELECT calculationenabled
        INTO checkcalc
        FROM cra_contracts
       WHERE ID = p_id;

      IF checkcalc = 1
      THEN
         UPDATE cra_contracts
            SET calculationenabled = 0
          WHERE ID = p_id;
      END IF;

      IF checkcalc = 0
      THEN
         UPDATE cra_contracts
            SET calculationenabled = 1
          WHERE ID = p_id;
      END IF;

      COMMIT;
   END;
   
   function checkdates(p_dat in date )
   return boolean
   is
     result boolean;
   begin
     result := to_char(p_dat,'D') = 2 or
               to_char(p_dat,'D') = 6;
      return result;         
   end;
END;
/


