PROCEDURE ins_transaction
(v_debt_id float, v_credit_id float, v_debt_ammount float, v_credit_ammount float, v_content varchar2,
  v_lammount float, v_debt_rate float, v_credit_rate float,  v_reportid number, v_countrid number,
  inbalc number default null, outbalc number default null)
is
begin
dbms_output.put_line(inbalc);
dbms_output.put_line(outbalc);
delete from transaction;
insert into transaction (debt_id, credit_id, debt_ammount, credit_ammount, content,
       lammount, debt_rate, credit_rate, reportid, countrid, inbalchar, outbalchar)
       values(v_debt_id, v_credit_id, v_debt_ammount, v_credit_ammount, v_content,
       v_lammount, v_debt_rate, v_credit_rate, v_reportid, v_countrid, inbalc, outbalc);
end ins_transaction;
