commit;
end;

procedure ins_date (v_start_date varchar2,v_end_date varchar2)
is
begin
delete from memorial_date;
insert into memorial_date(start_date,end_date)
values(v_start_date,v_end_date);
commit;
end ins_date;

procedure transaction_mn
is
   cursor c_trans
   is
      select *
        from transaction;

   trans           c_trans%rowtype;
   transactionid   integer;
begin
   open c_trans;

   fetch c_trans
    into trans;

   close c_trans;

   transactionid :=
      sb_transaction.transaction_add (debitid           => trans.debt_id,
                                      creditid          => trans.credit_id,
                                      debitamount       => trans.debt_ammount,
                                      creditamount      => trans.credit_ammount,
                                      lamount           => trans.lammount,
                                      debitrate         => trans.debt_rate,
                                      creditrate        => trans.credit_rate,
                                      trname            => trans.content,
                                      preportid         => trans.reportid,
                                      pcountrid         => trans.countrid,
                                      InBalanceChar		=> trans.inbalchar,
                                      OutBalanceChar	=> trans.outbalchar
                                     );
   commit;
end;
function open_Account (
 AccNumber account.acc_no%type,
 Currency account.val_acc%type default 0,
 Balance account.bal_cn1%type,
 CustomerID account.kli_id%type,
 OpenDate account.open_dat%type,
 Limite account.limit%type,
 RepSymb account.sim_otcet%type,
 Branch account.filial%type default 0,
 AccSymb account.tipacc%type,
 AccName account.name%type,
 Custid account.kli_id%type)
  return integer is
   Result integer;
begin
 SB_ACA.CheckObjectAccess('Accounts','insert');
 insert into account
  (id, op_id, acc_no, val_acc, bal_cn1, kli_id, open_dat, limit,
   sim_otcet, filial, tipacc, name/*, p_custid*/)
 values
  (TR_SEG_ACCOUNT.NEXTVAL, uid, AccNumber, Currency, Balance, CustomerID, OpenDate, Limite,
   RepSymb, Branch, AccSymb, AccName/*, Custid*/)
 returning ID into Result;

 insert into lazyrest
  (acc_id, ostat, pok_ostat, datdate, obr_d, obr_k, pok_obr_d, pok_obr_k)
 values
  (Result, 0, 0, sysdate, 0, 0, 0, 0);

commit;
return Result;
end;
END Customer_Operations;
/


