PROCEDURE c_trans 
   IS
   cursor cr is select debt_ammount,credit_ammount from order_trans;
        
      v_n float;
      v_m float;
      d_id float;
      c_id float;
      v_content varchar2(500);
     
      transactionid   INTEGER;
       BEGIN
       select debt_ammount into v_n from order_trans;
        select credit_ammount into v_m from order_trans;
        select debit_id into d_id from order_trans;
        select credit_id into c_id from order_trans;
        select content into v_content from order_trans;
           transactionid :=
            out_sb_transaction.transaction_add(
               debitid=>d_id,
               creditid=> c_id,
               debitamount=>v_n,
               creditamount=> v_m,
               lamount=> NULL,
               debitrate=> NULL,
               creditrate=> NULL,
               trname=> v_content
                           );
      COMMIT;
 
   END c_trans;
   
   Function currentdate
return Date
Is
 CurrentDate Date;  
Begin
  Select TEK_DAT Into CurrentDate From SYSDAT;
	return CurrentDate;	
End currentdate;


procedure delete_order(v_id varchar2)
is
begin
 delete from cust_order
  where id = v_id;
commit;	
end delete_order;


procedure delete_cust_trans
is
cursor cr is select id from cust_order;
rcr cr%rowtype;
begin
open cr;
fetch cr into rcr;
close cr;
 delete from cust_trans
  where cust_acc =rcr.id;
commit;	
end delete_cust_trans;













