PROCEDURE order_trans_(v_debit_ammount varchar2,v_credit_id varchar2,v_content varchar2)
is
cursor cr is select id from account_id;
rcr cr%rowtype;
begin
open cr;
fetch cr into rcr;
close cr;
delete from order_trans;
insert into order_trans
(debt_ammount,credit_ammount,debit_id,credit_id,content)
values(v_debit_ammount,v_debit_ammount,rcr.id,v_credit_id,v_content);
commit;
end order_trans_;



