CREATE OR REPLACE 
PACKAGE BODY       denomination
IS

procedure SMART_BANK
  (Divisor   number,  --5000
   StartDate date,    --01-Jan-2006
   MinPoint  number,  --25
   AZM_Code  number)     
is
  --***Down 25 ACTIVES***--
  A_Archost Archost%rowtype;
  cursor cA_Archost is
   select ID_Number, Acc_ID, Ostat, Pok_Ostat, DatDate, Obr_D, Obr_K,
          Pok_Obr_D, Pok_Obr_K, LastOpDate
   from Archost
   where (DatDate=StartDate) and (pok_ostat<0) and (pok_ostat > (-1)*MinPoint)
    and acc_ID in (select ID from account where val_ACC=AZM_Code);
  ACreditID      Number;
  ATrAmount      Number;  --0.01
  ATrAppoint     Varchar2(30);
            
  --***Down 25 PASSIVES***--
  P_Archost Archost%rowtype;
  cursor cP_Archost is
   select ID_Number, Acc_ID, Ostat, Pok_Ostat, DatDate, Obr_D, Obr_K,
          Pok_Obr_D, Pok_Obr_K, LastOpDate
   from Archost
   where (DatDate=StartDate) and (pok_ostat>0) and (pok_ostat < MinPoint)
    and acc_ID in (select ID from account where val_ACC=AZM_Code);
  PDebitID       Number;
  PTrAmount      Number;  --0.01
  PTrAppoint     Varchar2(30);
  
  TransactionID Integer;          
begin
  select Acc_ID,   TrAmount, TrAppoint
    into ACreditID, ATrAmount, ATrAppoint
    from DNM_RegulationAccs
   where ID_Key = 4501;
   
  select Acc_ID,  TrAmount, TrAppoint
    into PDebitID, PTrAmount, PTrAppoint
    from DNM_RegulationAccs
   where ID_Key = 2501;
  
  open cA_Archost;
  open cP_Archost;
  
  --***GENERAL***--
  update Archost 
     set pok_ostat = Round ((pok_ostat / Divisor),2)
   where (DatDate = StartDate);
     --and (pok_ostat >= MinPoint or pok_ostat <= -1*MinPoint);
  commit; 
  
  --***Down 25 ACTIVES***-- 
  loop
  fetch cA_Archost into A_Archost;
  exit when cA_Archost%NotFound;
  
  update Archost set pok_ostat = 0
   where DatDate = A_Archost.DatDate and Acc_ID = A_Archost.Acc_ID;
  
  TransactionID := SB_Transaction.Transaction_Add(
   DebitID => A_Archost.Acc_ID,
   CreditID => ACreditID,
   DebitAmount => null, 
   CreditAmount => ATrAmount,
   LAmount => null,
   DebitRate => null,
   CreditRate => null,
   TrName => ATrAppoint);       
  
  end loop;
  close cA_Archost;
  commit;
  
  --***Down 25 PASSIVES***--  
  loop
  fetch cP_Archost into P_Archost;
  exit when cP_Archost%NotFound;
  
  update Archost set pok_ostat = 0
   where DatDate = P_Archost.DatDate and Acc_ID = P_Archost.Acc_ID;
  
  TransactionID := SB_Transaction.Transaction_Add(
   DebitID => PDebitID,
   CreditID => P_Archost.Acc_ID,
   DebitAmount => null, 
   CreditAmount => PTrAmount,
   LAmount => null,
   DebitRate => null,
   CreditRate => null,
   TrName => PTrAppoint);       
  
  end loop;
  close cP_Archost;
  commit;
  
  SMART_BANK_FINAL(AZM_Code,Divisor,StartDate);
end;
--*********************************
procedure SMART_CREDITS
  (Divisor   number,
   StartDate date,
   AZM_Code  number)
is 
begin
  EXECUTE IMMEDIATE
   'update SBCM_CONTRACT_STATE set
    FACTICALDEBT = FACTICALDEBT / '||Divisor||',
    OVERDUEDEBT = OVERDUEDEBT / '||Divisor||',
    FACTICALINTERESTDEBT = FACTICALINTERESTDEBT /'||Divisor||',
    OVERDUEINTERESTDEBT = OVERDUEINTERESTDEBT /'||Divisor||',
    RESIDUARYAMOUNT = RESIDUARYAMOUNT /'||Divisor||',
    LASTFACTICALDEBT = LASTFACTICALDEBT /'||Divisor||',
    LASTOVERDUEDEBT = LASTOVERDUEDEBT /'||Divisor||'
    where ID# in 
     (select ID# from SBCM_CONTRACT_ACCOUNTS
      where CONTRACTACCID in 
       (select ID from Account where Val_ACC='||AZM_Code||'))';
  commit; 
  
  EXECUTE IMMEDIATE
   'update SBCM_CONTRACTS set
    AMOUNT = AMOUNT / '||Divisor||',
    PLEDGEPRICE = PLEDGEPRICE /'||Divisor||'
    where ID in
     (select ID# from SBCM_CONTRACT_ACCOUNTS
      where CONTRACTACCID in 
       (select ID from Account where Val_ACC='||AZM_Code||'))';
  commit;     
end;   
--*********************************
procedure SMART_BANK_Final
  (AZM_Code    number,
   Divisor     number,
   StartDate   date)      
is 
  r_Archost Archost%rowtype;
  cursor c_Archost is
   select ID_Number, Acc_ID, Ostat, Pok_Ostat, DatDate, Obr_D, Obr_K,
          Pok_Obr_D, Pok_Obr_K, LastOpDate
   from Archost
   where (DatDate = StartDate)
    and (Acc_ID in (select ID from Account where Val_Acc<>AZM_Code))
    and (Ostat<0)
    and (Ostat<>round(Ostat));
    
  SumPokOstat number;
begin
  select sum(Pok_Ostat) into SumPokOstat 
   from Archost where DatDate=StartDate;
   
 open c_Archost; 
 loop
  fetch c_Archost into r_Archost;  
  exit when c_Archost%NotFound;
  
  if SumPokOstat > 0 then    
   update Archost set Pok_Ostat = Pok_Ostat - 0.01
    where DatDate = StartDate
      and Acc_ID = r_Archost.Acc_ID;
   SumPokOstat := SumPokOstat - 0.01;   
  end if; /* if SumPokOstat > 0 */    
     
  if SumPokOstat < 0 then    
   update Archost set Pok_Ostat = Pok_Ostat + 0.01
    where DatDate = StartDate
      and Acc_ID = r_Archost.Acc_ID;
   SumPokOstat := SumPokOstat + 0.01;   
  end if; /* if SumPokOstat < 0 */ 
        
  end loop;
  close c_Archost;
  commit;
  
  update OperKurs set Ostat = Round ((Ostat / Divisor),4)
   where Dat = StartDate
     and Val_Kod <> AZM_Code;
     
  update Archost set Ostat = Pok_Ostat
   where DatDate = StartDate
     and Acc_ID in (select ID from Account where Val_Acc = AZM_Code);
  commit;  
end;
--*********************************
procedure CREDITSMGR
  (Divisor   number,
   StartDate date,
   AZM_Code  number)
is
begin
  EXECUTE IMMEDIATE
   'update CREDITSMGR.CM_History set   
    Rest = Rest / '||Divisor||',
    InterestRest = InterestRest / '||Divisor||',
    DueRest = DueRest / '||Divisor||',
    DueInterestRest = DueInterestRest / '||Divisor||',
    GivenAmount = GivenAmount / '||Divisor||',
    Obligation = Obligation / '||Divisor||',
    PledgePrice = PledgePrice / '||Divisor||' 
    where HDate = '''||StartDate||'''
     and CreditID in (select ID from CREDITSMGR.CM_Portfolio where Currency = '||AZM_Code||')';
    commit;
    
  EXECUTE IMMEDIATE 
   'update CREDITSMGR.CM_Portfolio set 
    InitialAmount = InitialAmount / '||Divisor||',
    CreditLineAmount = CreditLineAmount / '||Divisor||' 
   where Currency = '||AZM_Code;
  commit;
  
 EXECUTE IMMEDIATE 
   'update CREDITSMGR.CM_Interests set
    Interest = Interest / '||Divisor||',
    DueInterest = DueInterest / '||Divisor||' 
   where HDate = '''||StartDate||''' 
    and CreditID in (select ID from CREDITSMGR.CM_Portfolio where CURRENCY = '||AZM_Code||')';  
  commit;
  
  EXECUTE IMMEDIATE 
   'update CREDITSMGR.CM_Tranche_Schedule set
    TrcHAmount = TrcHAmount / '||Divisor||'
   where TrcHDate >= '''||StartDate||''' 
   and CreditID in (select ID from CREDITSMGR.CM_Portfolio where Currency = '||AZM_Code||')';
  commit;
  
  EXECUTE IMMEDIATE   
   'update CREDITSMGR.CM_Payment_Schedule set
    Principal = Principal / '||Divisor||',
    Interest = Interest / '||Divisor||'
   where PaymentDate >= '''||StartDate||''' 
    and CreditID in (select ID from CREDITSMGR.CM_Portfolio where Currency = '||AZM_Code||')';
  commit;  
end;   
--*********************************
procedure PermAssets
  (Divisor   number)
is
begin
  update Wares set 
   First_Price = First_Price / Divisor,
   Balance_Price = Balance_Price / Divisor,
   Remainder = Remainder / Divisor,
   AllAmort = AllAmort / Divisor,
   TaxAmort = TaxAmort / Divisor,
   AllTaxAmort = AllTaxAmort / Divisor,
   TaxPercentPrice = TaxPercentPrice / Divisor;   
  commit;    
end;
--*********************************
procedure SALARY
  (Divisor number)
is 
begin
  EXECUTE IMMEDIATE 
   'update SALARY.RMZ03 set OKLD = OKLD / '||Divisor;
  EXECUTE IMMEDIATE 
   'update SALARY.RMZ03 set SumBNG = 0';
  EXECUTE IMMEDIATE 
   'update SALARY.RMZ06 set OKLD = OKLD / '||Divisor;  
  commit;
end;
--*********************************     
END;
/


