CREATE OR REPLACE 
PACKAGE BODY hoxpack
IS

--TRANSACTION 
procedure ParentAndChildTransForIN(v_id number)
is 
    TransactionID number;
    curs number(22,2);
    accountval_kod number;
    V_commisionid number;
    V_debitid number;
    V_creditid number;
    v_amount number;
    v_valute number;
    v_trname varchar2(255);
    debit_id number;
begin
  select rec_client_acc_id into v_creditid from hoxmessage_in where id = v_id;
  --check credit account 
  if (v_creditid > 0 ) then  
    select val_cod into v_valute from hoxmessage_in where id =v_id;  
    select hox_id into v_debitid from hoxsw_account where valute= v_valute;
    select amount into v_amount from hoxmessage_in where id =v_id;
    select remit_inf into v_trname from hoxmessage_in where id =v_id;
    select val_acc into accountval_kod from account where (id=V_creditid) ;
    select ostat into curs  from operkurs where (val_kod=accountval_kod)and(dat=sbop.get_date);
    select transtypeid into v_commisionid from hoxsw_proper;
    --transactions
    TransactionID := 
                sb_transaction.transaction_add (
                               debitid=> V_debitid,
                               creditid=> v_creditid,
                               debitamount=> null,
                               creditamount=> v_amount,
                               lamount=> null,
                               debitrate=> null,
                               creditrate=> null,
                               trname=>  v_trname,
                               flags => 0,
                               parentID => null,
                               transactiondate=> sbop.get_date);

    --CHILD TRANSACTION
    SB_COMPLEX_TRANSACTIONSFORHOX.settransactions(V_commisionid,
                                            V_debitid,
                                            v_creditid,
                                            v_amount/curs,
                                            v_amount);

   -- CHANGE ICON to accept                     
   UPD_MESSAGE_IN_ICON(v_id,1);                        


   else                                          
   -- CHANGE ICON to reject                                             
     UPD_MESSAGE_IN_ICON(v_id,2);                        
end if;                                             
EXCEPTION when others then UPD_MESSAGE_IN_ICON(v_id,2);                        
 commit;
end;
--------------------------------------------------------------------------------
procedure ParentAndChildTrans(v_id number)
is
    Messages hoxmessage_out%rowtype;
    cursor CreditMessages is select * from hoxmessage_out where mt102_id=v_id;
    TransactionID number;
    V_debitid number;
    V_creditid number;
    V_commisionid number;
    accountval_kod number;
    debit_id number;
    curs number(22,2);
BEGIN
 open CreditMessages;
 Loop 
  Fetch CreditMessages into Messages;
  Exit when CreditMessages%notfound;
    select acc_id into v_debitid from hox102_out where id=v_id;
    select hox_id into v_creditid from hoxsw_account where valute= messages.val_cod;
    select transtypeid into v_commisionid from hoxsw_proper;
    select acc_id into debit_id from hox102_out where (id=messages.mt102_id); 
    select val_acc into accountval_kod from account where (id=debit_id) ;
    select ostat into curs  from operkurs where (val_kod=accountval_kod)and(dat=sbop.get_date);
    TransactionID := 
                sb_transaction.transaction_add (
                               debitid=> V_debitid,
                               creditid=> v_creditid,
                               debitamount=> null,
                               creditamount=> messages.amount,
                               lamount=> null,
                               debitrate=> null,
                               creditrate=> null,
                               trname=>  messages.remit_inf,
                               flags => 0,
                               parentID => null,
                               transactiondate=> sbop.get_date);
                                
    SB_COMPLEX_TRANSACTIONSFORHOX.settransactions(V_commisionid,
                                                  V_debitid,
                                                  V_creditid,
                                                  messages.amount/curs,
                                                  messages.amount);
                                                                        
 end loop;
 close CreditMessages;                              
END;
--------------------------------------------------------------------------------
--UPDATE------------------------------------------------------------------------
procedure UPD_MESSAGE_IN_ICON(v_id number, v_status number)
is 
begin
   update hoxmessage_in set status = v_status where id=v_id;
commit;
end;

procedure UPD_HOXMESSAGE_IN(v_id in hoxmessage_in.id%type,
                            v_acc_id in hoxmessage_in.rec_client_acc_id%type,
                            v_acc_no in hoxmessage_in.rec_client_acc%type
                            )
   is
begin
update hoxmessage_in set
                   rec_client_acc_id=v_acc_id,
                   rec_client_acc=v_acc_no
where id=v_id;
commit;
end;
--------------------------------------------------------------------------------
procedure UPD_HOX102_out
                   (
                    v_id IN HOX102_OUT.ID%type
                   ,V_OPERCODE IN HOX102_OUT.opercode%type
                   ,V_ACC_ID IN HOX102_OUT.acc_id%type
                   ,V_CLIENT_NAME IN HOX102_OUT.client_name%type
                   ,V_CLIENT_CODE IN HOX102_OUT.client_CODE%type
                   ,V_TRANS_REF IN HOX102_OUT.trans_ref%type
                   ,V_AMOUNT IN HOX102_OUT.amount%type
                   ,V_VAL_ACC IN HOX102_OUT.val_acc%type
                   ,V_TRANSDATE IN HOX102_OUT.transdate%type                     
                    )
  is
begin
  UPDATE   Hox102_Out set
                     OperCode=v_OPerCode
                    ,Acc_ID=V_ACC_ID
                    ,CLIENT_NAME=V_CLIENT_NAME
                    ,CLIENT_CODE=V_CLIENT_CODE
                    ,TRANS_REF=V_TRANS_REF
                    ,AMOUNT=V_AMOUNT
                    ,VAL_ACC=V_VAL_ACC
                    ,TRANSDATE=V_TRANSDATE
 WHERE               ID=v_id;
end;

--UPDATE MESS-------------------------------------------
procedure UPD_MESS_out(
                     v_id IN HOXMESSAGE_OUT.ID%type
                    ,V_REC_BANK_ID IN HOXMESSAGE_OUT.REC_BANK_ID%type
                    ,V_REC_BANK_SUB_ACC IN HOXMESSAGE_OUT.REC_BANK_SUB_ACC%type
                    ,V_CLIENT_ACC_NO IN HOXMESSAGE_OUT.CLIENT_ACC_NO%type
                    ,V_CLIENT_NAME IN HOXMESSAGE_OUT.CLIENT_NAME%type
                    ,V_CLIENT_CODE IN HOXMESSAGE_OUT.CLIENT_CODE%type
                    ,V_CLIENT_INN IN HOXMESSAGE_OUT.CLIENT_INN%type
                    ,V_REMIT_INF IN HOXMESSAGE_OUT.REMIT_INF%type
                    ,V_TRANS_COD IN HOXMESSAGE_OUT.TRANS_COD%type
                    ,V_ADD_INF IN HOXMESSAGE_OUT.ADD_INF%type
                    ,V_VAL_DATE IN HOXMESSAGE_OUT.VAL_DATE%type
                    ,V_VAL_COD IN HOXMESSAGE_OUT.VAL_COD%type
                    ,V_MESS_REF IN HOXMESSAGE_OUT.MESS_REFERENCE%type
                    ,V_AMOUNT IN HOXMESSAGE_OUT.AMOUNT%type
                    ,V_BNFCOUNT IN HOXMESSAGE_OUT.BNFCOUNT%type
                    ) 
  is
begin
  UPDATE   HoxMESSAGE_Out set
                     REC_BANK_ID=V_REC_BANK_ID
                    ,REC_BANK_SUB_ACC=V_REC_BANK_SUB_ACC
                    ,CLIENT_ACC_NO=V_CLIENT_ACC_NO
