--UPDATE MESSAGE ICON
procedure UPD_MESS_ICON(V_ID integer,V_STATUS integer) 
is
begin
   update hoxmessage_out set status = V_STATUS where id=v_id;
   commit;
end;
--UPDATE HOX102 ICON
function UPD_HOX102_ICON(V_ID integer,V_STATUS integer) return integer
is result integer;
   testiq integer;
  messcount integer;     
begin
   if v_status = 0 then
      update hox102_out set status = v_STATUS where id=v_id;
      result:=1;
      commit;
   end if;
   if v_status = 1 then
      select count(*) into testiq from hoxmessage_out where (status =1)and(mt102_id=V_id) ;
      select count(*) into messcount from hoxmessage_out where (mt102_id=V_id);
      if (testiq=messcount) then
         update hox102_out set status = v_STATUS where id=v_id;
         result := 1;
         commit; 
      else
         result := 0;
      end if;
   end if;
   if v_status=2 then
         update hox102_out set status = v_STATUS where id=v_id;
         result := 1; 
         commit; 
   end if;      
   return result;
end;
--UPD HOXTRANSTYPE_CODE
PROCEDURE INS_UPD_TRANSCODE(V_name Varchar2, v_code Integer)
is fn  integer;
begin
   select count(*) into fn from hoxTransType_Code where code = v_code;
   if fn = 0 then 
     insert into hoxTransType_Code (name,code) values (V_name,V_code);
   else
     update hoxTransType_Code set name=v_name, code=v_code;                   
   end if;  
  commit; 
end;
--UPDATE HOXSW_PROPER
PROCEDURE upd_proper(oper integer, V_value varchar2)
is
begin
  if oper = 1 then
  Update hoxsw_proper set swiftaccount=V_value;
  end if;
  if oper = 2 then
  Update hoxsw_proper set hoxaccount=V_value;
  end if;
  if oper = 3 then
  Update hoxsw_proper set hoxamount_limit=to_number(V_value);
  end if;
  commit;  
end; 
