CREATE OR REPLACE 
PACKAGE BODY       ifca_calculation
IS
 cursor c_IFCA_Accounts is
 select
   currentaccid, 
   interestaccid, 
   expenceaccid, 
   annualyrate,
   min_rest, 
   max_rest, 
   trdescription
 from 
   currentacc_passport; 

  FUNCTION getdateinterval (firstdate IN DATE, lastdate IN DATE)
      RETURN INTEGER
   IS
      result          INTEGER;
      currentmonth    DATE;
      MONTH           DATE    := firstdate;
      monthinterval   INTEGER;
      mounthindex     INTEGER;
      lastmonthday    INTEGER;
   BEGIN
      IF firstdate >= lastdate
      THEN
         result := 0;
      ELSE
         result := (  lastdate
                    - firstdate
                   );
         monthinterval := (  lastdate
                           - firstdate
                          ) / 30;

         FOR monthindex IN 0 .. monthinterval
         LOOP
            currentmonth := LAST_DAY (MONTH);
            lastmonthday := TO_NUMBER (TO_CHAR (currentmonth, 'DD'));

            IF  (currentmonth <= lastdate) AND (currentmonth > firstdate)
            THEN
               IF lastmonthday = 31
               THEN
                  result :=   result
                            - 1;
               END IF;

               IF lastmonthday = 28
               THEN
                  result :=   result
                            + 2;
               END IF;

               IF lastmonthday = 29
               THEN
                  result :=   result
                            + 1;
               END IF;
            END IF;

            MONTH := ADD_MONTHS (MONTH, 1);
         END LOOP;
      END IF;

      RETURN result;
   END;
   
 function Calculate
 return integer
 is
   currentaccid currentacc_passport.currentaccid%type;  
   interestaccid currentacc_passport.interestaccid%type; 
   expenceaccid currentacc_passport.expenceaccid%type;
   annualyrate currentacc_passport.annualyrate%type;
   min_rest currentacc_passport.min_rest%type;
   max_rest currentacc_passport.max_rest%type;
   trdescription currentacc_passport.trdescription%type;
   AccountRest Tenostat.ostat%type;
   Interest Tenostat.ostat%type;
   CurrDate Date;
   PrevDate Date;
   DaysBetween Integer;
   TempTrID Integer;
   TrCount Integer := 0;  
 begin
 
   Select TEK_DAT ,PRED_DAT Into CurrDate ,PrevDate
   From Sysdat;
 
   DaysBetween := GetDateInterval(PrevDate,CurrDate); 
   
   for IFCA in c_IFCA_Accounts
   loop
     currentaccid := IFCA.currentaccid;  
     interestaccid := IFCA.interestaccid; 
     expenceaccid := IFCA.expenceaccid;
     annualyrate := IFCA.annualyrate;
     min_rest := IFCA.min_rest;
     max_rest := IFCA.max_rest;
     trdescription := IFCA.trdescription;
     
     Select Ostat Into AccountRest 
     From Tenostat Where Acc_ID = currentaccid;
     
     Interest := Round((DaysBetween * AccountRest)/36000,2);  
     
     if  ((AccountRest >= min_rest)or(min_rest = 0)) and 
         ((AccountRest <= max_rest)or(max_rest = 0)) and 
         (Interest > 0) then
         
     TempTrID :=SB_TRANSACTION.Transaction_Add(
            DebitID      => expenceaccid
   				 ,CreditID     => interestaccid
  				 ,DebitAmount  => null
  				 ,CreditAmount => Interest
  				 ,LAmount      => null
  				 ,DebitRate    => 0
  				 ,CreditRate   => 0
  				 ,TrName       => trdescription
  				 ,Flags        => 0
  				 ,TransactionDate => CurrDate
         );
         
       TrCount := TrCount + 1;    
          
     end if;    
               
   end loop;
   commit work;
   return TrCount;
 end;
END;
/


-- End of DDL Script for Package AV.IFCA_CALCULATION

