      insuredenginenum   out  VARCHAR2,
      driveaccesspiople1 out  VARCHAR2,
      driveaccesspiople2 out  VARCHAR2,
      driverbirthday1    out  DATE,
      driverbirthday2    out  DATE,
      driverexperience1  out  NUMBER,
      driverexperience2  out  NUMBER,
      driveintended      out  VARCHAR2,
      drivecost          out  NUMBER,
      insuredsum         out  NUMBER,
      insuredfranshiz    out  number,
      begindate          out  DATE,
      enddate            out  DATE
   )
   return boolean
   IS
      retrow  ins_motorkasco%rowtype;
      tid number;
   BEGIN
      tid := get_blank.id;
      select * into retrow from ins_motorkasco
      where ins_motorkasco.id = get_blank.id;
      get_blank.profitname := retrow.profitname;
      get_blank.profitaddress := retrow.profitaddress;
      get_blank.profitphone := retrow.profitphone;
      get_blank.insuredtype := retrow.insuredtype;
      get_blank.insuredcolor := retrow.insuredcolor;
      get_blank.insuredoutputyear := retrow.insuredoutputyear;
      get_blank.insuredmodel := retrow.insuredmodel;
      get_blank.insuredstatenum := retrow.insuredstatenum;
      get_blank.underframenum := retrow.underframenum;
      get_blank.insuredbannum := retrow.insuredbannum;
      get_blank.insuredenginenum  := retrow.insuredenginenum;
      get_blank.driveaccesspiople1 := retrow.driveaccesspiople1;
      get_blank.driveaccesspiople2 := retrow.driveaccesspiople2;
      get_blank.driverbirthday1 := retrow.driverbirthday1;
      get_blank.driverbirthday2 := retrow.driverbirthday2;
      get_blank.driverexperience1 := retrow.driverexperience1;
      get_blank.driverexperience2 := retrow.driverexperience2;
      get_blank.driveintended := retrow.driveintended;
      get_blank.drivecost := retrow.drivecost;
      get_blank.insuredsum := retrow.insuredsum;
      get_blank.insuredfranshiz := retrow.insuredfranshiz;
      get_blank.begindate := retrow.begindate;
      get_blank.enddate := retrow.enddate;
      return true;
    EXCEPTION
      WHEN OTHERS
      THEN
         Raise;--Raise_Application_error(-20001, to_char(tid));
   END;

   function del_insurance(type number, insnum number )
   return boolean
   is
    tablename varchar2(64);
   begin
      select ii.tablename into tablename from ins_userinsurances ii
      where ii.id = type and ii.ins_id = insnum;
      execute immediate 'delete from '||tablename||' where id = '||to_char(insnum);
      if SQL%FOUND then
      return true;
      else return false;
      end if;
     exception
     when NO_DATA_FOUND then return false;
     when others then raise;
   end;

   function CheckSuggestionExisting(mk_id number)
   return boolean
   is
     res number;
   begin
     select id into res from ins_mk_suggestion ims
     where ims.mk_id = CheckSuggestionExisting.mk_id;
     if SQL%FOUND then return true;
     else return false;
     end if;
     exception
     when NO_DATA_FOUND then return false;
     when others then raise;
   end;


-- Enter further code below as specified in the Package spec.
END;
/


