 select tek_dat into currdate from sysdat;
 return currdate;
end;
--------------------------------	
Function add_account (
    customerid   in   number,
    op_id        in   number,
    accno        in   varchar,
    currencyid        integer,
    name         in   varchar,
    open_dat     in   date,
    balcn             integer,
    limit             number default 0,
    close_dat         date default null,
