FUNCTION  GetLastOprDay(
      Curr_Date IN Date,
      Curr_ID  IN integer     
)
 return  Date
is
 LOprDate Date;
 begin
  select  Max(VB.Dat) into  LOprDate 
  from out_PROVARCH  VB where
    (VB.Dat<=Curr_Date)
    and ((VB.Debt = Curr_ID) or (VB.Kredit = Curr_ID));
     return LOprDate; 
 end;

