PROCEDURE   GetValuteNameFromID(
   aValID IN integer,
   aDate Date,
   aValName  OUT VarChar2,
   aValu  OUT number
)  
IS
Begin
   Select  AV.VAL_NAME ,OP.Ostat  into  aValName ,aValu  
   from AVALUTE AV ,OperKurs OP 
   where (AV.VALUTE=aValID)and(aValID=Op.Val_Kod)and(Op.Dat=aDate);   
   EXCEPTION
  WHEN NO_DATA_FOUND THEN
  begin
    aValName :='';
    aValu :=0;
    raise;
  end;    
End;
procedure test(d date) as
 begin
   if d=sysdate then
   dbms_output.put_line('True'||To_Char(To_Number(d)));
   else
   dbms_output.put_line('False'||To_Char(To_Number(d)));
   end if;
--   EXECUTE IMMEDIATE 'Insert Into a1 (c1) Values ('||To_Number(d)||')'; 
 end; 
 FUNCTION ACTIVE
  ( aValue IN Number
    ,aTID IN Integer
    ,aAdd IN  Integer
    )
  RETURN  Number IS
  ReturnValue Number;
BEGIN
  if aValue=0 then
   return 0;
  end if;
  
  if  aValue<0 then
    ReturnValue :=abs(aValue);
   else
    ReturnValue :=0;
  end if;
  
  if ReturnValue<>0 then
  if  (aTID<>aAdd) then   
   if  aAdd=2 then
       ReturnValue :=0;
   end if;
   end if;
   else
   if  (aAdd=1)and(aADD<>aTID) then
   ReturnValue :=-abs(aValue);
   end if;   
  end if;
  return ReturnValue;
END;

 FUNCTION PASSIV
  ( aValue IN Number
    ,aTID IN Integer
    ,aAdd IN  Integer
    )
  RETURN  Number IS
  ReturnValue Number;
BEGIN
  if aValue=0 then
   return 0;
  end if;
  
  if  aValue>0 then
    ReturnValue :=abs(aValue);
   else
    ReturnValue :=0;
  end if;
  
  if ReturnValue<>0 then
  if  (aTID<>aAdd) then   
   if  aAdd=1 then
       ReturnValue :=0;
   end if;
   end if;
   else
   if  (aAdd=2)and(aADD<>aTID) then
   ReturnValue :=-abs(aValue);
   end if;   
  end if;
  Return ReturnValue;
END;
                   
BEGIN
 select user, trunc(tek_dat) into UserName, BankDay from sysdat;                           
END;
