function fLastOpdate(v_acc_id number,v_beg_dat date) return date
is
result date;
begin
 
select max(pr.dat) 
into   result 
from   out_provarch pr 
where  
        (pr.debt =v_acc_id or pr.kredit=v_acc_id) 
    and (pr.dat<v_beg_dat)  
    and (nvl(pr.vid_op,0)<>1);

return result; 
 exception 
  when no_data_found
   then
return null;
end;   
  
