function transaction_temp_add (Out_Transaction in out t_transaction) return integer is
Result integer;
AFlags integer;
begin
AFlags := Mask_Flags(Out_Transaction.Flags, sbdecls.atfTemporary/*+sbdecls.atfCommitImmediate*/);
if (not (Out_Transaction.Flags is null)) and (AFlags is null) then
 raise_application_error(-20001, 'Flags is null');
end if;
Insert into out_TempTranz (
   ID, OperatorID, ParentID,
   DebitID, CreditID, DebitAmount, CreditAmount, LAmount, 
   DebitRate, CreditRate, TrName, Flags, TempID, VID_OP,
   Kassa_B, Kassa_Z, --modified by Tars in 17/12/2002 
   SessionID, no_prov)   
 values (
  Out_Transaction.ID,
  Out_Transaction.OperatorID,
  Out_Transaction.ParentID,
  Out_Transaction.DebitID, Out_Transaction.CreditID, 
  Out_Transaction.DebitAmount, Out_Transaction.CreditAmount, 
  Out_Transaction.LAmount, Out_Transaction.DebitRate, 
  Out_Transaction.CreditRate, Out_Transaction.Name, 
  AFlags,
  TO_NUMBER(Out_Transaction.Param1),
  Out_Transaction.OperationType,
  Out_Transaction.InBalanceChar,
  Out_Transaction.OutBalanceChar,
  SessionID, Out_Transaction.TransactionNo)--TNarik
    returning ID into Result;
Out_Transaction.ID := Result;
return Result;
end;
-----------------------------------------
Function transaction_temp_add(
  OperatorID               integer,
  DebitID                    integer,
  CreditID                   integer,
  DebitAmount           number,
  CreditAmount          number,
  LAmount                  number,
  DebitRate                number,
  CreditRate               number,
  TrName                    varchar,
  Flags                        integer,
  InBalanceChar    in  integer,
  OutBalanceChar  in integer,
  TransactionID          integer default null,
  ATempID	   integer,
  OperationType integer default null,     -- Amt vid_op
  TransactionNo varchar default null     --TNarik
) return integer is
  Out_Transaction t_transaction;
begin
--dbms_output.put_line('transaction_temp_add '|| to_char(OperationType));
 Out_Transaction.ID := TransactionID;
 Out_Transaction.OperatorID := OperatorID;
 Out_Transaction.DebitID := DebitID;
 Out_Transaction.CreditID := CreditID;
 Out_Transaction.DebitAmount := DebitAmount;
 Out_Transaction.CreditAmount := CreditAmount;
 Out_Transaction.LAmount := LAmount;
 Out_Transaction.DebitRate := DebitRate;
 Out_Transaction.CreditRate := CreditRate;
 Out_Transaction.Flags := Flags; 
 Out_Transaction.Param1 := TO_CHAR(ATempID);
 Out_Transaction.InBalanceChar := InBalanceChar;
 Out_Transaction.OutBalanceChar := OutBalanceChar; 
 Out_Transaction.Name := TrName;
 Out_Transaction.OperationType :=OperationType;
 Out_Transaction.TransactionNo := TransactionNo;  
return transaction_temp_add(Out_Transaction);
end;
