Function transaction_add(Out_Transaction in out t_transaction)	return integer is
 cursor c_IsCashAccount(AccID1 integer, AccID2 integer) is 
  select count(*) as r from out_bal_spr1 where bal_cn in 
   (select bal_cn1 from out_account where 
     (ID in (AccID1, AccID2)) and (VAL_ACC = 0))	and (CashIncoming = 1);
  Result integer := 0;
  CurrentDate date;
  DebitRate number;
  CreditRate number;
  IsCashAccount c_IsCashAccount%rowtype;
begin
 SB_ACA.CheckObjectAccess('OUT_TRANSACTIONMANAGERFORM','insert');  --adm

/* Begin Amt */
CurrentDate := out_SBOP.get_date;
 if Out_Transaction.TrDate<CurrentDate then
  raise_application_error(-20083,'!!! Kechmish Gune Olmaz !!!');
-- p_repair.main(Transaction,1);
 return 0;
 end if;
/* End Amt */		
	
if Out_Transaction.Name is null then raise_application_error(
  sbdecls.Error_InvalidParameters, 'Transaction description is not specified');
end if;

open c_IsCashAccount(Out_Transaction.DebitID, Out_Transaction.CreditID);
fetch c_IsCashAccount into IsCashAccount;
close c_IsCashAccount;
	
if (Out_Transaction.InBalanceChar = 0) and (IsCashAccount.r <> 0) then
 raise_application_error(sbdecls.Error_InvalidParameters,
   'Cash transaction without cash symbols is not permitted');
end if;
		
-- Check if debit and credit accounts are equal
if Out_Transaction.DebitID = Out_Transaction.CreditID then
 raise_application_error(
  sbdecls.Error_InvalidParameters,
--'Debit and credit accounts MAY NOT be equal for transaction'
    To_char(Out_Transaction.DebitID) || '  ' ||To_char(Out_Transaction.CreditID));
end if;
        
  if (Out_Transaction.DebitAmount < 0) or (Out_Transaction.CreditAmount < 0) or (Out_Transaction.LAmount < 0) then
     raise_application_error(sbdecls.Error_InvalidParameters, 'Amounts may not be less than zero');
  end if;
	
 -- Generate transaction ID if required	
if Out_Transaction.ID is null then
 select TR_SEG_PROVARCH.nextval into Out_Transaction.ID from dual;
end if;
		
-- Condition 1. Use current date by default	
CurrentDate := out_SBOP.get_date;
if Out_Transaction.TrDate is null then
 Out_Transaction.TrDate := CurrentDate;
end if;
		
-- Condition 2. Always use current rates	
-- Added by amt 4-jan-4
   DebitRate:= GetRate (Out_Transaction.DebitID, CurrentDate);
   CreditRate:=GetRate(Out_Transaction.CreditID, CurrentDate);
   
-- Comment By amt 4-jan-4 		
/*
 	open sb_transaction_clib.c_RateByAcc(Transaction.DebitID, CurrentDate);
	fetch sb_transaction_clib.c_RateByAcc into DebitRate;
 	close sb_transaction_clib.c_RateByAcc;
 	open sb_transaction_clib.c_RateByAcc(Transaction.CreditID, CurrentDate);
	fetch sb_transaction_clib.c_RateByAcc into CreditRate;
 	close sb_transaction_clib.c_RateByAcc;
*/

if DebitRate is null then 
  raise_application_error(sbdecls.Error_NoRateForDateSpecified,
   'No rates found for debit account (ID="'||
    TO_CHAR(Out_Transaction.DebitID)||
  '") for current operation date');
end if;

if CreditRate is null then
 raise_application_error(
  sbdecls.Error_NoRateForDateSpecified,
  'No rates found for credit account (ID="'||
  TO_CHAR(Out_Transaction.CreditID)||
  '") for current operation date');
end if;
		
if not (Out_Transaction.DebitRate is null) then
 if Out_Transaction.DebitRate = DebitRate then
  Out_Transaction.DebitRate := null;				
 end if;
end if;

if not (Out_Transaction.CreditRate is null) then
 if Out_Transaction.CreditRate = CreditRate then
  Out_Transaction.CreditRate := null;				
 end if;
end if;

-- Amt ParentId 0 Call all Tansactions 
if BitAnd(Out_Transaction.Flags, sbdecls.atfTemporary) <> 0 then
 Result := transaction_temp_add(Out_Transaction);
else
 Result := transaction_delayed_add(Out_Transaction);		
 if BitAnd(Out_Transaction.Flags, sbdecls.atfCommitImmediate) <> 0 then
  Result := transaction_commit(Out_Transaction.ID);
 end if;
end if;
return Result;
end;
