function transaction_add (
  TransactionDate   date default null,
  DebitID                integer,
  CreditID               integer,
  DebitAmount       number,
  CreditAmount      number,
  LAmount              number,
  DebitRate            number default null,
  CreditRate           number default null, -- rates should be retreived from system dataset
  TrName               varchar,
  Flags                   integer default 0, -- transaction are delayed by default
  InBalanceChar		integer default null,
  OutBalanceChar		integer default null,
  TransactionID		integer default null,
  OperationType		integer default null,
  ParentID		integer default null,
  TempID			integer default null,
  OperatorId integer default null,
  TransactionNo varchar default null --TNarik
  ) return integer Is
Out_Transaction t_transaction;
begin
  Out_Transaction.ID := TransactionID;
  Out_Transaction.OperatorId :=OperatorId; 
  Out_Transaction.TrDate := TransactionDate;
  Out_Transaction.DebitID := DebitID;
  Out_Transaction.CreditID := CreditID;
  Out_Transaction.DebitAmount := DebitAmount;
  Out_Transaction.CreditAmount := CreditAmount;
  Out_Transaction.LAmount := LAmount;
  Out_Transaction.DebitRate := DebitRate;
  Out_Transaction.CreditRate := CreditRate;
  Out_Transaction.Flags := Flags;
  Out_Transaction.InBalanceChar := InBalanceChar;
  Out_Transaction.OutBalanceChar := OutBalanceChar;
  Out_Transaction.Param1 := TempID;
  Out_Transaction.OperationType := OperationType;
  Out_Transaction.ParentID := ParentID;
  Out_Transaction.Name := TrName; 
  Out_Transaction.TransactionNo := TransactionNo; 
return transaction_add(Out_Transaction);
end;
