Function transaction_temp_commit(Temp out_temptranz%rowtype) return integer as
  ATemp out_temptranz%rowtype := Temp;
  Result integer;
begin
/*
 We can not use here ADD_TRANSACTION, 
 because it may (and will) cause an deadlock
*/
if BitAnd(ATemp.Flags, sbdecls.atfCommitImmediate) <> 0 then
  Result := transaction_commited_add(
    ATemp.OperatorID,
    ATemp.DebitID,
    ATemp.CreditID,
    ATemp.DebitAmount,
    ATemp.CreditAmount,
    ATemp.LAmount,
    ATemp.DebitRate,
    ATemp.CreditRate,
    ATemp.TrName,
    ATemp.Flags, 
    ATemp.Kassa_B,
