procedure UpdateId
is
 old_id integer;
 new_id integer;
 cursor prov_doc
 is
  select * from provdoc 
  where vid_op<>1 or vid_op is null
  FOR UPDATE;
begin
  for rec in prov_doc
   loop
   old_id := rec.id;
   update provdoc
   set id=TR_SEG_PROVARCH.nextval
   where id=rec.id 
   RETURNING id INTO new_id;

   update provdoc set parentid=new_id
   where parentid=old_id;
  end loop;
end;
