procedure ContrAccounts
is
 cursor c_BankProperties is (select * from out_BankProperties);
 BankPro c_BankProperties%rowtype;
 D integer;
 K integer;
 F integer;
 V integer;
 SQ varchar2(500);
 x1 number;
 x2 number;
 x3 number;
 x4 number;
 x_temp number;
begin

  update out_tenostat set ostat =0, pok_ostat=0
   where acc_id in (select Debet from out_BankProperties)
      or acc_id in (select Kredit from out_BankProperties);

  commit;

  for BankPro in c_BankProperties
  loop
   D :=BankPro.Debet;
   K :=BankPro.Kredit;
   F :=BankPro.FilialID;
   V :=BankPro.Valute;
   --ACTIVE--
   /*X1*/ select nvl(sum(pok_ostat),0) 
     into x1 from out_tenostat
     where pok_ostat<0 and acc_id not in (select ID from out_account where bal_cn1 in (99981,99991) )--(D,K)
     and acc_id in (select id from out_account where val_acc=V and
     filial=F);
     select nvl(sum(pok_ostat),0)
     into x_temp from out_tenostat
     where acc_id in (select id from out_account where bal_cn1=99981 and val_acc=V and filial=F and acc_id not in (D,K));
     x1 :=x1+x_temp;

   /*X2*/ select nvl(sum(pok_ostat),0)
     into x2 from out_tenostat
     where pok_ostat<0 and acc_id not in (select ID from out_account where bal_cn1 in (99981,99991) ) --(D,K)
     and acc_id in (select id from out_account where val_acc=V and
     filial=F);
     select nvl(sum(pok_ostat),0)
     into x_temp from out_tenostat
     where acc_id in (select id from out_account where bal_cn1=99981 and val_acc=V and filial=F and acc_id not in (D,K));
     x2 :=x2+x_temp;

   update out_tenostat set
    ostat =(ostat+x1),
    pok_ostat =(pok_ostat+x2)
   where acc_id =D;

   --PASSIVE--
   /*X3*/ select nvl(sum(pok_ostat),0) 
     into X3 from out_tenostat
     where pok_ostat>0 and acc_id not in (select ID from out_account where bal_cn1 in (99981,99991) ) -- (D,K)
     and acc_id in (select id from out_account where val_acc=V and
     filial=F);
     select nvl(sum(pok_ostat),0)
     into x_temp from out_tenostat
     where acc_id in (select id from out_account where bal_cn1=99991 and val_acc=V and filial=F and acc_id not in (D,K));
     x3 :=x3+x_temp;

    /*X4*/ select nvl(sum(pok_ostat),0) 
     into x4 from out_tenostat
     where pok_ostat>0 and acc_id not in (select ID from out_account where bal_cn1 in (99981,99991) ) --(D,K)
     and acc_id in (select id from out_account where val_acc=V and
     filial=F); 
     select nvl(sum(pok_ostat),0)
     into x_temp from out_tenostat
     where acc_id in (select id from out_account where bal_cn1=99991 and val_acc=V and filial=F and acc_id not in (D,K));
     x4 :=x4+x_temp;

    update out_tenostat set
    ostat =(ostat+x3),
    pok_ostat =(pok_ostat+x4)
   where acc_id =K;
  end loop;
  commit;
  
  update out_tenostat set ostat =(-1)*ostat, pok_ostat=(-1)*pok_ostat
   where acc_id in (select Debet from out_BankProperties)
      or acc_id in (select Kredit from out_BankProperties);
  commit;
end;
END;
/


