function AccRest(i number, v_acc_id number) return number 
is
result number;
begin
if i=0 then
 select ostat into result from tenostat where acc_id=v_acc_id;
else
 select pok_ostat into result from tenostat where acc_id=v_acc_id;
end if;
 return result;
end;

procedure findrecords
is
 i integer;
 str   varchar2(6);
 str1   varchar2(6);
 cnt  integer;
 cnt1  integer;
begin
-- for i in 1..866;
 i:=1;
 loop
    str1:=to_char(i);
    for j  in 1..2 
    loop
      str1:='0'+str1;      
    end loop;
    str:='ATA'||str1;
--    dbms_output.put_line('reference= '||str);
    select count(*) into cnt from clients where reference=str and messtype<3;
    select count(*) into cnt1 from clients_ca where reference=str and messtype<3;
    if (cnt = 0)and(cnt1=0) then null; /*dbms_output.put_line('Not found= '||str);*/   end if;
 i:=i+1;  
 exit when i >866; 
 end loop;     
 end;
END;
