procedure AddAccsByBalCodeStr( v_BalSpec varchar2,
                               v_BalType   Number,
                               v_Currency  Number,                             
                               vStDate     date,
                               vEndDate    date  ) is
StrSql       varchar2(5000);
CurrCond     varchar2(100);   
BalTypeCond  varchar2(100);
BalSpecSize  Number(9);
vStDate1     date;
vEndDate1    date;
                  
begin

  -- vStDate1   :=  TO_date('23-10-2002','DD-MM-YYYY');
  -- vEndDate1  :=  TO_date('03-11-2002','DD-MM-YYYY');
   
  if ( v_BalType = - 1 ) then
        BalTypeCond := '' ;
    else
        BalTypeCond :=  to_char( v_BalType) ;
  end if;
  
  if ( v_Currency =- 1 ) then
        CurrCond := '';
    else
        CurrCond := ' and ( P.VAL_ACC='||to_char(v_Currency)||')';
  end if;

 
StrSql:='INSERT INTO  SMART.ACCS_EXTR (
ACC_ID,   ACC_NO, NAME, BAL_CN'||BalTypeCond||',        ST_DATE,          END_DATE )
SELECT 
P.ACC_ID, MIN(P.ACC_NO), MIN(P.NAME), MIN(P.BAL_CN'||BalTypeCond||'), MIN(P.PROV_DATE), MAX(P.PROV_DATE)
FROM
PROV_ALL P
where 
    -- for a 4 symbol specs, like 100*, 2*54
   (
    (
      ( length( to_char(BAL_CN'||BalTypeCond||'))=4) and  
      ( 
       ( 
         ( 
           (  substr('''||v_BalSpec||''',1,1) = ''*'')  
              and 
           (  substr(P.BAL_CN'||BalTypeCond||',1,1) >=0 and  substr(BAL_CN'||BalTypeCond||',1,1) <=9 )
         ) 
         or
           -- if first symb is digit, it must be equal to 
           -- corresponding  digit of BAL_CN1
         (  substr('''||v_BalSpec||''',1,1) = substr(BAL_CN'||BalTypeCond||',1,1)  )
       ) 
      and
       (  
         ( (  substr('''||v_BalSpec||''',2,1) = ''*'')  
              and 
           (  substr(BAL_CN'||BalTypeCond||',2,1) >=0 and  substr(BAL_CN'||BalTypeCond||',2,1) <=9 )
         ) 
         or
           -- if first symb is digit, it must be equal to 
           -- corresponding  digit of BAL_CN1
         (  substr('''||v_BalSpec||''',2,1) = substr(BAL_CN'||BalTypeCond||',2,1)  )
       )  
      and
       (  
         ( (  substr('''||v_BalSpec||''',3,1) = ''*'')  
              and 
           (  substr(BAL_CN'||BalTypeCond||',3,1) >=0 and  substr(BAL_CN'||BalTypeCond||',3,1) <=9 )
         ) 
         or
           -- if first symb is digit, it must be equal to 
           -- corresponding  digit of BAL_CN1
         (  substr('''||v_BalSpec||''',3,1) = substr(BAL_CN'||BalTypeCond||',3,1)  )
       )
      and
       ( 
         ( (  substr('''||v_BalSpec||''',4,1) = ''*'')  
              and 
           (  substr(BAL_CN'||BalTypeCond||',4,1) >=0 and  substr(BAL_CN'||BalTypeCond||',4,1) <=9 )
         ) 
         or
           -- if first symb is digit, it must be equal to 
           -- corresponding  digit of BAL_CN1
         (  substr('''||v_BalSpec||''',4,1) = substr(BAL_CN'||BalTypeCond||',4,1)  )
        )
      )
    ) 
      OR 
     -- for a 3 symbol specs, like 10*, 2*5     
     (
      ( length( to_char(BAL_CN'||BalTypeCond||'))=3) and  
      ( 
       ( 
         ( 
           (  substr('''||v_BalSpec||''',1,1) = ''*'')  
              and 
           (  substr(P.BAL_CN'||BalTypeCond||',1,1) >=0 and  substr(BAL_CN'||BalTypeCond||',1,1) <=9 )
         ) 
         or
           -- if first symb is digit, it must be equal to 
           -- corresponding  digit of BAL_CN1
         (  substr('''||v_BalSpec||''',1,1) = substr(BAL_CN'||BalTypeCond||',1,1)  )
       ) 
      and
       (  
         ( (  substr('''||v_BalSpec||''',2,1) = ''*'')  
              and 
           (  substr(BAL_CN'||BalTypeCond||',2,1) >=0 and  substr(BAL_CN'||BalTypeCond||',2,1) <=9 )
         ) 
         or
           -- if first symb is digit, it must be equal to 
           -- corresponding  digit of BAL_CN1
         (  substr('''||v_BalSpec||''',2,1) = substr(BAL_CN'||BalTypeCond||',2,1)  )
       )  
      and
       (  
         ( (  substr('''||v_BalSpec||''',3,1) = ''*'')  
              and 
           (  substr(BAL_CN'||BalTypeCond||',3,1) >=0 and  substr(BAL_CN'||BalTypeCond||',3,1) <=9 )
         ) 
         or
           -- if first symb is digit, it must be equal to 
           -- corresponding  digit of BAL_CN1
         (  substr('''||v_BalSpec||''',3,1) = substr(BAL_CN'||BalTypeCond||',3,1)  )
       )      
      )
    ) 
  )'||CurrCond||'
GROUP BY  P.ACC_ID
HAVING  ( NOT( MAX(P.PROV_DATE) <'''||to_char(vStDate)||''' OR MIN(P.PROV_DATE) >'''||to_char(vEndDate)||'''))';

 Execute Immediate StrSql; 
 commit;
end;
