--  dbms_sql.Close_cursor(v_cursor);
end if;
  EXECUTE IMMEDIATE StrSql;
-- v_Cursor:=dbms_sql.open_cursor;
-- dbms_sql.parse(v_Cursor,strsql,dbms_sql.v7);
-- nRow:=dbms_sql.execute(v_Cursor);
-- dbms_sql.Close_cursor(v_cursor);
END;

--*****************************************
FUNCTION IIFBALANCE
  (
        n integer
,       TypeId1  integer
, TypeId2  integer
,       aRemainder number
,       pRemainder number
        )RETURN  number IS

value number(15,2);
BEGIN
if TypeId1=1 and TypeId2=2 then
 if n=-1 then
  value:=0;
 else
  value:=-(aRemainder+pRemainder);
 end if;

elsif TypeId1=2 and TypeId2=1 then
 if n=-1 then
  value:=-(aRemainder+pRemainder);
 else
  value:=0;
 end if;

elsif TypeId1=3 and TypeId2=1 then
 if n=-1 then
  value:=(aRemainder+pRemainder);
 else
  value:=0;
 end if;

elsif TypeId1=3 and TypeId2=2 then
 if n=-1 then
