FUNCTION fdate( v_Date IN Date, v_OpenDate in Date) return date as
OptDate Date;
begin
 if v_Date<v_OpenDate then
  OptDate:=v_OpenDate;
 else
  OptDate:=v_Date;
 end if;
return OptDate;
end;
