  PROCEDURE checkmoneyborderaccess (
      moneyvalue number,
      user_name       VARCHAR2 DEFAULT USER
   );
  function IsConnected_num(user_name varchar2)
     return integer;
  procedure CheckUserConnected(user_name varchar2 default user);
