         RETURN FALSE;
      WHEN TOO_MANY_ROWS
      THEN
         RETURN FALSE;
   END;

   FUNCTION checklockuser_num (inusername VARCHAR2)
      RETURN INTEGER
   IS
   BEGIN
      IF (checklockuser (inusername))
      THEN
         RETURN 1;
      ELSE
         RETURN 0;
      END IF;
   END;
   
   function getaccountbalacc(accid number)
