       where id=accid;
      return res;
      exception when others then
        return -1;
   end;

    function checkbalaccaccess (
       pbalacc     number,
       poptype     number default 1,
       pusername   varchar2 default user
    )
       return integer
    is
       cnt   number;
    begin
       select bal_acc
         into cnt
         from sba_balance_acc a
        where a.username = pusername and a.bal_acc = pbalacc
              and a.optype = poptype;

       return 1;
    exception
       when no_data_found
       then
          return isadm_num;
       when others
       then
          return -1;
    end;

    function checksymbolaccess(symbs varchar2, usname varchar2 default user)
      return number
    is
      res number;
    begin
      select decode(count(*),0,0,1)
        into res
        from sba_userflags
       where username=usname
         and symbs like '%'||flagsymb||'%';

      return res;
    exception
       when no_data_found
       then
          return isadm_num;
       when others
       then
          return -1;
    end;
END;
