   PROCEDURE checkobjectaccess (
      module      VARCHAR2,
      action      VARCHAR2,
      user_name   VARCHAR2 DEFAULT USER
   )
   IS
      ex_grant   EXCEPTION;
      result     BOOLEAN;
      tempac     VARCHAR2 (56);
      obj        sba_usergrants%ROWTYPE;
      PRAGMA EXCEPTION_INIT (ex_grant,  -1422);
   BEGIN
      tempac := UPPER (action);

      BEGIN
         SELECT *
           INTO obj
           FROM sba_usergrants
          WHERE cur_user = UPPER (user_name) AND cur_module = UPPER (module);

         result := TRUE;
      EXCEPTION
