is
 STATUS dba_users.ACCOUNT_STATUS%type;
begin
 select ACCOUNT_STATUS into STATUS from dba_users
  where username=UPPER(InUserName) and  ACCOUNT_STATUS='LOCKED';
  
Return True;
EXCEPTION
 WHEN NO_DATA_FOUND  THEN
   RETURN False;
 WHEN TOO_MANY_ROWS then 
  RETURN False;
end;

