      username    VARCHAR2,
      passw       VARCHAR2,
      iscreate    BOOLEAN DEFAULT TRUE,
      iscascade   BOOLEAN DEFAULT TRUE
   )
   IS
      usstr   VARCHAR2 (256);
      tpbl    BOOLEAN;
   BEGIN
      IF iscreate
      THEN
         createprofile(username);
         usstr :=
                 'create user '
              || username
              || ' identified by '
              || passw
              || replace(def, '%s', username);--!!!!!!!!!!!!!!!!!!!!!!!!


     /*
         usstr :=
                 'create user '
              || username
              || ' identified by '
              || passw
              || def;*/
      ELSE /*Changed by Kera 2007-08-08 10:47 */

         dropuseraction (username);

