      tpbl := runsql (usstr);
         usstr :=    'alter user '
                  || username||' account lock';

      IF iscreate
      THEN
         EXECUTE IMMEDIATE    'grant UNLIMITED TABLESPACE to '
                           || UPPER (username);
      END IF;
   END;
