   PROCEDURE deletemodule (moduleid INTEGER)
   IS
      rolname   modules.description%TYPE;
      tp        BOOLEAN;
   BEGIN
      SELECT REPLACE (UPPER (description), ' ')
        INTO rolname
        FROM modules
       WHERE id = moduleid;

      DELETE FROM modules
            WHERE id = moduleid;

      DELETE FROM sba_objmanager
            WHERE OBJECT = rolname;

      rolname :=    'SBR_'
                 || rolname;

      IF sb_aca.checkrole (rolname)
      THEN
         tp := runsql (   drcrole
                       || rolname, TRUE);
      END IF;

      COMMIT;
   END;

   PROCEDURE addmodule (
      passw     VARCHAR2,
      classid   VARCHAR2,
      descr     VARCHAR2,
      trvdeck   VARCHAR2,
      can_ins   INTEGER,
      can_del   INTEGER,
      can_upd   INTEGER
   )
   IS
      tp   BOOLEAN;
   BEGIN
      INSERT INTO modules
                  (NAME, description, trvdesc, can_insert,
                   can_delete, can_update)
           VALUES (classid, UPPER (REPLACE (descr, ' ')), trvdeck, can_ins,
                   can_del, can_upd);

      tp := runsql (
                  crcrole
               || 'SBR_'
               || REPLACE (UPPER (descr), ' ')
               || psrole
               || passw,
               TRUE
            );
      COMMIT;
   END;

   PROCEDURE updatemodule (
      modnam        VARCHAR2,
      vclassid      VARCHAR2,
      vtrvdesc      VARCHAR2,
      vcan_insert   VARCHAR2,
      vcan_delete   VARCHAR2,
      vcan_update   VARCHAR2
   )
   IS
   BEGIN
      UPDATE modules
         SET NAME = vclassid,
             trvdesc = vtrvdesc,
             can_insert = vcan_insert,
             can_delete = vcan_delete,
             can_update = vcan_update
       WHERE UPPER (REPLACE (description, ' ')) =
                                                 UPPER (REPLACE (modnam, ' '));

      COMMIT;
   END;

   PROCEDURE saveresults (
      svstr    VARCHAR2,
      filloc   BOOLEAN,
      hand     UTL_FILE.file_type
   )
   IS
   BEGIN
      IF filloc
      THEN
         UTL_FILE.put_line (hand, svstr);
      ELSE
        null; --DBMS_OUTPUT.put_line (svstr);
      END IF;
   END;

   PROCEDURE createrolesalllist (
      filloc   BOOLEAN := FALSE,
      dir      VARCHAR2 := '',
      NAME     VARCHAR2 := ''
   )
   IS
      CURSOR c_roles
      IS
         SELECT *
           FROM dba_roles
          WHERE ROLE LIKE ('SBR_%');

      CURSOR c_granrole (gr VARCHAR2)
      IS
         SELECT *
           FROM dba_role_privs
          WHERE grantee = gr;

      CURSOR c_gransyspriv (gr VARCHAR2)
      IS
         SELECT *
           FROM dba_sys_privs
          WHERE grantee = gr;

      CURSOR c_grantabprivs (gr VARCHAR2)
      IS
         SELECT *
           FROM dba_tab_privs
          WHERE grantee = gr;

      CURSOR c_rol
      IS
         SELECT ROLE
           FROM dba_roles
          WHERE ROLE LIKE ('SBR%');

      file_handle   UTL_FILE.file_type;
   BEGIN
      IF filloc
      THEN
         file_handle := UTL_FILE.fopen (dir, NAME, 'w');
      END IF;

      saveresults (   prob
                   || '---Creating roles---', filloc, file_handle);

      FOR rolrec IN c_roles
      LOOP
         saveresults (
               crcrole
            || rolrec.ROLE
            || psrole
            || 'sm'
            || del,
            filloc,
            file_handle
         );
      END LOOP;

      FOR rec IN c_rol
      LOOP
         saveresults (   dil
                      || rec.ROLE
                      || dil, filloc, file_handle);
         saveresults (   prob
                      || '---Granting roles---', filloc, file_handle);

         FOR recrp IN c_granrole (rec.ROLE)
         LOOP
            saveresults (
                  'Grant '
               || recrp.granted_role
               || ' to '
               || rec.ROLE
               || del,
               filloc,
               file_handle
            );
         END LOOP;

         saveresults (
               prob
            || '---Granting system privileges---',
            filloc,
            file_handle
         );

         FOR recsp IN c_gransyspriv (rec.ROLE)
         LOOP
            saveresults (
                  'Grant '
               || recsp.PRIVILEGE
               || ' to '
               || rec.ROLE
               || ';',
               filloc,
               file_handle
            );
         END LOOP;

         saveresults (
               prob
            || '---Granting tab privs---',
            filloc,
            file_handle
         );

         FOR rectp IN c_grantabprivs (rec.ROLE)
         LOOP
            saveresults (
                  'Grant '
               || rectp.PRIVILEGE
               || ' on '
               || rectp.table_name
               || ' to '
               || rec.ROLE
               || ';',
               filloc,
               file_handle
            );
         END LOOP;

         saveresults (   crlf
                      || crlf, filloc, file_handle);
      END LOOP;

      IF UTL_FILE.is_open (file_handle)
      THEN
         UTL_FILE.fclose (file_handle);
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         IF UTL_FILE.is_open (file_handle)
         THEN
            UTL_FILE.fclose (file_handle);
         END IF;

         RAISE;
   END;

   
