CREATE OR REPLACE 
PACKAGE BODY       sb_archiveop
IS

	procedure add_std_transaction (
		ArchiveDate					date,
    DebitID             integer,
    CreditID            integer,
    DAmount        			number,
		CAmount							number,
		LAmount							number,
    DebitRate           number,
    CreditRate          number,
    TrName              varchar2,
    Flags               integer default 0,
    Result    in out   integer
  )
  as

		DebitCurrencyID integer; 
		CreditCurrencyID integer;

  begin
