CREATE OR REPLACE 
PACKAGE BODY sb_balance1
IS
FUNCTION SALDOTOPASSIVE
  ( aValue IN Number,
    BalType IN integer,
		Balance IN integer
    )
  RETURN  Number IS
  ReturnValue Number;
	aTID  Integer;
  aAdd   Integer;
BEGIN
    if  BalType=1  then
   Select  TypeID,AdditionalTypeId 
	        Into  aTid,aAdd From Bal_Spr1
					Where Bal_cn=Balance;
	end if;
	if  BalType=2  then
   Select  TypeID,AdditionalTypeId 
	        Into  aTid,aAdd From Bal_Spr2
					Where Bal_cn=Balance;
	end if;
	if  BalType=3  then
   Select  TypeID,AdditionalTypeId 
	        Into  aTid,aAdd From Bal_Spr3
					Where Bal_cn=Balance;
	end if;
	if  BalType=4  then
   Select  TypeID,AdditionalTypeId 
	        Into  aTid,aAdd From Bal_Spr4
					Where Bal_cn=Balance;
	end if;

  if aValue=0 then
   return 0;
  end if;
  
  if  aValue>0 then
    ReturnValue :=abs(aValue);
   else
    ReturnValue :=0;
  end if;
  
  if ReturnValue<>0 then
  if  (aTID<>aAdd) then   
   if  aAdd=1 then
       ReturnValue :=0;
   end if;
   end if;
   else
   if  (aAdd=2)And(aADD<>aTID) then
   ReturnValue :=-abs(aValue);
   end if;   
  end if;
  Return ReturnValue;
END;

--***************************
FUNCTION SALDOTOACTIVE
  ( aValue IN Number,
	 BalType IN integer,
	 Balance IN integer)
  RETURN  Number 
IS
  ReturnValue Number;
	aTID integer;
	aAdd integer;
BEGIN
  if  BalType=1  then
   Select  TypeID,AdditionalTypeId 
	        Into  aTid,aAdd From Bal_Spr1
					Where Bal_cn=Balance;
	end if;
	if  BalType=2  then
   Select  TypeID,AdditionalTypeId 
	        Into  aTid,aAdd From Bal_Spr2
					Where Bal_cn=Balance;
	end if;
	if  BalType=3  then
   Select  TypeID,AdditionalTypeId 
	        Into  aTid,aAdd From Bal_Spr3
					Where Bal_cn=Balance;
	end if;
	if  BalType=4  then
   Select  TypeID,AdditionalTypeId 
	        Into  aTid,aAdd From Bal_Spr4
					Where Bal_cn=Balance;
	end if;
					   
  if aValue=0 then
   return 0;
  end if;
  
  if  aValue<0 then
    ReturnValue :=abs(aValue);
   else
    ReturnValue :=0;
  end if;
  
  if ReturnValue<>0 then
  if  (aTID<>aAdd) then   
   if  aAdd=2 then
       ReturnValue :=0;
   end if;
   end if;
   else
   if  (aAdd=1)And(aADD<>aTID) then
   ReturnValue :=-abs(aValue);
   end if;   
  end if;
  return ReturnValue;
END;
