  cUnionHeader 
     constant VarChar2(512):=' 0 FA,0 FP,Sum(LastRemainder.LastActive),Sum(LastRemainder.LastPassive),Sum(TurnOver.DTurnOver),Sum(TurnOver.KTurnOver) From ';
  cUnionBody
     constant VarChar2(512):=' Where (not LastRemainder.BalanceBill in (Select Distinct  B.Bal_cn from  ArchOst Ar,Account Ac, BAL_SPR1 B Where (Ar.ACC_ID=Ac.ID)And(Ac.BAL_CN1=B.BAL_CN)And(Ar.DatDate=';     
