begin

  StatementFilter :=StatementFilter||TO_CHAR(BalanceBill);
  ReferenceFilter :=ReferenceFilter||TO_CHAR(BalanceBill);
  
  if  Currency=-1 then
    CurrencyFilter :=null;
   else
    CurrencyFilter:='And(VAL_ACC='||TO_CHAR(Currency)||')';
  end if;
    
  if   (Surface=1)or(Currency=-1)  then     
    Remainder :='POK_OSTAT';
