   Select  Max(DatDate) Into LDate  From ArchOst
           Where  DatDate<=LastDate;                      
   Select  Max(DatDate) Into FDate  From ArchOst
           Where  DatDate<=FirstDate;
					 
		       PresentDate:=FDate;
					 			   
