		        Where  DatDate<FDate; 	 
                                     
  FirstRemFilter :='(Select Sum(SB_MTOUTVIEW.ACTIVE(Ar.'
  ||Remainder||',B.TYPEID,B.ADDITIONALTYPEID)) FirstActive,Sum(SB_MTOUTVIEW.PASSIV(Ar.'||Remainder||',B.TYPEID,B.ADDITIONALTYPEID)) FirstPassive,B.BAL_CN BalanceBill,'
  ||''''||TO_CHAR(FDate)||''''||' FDate From ArchOst Ar,Account Ac,'
  ||ReferenceFilter||' B Where (Ar.ACC_ID=Ac.ID)And(Ac.'
  ||StatementFilter ||'=B.BAL_CN)And(Ar.DatDate='||''''||TO_DATE(FDate)
