      VarChar2(512);--:=' Where (not FirstRemainder.BalanceBill in (Select  B.Bal_cn from  ArchOst Ar,Account Ac, BAL_SPR1 B Where (Ar.ACC_ID=Ac.ID)And(Ac.BAL_CN1=B.BAL_CN)And(Ar.DatDate=';        
