Procedure OpenCursor(ACursor IN OUT Cursor_Type, AStrParam1 IN VarChar2,AStrParam2 IN VarChar2) 
is begin
  if  ACursor%isOpen  then
  close ACursor;
  end if;  
  Open ACursor For AStrParam1||AStrParam2;  
end;  
END;
