function calc_by_bal (CAP_DAT date,CAP_Type varchar2,Operation_type number)
return number
is
 dum_sum number;
 Cap_Sum number:=0;
begin

 for rec in  (SELECT * FROM capital where type=CAP_Type and op_type=Operation_type and bal_type=1)
 loop

  dum_sum:=0;

   select nvl(sum(Sums),0) into dum_sum from
(
SELECT
       ac.bal_cn1 as BALANCE,
       sum(AR.pok_ostat) AS Sums
FROM
  ACCOUNT ac,
  archost ar
WHERE
   AR.acc_id = AC.id and
   ac.bal_cn1 LIKE  rec.bal||'%' and
   AR.datdate = cap_dat
GROUP BY
  ac.bal_cn1
  );

 if (rec.percent is not null) then
  dum_sum:=dum_sum*rec.percent/100;
 end if;
  Cap_Sum:=Cap_Sum+dum_sum;
 end loop;
return nvl(Cap_Sum,0);
end;


function calc_by_acc (CAP_DAT date,CAP_Type varchar2,Operation_type number)
return number
is
 Cap_Sum number:=0;
begin
select sum(perc_pok_ostat) as acc_cap into Cap_Sum
 from
(SELECT cap.acc, cap.percent,ar.pok_ostat,ar.pok_ostat*nvl((cap.percent/100),1) perc_pok_ostat
FROM capital cap,archost ar
where
cap.acc=ar.acc_id
and ar.datdate=CAP_DAT
and type=CAP_Type and op_type=Operation_type and bal_type=1 and (acc is not null));
return nvl(Cap_Sum,0);
end;

function calc_by_acc_OUT (CAP_DAT date,CAP_Type varchar2,Operation_type number)
return number
is
 Cap_Sum number:=0;
begin
select sum(perc_pok_ostat) as acc_cap into Cap_Sum
 from
(SELECT cap.acc, cap.percent,ar.pok_ostat,ar.pok_ostat*nvl((cap.percent/100),1) perc_pok_ostat
FROM capital cap,CAPITAL_ARCH_OUT ar
where
cap.acc=ar.acc_id
and ar.datdate=CAP_DAT
and type=CAP_Type and op_type=Operation_type and bal_type=2 and (acc is not null));
return nvl(Cap_Sum,0);

exception
 when others then
  begin
   --dbms_output.put_line('Balansdan kenar qoshulmuyub');
   return 0;
   end;

end;

