CREATE OR REPLACE 
PACKAGE sb_expertanalyse
  IS

  CommaDelimiter constant char := ',';
  OrdinaryTransaction constant number := -1;
  MultiCurrencyTransaction constant number := -2;
  
  function CheckTipAcc(bTipacc Operation_balances.tipacc%type,
                aTipacc Account.tipacc%type) return number;
  function FlagExsist(bTipacc Operation_balances.tipacc%type,
                       aTipacc Account.tipacc%type
                       ) return boolean;
  function GetOperationType(OperationType Provarch.vid_op%type,
                           DebetCurrency Provarch.val_acc%type,
                           CreditCurrency Provarch.currencyid_c%type
                           ) return Vid_op.ID%type;
  function GetUserName(userid user$.id%type)
 return varchar2;
END;
/


CREATE OR REPLACE 
PACKAGE BODY             sb_expertanalyse
IS

 function CheckTipAcc(bTipacc Operation_balances.tipacc%type,
                      aTipacc Account.tipacc%type
                      ) return number
 is
 begin
  if bTipacc is null then return 1;
  end if;

  if (bTipacc is not null) and (aTipacc is null) then return 0;
  end if;
  
  if FlagExsist(bTipacc, aTipacc) then 
   return 1;
  else
   return 0;
  end if;   
  
 end;  
 
 function FlagExsist(bTipacc Operation_balances.tipacc%type,
                     aTipacc Account.tipacc%type
                     ) return boolean
 is
  BTip Operation_balances.tipacc%type;
  ATip Account.tipacc%type;  
  LengthBTip number;
  IsExsist Boolean :=true;  
  ch varchar(1);  
 begin
  BTip :=Upper(Replace(bTipacc,CommaDelimiter));
  ATip :=Upper(Replace(aTipacc,CommaDelimiter));
  
  LengthBTip :=Length(BTip);
 
  for POS in 1..LengthBTip
   loop
    ch :=substr(BTip,POS,1);
    IsExsist :=IsExsist and (Instr(ATip,ch)>0); 
    exit when not IsExsist; 
   end loop;
   
   if IsExsist then
    --dbms_output.put_line('IsExsist True');
    Return true;
   else
    --dbms_output.put_line('IsExsist False');
    Return false; 
   end if; 
 end;   

 function CheckCurrency(DebetCurrency Provarch.val_acc%type,
                        CreditCurrency Provarch.currencyid_c%type
                       ) return Vid_op.ID%type
 is
  Result Vid_op.id%type;
 begin
  if DebetCurrency = CreditCurrency then
   Result :=OrdinaryTransaction;
  else
   Result :=MultiCurrencyTransaction;
  end if;
  return Result;  
 end;                      

 
 function GetOperationType(OperationType Provarch.vid_op%type,
                           DebetCurrency Provarch.val_acc%type,
                           CreditCurrency Provarch.currencyid_c%type
                           ) return Vid_op.ID%type
 is
  Result Vid_op.id%type;
  NotFound boolean;
 
  cursor c_VidOp(OperationID Provarch.vid_op%type) is
    select ID from Vid_op where ID = OperationID; 
  ID number;
 begin
  /*1. Operation Type is Exist.Application defined type */
  if OperationType is not null then
   begin
    Open c_VidOp(OperationType);
     Fetch c_VidOp into ID;     
     NotFound :=c_VidOp%NotFound;  
    Close c_VidOp;

    if NotFound then
     Result :=CheckCurrency(DebetCurrency, CreditCurrency);
    else
     Result :=OperationType; 
    end if; 
   end;
  else
   Result :=CheckCurrency(DebetCurrency, CreditCurrency); 
  end if;
  Return Result;
 end;

function GetUserName(userid user$.id%type)
 return varchar2
is
 UserName user$.name%type;
begin
 begin
  select 
    Name 
  into 
    UserName 
  from 
    user$ 
   where 
    id = userid;
 
  Exception When NO_DATA_FOUND Then
   return '<UNKNOWN>';
 end;
 
 return UserName;
 
end;
                     
END;
/


