 is
 begin
  Select
    sum(First_Price) 
    ,sum(TaxPercentPrice)
     ,sum(AllTaxAmort)
      ,sum(TaxAmort)
  Into FirstPrice,BalancePrice,AllTaxAmort,TaxAmort
  From 
   Wares
  Where 
   GroupsID = IDGroups;

 Exception When NO_DATA_FOUND Then
  begin
   FirstPrice :=0;
   BalancePrice :=0;
   AllTaxAmort :=0;
   TaxAmort :=0;
  end; 
  -- dbms_output.put_line('FirstPrice '||TO_CHAR(FirstPrice));
 end; 

 
