 procedure StopCalculate(ObjectID number)
 is
 begin
 -- This function is not properly ended
  if ObjectID =-1 then
   Update Wares
     set
      Close_format =2
     where Balance_price =0;  
   commit;
  else 
   Update Wares
    set
      Close_format =2
     where ID = ObjectID;  
   commit;
  end if;     
 end; 
 
