function enable_delete_groups(v_groups_id number) return
boolean
is
Cursor c is select Count(*) as 
          CountWares from wares_all where groups_id=v_groups_id;
rc c%rowtype; 

b boolean;
begin
b:=true;
       open c;
       fetch c into rc;
       close c;
       
    if rc.CountWares=0 then 
    b:=true;
    else
    b:=false;
    end if;   
return b;
end;

