procedure calculate_wares_for_day(calc_date date)
is

begin

keep_before_calc;
--------------------------------------------------


update wares_all
   set
      close_format = 2 ,
      amort = remainder
   where 
       ( remainder = 0 )  or  ( remainder < amort );

update wares_all
  set 
     remainder = 0,
     all_amort = first_price
  where ( close_format = 2 );
 

 
update wares_all
  set
     tax_close_format = 2,
     tax_amort = tax_remainder
  where ( tax_remainder = 0 ) or ( tax_remainder < tax_amort ); 

update wares_all
  set 
     tax_remainder = 0,
     tax_all_amort = first_price
  where ( tax_close_format = 2 );

  
-------------old wares ------------------------------------------
update wares_all
  set
     amort=( first_price * bankdaysbetween(amort_date,calc_date) * percent )/36000
  where 
       ( close_format = 1 ) and ( amort_date < calc_date );


update wares_all
  set
     tax_amort = ( tax_first_price * bankdaysbetween(amort_date,calc_date) * tax_percent ) / 36000
  where 
       ( tax_close_format = 1 )
  and
       ( amort_date < calc_date );

 
update wares_all
  set
     all_amort = all_amort + amort,
     remainder = remainder - amort
  where 
       ( close_format = 1 )
 and
       ( amort_date < calc_date );   

update wares_all
  set
     tax_all_amort = tax_all_amort + tax_amort,
     tax_remainder = tax_remainder - tax_amort
  where 
      ( tax_close_format = 1 )
  and
      ( amort_date < calc_date );  
 
 
--------new wares-------------------------------------------------

update wares_all
  set
     amort = ( first_price * bankdaysbetween( inventar_date,calc_date )* percent ) / 36000
  where 
       ( close_format = 0 )
  and
       ( inventar_date < calc_date ); 

update wares_all
  set
     tax_amort = ( tax_first_price * bankdaysbetween( inventar_date,calc_date ) * tax_percent ) / 36000
  where 
      ( tax_close_format = 0 )
 and
      ( inventar_date < calc_date ); 
 
 
update wares_all
  set
     all_amort = all_amort + amort,
     remainder = remainder - amort
  where 
       ( close_format = 0 )
 and
       ( inventar_date < calc_date ); 

 
update wares_all
  set
     tax_all_amort = tax_all_amort + tax_amort,
     tax_remainder = tax_remainder - tax_amort
  where 
       ( tax_close_format = 0 )
  and
       ( inventar_date < inventar_date );
 
 
update wares_all
  set
      close_format = 1
  where 
       ( close_format = 0 )
  and
       ( inventar_date < calc_date );


update wares_all
  set
     tax_close_format = 1
  where 
      ( tax_close_format = 0 )
 and
      ( inventar_date < calc_date ); 

---------------------------------------------- 

update wares_all
  set
      amort_date = calc_date; 


keep_after_calc;
commit;

end;


procedure calculate_wares(calc_date date)
is

begin

keep_before_calc;
--------------------------------------------------


update wares_all
   set
      close_format=2,
      amort=remainder
   where
       ( remainder = 0 )  or  ( remainder < amort );

update wares_all
  set
     remainder=0,
     all_amort=first_price
  where ( close_format = 2 );



update wares_all
  set
     tax_close_format = 2,
     tax_amort = tax_remainder
  where ( tax_remainder = 0 ) or ( tax_remainder < tax_amort );

update wares_all
  set
     tax_remainder = 0,
     tax_all_amort = first_price
  where ( tax_close_format = 2 );


-------------old wares ------------------------------------------
update wares_all
  set
     amort=(first_price*30*percent)/36000
  where
       ( close_format = 1 ) and ( amort_date < calc_date );



update wares_all
  set
     tax_amort = ( tax_first_price * 30 * tax_percent ) / 36000
  where
       ( tax_close_format = 1 )
  and
       ( amort_date < calc_date );


update wares_all
  set
     all_amort = all_amort + amort,
     remainder = remainder - amort
  where
       ( close_format = 1 )
 and
       ( amort_date < calc_date );

update wares_all
  set
     tax_all_amort = tax_all_amort + tax_amort,
     tax_remainder = tax_remainder - tax_amort
  where
      ( tax_close_format = 1 )
  and
      ( amort_date < calc_date );


--------new wares-------------------------------------------------

update wares_all
  set
     amort = ( first_price * (bankdaysbetween( inventar_date,calc_date )+1)* percent ) / 36000
  where
       ( close_format = 0 )
  and
       ( inventar_date < calc_date );

update wares_all
  set
     tax_amort = ( tax_first_price * (bankdaysbetween( inventar_date,calc_date )+1) * tax_percent ) / 36000
  where
      ( tax_close_format = 0 )
 and
      ( inventar_date < calc_date );


update wares_all
  set
     all_amort = all_amort + amort,
     remainder = remainder - amort
  where
       ( close_format = 0 )
 and
       ( inventar_date < calc_date );


update wares_all
  set
     tax_all_amort = tax_all_amort + tax_amort,
     tax_remainder = tax_remainder - tax_amort
  where
       ( tax_close_format = 0 )
 and
       ( inventar_date < inventar_date );


update wares_all
  set
      close_format = 1
  where
       ( close_format = 0 )
 and
       ( inventar_date < calc_date );


update wares_all
  set
     tax_close_format = 1
  where
      ( tax_close_format = 0 )
 and
      ( inventar_date < calc_date );

----------------------------------------------

update wares_all
  set
      amort_date = calc_date;


keep_after_calc;
commit;

end;




procedure stop_calculate(status varchar2,v_id number)
is
begin
        if 
           status='nb' 
                   then
          update wares_all
             set 
                first_price=0,
                remainder=0,
                all_amort=0,
                amort=0,
                close_format=2
           where 
                  wares_id=v_id;
          elsif 
                status='nl'
                      then 
          update wares_all
             set 
                tax_close_format=2,
                tax_remainder=0,
                tax_all_amort=0,
                tax_amort=0,
                tax_first_price=0
           where 
                  wares_id=v_id;
             end if;                 

commit;
end;


procedure wares_all_transaction
is

v_group_name  varchar2(90); 
v_groups_id   number; 
v_debt_acc    number; 
v_cred_acc    number; 
v_debt_amount number(18,2);
v_trans_date  date;
begin
delete from wares_all_trans;
          for j in (select * from groups where exp_account is not null and amort_account is not null) 
          loop
              v_group_name:=j.name;
              v_groups_id:=j.id;
              v_debt_acc:=j.exp_account;                
              v_cred_acc:=j.amort_account;
              select sum(amort) into v_debt_amount from wares_all where groups_id=j.id;              
              v_trans_date:=sblogin.get_date;              
              insert into wares_all_trans(group_name, groups_id, debt_acc, cred_acc, debt_amount,trans_date)
              values(v_group_name, v_groups_id, v_debt_acc, v_cred_acc, v_debt_amount,v_trans_date);
              
          end loop;


commit;
end;

