Function  GetDiffRate( 
                       DCurrencyID IN Integer
											,CCurrencyID IN Integer 											                       
											,DDiffRate IN Operkurs.Ostat%type
											,CDiffRate IN Operkurs.Ostat%type
											,CurrentDate IN Date 
											)
  return Operkurs.Ostat%type
	Is
	  Result  Operkurs.Ostat%type;
	Begin
	  
	  if  DCurrencyID=CCurrencyID then 
		  return Null;
		elsif  DCurrencyID<>0 then
			Select Ostat Into   Result From Operkurs 
			  where Dat=CurrentDate and VAL_KOD=DCurrencyID;
			if  Result<>DDiffRate then return DDiffRate;
			 else Return Null;
			end if;
		elsif CCurrencyID<>0 then
			Select Ostat Into   Result From Operkurs 
			  where Dat=CurrentDate and VAL_KOD=CCurrencyID;
			if  Result<>CDiffRate then return CDiffRate; else Return Null;
			end if;   
	  end if;		
	End;  											 		                              
END;
     /* Nezerov Asif
        SMART  SYSTEMS  2002  */
/


