CREATE OR REPLACE 
PACKAGE sb_msg
  IS


  function getusersession (
      dusername   varchar2,
      dprogram    varchar2 default 'smartbank.exe'
   )
      return number;
  procedure sendmessage(msgid number);
  procedure getmessages(usnam varchar default user);
  procedure deletemsgtype(msid number);
  procedure getmessage(msid number,usnam varchar default user);
END;
/


CREATE OR REPLACE 
PACKAGE BODY       sb_msg
is
   function getusersession (
      dusername   varchar2,
      dprogram    varchar2 default 'smartbank.exe'
   )
      return number
   is
      res   number;
   begin
      select sid
        into res
        from v$session
       where upper (username) = upper (dusername)
         and upper (program) = upper (dprogram);

      return res;
   exception
      when no_data_found
      then
         return -1;
   end;
   
   procedure sendmessage(msgid number)
   is
     sesid number;
     usnam varchar(30);
     msgad varchar(255);
   begin
     select usname, MSG
       into usnam, msgad
       from sbmsg_operations
      where id = msgid;
     sesid := getusersession(usnam);
     if sesid>-1 then
       sb_session_mgr.sendmessage(sesid,msgad,'MSGTOUSER_'||sesid);
     else
       insert into sbmsg_messages values(msgid, sysdate, 0, 1);
       commit;
     end if;
   end;
   
   procedure getmessages(usnam varchar default user)
   is
     cursor c_msg is
       select o.id,o.msg
         from sbmsg_operations o, sbmsg_messages m
        where o.id=m.msgid and m.sent=0 and o.usname=usnam;
     sesid number;
   begin
     sesid := getusersession(usnam);
     for z in c_msg loop
       sb_session_mgr.sendmessage(sesid,z.msg,'MSGTOUSER_'||sesid);
       update sbmsg_messages set sent=1 where msgid=z.id;
       commit;
     end loop;
   end;
   
   procedure getmessage(msid number,usnam varchar default user)
   is
     cursor c_msg is
       select o.id,o.msg
         from sbmsg_operations o, sbmsg_messages m
        where o.id=m.msgid and m.sent=0 and o.usname=usnam and m.id=msid;
     sesid number;
   begin
     sesid := getusersession(usnam);
     for z in c_msg loop
       sb_session_mgr.sendmessage(sesid,z.msg,'MSGTOUSER_'||sesid);
       update sbmsg_messages set sent=1 where msgid=z.id;
       commit;
     end loop;
   end;
   
   procedure deletemsgtype(msid number)
   is
   begin
     delete from sbmsg_operations where id=msid;
     commit;
   end;
end;
/


