FUNCTION PASCONVERT
(
  cValue Number
, cTypeID integer
, cAddTypeID integer  
) return Number 
IS  
retVal number;
Begin
     if  cValue=0  then
       return 0;       
   end if;
   if  cValue>0 then
   retVal:=abs(cValue);
   else
   retVal:=0;
   end if; 
   if (cTypeId=1)and(retVal <>0) then
     retVal:=0; 
   end if;
   if (cTypeID=2)and(retVal=0) then
