 end; 
 FUNCTION ACTIVE
  ( aValue IN Number
    ,aTID IN Integer
    ,aAdd IN  Integer
    )
  RETURN  Number IS
  ReturnValue Number;
BEGIN
  if aValue=0 then
   return 0;
  end if;
  
  if  aValue<0 then
    ReturnValue :=abs(aValue);
   else
    ReturnValue :=0;
  end if;
  
  if ReturnValue<>0 then
  if  (aTID<>aAdd) then   
   if  aAdd=2 then
       ReturnValue :=0;
   end if;
   end if;
   else
   if  (aAdd=1)and(aADD<>aTID) then
   ReturnValue :=-abs(aValue);
   end if;   
  end if;
  return ReturnValue;
END;

 FUNCTION PASSIV
  ( aValue IN Number
    ,aTID IN Integer
    ,aAdd IN  Integer
    )
  RETURN  Number IS
  ReturnValue Number;
BEGIN
  if aValue=0 then
   return 0;
  end if;
  
  if  aValue>0 then
    ReturnValue :=abs(aValue);
   else
    ReturnValue :=0;
  end if;
  
  if ReturnValue<>0 then
  if  (aTID<>aAdd) then   
   if  aAdd=1 then
       ReturnValue :=0;
   end if;
   end if;
   else
   if  (aAdd=2)and(aADD<>aTID) then
   ReturnValue :=-abs(aValue);
   end if;   
  end if;
  Return ReturnValue;
END;
                   
BEGIN
 select user, trunc(tek_dat) into UserName, BankDay from sysdat;                           
END;
