CREATE OR REPLACE 
PACKAGE sb_sd
IS
   PROCEDURE addtempar (bdat IN DATE, edat IN DATE);

   PROCEDURE addtempprovar (bdat IN DATE, edat IN DATE);

   FUNCTION get_accno (id_prov IN NUMBER)
      RETURN VARCHAR2;

   FUNCTION get_rez (acc_id IN NUMBER)
      RETURN NUMBER;

   FUNCTION get_filial (fil_id IN NUMBER)
      RETURN NUMBER;

   FUNCTION get_tip (tip_id IN NUMBER)
      RETURN VARCHAR2;

   FUNCTION get_balans (bal_id IN NUMBER)
      RETURN NUMBER;
END;
/


CREATE OR REPLACE 
PACKAGE BODY       sb_sd
IS
   PROCEDURE addtempar (bdat IN DATE, edat IN DATE)
   IS
   BEGIN
      INSERT INTO temparchost
         SELECT   ac.acc_no, ac.bal_cn1, ac.val_acc, ac.tipacc, ar.ostat,
                  ar.pok_ostat, ar.datdate, ar.obr_k, ar.obr_d, ar.pok_obr_d,
                  ar.pok_obr_k, ac.filial
             FROM ACCOUNT ac, archost ar
            WHERE ac.ID = ar.acc_id
              AND ar.datdate BETWEEN (SELECT MAX (datdate)
                                        FROM archost
                                       WHERE datdate < bdat)
                                 AND (SELECT MAX (datdate)
                                        FROM archost
                                       WHERE datdate <= edat)
         ORDER BY datdate;
   END;

   PROCEDURE addtempprovar (bdat IN DATE, edat IN DATE)
   IS
   BEGIN
      INSERT INTO tempprovar
         SELECT   pr.ID, pr.dat, get_accno (pr.debt), get_accno (pr.kredit),
                  pr.val_acc, pr.currencyid_c, pr.ammount, pr.lammount,
                  pr.ammount_c, get_balans (pr.debt), get_balans (pr.kredit),
                  get_rez (pr.debt), get_rez (pr.kredit),
                  get_filial (pr.debt), get_filial (pr.kredit),
                  get_tip (pr.debt), get_tip (pr.kredit)
             FROM provarch pr, ACCOUNT ac, customers cu
            WHERE pr.dat BETWEEN (SELECT max(dat)
                                    FROM provarch
                                   WHERE dat <= bdat) AND (SELECT min (dat)
                                                             FROM provarch
                                                            WHERE dat <= edat)
            and pr.debt=ac.id
            or  pr.kredit=ac.id
         ORDER BY dat;
   END;


   

   FUNCTION get_rez (acc_id IN NUMBER)
      RETURN NUMBER
   IS
      rezident   NUMBER;
   BEGIN
      SELECT nerezident
        INTO rezident
        FROM customers
       WHERE ID = (SELECT kli_id
                     FROM ACCOUNT
                    WHERE ID = acc_id);

      RETURN rezident;
   END;
   
   FUNCTION get_accno (id_prov IN NUMBER)
      RETURN VARCHAR2
   IS
      accno   VARCHAR2 (50);
   BEGIN
      SELECT acc_no
        INTO accno
        FROM ACCOUNT
       WHERE ACCOUNT.ID = id_prov;

      RETURN accno;
   END;

   FUNCTION get_filial (fil_id IN NUMBER)
      RETURN NUMBER
   IS
      myfilial   NUMBER;
   BEGIN
      SELECT filial
        INTO myfilial
        FROM ACCOUNT
       WHERE ID = fil_id;

      RETURN myfilial;
   END;

   FUNCTION get_tip (tip_id IN NUMBER)
      RETURN VARCHAR2
   IS
      mytip   VARCHAR2 (20);
   BEGIN
      SELECT tipacc
        INTO mytip
        FROM ACCOUNT
       WHERE ID = tip_id;

      RETURN mytip;
   END;

   FUNCTION get_balans (bal_id IN NUMBER)
      RETURN NUMBER
   IS
      mybalans   NUMBER;
   BEGIN
      SELECT bal_cn1
        INTO mybalans
        FROM ACCOUNT
       WHERE ID = bal_id;

      RETURN mybalans;
   END;
END;
/


