CREATE OR REPLACE 
PACKAGE sb_session_mgr
  IS
	
	AllUsersMask constant varchar2(2) := '%';
	
	MsgName_MsgToUser constant varchar2(30) := 'MSGTOUSER_';
	MsgName_ShutdownUserSession constant varchar2(30) := 'SHUTDOWN_';
	MsgName_MessageBroadcast constant varchar2(30) := 'MESSAGEBROADCAST';
	MsgName_Shutdown constant varchar2(30) := 'SHUTDOWN';
	
  PROCEDURE KillAll(
		UserMask VARCHAR2 default AllUsersMask,
		Message VARCHAR2 default null,	-- no message by default
		Timeout INTEGER default 0  -- no timeout before killing by default
		);
  procedure SendMessage(
		SessionID IN VARCHAR2, 
		Message IN VARCHAR2, 
		MessageName in varchar2 default null);
  PROCEDURE KillSession (
		session_id IN VARCHAR2,
		serial_num IN VARCHAR2,
		Message IN VARCHAR2 default null,
		UserTimeout IN INTEGER default 0,
		SleepTimeout IN INTEGER default null);
END; -- Package spec
/


CREATE OR REPLACE 
PACKAGE BODY       sb_session_mgr
IS

	function UserBySessionSID(session_id IN VARCHAR2)
		return VARCHAR2
	is
		cursor c_UserBySessionSID(SessionSID IN INTEGER)
		is
			select USERNAME
			from sys.v_$session
			where AudSID = SessionSID;
		Result varchar2(32); 
	begin
		open c_UserBySessionSID(Session_ID);
		fetch c_UserBySessionSID into Result;
		if c_UserBySessionSID%notfound then
			Result := null;
		end if; 
		close c_UserBySessionSID;
		if Result is null then
			raise_application_error(sbdecls.Error_SessionNotFound, 'Session not found');
		end if;
		return Result;
	end;

	function BuildUserMessageName(
		MessageName in varchar2, 
		SessionID in varchar2)
	return varchar2
	is
	begin
		return MessageName||SessionID;
	end;
	
  PROCEDURE KillSession (
		session_id IN VARCHAR2,
		serial_num IN VARCHAR2,
		Message IN VARCHAR2 default null,
		UserTimeout IN INTEGER default 0,
		SleepTimeout IN INTEGER default null)
  AS
     cur INTEGER;
     ret INTEGER;
     string VARCHAR2(100);
		 ASleepTimeout INTEGER;
		 SessionFound boolean;
		 
		cursor c_Session(SessionID INTEGER)
		is
			select * from sys.v_$session
			where SID = SessionID;
		r_session c_Session%rowtype;
		 
  BEGIN
	
		if ASleepTimeout is null then
			ASleepTimeout := UserTimeout;
		end if;
		
		if Message is not null then
			SendMessage(
				session_id, 
'timeout='||TO_CHAR(UserTimeout)||'
'||
'message='||Message||'', 
				BuildUserMessageName(MsgName_ShutdownUserSession,session_id));
		end if;
		
		dbms_lock.sleep(ASleepTimeout);
		
		open c_Session(session_id);
		fetch c_Session into r_session;
		SessionFound := c_Session%Found;
		close c_Session;
		
		if not (SessionFound and r_session.Status <> 'KILLED') then
			--dbms_output.put_line('WARNING: KillSesion: Session does not exist or already exited');
			return;
		end if;
		
		--dbms_output.put_line('Killing session: ID='||session_id||', serial: '||serial_num);
    string := 'ALTER SYSTEM KILL SESSION' ||
             CHR (10) ||
             CHR (39) ||
             session_id ||
             ',' ||
             serial_num ||
             CHR (39);
-- string :=
--          'ALTER SYSTEM DISCONNECT SESSION' || CHR(10) ||
-- CHR(39)||session_id||','||serial_num||CHR(39)||CHR(10)||
--' POST_TRANSACTION';
    --dbms_output.put_line(string);
    cur := DBMS_SQL.open_cursor;
    DBMS_SQL.parse (cur, string, DBMS_SQL.v7);
    ret := DBMS_SQL.execute (cur);
    DBMS_SQL.close_cursor (cur);

  EXCEPTION
     WHEN OTHERS
     THEN
        raise_application_error (-20001, 'Error in execution', TRUE);
        IF DBMS_SQL.is_open (cur)
        THEN
           DBMS_SQL.close_cursor (cur);
        END IF;
  END;
	
	PROCEDURE KillAll(
		UserMask VARCHAR2 default AllUsersMask,
		Message VARCHAR2 default null,	-- no message by default
		Timeout INTEGER default 0  -- no timeout before killing by default
		)
	IS
	
		CURSOR c_SessionsToKill(UserMask varchar2)
		IS
  		SELECT sid, serial#, UserEnv('SESSIONID') as AudSID1
  		FROM   v$session
  		WHERE  
  			(username IS NOT NULL)
  	    and (UserName <> 'SYS')
				and (AudSID <> UserEnv('SESSIONID'))
				and (UserName like UPPER(UserMask));
				
		KillsCount integer := 0;
			
	BEGIN
		--dbms_output.put_line('KillAll entry');
	    --dbms_output.put_line('User Mask =  '||UserMask);
		-- Notify users about shutdown
		--dbms_output.put_line('Notifying users about scheduled shutdown');
		FOR r_session IN c_SessionsToKill(UserMask)
		LOOP
			SendMessage(
				r_session.sid, 
				'timeout='
					||TO_CHAR(Timeout), 
				BuildUserMessageName(
					MsgName_ShutdownUserSession, 
					r_session.sid
				)
			);
		END LOOP;		

		-- sleep before killing (if requested)
		--dbms_output.put_line('Waiting for users to disconnect.');
		dbms_lock.sleep(Timeout);
		
		-- initiate shutdown
		--dbms_output.put_line('Initiating shutdown.');
		FOR r_session IN c_SessionsToKill(UserMask)
		LOOP
			KillSession(
				session_id 		=> r_session.sid, 
				serial_num 		=> r_session.serial#, 
				Message		 		=> Message, 
				UserTimeout 	=> Timeout,
				SleepTimeout 	=> 0);
			KillsCount := KillsCount + 1;
		END LOOP;
		--dbms_output.put_line('Shutdown complete.');		
		--dbms_output.put_line(TO_CHAR(KillsCount)||' sessions killed.');
	END;
	
	procedure SendMessage(
		SessionID IN VARCHAR2, 
		Message IN VARCHAR2, 
		MessageName in varchar2 default null)
	is
		AMessageName varchar2(30) := MessageName;
	begin
		if AMessageName is null then
			AMessageName := BuildUserMessagename(MsgName_MsgToUser, SessionID);
		end if; 
		--dbms_output.put_line('Sending message to user: SessionID='||SessionID||', SignalName='||AMessageName);
/*		execute immediate 
'
begin
	dbms_alert.signal('''||AMessageName||SessionID||''', '''||Message||''');	
	commit;		
end;
';*/

		dbms_alert.signal(AMessageName, Message);	
		commit;
				
	end;
	
END;
/


