  function GetAccNo(Acc_id number) return varchar2;
  function GetAccountID(AccountNumber varchar) return number;
  Function get_date return sysdat.tek_dat%type;
  Function CheckCurrency 
(
   d_or_k       number
,  currencyid_d number 
,  currencyid_c number
,  ammount      number
,  ammount_c    number
