CREATE OR REPLACE 
PACKAGE sb_transaction_clib
  IS

	cursor c_RateByDate(CurrencyID integer, TargetDate date)
	is
		select OSTAT as Result
			from OPERKURS
		where
			(DAT = TargetDate)
			and (VAL_KOD = CurrencyID)
	;
	
	cursor c_RateByAcc(AccID integer, TargetDate date)
	is
		select OSTAT as Result
			from OPERKURS
		where
			(DAT = TargetDate)
			and (VAL_KOD = (
				select VAL_ACC 
					from account
				where
					ID = AccID
				)
			)
	;
	
	cursor c_CountDelayedRest(TargetDate date)
	is
		select count(*) from LAZYREST
		where DATDATE = TargetDate
	;
		
END;
