   PROCEDURE Getextraction 
    ( BegDate IN date,
      EndDate IN date) 
    IS
   UserTab Varchar2(96);
   StrSql varchar2(1000);
   BEGIN 
    select user into UserName from sysdat;
    UserTab:= 'Trans_'||UserName;
    strsql:=
        ' create table ' || UserTab || ' as
          select p.*, acd.acc_no Debit, acc.acc_no Credit, avd.val_name CurrencyDeb, avc.val_name CurrencyCred
          from provarch p, account acd, account acc, avalute avd, avalute avc
          where (DAT between '''|| To_Char(BegDate)|| ''' and ''' || To_Char(EndDate)||''') and (p.debt=acd.id) and (p.kredit=acc.id) and (p.val_acc=avd.valute) and (p.currencyid_c=avc.valute)
          order by dat'
    ;
    to_table(UserTab,StrSql);
    commit;
   END;
   
PROCEDURE TO_TABLE
(
  UserTab IN varchar2
, StrSql  IN varchar2
)
is
 nRow integer;
 v_Cursor integer;
BEGIN
select count(*) into nRow from tab where TNAME=UserTab;
--update a1 set c5=strsql;
--commit;
nRow:= 1;
if nRow<>0 then
-- EXECUTE IMMEDIATE 'drop table ' || UserTab;
