CREATE OR REPLACE 
PACKAGE BODY       sbcm_construction
IS
   /*  Constants */
   firstpaytransactionoptype   CONSTANT INTEGER := 84;
   paytransactionoptype        CONSTANT INTEGER := 85;

   FUNCTION constuction_contracts_add (
      p_contractno             IN   VARCHAR2,
      p_opendate               IN   DATE,
      p_closedate              IN   DATE,
      p_creditamount           IN   NUMBER,
      p_initialamount          IN   NUMBER,
      p_amountflatkv           IN   NUMBER,
      p_buildingno             IN   VARCHAR2,
      p_blokno                 IN   VARCHAR2,
      p_flatno                 IN   VARCHAR2,
      p_roomcount              IN   NUMBER,
      p_clientid               IN   NUMBER,
      p_currency               IN   NUMBER,
      p_interestrate           IN   NUMBER DEFAULT 0,
      p_penalityinterestrate   IN   NUMBER,
      p_clienttype             IN   INTEGER,
      p_personaltype           IN   INTEGER,
      p_branchid               IN   INTEGER,
      p_flatid                 IN   INTEGER
   )
      RETURN INTEGER
   IS
      RESULT   INTEGER;
   BEGIN
      INSERT INTO constuction_contracts_active
                  (contractno, opendate, closedate, creditamount,
                   initialamount, amountflatkv, buildingno, blokno,
                   flatno, flatid, roomcount, clientid, currency,
                   interestrate, penalityinterestrate, clienttype,
                   personaltype, usid, branchid, type#
                  )
           VALUES (p_contractno, p_opendate, p_closedate, p_creditamount,
                   p_initialamount, p_amountflatkv, p_buildingno, p_blokno,
                   p_flatno, p_flatid, p_roomcount, p_clientid, p_currency,
                   p_interestrate, p_penalityinterestrate, p_clienttype,
                   p_personaltype, UID, p_branchid, 0
                  )
        RETURNING ID
             INTO RESULT;

      RETURN RESULT;
   END;

   FUNCTION constuction_contracts_edit (
      p_creditid               IN   INTEGER,
      p_contractno             IN   VARCHAR2,
      p_opendate               IN   DATE,
      p_closedate              IN   DATE,
      p_creditamount           IN   NUMBER,
      p_initialamount          IN   NUMBER,
      p_amountflatkv           IN   NUMBER,
      p_buildingno             IN   VARCHAR2,
      p_blokno                 IN   VARCHAR2,
      p_flatno                 IN   VARCHAR2,
      p_roomcount              IN   NUMBER,
      p_clientid               IN   NUMBER,
      p_currency               IN   NUMBER,
      p_interestrate           IN   NUMBER,
      p_penalityinterestrate   IN   NUMBER,
      p_clienttype             IN   INTEGER,
      p_personaltype           IN   INTEGER,
      p_branchid               IN   INTEGER,
      p_flatid                 IN   INTEGER
   )
      RETURN INTEGER
   IS
   BEGIN
      UPDATE constuction_contracts_active
         SET contractno = p_contractno,
             opendate = p_opendate,
             closedate = p_closedate,
             creditamount = p_creditamount,
             amountflatkv = p_amountflatkv,
             buildingno = p_buildingno,
             blokno = p_blokno,
             flatno = p_flatno,
             flatid = p_flatid,
             roomcount = p_roomcount,
             clientid = p_clientid,
             currency = p_currency,
             interestrate = p_interestrate,
             penalityinterestrate = p_penalityinterestrate,
             clienttype = p_clienttype,
             personaltype = p_personaltype,
             branchid = p_branchid
       WHERE ID = p_creditid;

      RETURN p_creditid;
   END;

   PROCEDURE construction_accounts_add (
      p_creditid        IN   INTEGER,
      p_loanaccid       IN   INTEGER,
      p_interestaccid   IN   INTEGER,
      p_clientaccid     IN   INTEGER
   )
   IS
   BEGIN
      INSERT INTO sbcm_construction_accounts
                  (id#, loanaccid, interestaccid, clientaccid
                  )
           VALUES (p_creditid, p_loanaccid, p_interestaccid, p_clientaccid
                  );
   END;

   PROCEDURE construction_accounts_edit (
      p_creditid        IN   INTEGER,
      p_loanaccid       IN   INTEGER,
      p_interestaccid   IN   INTEGER,
      p_clientaccid     IN   INTEGER
   )
   IS
   BEGIN
      UPDATE sbcm_construction_accounts
         SET loanaccid = p_loanaccid,
             interestaccid = p_interestaccid,
             clientaccid = p_clientaccid
       WHERE id# = p_creditid;
   END;

   PROCEDURE construction_state_add (
      p_creditid     IN   INTEGER,
      p_pledgid      IN   INTEGER,
      p_pledgprice   IN   NUMBER
   )
   IS
      currdat   DATE;
   BEGIN
      SELECT tek_dat
        INTO currdat
        FROM sysdat;

      INSERT INTO constuction_curr_state
                  (id#, hdate, rest, interestrest, duerest, dueinterestrest,
                   pledgid, pledgprice, stopcalcdate
                  )
           VALUES (p_creditid, currdat, 0, 0, 0, 0,
                   p_pledgid, p_pledgprice, NULL
                  );
   END;

   PROCEDURE construction_state_edit (
      p_creditid     IN   INTEGER,
      p_pledgid      IN   INTEGER,
      p_pledgprice   IN   NUMBER
   )
   IS
   BEGIN
      UPDATE constuction_curr_state
         SET pledgid = p_pledgid,
             pledgprice = p_pledgprice
       WHERE id# = p_creditid;
   END;

   FUNCTION contract_add (
      contractno             IN   VARCHAR2,
      opendate               IN   DATE,
      closedate              IN   DATE,
      creditamount           IN   NUMBER,
      initialamount          IN   NUMBER,
      amountflatkv           IN   NUMBER,
      buildingno             IN   VARCHAR2,
      blokno                 IN   VARCHAR2,
      flatno                 IN   VARCHAR2,
      roomcount              IN   NUMBER,
      clientid               IN   NUMBER,
      currency               IN   NUMBER,
      interestrate           IN   NUMBER,
      penalityinterestrate   IN   NUMBER,
      clienttype             IN   INTEGER,
      personaltype           IN   INTEGER,
      branchid               IN   INTEGER,
      loanaccid              IN   INTEGER,
      interestaccid          IN   INTEGER DEFAULT NULL,
      clientaccid            IN   INTEGER DEFAULT NULL,
      pledgid                IN   INTEGER,
      pledgprice             IN   NUMBER,
      flatid                 IN   INTEGER
   )
      RETURN INTEGER
   IS
      RESULT    INTEGER;
      currdat   DATE;
   BEGIN
      SELECT tek_dat
        INTO currdat
        FROM sysdat;

      RESULT :=
         constuction_contracts_add (p_contractno                => contractno,
                                    p_opendate                  => opendate,
                                    p_closedate                 => closedate,
                                    p_creditamount              => creditamount,
                                    p_initialamount             => initialamount,
                                    p_amountflatkv              => amountflatkv,
                                    p_buildingno                => buildingno,
                                    p_blokno                    => blokno,
                                    p_flatno                    => flatno,
                                    p_roomcount                 => roomcount,
                                    p_clientid                  => clientid,
                                    p_currency                  => currency,
                                    p_interestrate              => interestrate,
                                    p_penalityinterestrate      => penalityinterestrate,
                                    p_clienttype                => clienttype,
                                    p_personaltype              => personaltype,
                                    p_branchid                  => branchid,
                                    p_flatid                    => flatid
                                   );
      construction_accounts_add (p_creditid           => RESULT,
                                 p_loanaccid          => loanaccid,
                                 p_interestaccid      => interestaccid,
                                 p_clientaccid        => clientaccid
                                );
      construction_state_add (p_creditid        => RESULT,
                              p_pledgid         => pledgid,
                              p_pledgprice      => pledgprice
                             );
      RETURN RESULT;
      COMMIT WORK;
   /*EXCEPTION
      WHEN OTHERS
      THEN
         ROLLBACK WORK;*/
   END;

   FUNCTION contract_edit (
      creditid               IN   INTEGER,
      contractno             IN   VARCHAR2,
      opendate               IN   DATE,
      closedate              IN   DATE,
      creditamount           IN   NUMBER,
      initialamount          IN   NUMBER,
      amountflatkv           IN   NUMBER,
      buildingno             IN   VARCHAR2,
      blokno                 IN   VARCHAR2,
      flatno                 IN   VARCHAR2,
      roomcount              IN   NUMBER,
      clientid               IN   NUMBER,
      currency               IN   NUMBER,
      interestrate           IN   NUMBER,
      penalityinterestrate   IN   NUMBER,
      clienttype             IN   INTEGER,
      personaltype           IN   INTEGER,
      branchid               IN   INTEGER,
      loanaccid              IN   INTEGER,
      interestaccid          IN   INTEGER,
      clientaccid            IN   INTEGER,
      pledgid                IN   INTEGER,
      pledgprice             IN   NUMBER,
      flatid                 IN   INTEGER
   )
      RETURN INTEGER
   IS
      RESULT   INTEGER;
   BEGIN
      RESULT :=
         constuction_contracts_edit (p_creditid                  => creditid,
                                     p_contractno                => contractno,
                                     p_opendate                  => opendate,
                                     p_closedate                 => closedate,
                                     p_creditamount              => creditamount,
                                     p_initialamount             => initialamount,
                                     p_amountflatkv              => amountflatkv,
                                     p_buildingno                => buildingno,
                                     p_blokno                    => blokno,
                                     p_flatno                    => flatno,
                                     p_roomcount                 => roomcount,
                                     p_clientid                  => clientid,
                                     p_currency                  => currency,
                                     p_interestrate              => interestrate,
                                     p_penalityinterestrate      => penalityinterestrate,
                                     p_clienttype                => clienttype,
                                     p_personaltype              => personaltype,
                                     p_branchid                  => branchid,
                                     p_flatid                    => flatid
                                    );
      construction_accounts_edit (p_creditid           => creditid,
                                  p_loanaccid          => loanaccid,
                                  p_interestaccid      => interestaccid,
                                  p_clientaccid        => clientaccid
                                 );
      construction_state_edit (p_creditid        => creditid,
                               p_pledgid         => pledgid,
                               p_pledgprice      => pledgprice
                              );
      COMMIT WORK;
      RETURN RESULT;
   /*EXCEPTION
      WHEN OTHERS
      THEN
         ROLLBACK WORK;*/
   END;

   PROCEDURE contract_close (p_creditid IN INTEGER,p_desc in varchar2)
   IS
   ContRest number;
   CommitType number;
   BEGIN
     
     select rest into ContRest
     from constuction_curr_state
     where id#= p_creditid;
     
     select COMMITCONTRACT into CommitType
     from sbcm_construction_contracts
     where id = p_creditid;
     
     if ContRest>0 then 
        Raise_application_error(-20007,'Qaliqi olan muqavileni baqlamaq olmaz !');
     end if;
      UPDATE sbcm_construction_contracts
         SET type# = 1,
             closedescription = p_desc,
             Flatid = null 
       WHERE ID = p_creditid;

      UPDATE cc_flats
         SET buyer = null
       WHERE ID = (select flatid from sbcm_construction_contracts where id=p_creditid);

      if CommitType = 0 then
         delete sbcm_construction_contracts
         where id = p_creditid;
      end if;
      
      COMMIT;
   END;

   FUNCTION get_contractaccount (p_contractaccid IN INTEGER)
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (25);
   BEGIN
      SELECT acc_no
        INTO RESULT
        FROM ACCOUNT
       WHERE ID = p_contractaccid;

      RETURN RESULT;
   END;

   FUNCTION get_contractpayments (p_creditid IN INTEGER)
      RETURN NUMBER
   IS
      CURSOR c_pay
      IS
         SELECT SUM (payamt)
           FROM sbcm_construction_payments
          WHERE id# = p_creditid;

      RESULT   NUMBER;
   BEGIN
      OPEN c_pay;
      FETCH c_pay INTO RESULT;
      CLOSE c_pay;
      RETURN NVL (RESULT, 0);
   END;

   FUNCTION get_credit_customers (p_id IN INTEGER)
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (80);
   BEGIN
      SELECT byr_name
        INTO RESULT
        FROM cc_buyers
       WHERE ID = p_id;

      RETURN RESULT;
   END;

   FUNCTION transactionexist (p_trid IN INTEGER)
      RETURN BOOLEAN
   IS
      CURSOR c_transactions (trid IN INTEGER)
      IS
         SELECT ID
           FROM provarch
          WHERE ID = trid;

      CURSOR c_lazytransactions (trid IN INTEGER)
      IS
         SELECT ID
           FROM lazytransaction
          WHERE ID = trid;

      temprec   c_transactions%ROWTYPE;
      oprec     c_lazytransactions%ROWTYPE;
      RESULT    BOOLEAN;
   BEGIN
      OPEN c_lazytransactions (p_trid);
      FETCH c_lazytransactions INTO oprec;
      OPEN c_transactions (p_trid);
      FETCH c_transactions INTO temprec;
      RESULT := (c_transactions%FOUND) OR (c_lazytransactions%FOUND);
      CLOSE c_transactions;
      CLOSE c_lazytransactions;
      RETURN RESULT;
   END;

   FUNCTION addtransaction (
      p_trid              IN   INTEGER DEFAULT NULL,
      p_debitid           IN   INTEGER,
      p_creditid          IN   INTEGER,
      p_debitamount       IN   NUMBER,
      p_creditamount      IN   NUMBER,
      p_lamount           IN   NUMBER,
      p_trname            IN   VARCHAR2,
      p_flags             IN   INTEGER,
      p_transactiondate   IN   DATE,
      p_operationtype     IN   INTEGER,
      p_inbalancechar     IN   INTEGER
   )
      RETURN INTEGER
   IS
      RESULT   INTEGER;
   BEGIN
      RESULT :=
         sb_transaction.transaction_add (transactionid        => p_trid,
                                         debitid              => p_debitid,
                                         creditid             => p_creditid,
                                         debitamount          => p_debitamount,
                                         creditamount         => p_creditamount,
                                         lamount              => p_lamount,
                                         debitrate            => 0,
                                         creditrate           => 0,
                                         trname               => p_trname,
                                         flags                => p_flags,
                                         transactiondate      => p_transactiondate,
                                         inbalancechar        => p_inbalancechar,
                                         operationtype        => p_operationtype
                                        );
      RETURN RESULT;
   END;

   FUNCTION deletetransaction (p_trid IN INTEGER)
      RETURN INTEGER
   IS
   BEGIN
      sb_transaction.transaction_delete (p_trid);
      RETURN p_trid;
   END;

   FUNCTION tempadd_transaction (
      p_trid            IN   INTEGER DEFAULT NULL,
      p_debitaccid      IN   INTEGER,
      p_creditaccid     IN   INTEGER,
      p_debitamount     IN   NUMBER,
      p_creditamount    IN   NUMBER,
      p_natamount       IN   NUMBER DEFAULT NULL,
      p_flags           IN   INTEGER, -- No SBTransacion Flags  !!!!!
      p_optype          IN   INTEGER DEFAULT NULL,
      p_inbalancechar   IN   INTEGER,
      p_trdate          IN   DATE,
      p_trdescription   IN   VARCHAR2
   )
      RETURN INTEGER
   IS
      RESULT   INTEGER;
      temp     INTEGER;
   BEGIN
      IF p_trid IS NULL
      THEN
         SELECT tr_seg_provarch.NEXTVAL
           INTO temp
           FROM DUAL;
      ELSE
         temp := p_trid;
      END IF;

      INSERT INTO sbcm_transactions
                  (trid, debitaccid, creditaccid, debitamount,
                   creditamount, natamount, flags, optype,
                   inbalancechar, trdate, trdescription
                  )
           VALUES (temp, p_debitaccid, p_creditaccid, p_debitamount,
                   p_creditamount, p_natamount, p_flags, p_optype,
                   p_inbalancechar, p_trdate, p_trdescription
                  )
        RETURNING trid
             INTO RESULT;

      RETURN RESULT;
   END;

   PROCEDURE commitdelayedtransactions (docommit IN BOOLEAN DEFAULT TRUE)
   IS
      CURSOR c_delayedtransactions
      IS
         SELECT trid, debitaccid, creditaccid, debitamount, creditamount,
                natamount, flags, optype, inbalancechar, trdate,
                trdescription
           FROM sbcm_transactions;

      TRANSACTION   c_delayedtransactions%ROWTYPE;
      RESULT        INTEGER;
   BEGIN
      IF docommit
      THEN
         FOR TRANSACTION IN c_delayedtransactions
         LOOP
            RESULT :=
               addtransaction (p_trid                 => TRANSACTION.trid,
                               p_debitid              => TRANSACTION.debitaccid,
                               p_creditid             => TRANSACTION.creditaccid,
                               p_debitamount          => TRANSACTION.debitamount,
                               p_creditamount         => TRANSACTION.creditamount,
                               p_lamount              => TRANSACTION.natamount,
                               p_trname               => TRANSACTION.trdescription,
                               p_flags                => 0 /*SBDECLS.atfCommitImmediate*/,
                               p_transactiondate      => TRANSACTION.trdate,
                               p_operationtype        => TRANSACTION.optype,
                               p_inbalancechar        => TRANSACTION.inbalancechar
                              );
         END LOOP;

         COMMIT WORK;
      ELSE
         ROLLBACK WORK;
      END IF;
   END;

   PROCEDURE paymenttracttransactions (
      p_contractid   IN   INTEGER,
      p_dat          IN   DATE,
      p_flatamt      IN   NUMBER,
      p_showtr       IN   BOOLEAN DEFAULT TRUE,
      p_debitaccid   IN   INTEGER
   )
   IS
      debitaccid            INTEGER       := p_debitaccid;
      creditaccid           INTEGER;
      tramt                 NUMBER;
      firsttransactionid    INTEGER;
      secondtransactionid   INTEGER;
      p_contractno          VARCHAR2 (81);
      checkpayments         BOOLEAN;
      countpayments         INTEGER;
      opmode                INTEGER;
      checkpayamt           INTEGER;
   BEGIN
      /*------------------------First Transactions--------------------------------------*/
      checkpayments := FALSE;

      SELECT COUNT (*)
        INTO countpayments
        FROM sbcm_construction_payments
       WHERE id# = p_contractid;

      IF countpayments = 0
      THEN
         checkpayments := TRUE;
      END IF;

      IF checkpayments
      THEN
         opmode := firstpaytransactionoptype;
         checkpayamt := 1;
      ELSE
         opmode := paytransactionoptype;
         checkpayamt := 0;
      END IF;

      SELECT loanaccid
        INTO creditaccid
        FROM sbcm_construction_accounts
       WHERE id# = p_contractid;

      SELECT contractno
        INTO p_contractno
        FROM sbcm_construction_contracts
       WHERE ID = p_contractid;

      IF NOT p_showtr
      THEN
         firsttransactionid :=
            addtransaction (p_trid                 => NULL,
                            p_debitid              => debitaccid,
                            p_creditid             => creditaccid,
                            p_debitamount          => p_flatamt,
                            p_creditamount         => p_flatamt,
                            p_lamount              => NULL,
                            p_trname               =>    'К?едитин ?дянилмяси-'
                                                      || p_contractno,
                            p_flags                => 0,
                            p_transactiondate      => p_dat,
                            p_operationtype        => opmode,
                            p_inbalancechar        => NULL
                           );
      ELSE
         firsttransactionid :=
            tempadd_transaction (p_trid               => NULL,
                                 p_debitaccid         => debitaccid,
                                 p_creditaccid        => creditaccid,
                                 p_debitamount        => p_flatamt,
                                 p_creditamount       => p_flatamt,
                                 p_natamount          => NULL,
                                 p_flags              => 0, -- No SBTransacion Flags  !!!!!
                                 p_optype             => opmode,
                                 p_inbalancechar      => NULL,
                                 p_trdate             => p_dat,
                                 p_trdescription      =>    'К?едитин ?дянилмяси--'
                                                         || p_contractno
                                );

         INSERT INTO sbcm_construction_payments
                     (paydate, id#, payamt, trid,
                      firtspay
                     )
              VALUES (p_dat, p_contractid, p_flatamt, firsttransactionid,
                      checkpayamt
                     );

         UPDATE sbcm_construction_accounts
            SET clientaccid = debitaccid
          WHERE id# = p_contractid;
      END IF;
   /*---------------------------End Firt Transactions-------------------------------*/
   END;

   PROCEDURE commitcontracts (p_contractid IN INTEGER)
   IS
      contid   INTEGER := p_contractid;
   BEGIN
      UPDATE sbcm_construction_contracts
         SET commitcontract = 1
       WHERE ID = contid;

      UPDATE cc_flats
         SET buyer = (SELECT clientid
                        FROM sbcm_construction_contracts
                       WHERE ID = contid)
       WHERE ID = (SELECT flatid
                     FROM sbcm_construction_contracts
                    WHERE ID = contid);
   END;

   PROCEDURE rollbackcontracts (p_contractid IN INTEGER)
   IS
      contid   INTEGER := p_contractid;
   BEGIN
      UPDATE sbcm_construction_contracts
         SET commitcontract = 0
       WHERE ID = contid;

      UPDATE cc_flats
         SET buyer = NULL
       WHERE ID = (SELECT flatid
                     FROM sbcm_construction_contracts
                    WHERE ID = contid);
   END;

   FUNCTION get_companyid (p_flatid IN INTEGER)
      RETURN INTEGER
   IS
      RESULT   INTEGER;
   BEGIN
      SELECT comp_id
        INTO RESULT
        FROM cc_buildings
       WHERE ID = (SELECT bld_id
                     FROM cc_flats
                    WHERE ID = p_flatid);

      RETURN RESULT;
   END;

   FUNCTION get_buildingid (p_flatid IN INTEGER)
      RETURN INTEGER
   IS
      RESULT   INTEGER;
   BEGIN
      SELECT bld_id
        INTO RESULT
        FROM cc_flats
       WHERE ID = p_flatid;

      RETURN RESULT;
   END;

   PROCEDURE checkconstructiontransaction (
      checktrid    IN       INTEGER,
      checkdeltr   IN       BOOLEAN DEFAULT FALSE,
      RESULT       OUT      INTEGER
   )
   IS
      CURSOR c_delayedtr (p_ctrid IN INTEGER)
      IS
         SELECT *
           FROM today_transactions_all_cc
          WHERE ID = p_ctrid;

      CURSOR c_contid (p_accid IN INTEGER)
      IS
         SELECT id#
           FROM sbcm_construction_accounts
          WHERE loanaccid = p_accid;

      delayedtr            c_delayedtr%ROWTYPE;
      creditaccid          INTEGER;
      debitaccid           INTEGER;
      firsttransactionid   INTEGER;
      flatamt              NUMBER;
      contractnum          VARCHAR2 (35);
      resulttrid           INTEGER               := -1;
      contractid           INTEGER;
      currdat              DATE;
   BEGIN
      SELECT tek_dat
        INTO currdat
        FROM sysdat;

      OPEN c_delayedtr (checktrid);
      FETCH c_delayedtr INTO delayedtr;
      CLOSE c_delayedtr;
      OPEN c_contid (delayedtr.creditid);
      FETCH c_contid INTO contractid;
      CLOSE c_contid;

      IF contractid IS NULL
      THEN
         RETURN;
      END IF;

      IF delayedtr.vid_op = firstpaytransactionoptype AND NOT checkdeltr
      THEN
         SELECT creditamount, contractno
           INTO flatamt, contractnum
           FROM sbcm_construction_contracts
          WHERE ID = contractid;

         SELECT accid
           INTO creditaccid
           FROM sbcm_construction_accs
          WHERE parentid = (SELECT ID
                              FROM sbcm_construction_settings
                             WHERE prname = 'ConstrInternalAcc');

         resulttrid :=
            child_transaction_commit (operatorid          => delayedtr.operatorid,
                                      debitid             => delayedtr.creditid,
                                      creditid            => creditaccid,
                                      damount             => flatamt,
                                      camount             => flatamt,
                                      lamount             => NULL,
                                      debitrate           => NULL,
                                      creditrate          => NULL,
                                      trname              =>    'К?едитин ве?илмяси '
                                                             || contractnum,
                                      flags               => sbdecls.atfcommitimmediate,
                                      inbalancechar       => delayedtr.inbalancechar,
                                      outbalancechar      => delayedtr.outbalancechar,
                                      operationtype       => firstpaytransactionoptype,
                                      parentid            => NULL,
                                      transactionid       => NULL,
                                      transactionno       => NULL
                                     );

         UPDATE constuction_curr_state
            SET rest = flatamt - delayedtr.debitamount
          WHERE id# = contractid;

         INSERT INTO sbcm_construction_tranches
                     (tranchedate, id#, tramt, trid
                     )
              VALUES (currdat, contractid, flatamt, resulttrid
                     );

         commitcontracts (contractid);
      END IF;

      IF     (    (checktransactionforconstr (delayedtr.creditid))
              AND (NVL (delayedtr.vid_op, 0) NOT IN
                            (firstpaytransactionoptype, paytransactionoptype)
                  )
             )
         AND (NOT checkdeltr)
      THEN
         UPDATE constuction_curr_state
            SET rest = rest - delayedtr.debitamount
          WHERE id# = contractid;

         INSERT INTO sbcm_construction_payments
                     (paydate, id#, payamt,
                      trid, firtspay
                     )
              VALUES (currdat, contractid, delayedtr.debitamount,
                      delayedtr.ID, 0
                     );
      END IF;

      IF (checktransactionforconstr (delayedtr.creditid)) AND checkdeltr
      THEN
      
         UPDATE constuction_curr_state
            SET rest = rest + delayedtr.debitamount
          WHERE id# = contractid;

         DELETE      sbcm_construction_payments
               WHERE id# = contractid AND trid = delayedtr.ID;

         IF delayedtr.vid_op = firstpaytransactionoptype
         THEN
            DELETE      sbcm_construction_tranches
                  WHERE id# = contractid;

            UPDATE constuction_curr_state
               SET rest = 0
             WHERE id# = contractid;

            rollbackcontracts (contractid);
         END IF;
      END IF;

      RESULT := resulttrid;
   END;

   FUNCTION child_transaction_commit (
      operatorid            INTEGER,
      debitid               INTEGER,
      creditid              INTEGER,
      damount               NUMBER,
      camount               NUMBER,
      lamount               NUMBER,
      debitrate             NUMBER,
      creditrate            NUMBER,
      trname                VARCHAR2,
      flags                 INTEGER DEFAULT 0,
      inbalancechar         INTEGER,
      outbalancechar        INTEGER,
      operationtype         INTEGER DEFAULT NULL,
      parentid              INTEGER DEFAULT NULL,
      transactionid    IN   INTEGER,
      transactionno         VARCHAR DEFAULT NULL
   )
      RETURN INTEGER
   AS
      debitcurrency       ACCOUNT.val_acc%TYPE;
      creditcurrency      ACCOUNT.val_acc%TYPE;
      debitorate          NUMBER;
      creditorate         NUMBER;
      debitamount         tenostat.ostat%TYPE;
      creditamount        tenostat.ostat%TYPE;
      debitlamount        tenostat.pok_ostat%TYPE;
      creditlamount       tenostat.pok_ostat%TYPE;
      currencyrate        NUMBER;
      currentdate         DATE;
      debitlimit          ACCOUNT.LIMIT%TYPE;
      creditlimit         ACCOUNT.LIMIT%TYPE;
      debitacctype        bal_spr1.typeid%TYPE;
      creditacctype       INTEGER;
      debetcid            INTEGER;
      creditcid           INTEGER;
      debit_dturnover     tenostat.obr_d%TYPE;
      debit_dlturnover    tenostat.pok_obr_d%TYPE;
      debit_cturnover     tenostat.obr_k%TYPE;
      debit_clturnover    tenostat.pok_obr_k%TYPE;
      credit_dturnover    tenostat.obr_d%TYPE;
      credit_dlturnover   tenostat.pok_obr_d%TYPE;
      credit_cturnover    tenostat.obr_k%TYPE;
      credit_clturnover   tenostat.pok_obr_k%TYPE;
      debit_sid           INTEGER;
      credit_sid          INTEGER;
      trdebitamount       NUMBER (15, 4);
      trcreditamount      NUMBER (15, 4);
      trlamount           NUMBER (15, 4);
      atransactionid      INTEGER                   := transactionid;
      closeday            INTEGER;
      RESULT              INTEGER;
   BEGIN
      /* get accounts' data */
      SELECT val_acc, LIMIT, bal_cn1
        INTO debitcurrency, debitlimit, debit_sid
        FROM ACCOUNT
       WHERE ID = debitid;

      SELECT val_acc, LIMIT, bal_cn1
        INTO creditcurrency, creditlimit, credit_sid
        FROM ACCOUNT
       WHERE ID = creditid;

      /* get account's states */
      SELECT ostat, pok_ostat, obr_d, pok_obr_d,
             obr_k, pok_obr_k
        INTO debitamount, debitlamount, debit_dturnover, debit_dlturnover,
             debit_cturnover, debit_clturnover
        FROM tenostat
       WHERE acc_id = debitid;

      SELECT ostat, pok_ostat, obr_d,
             pok_obr_d, obr_k, pok_obr_k
        INTO creditamount, creditlamount, credit_dturnover,
             credit_dlturnover, credit_cturnover, credit_clturnover
        FROM tenostat
       WHERE acc_id = creditid;

      /* get account's flags (active, passive, etc.) */
      SELECT typeid
        INTO debitacctype
        FROM bal_spr1
       WHERE bal_cn = debit_sid;

      SELECT typeid
        INTO creditacctype
        FROM bal_spr1
       WHERE bal_cn = credit_sid;

/* Amt 30-nov-05 */
      SELECT tek_dat, CLOSE
        INTO currentdate, closeday
        FROM sysdat;

      IF closeday = 1
      THEN
         raise_application_error (-20031, 'Gun Hele Tam Baglanmayib');
      END IF;

      IF closeday = 2 AND NVL (operationtype, 0) <> 1
      THEN
         IF debitcurrency <> 0 OR creditcurrency <> 0
         THEN
            raise_application_error (-20032, 'Mezenne Fergi Hesablanir');
         END IF;
      END IF;

/* amt end */
      IF atransactionid IS NULL
      THEN
         SELECT tr_seg_provarch.NEXTVAL
           INTO atransactionid
           FROM DUAL;
      END IF;

--raise_application_error(-20007,'Trid = '||ATransactionID);
      IF (trdebitamount = 0) AND (trlamount = 0)
      THEN
         raise_application_error (sbdecls.error_nullamounts,
                                  'Amount or LAmount must be non-zero'
                                 );
      END IF;

      /* Check arest flags DI__ABLO*/
      IF     sbutil.findaccflag (debitid, 'DebitArested')
         AND NVL (operationtype, 0) <> 1
      THEN
         raise_application_error (sbdecls.error_debitaccountarested,
                                  'Debit account are under arest'
                                 );
      END IF;

      IF     sbutil.findaccflag (creditid, 'CreditArested')
         AND NVL (operationtype, 0) <> 1
      THEN
         raise_application_error (sbdecls.error_creditaccountarested,
                                  'Credit account are under arest'
                                 );
      END IF;

      /* get rates of account's currencies */
      SELECT ostat
        INTO debitorate
        FROM operkurs PARTITION (today)
       WHERE (val_kod = debitcurrency);

      SELECT ostat
        INTO creditorate
        FROM operkurs PARTITION (today)
       WHERE (val_kod = creditcurrency);

      /* amt 19-dec-05 */
      trdebitamount := damount;
      trcreditamount := camount;
      trlamount := lamount;

      /* amt end */
      IF trlamount IS NULL
      THEN
         IF trdebitamount IS NOT NULL
         THEN
            trlamount := trdebitamount * debitorate;
         ELSIF trcreditamount IS NULL
         THEN
            raise_application_error (sbdecls.error_insufficientparameters,
                                     'One of amounts must be not null'
                                    );
         ELSE
            trlamount := trcreditamount * creditorate;
         END IF;
      END IF;

      IF trdebitamount IS NULL
      THEN
         trdebitamount := trlamount / debitorate;
      END IF;

      IF trcreditamount IS NULL
      THEN
         trcreditamount := trlamount / creditorate;
      END IF;

      /* check account's balance & limit conditions and raise an exception if they are violated */

--  amt begin
      IF NOT (   sbutil.findaccflag (debitid, 'Overdraft')
              OR (debitacctype = sbdecls.atactive)
              OR (debitacctype = sbdecls.atactivepassive)
              OR (debitamount - debitlimit >= trdebitamount)
             )
      THEN
         raise_application_error (sbdecls.error_debitbalanceviolation,
                                      'Amount or limit condition on debet account is not enought for transaction. '
                                   || 'Balance: '
                                   || debitamount
                                   || ', localized balance: '
                                   || debitlamount
                                   || '. Required: '
                                   || trdebitamount
                                   || ', '
                                   || trlamount
                                 );
      END IF;

      IF NOT (   sbutil.findaccflag (creditid, 'Overdraft')
              OR (creditacctype = sbdecls.atpassive)
              OR (creditacctype = sbdecls.atactivepassive)
              OR (creditamount - creditlimit <= -trcreditamount)
             )
      THEN
         raise_application_error (sbdecls.error_creditbalanceviolation,
                                      'Amount or limit condition on credit account is not enought for transaction. '
                                   || 'Balance: '
                                   || creditamount
                                   || ', localized balance: '
                                   || creditlamount
                                   || '. Required: '
                                   || trcreditamount
                                   || ', '
                                   || trlamount
                                 );
      END IF;

/* amt end */
      IF BITAND (flags, sbdecls.atfnoadd) = 0
      THEN
         /* Add in PROVARCH */
         INSERT INTO provarch
                     (ID, op_id, vid_op, parentid,
                      dat, debt, kredit, val_acc,
                      currencyid_c, ammount, lammount, tim, shifr,
                      rate_d, rate_c, ammount_c, kassa_b,
                      kassa_z, NAME, no_prov
                     )
              VALUES (atransactionid, operatorid, operationtype, parentid,
                      currentdate, debitid, creditid, debitcurrency,
                      creditcurrency, trdebitamount, trlamount, SYSDATE, 3,
                      debitrate, creditrate, trcreditamount, inbalancechar,
                      outbalancechar, trname, transactionno
                     ) --TNarik
           RETURNING ID
                INTO RESULT;

         /* add transaction into provdoc */
         debit_dturnover := debit_dturnover + trdebitamount;
         debit_dlturnover := debit_dlturnover + trlamount;
         credit_cturnover := credit_cturnover + trcreditamount;
         credit_clturnover := credit_clturnover + trlamount;

         UPDATE tenostat
            SET ostat = ostat - trdebitamount,
                pok_ostat = pok_ostat - trlamount,
                datdate = currentdate,
                obr_d = debit_dturnover,
                pok_obr_d = debit_dlturnover
          WHERE acc_id = debitid;

         IF SQL%ROWCOUNT <> 1
         THEN
            raise_application_error (-20001,
                                     'DEBIT - ERROR, Please report to administrator'
                                    );
         END IF;

         UPDATE tenostat
            SET ostat = ostat + trcreditamount,
                pok_ostat = pok_ostat + trlamount,
                datdate = currentdate,
                obr_k = credit_cturnover,
                pok_obr_k = credit_clturnover
          WHERE acc_id = creditid;

         IF SQL%ROWCOUNT <> 1
         THEN
            raise_application_error (-20001,
                                     'CREDIT - ERROR, Please report to administrator'
                                    );
         END IF;

         IF parentid IS NOT NULL AND operationtype = 0
         THEN
            UPDATE lazyrest
               SET ostat = ostat - trdebitamount,
                   pok_ostat = pok_ostat - trlamount,
                   datdate = currentdate,
                   obr_d = debit_dturnover,
                   pok_obr_d = debit_dlturnover
             WHERE acc_id = debitid;

            UPDATE lazyrest
               SET ostat = ostat + trcreditamount,
                   pok_ostat = pok_ostat + trlamount,
                   datdate = currentdate,
                   obr_k = credit_cturnover,
                   pok_obr_k = credit_clturnover
             WHERE acc_id = creditid;
         END IF;
      END IF;

      /* if bitand ... atfNoAdd ... */
      RETURN RESULT;
   END;

   FUNCTION partspayment_get (
      p_amount       IN   NUMBER,
      p_periods      IN   INTEGER,
      p_periodrate   IN   INTEGER
   )
      RETURN NUMBER
   IS
      RESULT   NUMBER (18, 2);
   BEGIN
      RESULT := p_amount / p_periods;
      RETURN RESULT;
   END;

   FUNCTION paymentplane_addedit (
      p_id           IN   INTEGER,
      p_creditid     IN   INTEGER,
      p_paydate      IN   DATE,
      p_principial   IN   NUMBER,
      p_interest     IN   NUMBER
   )
      RETURN INTEGER
   IS
      RESULT   INTEGER;
   BEGIN
      UPDATE sbcm_construction_plane
         SET paymentdate = p_paydate,
             mainamt = p_principial,
             intamt = p_interest
       WHERE ID = p_id;

      IF SQL%ROWCOUNT = 0
      THEN
         INSERT INTO sbcm_construction_plane
                     (id#, paymentdate, mainamt, intamt
                     )
              VALUES (p_creditid, p_paydate, p_principial, p_interest
                     )
           RETURNING ID
                INTO RESULT;
      END IF;

      COMMIT WORK;
      RETURN RESULT;
   END;

   PROCEDURE add_payment_plane (
      p_creditid       IN   INTEGER,
      p_amount         IN   NUMBER,
      p_rate           IN   NUMBER,
      p_firstpaydate   IN   DATE,
      p_startdate      IN   DATE,
      p_periods        IN   INTEGER,
      p_periodrate     IN   INTEGER -- In Months 
   )
   IS
      equalpayment    NUMBER;
      intramt         NUMBER;
      principialamt   NUMBER;
      fullpayment     NUMBER  := p_amount;
      paydate         DATE    := p_firstpaydate;
      daycnt          INTEGER;
      temp            INTEGER;
   BEGIN
      equalpayment := partspayment_get (fullpayment, p_periods, p_periodrate);
      daycnt := bankdaysbetween (p_startdate, p_firstpaydate);
      intramt := calcpercent (p_amount, p_rate, daycnt);
      principialamt := equalpayment;
      temp :=
         paymentplane_addedit (0, p_creditid, paydate, principialamt,
                               intramt);
      fullpayment := p_amount - equalpayment;

      FOR i IN 2 .. p_periods
      LOOP
         intramt := calcpercent (fullpayment, p_rate, p_periodrate * 30);
         principialamt := equalpayment;
         paydate := ADD_MONTHS (paydate, 1);
         temp :=
            paymentplane_addedit (0,
                                  p_creditid,
                                  paydate,
                                  principialamt,
                                  intramt
                                 );

         IF fullpayment >= equalpayment
         THEN
            fullpayment := fullpayment - equalpayment;
         ELSE
            fullpayment := 0;
         END IF;
      END LOOP;
   END;

   FUNCTION calcpercent (
      p_sum           IN   NUMBER,
      p_rate          IN   NUMBER,
      p_coefficient   IN   NUMBER,
      p_delimmer      IN   NUMBER DEFAULT 360
   )
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      RESULT := (p_sum * p_rate * p_coefficient) / (p_delimmer * 100);
      RETURN RESULT;
   END;

   FUNCTION bankdaysbetween (firstdate IN DATE, lastdate IN DATE)
      RETURN INTEGER
   IS
      RESULT          INTEGER;
      currentmonth    DATE;
      MONTH           DATE    := firstdate;
      monthinterval   INTEGER;
      mounthindex     INTEGER;
      lastmonthday    INTEGER;
      bankyeardays    INTEGER := 360;
   BEGIN
      IF firstdate >= lastdate
      THEN
         RESULT := 0;
      ELSE
         RESULT := (lastdate - firstdate);

         IF bankyeardays > 360
         THEN
            RETURN RESULT;
         END IF;

         monthinterval := (lastdate - firstdate) / 30;

         FOR monthindex IN 0 .. monthinterval
         LOOP
            currentmonth := LAST_DAY (MONTH);
            lastmonthday := TO_NUMBER (TO_CHAR (currentmonth, 'DD'));

            IF (currentmonth <= lastdate) AND (currentmonth > firstdate)
            THEN
               IF lastmonthday = 31
               THEN
                  RESULT := RESULT - 1;
               END IF;

               IF lastmonthday = 28
               THEN
                  RESULT := RESULT + 2;
               END IF;

               IF lastmonthday = 29
               THEN
                  RESULT := RESULT + 1;
               END IF;
            END IF;

            MONTH := ADD_MONTHS (MONTH, 1);
         END LOOP;
      END IF;

      RETURN RESULT;
   END;

   PROCEDURE deletepaymentplane (p_id IN INTEGER)
   IS
   BEGIN
      DELETE      sbcm_construction_plane
            WHERE ID = p_id;

      COMMIT;
   END;

   PROCEDURE deletepayment (p_payid IN INTEGER)
   IS
      CURSOR c_pay
      IS
         SELECT *
           FROM sbcm_construction_payments
          WHERE ID = p_payid;

      CURSOR c_tranche
      IS
         SELECT *
           FROM sbcm_construction_tranches
          WHERE id# = (SELECT id#
                         FROM sbcm_construction_payments
                        WHERE ID = p_payid);

      payinfo      c_pay%ROWTYPE;
      tranche      c_tranche%ROWTYPE;
      RESULT       INTEGER;
      currdat      DATE;
      contractid   INTEGER;
   BEGIN
      SELECT tek_dat
        INTO currdat
        FROM sysdat;

      OPEN c_pay;
      FETCH c_pay INTO payinfo;
      CLOSE c_pay;

      SELECT id#
        INTO contractid
        FROM sbcm_construction_payments
       WHERE ID = p_payid;

      IF payinfo.paydate < currdat
      THEN
         raise_application_error (-20007,
                                  'А?хив ?цнцндяки ямялиййаты силмяк олмаз'
                                 );
      END IF;

      IF transactionexist (payinfo.trid)
      THEN
         RESULT := deletetransaction (payinfo.trid);
      END IF;

      IF NVL (payinfo.firtspay, 0) = 1
      THEN
         OPEN c_tranche;
         FETCH c_tranche INTO tranche;
         CLOSE c_tranche;

         IF transactionexist (tranche.trid)
         THEN
            RESULT := deletetransaction (tranche.trid);

            DELETE      sbcm_construction_tranches
                  WHERE id# = (contractid);

            rollbackcontracts (contractid);
         END IF;
      END IF;

      DELETE      sbcm_construction_payments
            WHERE ID = p_payid;

      COMMIT;
   END;

   FUNCTION checktransactionforconstr (p_accid IN INTEGER)
      RETURN BOOLEAN
   IS
      RESULT        BOOLEAN;

      CURSOR c_checkconstr
      IS
         SELECT COUNT (*) AS cnt
           FROM sbcm_construction_accounts
          WHERE loanaccid = p_accid;

      checkconstr   c_checkconstr%ROWTYPE;
   BEGIN
      RESULT := FALSE;
      OPEN c_checkconstr;
      FETCH c_checkconstr INTO checkconstr;
      RESULT := c_checkconstr%FOUND;
      CLOSE c_checkconstr;
      RETURN RESULT;
   END;

   FUNCTION get_flatstatus (p_flatid IN INTEGER)
      RETURN INTEGER
   IS
      RESULT        INTEGER;
      cntflatconc   INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO cntflatconc
        FROM sbcm_construction_contracts
       WHERE flatid = p_flatid;

      IF cntflatconc = 0
      THEN
         RESULT := 0;
      ELSE
         RESULT := 1;
      END IF;

      RETURN RESULT;
   END;
   
   function Get_BuyerNameFromFlatID(p_fid in integer) 
   return varchar2
   is
   result varchar2(80);
       
       cursor c_cc is
       select flatid from sbcm_construction_contracts
       where flatid= p_fid;
       fid integer;
   begin
      
      open c_cc ;
      fetch c_cc into fid;
      close c_cc;
      
       if fid is not null then
         select BYR_NAME into result
         from cc_buyers
         where id =(select BUYER from cc_flats where id= fid);
         else result := ' ';
         
      end if;
      
      return result;
   end;
END;
/


