Procedure  AddStateCache(
            p_ID IN Number
           ) 
Is
Begin
   Insert Into SBCM_STATE_CACHE(
	               ID#
	              ,FacticalInterest 
							  ,OverdueInterest 	
	              )
					Values(
					 p_ID
					,0
					,0  
					);			
End;
 
Procedure  AddValue(
            InterestMode IN Integer
					 ,p_HDate IN Date
					 ,p_Percent IN Number 	
           ) 
Is
Begin
  if  InterestMode = 0  then
	  Interests(InterestIndex).HDate:=p_HDate;
		Interests(InterestIndex).Percent:=p_Percent;
		InterestIndex:=InterestIndex + 1;
	 else
	  OInterests(OInterestIndex).HDate:=p_HDate;
		OInterests(OInterestIndex).Percent:=p_Percent;
		OInterestIndex:=OInterestIndex + 1;
	end if;
End;					 
Procedure  Init(   
             PercentMode IN Integer         
            ,maxLength IN Integer												
					  ) 			 
Is
Begin
 if  PercentMode = 0 then    	
	 Interests :=TInterests();
   Interests.Extend(maxLength);
	 InterestIndex :=1;
 else	 
	 OInterests :=TInterests();
   OInterests.Extend(maxLength); 
	 OInterestIndex :=1;
 end if;	 
End;
Procedure Free
Is
Begin  		
	 Interests.Delete; 
	 InterestIndex :=1;	
	 OInterests.Delete;
	 OInterestIndex :=1;	   
End;											
