Procedure  UpdateContract(
						p_ID   Number
     	     ,p_Type  Integer
             ,p_OpenDate Date
        	 ,p_CloseDate Date
        	 ,p_Amount  Number
        	 ,p_ContractNo VarChar2
        	 ,p_ContractType Integer
        	 ,p_PledgeType  Integer
        	 ,p_ReliabilityID  Integer
        	 ,p_ClientType  Number
	    	   ,p_PledgePrice Number
           ,p_OverdueReliabilityID Number,
            p_personaltype in integer,
            p_Currency in integer,
            p_branchid in integer
            ,p_customerid in integer
            ,p_firstinterestpaydat in date default null
          )
 Is 
 Begin 
    Update SBCM_Contracts  Set
    		  Type# = p_Type
    		 ,Opendate = p_OpenDate
    		 ,CloseDate = p_CloseDate
    		 ,Amount = p_Amount
    		 ,ContractNo = p_ContractNo
    		 ,ContractType = p_ContractType
    		 ,PledgeType = p_PledgeType
				 ,ReliabilityID = p_ReliabilityID
				 ,ClientType = p_ClientType
				 ,PledgePrice = p_PledgePrice
         ,OverdueReliabilityID = p_OverdueReliabilityID
         ,personaltype = p_personaltype
         ,currency = p_currency
         ,branchid = p_branchid 
         ,customerid = p_customerid
         ,firstinterestpaydat = p_firstinterestpaydat
			Where 
			  ID = p_ID;
	 --commit;				 		 		
 End;
