function Get_DefaultContractRate(p_DepositType in integer,
                                 p_Currency in integer,
                                 p_DepositAmount in number,
                                 p_defint in boolean default true)
return number
is
 result number;
 
 cursor c_Rate is
 select interestrate,dueintrate
 from sbcm_depositpersetting
 where depositid = p_DepositType
 and currencyid = p_Currency
 and p_DepositAmount between firstamount and lastamount;
  
  Rate c_Rate%rowtype;
  
begin
   
   open c_Rate;
   fetch c_Rate into Rate;
   close c_Rate;
   
   if p_defint then
       result := Rate.interestrate;
    else
      result := Rate.dueintrate;      
   end if;

   return nvl(result,0);

end;

   FUNCTION getperiod (bdat IN DATE, edat IN DATE)
      RETURN INTEGER
   IS
   BEGIN
      RETURN MONTHS_BETWEEN (edat, bdat);
   END;


   function Get_DepositWcinterval(p_depositID in integer)
   return number
   is
     result number;

    cursor c_dint is
     select dateinterval 
      from sbcm_deposit_types
     where id  =  p_depositID;
     
   begin
   
     open c_dint ;
     fetch c_dint into result;
     close c_dint ;
   
     return result;
   end;
   
   function Check_BankAccount(p_categoryID in integer,
                                 p_currencyID in integer,
                                 p_BranchID in integer,
                                 p_movie_desc in varchar2 default 'outComeAccForDeposit')
   return boolean                              
   is
     result boolean;
     
     cursor c_check is
     select accid from sbcm_settings
     where parentid = (select id from sbcm_movie_names where typeid = p_categoryID 
                       and name = p_movie_desc)
     and currencyid = p_currencyID
     and branchid =  p_BranchID;
     
     chck c_check%rowtype;
                      
   begin
      open c_check;
      fetch c_check into chck;
      result := (c_check%found) and (chck.accid <> 0);
      close c_check;
      
      return result;
   end;     
   
