CREATE OR REPLACE 
PACKAGE sbcm_control
IS
   PROCEDURE control;
END;
/


CREATE OR REPLACE 
PACKAGE BODY             sbcm_control
IS
/*Filialin id -sini yazmagi unutma!*/
   PROCEDURE control
   IS
      CURSOR c_acc
      IS
         SELECT   contractaccid, interestaccid
             FROM sbcm_contract_accounts
            WHERE id# IN (SELECT ID
                            FROM sbcm_contracts
                           WHERE type# = 3)
         and contractaccid in (select id from account where filial=sb_aca.getuserfilial())                  
         GROUP BY contractaccid, interestaccid;

      CURSOR c_dep (p_id IN INTEGER)
      IS
         SELECT ID, contractno
           FROM sbcm_contracts
          WHERE ID IN (SELECT id#
                         FROM sbcm_contract_accounts
                        WHERE contractaccid = p_id );

      CURSOR c_rest (p_id IN INTEGER)
      IS
         SELECT facticaldebt, facticalinterestdebt
           FROM sbcm_contract_state
          WHERE id# = p_id;

      CURSOR c_sm_rest (p_id IN INTEGER)
      IS
         SELECT ABS (ostat) AS ostat
           FROM tenostat
          WHERE acc_id = p_id;

      dep_rest             c_rest%ROWTYPE;
      sm_rest              c_sm_rest%ROWTYPE;
      sumrest              NUMBER;
      suminterestrest      NUMBER;
      sumduerest           NUMBER;
      sumdueinterestrest   NUMBER;
      smrest               NUMBER;
      sminterestrest       NUMBER;
      smduerest            NUMBER;
      smdueinterestrest    NUMBER;
      accid                NUMBER;
      custid               NUMBER;
      depnum               VARCHAR2 (50);
      custname             VARCHAR2 (80);
      filname               varchar2(80); 
   BEGIN
      sumrest := 0;
      suminterestrest := 0;

      FOR acc IN c_acc
      LOOP
         FOR dep IN c_dep (acc.contractaccid)
         LOOP
            OPEN c_rest (dep.ID);
            FETCH c_rest INTO dep_rest;
            CLOSE c_rest;
            sumrest := sumrest + dep_rest.facticaldebt;
            suminterestrest :=
                               suminterestrest
                               + dep_rest.facticalinterestdebt;
            accid := acc.contractaccid;
            depnum := dep.contractno;
         END LOOP; --crd

         OPEN c_sm_rest (acc.contractaccid);
         FETCH c_sm_rest INTO sm_rest;
         CLOSE c_sm_rest;
         smrest := sm_rest.ostat;
         OPEN c_sm_rest (acc.interestaccid);
         FETCH c_sm_rest INTO sm_rest;
         CLOSE c_sm_rest;
         sminterestrest := sm_rest.ostat;

         SELECT NAME
           INTO custname
           FROM customers
          WHERE ID = (SELECT kli_id
                        FROM ACCOUNT
                       WHERE ID = accid);
                       
         select name into filname
         from filial where 
         id=(select filial from account where id=accid); 
         IF (smrest <> sumrest) --1
                                OR (sminterestrest <> suminterestrest)
         THEN
            INSERT INTO sbcm_controls
                        (contractnum, custname, drest,
                         dintrest,filial
                        )
                 VALUES (depnum, custname, ABS (smrest - sumrest),
                         ABS (sminterestrest - suminterestrest),filname
                        );
         END IF;

         sumrest := 0;
         suminterestrest := 0;
      END LOOP;
   END;
END;
/


-- End of DDL Script for Package AV.SBCM_CONTROL

