   PROCEDURE addtranch (
      contractid       IN   sbcm_contracts.id%TYPE,
      hdate            IN   DATE,
      total            IN   NUMBER,
      usetransaction   IN   BOOLEAN
   );
  function IfFirstTranch(ContractID in Integer)
   return 
     Boolean;
  procedure DeleteDepositMoney(P_DepMoneyID in integer);
  PROCEDURE depositmoney (
      P_ClientAccID    IN   INTEGER,
      contractid       IN   sbcm_contracts.id%TYPE,
      hdate            IN   DATE,
      total            IN   NUMBER,
      PERCENT          IN   NUMBER,
      usetransaction   IN   BOOLEAN
   );
  procedure CommitDepositMoney(
            DoCommit in Boolean 
  );
END; -- Package spec
/


CREATE OR REPLACE 
PACKAGE BODY sbcm_credit_tranches
IS

   function IfFirstTranch(ContractID in Integer)
   return 
     Boolean
   is
     tranchCount Integer;
     Result Boolean;
   begin
     select count(*) into tranchCount 
     from SBCM_Tranches
     where ID# = ContractID;
     if tranchCount = 0 then
     Result := TRUE;
     else
     Result :=FALSE;
     end if;
     return Result;     
   end;  
   
   PROCEDURE addtocollection (
      contractid   IN   sbcm_contracts.id%TYPE,
      p_hdate      IN   DATE,
      p_amount     IN   NUMBER,
      p_percent    IN   NUMBER
   )
   IS
   BEGIN
      INSERT INTO sbcm_collection
                  (id#, hdate, amount, PERCENT)
           VALUES (contractid, p_hdate, p_amount, p_percent);
   END;

   PROCEDURE updateresiduaryamount (
      contractid    IN   sbcm_contracts.id%TYPE,
      tranchtotal   IN   NUMBER
   )
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET residuaryamount =   residuaryamount
                               - tranchtotal
       WHERE id# = contractid;
   END;

   PROCEDURE setlastprocessdate (
      contractid   IN       sbcm_contracts.id%TYPE,
      tranchdate   IN OUT   DATE
   )
   IS
     CalcLeft Integer:=0;
   BEGIN
      CalcLeft := sbcm_stored_programs.booltoint (sbcm_stored_programs.usingleft);
     -- dbms_output.put_line('CalcLeft =  '||TO_CHAR(CalcLeft));
      if (IfFirstTranch(ContractID)) 
      or (SBCM_STORED_PROGRAMS.getfacticaldebt(contractid) = 0) then
      
      tranchdate :=
               tranchdate
             - CalcLeft;
            
      UPDATE sbcm_contract_state
         SET lastprocessdate = tranchdate
       WHERE id# = contractid;

      end if;
      
   END;

   FUNCTION checkcantranch (
      contractid    IN   sbcm_contracts.id%TYPE,
      tranchtotal   IN   NUMBER
   )
      RETURN BOOLEAN
   IS
      result            BOOLEAN;
      residuaryamount   NUMBER;
   BEGIN
      residuaryamount := sbcm_stored_programs.getresiduaryamount (contractid);
      result := (residuaryamount >= tranchtotal);
      RETURN result;
   END;

   PROCEDURE inserttranch (
      p_id        IN   sbcm_contracts.id%TYPE,
      p_hdate     IN   sbcm_tranches.hdate%TYPE,
      p_total     IN   NUMBER,
      p_reserve   IN   NUMBER,
      p_trid      IN   number default null
   )
   IS
   BEGIN
      INSERT INTO sbcm_tranches
                  (id#, hdate, total, reserve,TRID)
           VALUES (p_id, p_hdate, p_total, p_reserve,p_trid);
   END;

   PROCEDURE customerdebtincrease (
      contractid   IN   sbcm_contracts.id%TYPE,
      increaseby   IN   NUMBER
   )
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET lastfacticaldebt = facticaldebt,
             facticaldebt =   facticaldebt
                            + increaseby
       WHERE id# = contractid;
   END;

   PROCEDURE addtranch (
      contractid       IN   sbcm_contracts.id%TYPE,
      hdate            IN   DATE,
      total            IN   NUMBER,
      usetransaction   IN   BOOLEAN
   )
   IS
      credittransid         NUMBER;
      reservetransid        NUMBER;
      contractaccid         ACCOUNT.id%TYPE;
      clientaccid           ACCOUNT.id%TYPE;
      reserveaccid          ACCOUNT.id%TYPE;
      outcomereserveaccid   ACCOUNT.id%TYPE;
      dcurrency             avalute.valute%TYPE;
      ccurrency             avalute.valute%TYPE;
      debtamount            NUMBER (15, 2);
      creditamount          NUMBER (15, 2);
      reserveamount         NUMBER (15, 2);
      lamount               NUMBER (15, 2);
      reliabilitypercent    NUMBER (15, 2);
      bankyeardays          INTEGER;
      tranchdate            DATE;
      contractnum           VARCHAR2 (256);
      cashsymbol            integer;
   BEGIN
   SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
      IF NOT checkcantranch (contractid, total)
      THEN
         raise_application_error (
            sbcm_exceptions.etrancherror,
            'Tranch Total Must Be Less Than Resuduary Amount!'
         );
      END IF;
      IF usetransaction
      THEN
         contractnum :=
                      sbcm_stored_programs.contractnumasvarchar2 (contractid);
         contractaccid := sbcm_stored_programs.getcontractaccid (contractid);
         clientaccid := sbcm_stored_programs.getclientaccid (contractid);
         reserveaccid := sbcm_stored_programs.getreserveaccid (contractid);
         outcomereserveaccid :=
               sbcm_stored_programs.getselectedaccid (
                  contractid,
                  'outComeAccForReserve'
               );
         dcurrency :=
                    sbcm_stored_programs.getaccountcurrencyid (contractaccid);
         ccurrency := sbcm_stored_programs.getaccountcurrencyid (clientaccid);

         --Contract Conclusion in one Currncy!
         
         cashsymbol := sbcm_stored_programs.getcashsymbolifexsist('cmrCahsSymbolOnTransh',clientaccid);          

         IF dcurrency <> ccurrency
         THEN
            debtamount := total;
            creditamount := NULL;
         ELSE
            debtamount := total;
            creditamount := total;
         END IF;

         lamount := NULL;
         reliabilitypercent :=
                       sbcm_stored_programs.getreliabilitypercent (contractid);
         bankyeardays := sbcm_stored_programs.getreference ('cmrYearDayCount');
         reserveamount := sbcm_stored_programs.ReserveInNational(
                                               hdate ,
                                               total ,
                                               ContractID ,
                                               reliabilitypercent
                                               );
         credittransid :=
               sb_transaction.transaction_add (
                  debitid=> contractaccid,
                  creditid=> clientaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> lamount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    'К?едит Т?анщы № '
                           || contractnum,
                  flags => 0,
                  transactiondate=> tranchdate ,
                  InBalanceChar => cashsymbol
               );
         reservetransid :=
               sb_transaction.transaction_add (
                  debitid=> outcomereserveaccid,
                  creditid=> reserveaccid,
                  debitamount=> reserveamount,
                  creditamount=> NULL,
                  lamount=> NULL,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    'Т?анщ заманы ещтиййата пул к?чцлмяси № '
                           || contractnum,
                  flags => 0,
                  transactiondate=> tranchdate
               );
      END IF; --Use Transactions

      tranchdate := hdate;
      setlastprocessdate (contractid, tranchdate);      
      customerdebtincrease (contractid, total);      
      updateresiduaryamount (contractid, total);      
      inserttranch (contractid, tranchdate, total, reserveamount);      
      COMMIT;
   END;

   PROCEDURE depositmoney (
      P_ClientAccID    IN   INTEGER,
      contractid       IN   sbcm_contracts.id%TYPE,
      hdate            IN   DATE,
      total            IN   NUMBER,
      PERCENT          IN   NUMBER,
      usetransaction   IN   BOOLEAN
   )
   IS
      debtaccid          INTEGER;
      creditaccid        INTEGER;
      damount            NUMBER (18, 2);
      camount            NUMBER (18, 2);
      deposittransid     INTEGER;
      depositmoneydate   DATE           := hdate;
      contractnum        VARCHAR2 (256);
      firstpercent       NUMBER (7, 2);
       balacc   number;
      cass number;
   BEGIN
   SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
     
      IF usetransaction
      THEN
         contractnum :=
                      sbcm_stored_programs.contractnumasvarchar2 (contractid);
         debtaccid := P_ClientAccID/*sbcm_stored_programs.getclientaccid (contractid)*/;
         creditaccid := sbcm_stored_programs.getcontractaccid (contractid);
         damount := total;
         camount := NULL;
         
          select bal_cn1 into balacc
    from account where id = debtaccid;

    if balacc  = 1001 then
       cass := 16;
     else cass := null;
    end if;

     deposittransid := 
      SBCM_TRANSACTIONMGR.SBCM_TransactionAdd(
         p_trid => null ,
         p_debitaccid => debtaccid ,
         p_creditaccid => creditaccid ,
         p_debitamount => damount ,
         p_creditamount => null ,
         p_natamount => null ,
         p_flags => 0 ,
         p_optype => 87 ,
         p_inbalancechar => cass ,
         p_trdate => hdate ,
         p_trdescription => 'Депозит Щесабына пул дахил олу? № '
                           || contractnum
         );
         
               
      END IF;

      firstpercent := sbcm_stored_programs.getpercent (contractid);

      IF firstpercent = PERCENT
      THEN
         customerdebtincrease (contractid, total);
      ELSE
         addtocollection (contractid, hdate, total, PERCENT);
      END IF;
      
      inserttranch (contractid, hdate, total, PERCENT,deposittransid);
      
      UPDATE sbcm_contract_state
      SET lastprocessdate = depositmoneydate
      WHERE id# = contractid;

      if not usetransaction then
       commit;
      end if; 
   END;
   
  procedure CommitDepositMoney(
            DoCommit in Boolean 
  )
  is
  begin
    if  DoCommit  then
      SBCM_TRANSACTIONMGR.SBCM_CommitDelayedTransactions(0/*SBDECLS.atfCommitImmediate*/);
      commit work;
    else
      rollback work;
    end if;
  end;
 
 procedure DeleteDepositMoney(P_DepMoneyID in integer) is
 
 cursor c_DepMpney is
 select id#,
        hdate,
        total,
        trid
 from sbcm_tranches
 where id=P_DepMoneyID;
 
 DepMpney c_DepMpney%rowtype;
 currdat date;  
 MoneyDay date;
 DepMoneyID integer;       
 begin
    
    select tek_dat 
         into currdat
         from sysdat;
         
    open c_DepMpney;
    fetch c_DepMpney into DepMpney;
    MoneyDay:=DepMpney.hdate;
    close c_DepMpney;
 

   if DepMpney.hdate <> currdat then
      raise_application_error(-20007,'Arxiv ямялиййаты силмяк олмаз!');
   end if; 
    
    if DepMpney.trid is not null then
       DepMoneyID:=SBCM_TRANSACTIONMGR.sbdeletetransaction(DepMpney.trid);
    end if;
    
    update sbcm_contract_state
    set facticaldebt = facticaldebt-DepMpney.total
    where id#=DepMpney.id#;
    
    delete sbcm_tranches
    where id=P_DepMoneyID;
    
    commit;
 end;
   
END;
/


