CREATE OR REPLACE 
PACKAGE BODY                                     sbcm_expire
IS
procedure  ExpireContractDebts(
               ContractID IN  SBCM_Contracts.ID%type
							,Value IN Number 
							)
 Is
 begin
   Update SBCM_Contract_State
	 Set
	   FacticalDebt = FacticalDebt - Value ,
		 OverdueDebt  = OverdueDebt  + Value
	 Where 
	   ID# = ContractID;	  
 end;
Procedure  InsertExpires(
            ContractID IN SBCM_Contracts.ID%type
					 ,p_HDate IN Date		
					 ,p_Amount IN Number	
           )
 Is
 begin 
    Insert Into  SBCM_Expires(
		              ID#
								 ,HDate								
								 ,Amount	
		             )
								Values(
								 ContractID
								,p_HDate								
								,p_Amount  
								); 
 end;					  
function   CheckCanExpire(
              ContractID IN SBCM_Contracts.ID%type
						 ,Value in number
             ,CheckParam in boolean
						 )
return Boolean						 
 is
   Result Boolean;
 begin
   if  CheckParam then
   Result :=(SBCM_Stored_Programs.GetFacticalDebt(ContractID)>=Value);
   else
   Result :=(SBCM_Stored_Programs.GetOverdueDebt(ContractID)>=Value);
   end if;   			 	   
   return Result;
 end;
 						  
 Procedure  AddExpire(
            ContractID in SBCM_Contracts.ID%type
					 ,HDate in date	
					 ,FacticalDebt     in number
           ,ExpiredDebt      in number
           ,ReserveID        in integer
           ,ExpiredReserveID in integer	
           ,ChangeReserve        in boolean
           ,ChangeExpiredReserve in boolean
           ,TransactionsON       in boolean           
           )
					 
 Is	 
	 Debit    integer;
	 Credit  integer;   
	 TransID integer;       
	 OutReserveTransID integer;
   InReserveTransID  integer;         
   TransactionDesc varchar2(64) :='E??aeoei ?ayieeiy?e y??eeae?eeie?ae? ? ';      	
 begin
 SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
  if  FacticalDebt > 0  then
  if  not CheckCanExpire(
    	      ContractID
    			 ,FacticalDebt
           ,TRUE
    	     ) then
	raise_application_error(
		       SBCM_EXCEPTIONS.EExpireError
					,' Expired amount must be less than debt.'
					);          				 
	end if;
  if ChangeExpiredReserve then
  sbcm_reserve_cont.ChangeSecondaryReserve(
                    ContractID , 
                    HDate ,
                    ReserveID ,
                    FacticalDebt , 
                    TransactionsON ,
                    OutReserveTransID ,
                    InReserveTransID ,
                    FALSE
                    );
  end if;
  if ChangeReserve then  
  sbcm_reserve_cont.ChangePrimaryReserve(
                    ContractID , 
                    HDate ,
                    ExpiredReserveID ,
                    -FacticalDebt , 
                    TransactionsON ,
                    OutReserveTransID ,
                    InReserveTransID ,
                    FALSE
                    );
  end if;  
  Debit := sbcm_stored_programs.getcontractaccid(ContractID);
  Credit := sbcm_stored_programs.getoverdueaccid(ContractID);
  
  expireContractDebts(ContractID,FacticalDebt);
                          
  elsif ExpiredDebt > 0 then
  if  not CheckCanExpire(
    	      ContractID
    			 ,ExpiredDebt
           ,FALSE
    	     ) then
	raise_application_error(
		       SBCM_EXCEPTIONS.EExpireError
					,' Returned amount must be less than expired debt.'
					);          				 
	end if;
  if ChangeExpiredReserve then  
  sbcm_reserve_cont.ChangeSecondaryReserve(
                    ContractID , 
                    HDate ,
                    ExpiredReserveID ,
                    -ExpiredDebt , 
                    TransactionsON ,
                    OutReserveTransID ,
                    InReserveTransID ,
                    FALSE
                    );
  end if;
  if ChangeReserve then
  sbcm_reserve_cont.ChangePrimaryReserve(
                    ContractID , 
                    HDate ,
                    ReserveID ,
                    ExpiredDebt , 
                    TransactionsON ,
                    OutReserveTransID ,
                    InReserveTransID ,
                    FALSE
                    );
  end if;  
  Debit := sbcm_stored_programs.getoverdueaccid(ContractID); 
  Credit := sbcm_stored_programs.getcontractaccid(ContractID);
  expireContractDebts(ContractID , -ExpiredDebt);                        
  end if;
  
  if  TransactionsON  then
  TransactionDesc := TransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);
  TransID := 
  SB_TRANSACTION.Transaction_Add(
		                  DebitID      => Credit
            				 ,CreditID     => Debit
            				 ,DebitAmount  => FacticalDebt
            				 ,CreditAmount => null
            				 ,LAmount      => null
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => TransactionDesc
            				 ,Flags        => 0
            				 ,TransactionDate =>HDate
		                 );  
  end if;
  
  commit;
        
 end;
 
procedure  ExpireInterestDebts(
                  ContractID IN SBCM_Contracts.ID%type
                 ,Total IN Number 
                 )
is
begin
   update SBCM_Contract_State
   set
     FacticalInterestDebt = FacticalInterestDebt - Total
    ,OverdueInterestDebt  = OverdueInterestDebt  + Total
   where 
      ID# = ContractID;    
end;                   					  
END;
/


