	  ID	 
	 ,HDate 
  From  SBCM_Prolongations
	Where
	  ID = 	
	(Select
	  Max(ID) From  SBCM_Prolongations
	 Where 
	   ID# = ContID);				

 	cursor  OverdueReliabilityExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select
	  Reliabilitys.Percent 
		From SBCM_Contracts Contracts,SBCM_Reliability Reliabilitys
	Where (Contracts.ID = ContractID)
		And	(Reliabilitys.ID = Contracts.OverdueReliabilityID);		

  cursor LastFacticalDebtExporter(ContractID in SBCM_Contracts.ID%type) is
  select 
    LastFacticalDebt 
  from SBCM_Contract_State
  where ID# = ContractID;  

  cursor LastOverdueDebtExporter(ContractID in SBCM_Contracts.ID%type) is
  select 
    LastOverdueDebt 
  from SBCM_Contract_State
  where ID# = ContractID;
    
  cursor AllContracts is
  select
        ID
      , Contracts.ReliabilityID
      , Contracts.OverdueReliabilityID
      , State.FacticalDebt
      , State.FacticalInterestDebt
      , State.OverdueDebt
      , State.OverdueInterestDebt 
  from 
      SBCM_Contracts  Contracts ,
      SBCM_Contract_State State 
  where 
      Contracts.ID = State.ID#
      and Contracts.type# in 
      (select 
         ID 
       from 
         SBCM_Contract_Types
       where 
         upper(Name) in ('CREDIT','DEPOSIT'))   
       order by 
          Contracts.ID;
  
END; -- Package spec
