procedure  InitPayments(
            ContractID IN SBCM_Contracts.ID%type
					 ,FacticalDebtPayment IN Number
					 ,OverdueDebtPayment  IN Number
					 ,InterestDebtPayment IN Number					 
					 ,OverdueInterestDebtPayment IN Number
                     ,p_trID in number default null
                     ,P_intTrID	in number default null
           )
 Is
 currdat date;
 begin
 
 select tek_dat into currdat
 from sysdat;
 
    -- if Transactions  then
		Update  SBCM_Contract_State
		Set
      LastFacticalDebt = FacticalDebt
     ,LastOverdueDebt  = OverdueDebt 
		 ,FacticalDebt = FacticalDebt - FacticalDebtPayment
		 ,OverdueDebt = Overduedebt - OverdueDebtPayment	
		 ,FacticalInterestDebt = FacticalInterestDebt - InterestDebtPayment		 
		 ,OverdueInterestDebt = OverdueInterestDebt - OverdueInterestdebtPayment
		Where ID# = ContractID; 
        
       insert into sbcm_payments(id#, hdate, facticaldebt, interestdebt, overduedebt,
       overdueinterestdebt,trid, inttrid)
       values(ContractID,currdat,FacticalDebtPayment,InterestDebtPayment,0,0,p_trID,P_intTrID);
        		   	 
 end;
 			
Function   CheckCanPayment( 
            ContractID IN SBCM_Contracts.ID%type
					 ,FacticalDebtPayment IN Number
					 ,OverdueDebtPayment  IN Number
					 ,InterestDebtPayment IN Number					 
					 ,OverdueInterestDebtPayment IN Number
					 )
 return  Boolean
 Is
   Result Boolean;
 begin
   Result :=
	      (SBCM_Stored_Programs.GetFacticalDebt(ContractID)>=FacticalDebtPayment)
		 And(SBCM_Stored_Programs.GetOverdueDebt(ContractID)>=OverdueDebtPayment)
		 And(SBCM_Stored_Programs.GetFacticalInterestDebt(ContractID)>=InterestDebtPayment)
		 And(SBCM_Stored_Programs.GetOverdueInterestDebt(ContractID)>=OverdueInterestDebtPayment);		

  return  Result;	          
 end;
