Procedure  WithDrawMoney(
            ContractID IN SBCM_Contracts.ID%type
           ,P_AccID IN INTEGER
           ,HDate IN Date 
           ,FacticalDebtWithdraw IN Number
           ,InterestDebtWithdraw IN Number
           ,UseTransactions IN Boolean
           ,showTransaction in Boolean
           )
Is
  DepositAccID  Integer;
  ClientAccID   Integer;
  InterestAccID Integer;
  
  DAmount  Number(18,2);
  CAmount  Number(18,2);
  LAmount  Number(18,2) :=null;
  
  TransactionID Integer;
  TransactionIntID integer;
  ContractNum Varchar2(256);
Begin
  SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
		 if  not CheckCanPayment(
            ContractID 
					 ,FacticalDebtWithDraw 
					 ,0  
					 ,InterestDebtWithdraw 					 
					 ,0 
		    )  then
		 RAISE_APPLICATION_ERROR(
            SBCM_EXCEPTIONS.EPaymentError
           ,'%Payment Must Be Less Than Debt!'
           );
		end if;
	
  if UseTransactions then
  ClientAccID  :=P_AccID/*SBCM_STORED_PROGRAMS.GetClientAccID(ContractID)*/;  
  ContractNum := SBCM_STORED_PROGRAMS.ContractNumAsVarchar2(ContractID);  
  if  FacticalDebtWithDraw<>0 then
  
    DepositAccID :=SBCM_STORED_PROGRAMS.GetContractAccID(ContractID);
    DAmount :=FacticalDebtWithDraw;
    CAmount :=FacticalDebtWithDraw;
    LAmount :=null;
    
    if  showTransaction then
    TransactionID :=
      SBCM_TRANSACTIONMGR.SBCM_TransactionAdd(
         p_trid => null ,
         p_debitaccid => DepositAccID ,
         p_creditaccid => ClientAccID ,
         p_debitamount => DAmount ,
         p_creditamount => CAmount ,
         p_natamount => LAmount ,
         p_flags => 0 ,
         p_optype => 87 ,
         p_inbalancechar => null ,
         p_trdate => hdate ,
         p_trdescription => 'A?iiceo U??aauiaaia ioe ?u?a?ueu? ? '
                           || contractnum
         );
      end if;
        if not showTransaction then 
          TransactionID :=
               sb_transaction.transaction_add (
                  debitid=> DepositAccID,
                  creditid=> ClientAccID,
                  debitamount=> DAmount,
                  creditamount=> CAmount,
                  lamount=> LAmount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    'A?iiceoey?ei oaec u??aa ? '
                           || contractnum,
                  flags => 0,
                  transactiondate=> hdate
               );
    end if;           
  end if;
  
  if  InterestDebtWithdraw<>0 then
  
    InterestAccID:=SBCM_STORED_PROGRAMS.GetInterestAccID(ContractID);  
    DAmount :=InterestDebtWithdraw;
    CAmount :=InterestDebtWithdraw;
    LAmount :=null;

    if showTransaction then 
     TransactionIntID:=SBCM_TRANSACTIONMGR.SBCM_TransactionAdd(
         p_trid => null ,
         p_debitaccid => InterestAccID ,
         p_creditaccid => ClientAccID ,
         p_debitamount => DAmount ,
         p_creditamount => CAmount ,
         p_natamount => LAmount ,
         p_flags => 0 ,
         p_optype => 87 ,
         p_inbalancechar => null ,
         p_trdate => hdate ,
         p_trdescription => 'A?iiceo oc?y 30 yoieoe oaec ?a?e u??aaa e???oeo?  ?  '
                           || contractnum
         );  
     end if;          
         
       if not showTransaction then 
          TransactionID :=
               sb_transaction.transaction_add (
                  debitid=> InterestAccID,
                  creditid=> ClientAccID,
                  debitamount=> DAmount,
                  creditamount=> CAmount,
                  lamount=> LAmount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    'A?iiceo oc?y 30 yoieoe oaec ?a?e u??aaa e???oeo?  ?  '
                           || contractnum,
                  flags => 0,
                  transactiondate=> hdate
               );
    end if;           
          
  end if;
  end if; --Using Transactions  
  InitPayments(
              ContractID
             ,FacticalDebtWithDraw
             ,0
             ,InterestDebtWithdraw             
             ,0 
             ,TransactionID
             ,TransactionIntID
             );
               

 
End;

Procedure  Capitalization(
                     ContractID IN SBCM_Contracts.ID%type
                    ,HDate      IN Date  
                    ,Total      IN Number 
                    ,UseTransactions IN Boolean  
                    )
Is

  DebtAccID   Integer;
  CreditAccID Integer;
  
  DebtAmount   Number(18,2);
  CreditAmount Number(18,2);
  LAmount      Number(18,2) :=null;
  
  TransactionID Integer;
  ContractNum   Varchar2(256);
  
Begin

SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
		 if sbcm_stored_programs.getfacticalinterestdebt(contractid)<total then
		 RAISE_APPLICATION_ERROR(
            SBCM_EXCEPTIONS.EPaymentError
           ,'%Payment Must Be Less Than Debt!'
           );
		end if;

  
  if UseTransactions  then
  DebtAccID   := SBCM_STORED_PROGRAMS.GetInterestAccID(ContractID);
  CreditAccID := SBCM_STORED_PROGRAMS.GetContractAccID(ContractID);    
  
  ContractNum := SBCM_STORED_PROGRAMS.ContractNumAsVarchar2(ContractID); 
      
  DebtAmount   := Total;
  CreditAmount := null;
  
                      
     TransactionID :=
      SBCM_TRANSACTIONMGR.SBCM_TransactionAdd(
         p_trid => null ,
         p_debitaccid => DebtAccID ,
         p_creditaccid => CreditAccID ,
         p_debitamount => DebtAmount ,
         p_creditamount => CreditAmount ,
         p_natamount => LAmount ,
         p_flags => 0 ,
         p_optype => 87 ,
         p_inbalancechar => null ,
         p_trdate => hdate ,
         p_trdescription => 'A?iiceo oc?y  oaec eaieoaeea?au?ueu? ? '||ContractNum
         );
      end if;


        /* InitPayments(
              ContractID
             ,-Trunc(Total)
             ,0
             ,Trunc(Total)             
             ,0 
             ); */
             
   update sbcm_contract_state
   set facticaldebt = facticaldebt+Total,
       facticalinterestdebt = facticalinterestdebt - Total
   where id# = ContractID;
   
   insert into sbcm_capitalization(id#, hdate, total, trid)
   values (ContractID,hdate,Total,TransactionID);     
        
  
End;

procedure DeleteCapitalization(p_capitalizationID in integer)
is
 cursor c_capital is
 select hdate, total, trid,id#
 from sbcm_capitalization
 where id = p_capitalizationID;
 
 cap c_capital%rowtype;
 capitalid integer;
begin
   
   open c_capital;
   fetch c_capital into cap;
   close c_capital;
   
   if cap.hdate < sbop.get_date then
       raise_application_error(-20007,'Can not delete operation'); 
   end if;
   
   update sbcm_contract_state
   set facticaldebt = facticaldebt - cap.total,
       facticalinterestdebt = facticalinterestdebt +  cap.total 
    where id# = cap.id#;
    
    if cap.trid is not null then
       capitalid:=SBCM_TRANSACTIONMGR.sbdeletetransaction(cap.trid);
    end if;
       
   delete from sbcm_capitalization
   where id = p_capitalizationID;
     
end;

  procedure CommitWithDrawMoney(
            DoCommit in Boolean 
  )
  is
  begin
    if  DoCommit  then
      SBCM_TRANSACTIONMGR.SBCM_CommitDelayedTransactions(0/*SBDECLS.atfCommitImmediate*/);
      commit work;
    else
      rollback work;
    end if;
  end;

 procedure DeleteWithDrawMoney(P_DepWMoneyID in integer) is
 
 cursor c_DepMpney is
 select id#, 
        hdate, 
        facticaldebt as Payfacticaldebt, 
        interestdebt as Payinterestdebt,
        trid,
        inttrid
 from sbcm_payments
 where id=P_DepWMoneyID;
 
 DepMpney c_DepMpney%rowtype;
 currdat date;  
 MoneyDay date;
 DepMoneyID integer;       
 begin
    
    select tek_dat 
         into currdat
         from sysdat;
         
    open c_DepMpney;
    fetch c_DepMpney into DepMpney;
    MoneyDay:=DepMpney.hdate;
    close c_DepMpney;
 

   if DepMpney.hdate <> currdat then
      raise_application_error(-20007,'Arxiv yiyeeeeaou ?eeiye ieiac!');
   end if; 
    
    if DepMpney.trid is not null then
       DepMoneyID:=SBCM_TRANSACTIONMGR.sbdeletetransaction(DepMpney.trid);
    end if;

    if DepMpney.inttrid is not null then
       DepMoneyID:=SBCM_TRANSACTIONMGR.sbdeletetransaction(DepMpney.inttrid);
    end if;
    
    update sbcm_contract_state
    set facticaldebt = facticaldebt+DepMpney.Payfacticaldebt,
        FACTICALINTERESTDEBT = FACTICALINTERESTDEBT+DepMpney.Payfacticaldebt
    where id#=DepMpney.id#;
    
    delete sbcm_payments
    where id=P_DepWMoneyID;
    
    commit;
 end;
  
  procedure UntimeWithDrawMoney(ContractID in integer,
                                p_CalcPercentDate in date,
                                p_CreditAccID in integer)
  is
   currdat Date;
   
   cursor c_ContractInfo is
   select contractno,
          currency,
          amount,
          opendate,
          closedate
   from sbcm_contracts
   where id = ContractID;
   
          
   
   cursor c_Accs is
   select ContractAccID,
          ClientAccID 
   from sbcm_contract_accounts
   where id# = ContractID;
   
   cursor c_Payment is
   select sum(interestdebt) as smint
   from sbcm_payments
   where id# = ContractID;
   
   
   Accs c_Accs%rowtype;
   Payment c_Payment%rowtype;
   
   DebitAccID integer;
   CreditAccID integer;
   TrAmt number(18,2);
   Interestrest number;
   rest number;
   annualInt number;
   annualIntOverDueInt number;
   VirtualIntDebt number;   
   ContractInfo c_ContractInfo%rowtype;
   FTransactionID integer;
   STransactionID integer;    
  begin
  
      select tek_dat into currdat
        from sysdat;
        
        open c_ContractInfo;
        fetch c_ContractInfo into ContractInfo;
        close c_ContractInfo;
        
        annualInt := sbcm_stored_programs.getpercent(ContractID);
        annualIntOverDueInt := sbcm_stored_programs.getoverduepercent(ContractID); 
        
        VirtualIntDebt := sbcm_percent_converting.calcpercent(p_sum => ContractInfo.amount,
                                                              p_rate => annualIntOverDueInt,
                                                              p_coefficient =>
                                                              sbcm_percent_converting.getdateinterval(p_CalcPercentDate,currdat));
        
        
       select facticalinterestdebt,facticaldebt into
        Interestrest,rest 
       from sbcm_contract_state
       where id# = ContractID;
       
       open C_Payment;
       fetch c_Payment into Payment;
       close c_Payment;

       TrAmt := ContractInfo.amount + VirtualIntDebt - (Interestrest + Payment.smint); 
              
       open c_Accs;
       fetch C_Accs into Accs;
       close c_Accs;
       

    FTransactionID :=
      SBCM_TRANSACTIONMGR.SBCM_TransactionAdd(
         p_trid => null ,
         p_debitaccid => Accs.ContractAccID ,
         p_creditaccid => Accs.ClientAccID ,
         p_debitamount => TrAmt ,
         p_creditamount => TrAmt ,
         p_natamount => null ,
         p_flags => 0 ,
         p_optype => 87 ,
         p_inbalancechar => null ,
         p_trdate => currdat ,
         p_trdescription => 'A?iiceo U??aauiaai ioe ?u?a?ueu? ? '
                           || ContractInfo.contractno
         );


         
    sTransactionID :=
      SBCM_TRANSACTIONMGR.SBCM_TransactionAdd(
         p_trid => null ,
         p_debitaccid => Accs.ContractAccID ,
         p_creditaccid => p_CreditAccID ,
         p_debitamount => (ContractInfo.Amount - TrAmt) ,
         p_creditamount => (ContractInfo.Amount - TrAmt) ,
         p_natamount => null ,
         p_flags => 0 ,
         p_optype => 87 ,
         p_inbalancechar => null ,
         p_trdate => currdat ,
         p_trdescription => 'A?iiceoei aa?o?uc ?aeoa?ueia?uia y??y yyee? ? '
                           || ContractInfo.contractno
         );
         
     update sbcm_contract_state
     set facticaldebt = 0,
         facticalinterestdebt = 0
     where id# = ContractID;
     
     insert into sbcm_payments 
            (id#, hdate, facticaldebt, interestdebt,trid,inttrid)
     values (ContractID,p_CalcPercentDate,rest,interestrest,FTransactionID,STransactionID);
                               
         
         
  end;
            					  					 					  					 
END;
/


