CREATE OR REPLACE 
PACKAGE BODY sbcm_percent_converting
IS
   
/*--------------------------------------------*/
 /*  Warning :                                 */
 /*  This Procedure was working  succesful     */
/*  only when Contract has regulyar Percents! */
 /*                                            */
 /*--------------------------------------------*/
   PROCEDURE setlastdebts (contractid IN INTEGER)
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET lastfacticaldebt = facticaldebt,
             lastoverduedebt = overduedebt
       WHERE id# = contractid;
   END;

   FUNCTION iscapitalizationon
      RETURN BOOLEAN
   IS
      result   BOOLEAN;
   BEGIN
      result :=
          (sbcm_stored_programs.getreference ('cmrAutoCapitalization') = 'ON');
      RETURN result;
   END;

   FUNCTION iswithdrawon
      RETURN BOOLEAN
   IS
      result   BOOLEAN;
   BEGIN
      result :=
         (sbcm_stored_programs.getreference ('cmrAutoPaymentPercents') = 'ON');
      RETURN result;
   END;

   FUNCTION convertfloatableinterest (
      contractid     IN   sbcm_contracts.id%TYPE,
      dateinterval   IN   INTEGER
   )
      RETURN NUMBER
   IS
      result       NUMBER (18, 2)                            := 0.00;
      collection   sbcm_exports.collectionexporter%ROWTYPE;
      temp         NUMBER;
   BEGIN
      FOR collection IN sbcm_exports.collectionexporter (contractid)
      LOOP
         temp := getconverteddebt (
                    dateinterval,
                    collection.amount,
                    collection.PERCENT
                 );
         result :=   result
                   + temp;
      END LOOP;

      RETURN result;
   END;

   PROCEDURE setlastprocessdate (
      contractid   IN   sbcm_contracts.id%TYPE,
      convdate     IN   DATE
   )
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET lastprocessdate = convdate
       WHERE id# = contractid;
   END;

   PROCEDURE updatestatecache (
      contractid            IN   sbcm_contracts.id%TYPE,
      interestdebt          IN   NUMBER,
      overdueinterestdebt   IN   NUMBER
   )
   IS
   BEGIN
      UPDATE sbcm_state_cache
         SET facticalinterest = interestdebt,
             overdueinterest = overdueinterestdebt
       WHERE id# = contractid;
   END;

   FUNCTION getconverteddebt (
      dateinterval   IN   INTEGER,
      debt           IN   NUMBER,
      PERCENT        IN   NUMBER
   )
      RETURN NUMBER
   IS
      result           NUMBER (18, 2);
      daysofbankyear   INTEGER        := 360;
   BEGIN
     -- daysofbankyear := sbcm_stored_programs.getreference ('cmrYearDayCount');
      result :=   (debt * PERCENT * dateinterval)
                / (daysofbankyear * 100);
      RETURN result;
   END;

   FUNCTION getdateinterval (firstdate IN DATE, lastdate IN DATE)
      RETURN INTEGER
   IS
      result          INTEGER;
      currentmonth    DATE;
      MONTH           DATE    := firstdate;
      monthinterval   INTEGER;
      mounthindex     INTEGER;
      lastmonthday    INTEGER;
   BEGIN
      IF firstdate >= lastdate
      THEN
         result := 0;
      ELSE
         result := (  lastdate
                    - firstdate
                   );
         monthinterval := (  lastdate
                           - firstdate
                          ) / 30;

         FOR monthindex IN 0 .. monthinterval
         LOOP
            currentmonth := LAST_DAY (MONTH);
            lastmonthday := TO_NUMBER (TO_CHAR (currentmonth, 'DD'));

            IF  (currentmonth <= lastdate) AND (currentmonth > firstdate)
            THEN
               IF lastmonthday = 31
               THEN
                  result :=   result
                            - 1;
               END IF;

               IF lastmonthday = 28
               THEN
                  result :=   result
                            + 2;
               END IF;

               IF lastmonthday = 29
               THEN
                  result :=   result
                            + 1;
               END IF;
            END IF;

            MONTH := ADD_MONTHS (MONTH, 1);
         END LOOP;
      END IF;

      RETURN result;
   END;

   PROCEDURE increaseinterestdebt (
      contractid                     IN   sbcm_contracts.id%TYPE,
      facticalinterestdebtincrease   IN   NUMBER,
      overdueinterestdebtincrease    IN   NUMBER,
      INTPRECISIONincrease           in number
   )
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET facticalinterestdebt =
                          facticalinterestdebt
                        + facticalinterestdebtincrease,
             overdueinterestdebt =
                            overdueinterestdebt
                          + overdueinterestdebtincrease
       WHERE id# = contractid;
       
       update sbcm_deposit_interests
       set interest = facticalinterestdebtincrease, 
           overdureinterest = overdueinterestdebtincrease, 
           intprecision = INTPRECISIONincrease
       where id# = contractid;
       
   END;

   FUNCTION convertpercents (
      contractid    IN   sbcm_contracts.id%TYPE,
      convertdate   IN   DATE
   )
      RETURN INTEGER
   IS
      firstdate               DATE;
      lastdate                DATE;
      dateinterval            INTEGER;
      convertedfacticaldebt   NUMBER (15, 2)        := 0;
      convertedoverduedebt    NUMBER (15, 2)        := 0;
      facticaldebt            NUMBER (15, 2);
      overduedebt             NUMBER (15, 2);
      PERCENT                 NUMBER;
      overduepercent          NUMBER;
      debtamount              NUMBER (15, 2);
      creditamount            NUMBER (15, 2);
      lamount                 NUMBER (15, 2);
      interestaccid           ACCOUNT.id%TYPE;
      overdueinterestaccid    ACCOUNT.id%TYPE;
      incomeinterestaccid     ACCOUNT.id%TYPE;
      tempid                  NUMBER;
      transid                 NUMBER;
      contractcurrency        avalute.valute%TYPE;
   BEGIN
      facticaldebt := sbcm_stored_programs.getfacticaldebt (contractid);
      overduedebt := sbcm_stored_programs.getoverduedebt (contractid);

      IF    ((facticaldebt = 0) AND (overduedebt = 0))
         OR (NOT sbcm_stored_programs.iscalculationenabled (contractid))
      THEN
         raise_application_error (
            -20207,
            '((FacticalDebt = 0.00)AND(OverdueDebt = 0.00)) OR Calculation Disabled!'
         );
      END IF;

      firstdate := sbcm_stored_programs.getlastprocessdate (contractid);
      lastdate := convertdate;

      IF firstdate >= lastdate
      THEN
         raise_application_error (-20206, 'Invalid Convertion Date!');
      END IF;

      dateinterval := getdateinterval (firstdate, lastdate);
      contractcurrency :=
                         sbcm_stored_programs.getcontractcurrency (contractid);
      PERCENT := sbcm_stored_programs.getpercent (contractid);
      overduepercent := sbcm_stored_programs.getoverduepercent (contractid);
      incomeinterestaccid :=
            sbcm_stored_programs.getselectedaccid (
               contractid,
               'inComeAccForInterests'
            );
      tempid := sb_transaction.gen_temp_id ();

      -- Converting Main Debt --

      IF facticaldebt <> 0
      THEN
         interestaccid := sbcm_stored_programs.getinterestaccid (contractid);
         convertedfacticaldebt :=
                       getconverteddebt (dateinterval, facticaldebt, PERCENT);

         IF contractcurrency = 0
         THEN
            debtamount := ROUND (convertedfacticaldebt);
            creditamount := ROUND (convertedfacticaldebt);
         ELSE
            debtamount := convertedfacticaldebt;
            creditamount := convertedfacticaldebt;
         END IF;

         lamount := NULL;
         transid :=
               sb_transaction.transaction_add (
                  debitid=> interestaccid,
                  creditid=> incomeinterestaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> lamount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=> 'Щесабланмыш фаизля?дян ?яли?',
                  flags => 0,
                  tempid=> tempid,
                  transactiondate=> convertdate
               );
      END IF;

      IF overduedebt <> 0
      THEN
         overdueinterestaccid :=
                    sbcm_stored_programs.getoverdueinterestaccid (contractid);
         convertedoverduedebt :=
                 getconverteddebt (dateinterval, overduedebt, overduepercent);

         IF contractcurrency = 0
         THEN
            debtamount := ROUND (convertedoverduedebt);
            creditamount := ROUND (convertedoverduedebt);
         ELSE
            debtamount := convertedoverduedebt;
            creditamount := convertedoverduedebt;
         END IF;

         lamount := NULL;
         transid :=
               sb_transaction.transaction_add (
                  debitid=> overdueinterestaccid,
                  creditid=> incomeinterestaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> lamount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=> ' Мцддяти кечмиш фаизля?ин Щесабланмасындан  ?яли?',
                  flags => 0,
                  tempid=> tempid,
                  transactiondate=> convertdate
               );
      END IF;

      updatestatecache (
         contractid,
         convertedfacticaldebt,
         convertedoverduedebt
      );
      increaseinterestdebt (
         contractid,
         convertedfacticaldebt,
         convertedoverduedebt,0
      );
      setlastprocessdate (contractid, convertdate);
      COMMIT;
      RETURN tempid;
   END;

   FUNCTION getlastdate (
      contractid       IN   sbcm_contracts.id%TYPE,
      convertingdate   IN   DATE
   )
      RETURN DATE
   IS
      result      DATE;
      closedate   DATE;
   BEGIN
      closedate := sbcm_stored_programs.sbcmgetolddate (contractid);

      IF convertingdate = closedate
      THEN
         result :=
                 convertingdate
               + sbcm_stored_programs.booltoint (
                    sbcm_stored_programs.usingright
                 );
      ELSE
         result := convertingdate;
      END IF;

      RETURN result;
   END;

   FUNCTION converdeposits (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE,
      TransactionFlag in integer default 0,
      ShowErrMsg  in boolean default true
   )
      RETURN INTEGER
   /*
      Result :
               1 - Capitalization Added ;
               2 - Interests Withdrawed ;
               0 - No Operation Processed;
   */
   IS
      outcomeforinterestaccid       INTEGER;
      interestaccid                 INTEGER;
      contractaccid                 INTEGER;
      facticaldebt                  NUMBER  := 0;
      converteddebt                 NUMBER  := 0;
      debtamount                    NUMBER  := 0;
      creditamount                  NUMBER  := 0;
      firstdate                     DATE;
      lastdate                      DATE;
      dateinterval                  INTEGER;
      PERCENT                       NUMBER ;
      transactionid                 INTEGER;
      contractnum                   VARCHAR2 (256);
      additionaldeposittypea        VARCHAR2 (32);
      additionaldeposittype         VARCHAR2 (32);
      lastwcdate                    DATE;
      wcinterval                    INTEGER;
      daysprocessed                 INTEGER;
      TEMPORARY                     INTEGER;
      actualwcdate                  DATE;
      interestbeforewc              NUMBER  := 0;
      interestafterwc               NUMBER  := 0;
      transactiononcapitalization   BOOLEAN;
      transactiononwithdraw         BOOLEAN;
      totalinterest                 NUMBER  := 0;
      processwc                     BOOLEAN        := FALSE;
      result                        INTEGER;
      intprec                       number;
      CalcAccRate                   Number;

   BEGIN
    SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
      /* ----  Initialization  ---- */
      result := 0;
      facticaldebt := sbcm_stored_programs.getfacticaldebt (contractid); -- Main Debt
      outcomeforinterestaccid :=
            sbcm_stored_programs.getselectedaccid (
               contractid,
               'outComeAccForDeposit'
            ); -- Out come Account for Deposit
      additionaldeposittypea :=
          LOWER (sbcm_stored_programs.getadditionaldeposittypea (contractid));
      additionaldeposittype :=
           LOWER (sbcm_stored_programs.getadditionaldeposittype (contractid));
      PERCENT := sbcm_stored_programs.getpercent (contractid); -- Percent 
      interestaccid := sbcm_stored_programs.getinterestaccid (contractid); -- Interest Account 
      contractaccid := sbcm_stored_programs.getcontractaccid (contractid);
      --contractnum := sbcm_stored_programs.get_contractaccount(sbcm_stored_programs.GetContractAccID(contractid));  --sbcm_stored_programs.contractnumasvarchar2 (contractid);  Number of Account
      firstdate := sbcm_stored_programs.getlastprocessdate (contractid); -- Lats Process Date of Contract
      lastdate := hdate; -- Convertion Date
      transactiononcapitalization :=
            (sbcm_stored_programs.getreference (
                'cmrTransactionOnCapitalization'
             ) = 'ON'
            );
      transactiononwithdraw :=
            (sbcm_stored_programs.getreference ('cmrTransactionOnWithdraw') =
                                                                         'ON'
            );
      wcinterval := sbcm_stored_programs.getwcdateinterval (contractid);
      lastwcdate := sbcm_stored_programs.getlastwcdate (contractid);
      daysprocessed := getdateinterval (lastwcdate, hdate);

      select intprecision into intprec
      from sbcm_deposit_interests where id# = contractid;
      
      select contractno into contractnum
      from sbcm_contracts
      where id = contractid;
 

      /* ---- End Initialization ---- */

      /*  Checking  Validate  */
      IF (facticaldebt = 0)and(CalcAccRate = 1)
      THEN
         raise_application_error (-20207, 'Contract has not Rests .^');
      END IF;

      IF NOT sbcm_stored_programs.iscalculationenabled (contractid)
      THEN
         raise_application_error (
            -20207,
            'Calculation Percents is Disabled .^'
         );
      END IF;

      IF firstdate >= lastdate
      THEN
         raise_application_error (-20206, 'Invalid Convertion Date . ^');
      END IF;

      IF      (additionaldeposittype = 'collection')
          AND (   (    (additionaldeposittypea = 'capitalization')
                   AND iscapitalizationon
                  )
               OR ((additionaldeposittypea = 'withdraw') AND iswithdrawon)
              )
      THEN
         raise_application_error (
            -20287,
            '%Can not Perform this operation for Collection Deposits.^'
         );
      END IF;

      /*   End  Checking  Validate  */

      /* Converting Interest */

      IF  not(    (   iscapitalizationon
               OR iswithdrawon
              )
          AND (wcinterval > 0)
          AND (daysprocessed >= wcinterval))
      THEN
      
               converteddebt := 
                          CalcPercent(
                           facticaldebt,
                           PERCENT,
                           getdateinterval (firstdate, lastdate)
                           )+intprec;
                          
         IF additionaldeposittype = 'collection'
         THEN
            converteddebt :=
                       converteddebt
                      + convertfloatableinterest (
                           contractid,
                           getdateinterval (firstdate, lastdate))+intprec;
         END IF;

         increaseinterestdebt (contractid, 

                               sbcmPrecision2(converteddebt), 
                               0,
                               sbcmPrecision7(converteddebt));
        ELSE

         TEMPORARY :=   daysprocessed
                      - wcinterval;
         actualwcdate :=   hdate
                         - TEMPORARY;
         interestbeforewc := getconverteddebt (
                                getdateinterval (firstdate, actualwcdate),
                                facticaldebt,
                                PERCENT
                             )+intprec;

         IF  additionaldeposittypea = 'capitalization' AND iscapitalizationon
         THEN
            increaseinterestdebt (
                             contractid, 
                             sbcmPrecision2(interestbeforewc), 
                             0,
                             sbcmPrecision7(interestbeforewc));
            totalinterest :=
                    sbcm_stored_programs.getfacticalinterestdebt (contractid);
            processwc := TRUE;
            interestafterwc := getconverteddebt (
                                  getdateinterval (actualwcdate, lastdate),
                                    facticaldebt
                                  + totalinterest,
                                  PERCENT
                               )+intprec;
            increaseinterestdebt (
                          contractid, 
                          sbcmPrecision2(interestafterwc), 0,
                          sbcmPrecision7(interestafterwc));
            result := 1;
         ELSIF  additionaldeposittypea = 'withdraw' AND iswithdrawon
         THEN

            increaseinterestdebt (contractid, sbcmPrecision2(interestafterwc), 0,0);
            totalinterest :=
                    sbcm_stored_programs.getfacticalinterestdebt (contractid);
            processwc := TRUE;
            interestafterwc := getconverteddebt (
                                  getdateinterval (actualwcdate, lastdate),
                                  facticaldebt,
                                  PERCENT
                               )+intprec;
            increaseinterestdebt (contractid
                                 ,sbcmPrecision2(interestafterwc), 
                                 0,
                                 sbcmPrecision7(interestafterwc));
            result := 2;
         END IF;

         updatelastwcdate (contractid, actualwcdate);
         converteddebt :=   interestafterwc
                          + interestbeforewc;

      END IF;

      debtamount := sbcmPrecision2(converteddebt);
      
      creditamount := NULL;

     -- raise_application_error(-20007,'debtamount = '||debtamount);
      IF debtamount <> 0
      THEN
         transactionid :=
               sb_transaction.transaction_add (
                  debitid=> outcomeforinterestaccid,
                  creditid=> interestaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> NULL,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    'Депозитля?ин фаиз щесаб № '
                           || contractnum||' -'||firstdate||'-'||lastdate,
                  flags => TransactionFlag,
                  transactiondate=> hdate
               );
      END IF;

      updDepositInr(contractid,transactionid);

      setlastprocessdate (contractid, hdate);
      sbcm_stored_programs.sbdmsettotalpercents (contractid, converteddebt);

      IF processwc
      THEN
   --    Raise_application_error(-20007,'Salam');

         IF additionaldeposittypea = 'capitalization'
         THEN
            sbcm_payment.capitalization (
               contractid,
               hdate,
               totalinterest,
               transactiononcapitalization
            );
         ELSIF additionaldeposittypea = 'withdraw'
         THEN

            sbcm_payment.withdrawmoney (
               contractid,
               SBCM_STORED_PROGRAMS.GetClientAccID(ContractID),
               hdate,
               0,
               totalinterest,
               transactiononwithdraw,
               False
            );
         END IF;
         commit work;
      END IF;
   
   
       sbcm_prolongation.auto_Prolongation(ContractID);
      COMMIT;

          RETURN result;
  
    /* exception when OTHERS then
     begin
       rollback work;
     
       if ShowErrMsg then
          Raise;
       end if; 
    end;   */
          

   END;

