   PROCEDURE convertinglazypercents (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE
   )
   IS
      firstdate               DATE;
      lastdate                DATE;
      dateinterval            INTEGER;
      convertedfacticaldebt   NUMBER (15, 2);
      convertedoverduedebt    NUMBER (15, 2);
      facticaldebt            NUMBER (15, 2);
      overduedebt             NUMBER (15, 2);
      PERCENT                 NUMBER (7, 2);
      overduepercent          NUMBER (7, 2);
      finterestdebt           NUMBER (18, 2);
      ointerestdebt           NUMBER (18, 2);
      lfacticaldebt           NUMBER (18, 2);
      loverduedebt            NUMBER (18, 2);
--      DecimialKind            BOOLEAN := FALSE;
      CalcDecimials           Integer := 2;
   BEGIN
   SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
      facticaldebt := sbcm_stored_programs.getfacticaldebt (contractid);
      overduedebt := sbcm_stored_programs.getoverduedebt (contractid);
      
      CalcDecimials :=2;-- TO_NUMBER(sbcm_stored_programs.getreference('cmrCalcDecimials'));
  --    DecimialKind := sbcm_stored_programs.getreference('cmrCalcDecimialsKind') = 'ON';
      
      IF    ((facticaldebt = 0) AND (overduedebt = 0))
         OR (NOT sbcm_stored_programs.iscalculationenabled (contractid))
      THEN
         raise_application_error (
            -20207,
            '((FacticalDebt = 0.00)AND(OverdueDebt = 0.00)) OR Calculation Disabled!'
         );
      END IF;

      SELECT facticalinterestdebt, overdueinterestdebt
        INTO finterestdebt, ointerestdebt
        FROM sbcm_contract_state
       WHERE id# = contractid;

      if sbcm_stored_programs.usingleft then
       
      SELECT facticaldebt, overduedebt
        INTO lfacticaldebt, loverduedebt
        FROM sbcm_contract_state
       WHERE id# = contractid;
      else
        lfacticaldebt := facticaldebt;
        loverduedebt := overduedebt;
      end if;
      firstdate := sbcm_stored_programs.getlastprocessdate (contractid);
      lastdate := hdate;

      IF firstdate >= lastdate
      THEN
         raise_application_error (-20206, 'Invalid Convertion Date!');
      END IF;

      dateinterval := getdateinterval (firstdate, lastdate);
      PERCENT := sbcm_stored_programs.getpercent (contractid);
      overduepercent := sbcm_stored_programs.getoverduepercent (contractid);


      -- Converting Main Debt --

      IF facticaldebt <> 0 or lFacticalDebt <> 0
      THEN
--      if not DecimialKind then
         convertedfacticaldebt :=
               ROUND (
                    getconverteddebt (
                       getdateinterval (  lastdate
                                        - 1, lastdate),
                       facticaldebt,
                       PERCENT
                    )
                  + getconverteddebt (
                       getdateinterval (firstdate,   lastdate
                                                   - 1),
                       lfacticaldebt,
                       PERCENT
                    ),CalcDecimials
                  
                                 );
         if   ROUND (
                        (  convertedfacticaldebt
                         + finterestdebt
                        ),
                        CalcDecimials
                     ) <> 0 then    
         postdifferedtransaction (
            contractid=> contractid,
            balanceinterest=> ROUND (
                        (  convertedfacticaldebt
                         + finterestdebt
                        ),
                        CalcDecimials
                     )
         );
         end if;
      END IF;

      IF overduedebt <> 0 or lOverdueDebt <> 0
      THEN
         convertedoverduedebt :=
               ROUND (
                    getconverteddebt (
                       getdateinterval (  lastdate
                                        - 1, lastdate),
                       overduedebt,
                       overduepercent
                    )
                  + getconverteddebt (
                       getdateinterval (firstdate,   lastdate
                                                   - 1),
                       loverduedebt,
                       overduepercent
                    ),
                  CalcDecimials
               );
         if ROUND (
                        (  convertedoverduedebt
                         + ointerestdebt
                        ),
                        CalcDecimials
                     ) <> 0 then       
         postdifferedtransaction (
            contractid=> contractid,
            balanceinterest=> ROUND (
                        (  convertedoverduedebt
                         + ointerestdebt
                        ),
                        CalcDecimials
                     )
         );
         end if;
      END IF;

      COMMIT;
      
   END;

   PROCEDURE deldefferedtransactions
   IS
   BEGIN
      DELETE FROM sbcm_deffered_transactions;

      COMMIT;
   END;

   PROCEDURE applydefferedtransactions (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE
   )
   IS
      facticaldebt            NUMBER (18, 2);
      overduedebt             NUMBER (18, 2);
      finterestdebt           NUMBER (18, 2);
      ointerestdebt           NUMBER (18, 2);
      balanceinterest         NUMBER (18, 2);
      debitid                 INTEGER;
      creditid                INTEGER;
      debitamount             NUMBER (18, 2);
      creditamount            NUMBER (18, 2);
      lamount                 NUMBER (18, 2);
      binterest               NUMBER (18, 2);
      convertedfacticaldebt   NUMBER (18, 2) := 0;
      convertedoverduedebt    NUMBER (18, 2) := 0;
      transid                 INTEGER;
      pcid                    INTEGER;
      contractnum             VARCHAR2 (256);
   BEGIN
      creditid :=
            sbcm_stored_programs.getselectedaccid (
               contractid,
               'inComeAccForInterests'
            );
      facticaldebt := sbcm_stored_programs.getfacticaldebt (contractid);
      overduedebt := sbcm_stored_programs.getoverduedebt (contractid);
      
      setlastdebts (contractid);

      SELECT contractno
        INTO contractnum
        FROM sbcm_contracts
       WHERE id = contractid;

      SELECT facticalinterestdebt, overdueinterestdebt
        INTO finterestdebt, ointerestdebt
        FROM sbcm_contract_state
       WHERE id# = contractid;

      pcid := contractid;

      SELECT balanceinterest
        INTO binterest
        FROM sbcm_deffered_transactions
       WHERE contractid = pcid;

      IF facticaldebt <> 0
      THEN
         debitid := sbcm_stored_programs.getinterestaccid (contractid);
         debitamount :=   binterest
                        - finterestdebt;
         convertedfacticaldebt := debitamount;
      ELSE
         debitid := sbcm_stored_programs.getoverdueinterestaccid (contractid);
         debitamount :=   binterest
                        - ointerestdebt;
         convertedoverduedebt := debitamount;
      END IF;

      creditamount := debitamount;
      lamount := NULL;
      contractnum :=    'Щесабланмыш фаизля?дян ?яли? №'
                     || contractnum;

      IF debitamount <> 0
      THEN
         transid :=
               sb_transaction.transaction_add (
                  debitid=> debitid,
                  creditid=> creditid,
                  debitamount=> debitamount,
                  creditamount=> NULL,
                  lamount=> lamount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=> contractnum,
                  flags => 0,
                  transactiondate=> hdate
               );
      END IF;

      increaseinterestdebt (
         contractid,
         convertedfacticaldebt,
         convertedoverduedebt,0
      );
      setlastprocessdate (contractid, hdate);
      COMMIT;
   END;

   PROCEDURE updatelastwcdate (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE
   )
   IS
   BEGIN
      IF NOT hdate IS NULL
      THEN
         UPDATE sbcm_contract_state
            SET stopcalculationdate = hdate
          WHERE id# = contractid;
      END IF;
   END;

