   END;
   
   function sbcmPrecision7(p_Value in Number)
   return Number             
   is
     Result Number;
     Temp Number := p_Value;  
   begin
     Temp := Temp * 100 - Trunc(Temp * 100);
     Result := Temp / 100;
     return Result;
   end;
   
   function sbcmPrecision2(p_Value in Number)
   return Number             
   is
     Result Number;
     Temp Number := p_Value;  
   begin
     Temp := Temp * 100 - Trunc(Temp * 100);
     Result := p_Value - Temp / 100;
     return Result;
   end;

   
    function CalcPercent(
            p_Sum in Number,
            p_Rate in Number  ,
            p_Coefficient in Number ,
            p_Delimmer in Number default 360
            )
   return number       
   is
     Result Number (18,6);
   begin
     Result := ( p_Sum * p_Rate * p_Coefficient ) / ( p_Delimmer * 100 );
     return Result;
   end;  
   
   Procedure CancelDepositIntCalc(p_contractID in integer)
   is
   
     cursor c_state(cid in integer)
     is
     select 
        facticaldebt, 
        overduedebt, 
        facticalinterestdebt,
        overdueinterestdebt,
        stopcalculationdate,
        lastprocessdate, 
        calculationenabled,
        lastfacticaldebt,
        lastoverduedebt
     from sbcm_contract_state
     where id# = cid;
     
     cursor c_calcdeposit(cid in integer)
     is
     SELECT 
        hdate, 
        interest, 
        overdureinterest, 
        intprecision,
        dueintprecision, 
        inttrid, 
        dueinttrid,
        withdrawtrid
     FROM sbcm_deposit_interests
     where id# = cid;     
     
     StateInfo c_state%rowtype;
     CalcInfo c_calcdeposit%rowtype;
     
     intprec number;
     dueintprec number;
     
     inttrid  integer;
     dueinttrid  integer;
     withdrawtrid integer;
     Result integer;
     
        
   begin
        
     if sbcm_stored_programs.checkcontractstate(p_contractid) = -10 then     
     
     open c_state(p_contractID);
     fetch c_state into StateInfo;
     close c_state;

     open c_calcdeposit(p_contractID);
     fetch c_calcdeposit into CalcInfo;
     close c_calcdeposit;
     
     intprec := CalcInfo.intprecision;
     dueintprec := CalcInfo.dueintprecision;
     
     inttrid := CalcInfo.inttrid;
     dueinttrid := CalcInfo.dueinttrid; 
     withdrawtrid := CalcInfo.withdrawtrid; 
 --  raise_application_error(-20007,'Dedimmi = '||inttrid);
     
      if (inttrid is not null) and (transactionexist(inttrid))then
         SB_TRANSACTION.Transaction_Delete(IntTrID);        
      end if;
      
      if (DueIntTrID is not null) and (transactionexist(DueIntTrID)) then
        SB_TRANSACTION.Transaction_Delete(DueIntTrID);        
      end if;

      if (withdrawtrid is not null) and (transactionexist(withdrawtrid)) then
          SB_TRANSACTION.Transaction_Delete(withdrawtrid);
      end if;
      
     update sbcm_contract_state 
     set 
       lastprocessdate  = lastprocessdate - 1,
       facticalinterestdebt = facticalinterestdebt - CalcInfo.interest,
       overdueinterestdebt = overdueinterestdebt - CalcInfo.overdureinterest
     where ID# = p_contractID;  -- // New
      
    update sbcm_deposit_interests
       set 
           INTEREST = 0,
           INTTRID = null ,
           DUEINTTRID = null ,           
           intprecision = IntPrec ,
           DUEintprecision = DueIntPrec 
     where ID# = p_contractID; 
     
     Commit work;       
     end if;  
   end;       
   
   procedure updDepositInr(p_id in integer,trid in integer)
   is
   begin
   
      update sbcm_deposit_interests 
      set inttrid = trid
      where id#= p_id;
   
      commit;
   end;  
   
   function transactionexist(p_id in integer)
   return boolean
   is
   
   cursor c_pr(pid in integer)
   is 
   select id from provarch
   where id  = pid;

   cursor c_laz(pid in integer)
   is 
   select id from lazytransaction
   where id  = pid;
   
   pr c_pr%rowtype;
   laz c_laz%rowtype;
    
   Result boolean;
   
   begin
     
     open c_pr(p_id);
     fetch c_pr into pr;
     
     open c_laz(p_id);
     fetch c_laz into laz;
     
     result := (c_pr%found) or (c_laz%found);
     close c_pr;
     close c_laz;
      
     return result;  
   end;        
   
  function Get_DepositOverdueIntAmt(P_ContractID in integer)
   return number
   is
    Result number;
    DuePercent number; 
    TekDat date;
    Opendat date;
    DepAmount number;
   begin
     
     select tek_dat into TekDat from sysdat;
     
     select overdueinterest into duePercent
       from sbcm_overdueinterests
       where id# = P_ContractID;
       
      select opendate ,amount into opendat,DepAmount
      from sbcm_contracts
      where id = p_contractid;
      
      result := CalcPercent(
            p_Sum =>DepAmount,
            p_Rate => duePercent ,
            p_Coefficient=> getdateinterval(opendat,TekDat)
            );
       
      return result; 
   end;
   
   procedure CalcAllDeposits
   is
     
     
     cursor c_AllDeposits is
     select id from sbcm_contracts
     where type# = 3
     and id in (select id# from sbcm_contract_state
     where calculationenabled = 1);
     
     TekDat Date;
     flag integer;
     Result integer;
   begin
    select Tek_Dat 
           into TekDat from sysdat;
    flag := sbdecls.atfCommitImmediate;       
           
   for AllDeposits in c_AllDeposits
   loop
    
    Result := converdeposits (
      contractid => AllDeposits.id,
      hdate => TekDat,
      TransactionFlag => flag,
      ShowErrMsg => false
   );
   
   end loop;        
   
   end;

END;
--     :=SBCM_Stored_Programs.GetOpenDate(ContractID);
/


