CREATE OR REPLACE 
PACKAGE sbcm_period_reports
IS
   FUNCTION get_currency_ostat (p_id IN INTEGER, p_dat IN DATE)
      RETURN NUMBER;

  PROCEDURE initreportdata (
      bdat         IN   DATE,
      edat         IN   DATE,
      ffilterstr   IN   VARCHAR2,
      sfilterstr   IN   VARCHAR2
   );
  function concatfilter (s IN  VARCHAR2, prefix in VARCHAR2)
   return varchar2;
END;
/


CREATE OR REPLACE 
PACKAGE BODY             sbcm_period_reports
IS
   FUNCTION get_currency_ostat (p_id IN INTEGER, p_dat IN DATE)
      RETURN NUMBER
   IS
      CURSOR c_o
      IS
         SELECT ostat
           FROM operkurs
          WHERE val_kod = (SELECT val_acc
                             FROM ACCOUNT
                            WHERE ID = (SELECT contractaccid
                                          FROM sbcm_contract_accounts
                                         WHERE id# = p_id))
            AND dat = (SELECT MAX (dat)
                         FROM operkurs
                        WHERE dat <= p_dat);

      RESULT   NUMBER;
   BEGIN
      OPEN c_o;
      FETCH c_o INTO RESULT;
      CLOSE c_o;
      RETURN RESULT;
   END;

   FUNCTION get_contract_tranches (
      p_contractid   IN   INTEGER,
      bdat           IN   DATE,
      edat           IN   DATE
   )
      RETURN NUMBER
   IS
      RESULT   NUMBER;

      CURSOR c_tranche
      IS
         SELECT SUM (total * get_currency_ostat (p_contractid, hdate)
                    ) AS tramte
           FROM sbcm_tranches
          WHERE id# = p_contractid AND hdate BETWEEN bdat AND edat;
   BEGIN
      OPEN c_tranche;
      FETCH c_tranche INTO RESULT;
      CLOSE c_tranche;
   END;

   PROCEDURE initreportdata (
      bdat         IN   DATE,
      edat         IN   DATE,
      ffilterstr   IN   VARCHAR2,
      sfilterstr   IN   VARCHAR2
   )
   IS
      querystr   VARCHAR2 (2048);
      condstr    VARCHAR2 (1024);
      condstrs   VARCHAR2 (1024);
      RESULT     VARCHAR2 (1024);
   BEGIN
      COMMIT;
      RESULT := '';
      querystr :=
             '
      INSERT INTO sbcm_contract_hist
         SELECT id#, hdate, facticaldebt, facticalinterestdebt
           FROM sbcm_contract_history
          WHERE hdate IN ('''
          || (bdat)
          || ''','''
          || TO_DATE (edat)
          || ''')';

      IF LENGTH (ffilterstr) > 0
      THEN
         condstr := '  id# in (select id from sbcm_contracts cont where ';
         condstr := condstr || ffilterstr || ')';
      END IF;

      IF LENGTH (sfilterstr) > 0
      THEN
         condstrs := ' and ' || sfilterstr;
      END IF;

      RESULT := concatfilter (RESULT, sfilterstr);
      querystr := concatfilter (querystr, RESULT);
      querystr := concatfilter (querystr, condstr);
      EXECUTE IMMEDIATE querystr;

      INSERT INTO sbcm_payments_temp
         SELECT   id#, SUM (facticaldebt), SUM (interestdebt),
                  SUM (facticaldebt * get_currency_ostat (id#, hdate)),
                  SUM (interestdebt * get_currency_ostat (id#, hdate))
             FROM sbcm_payments
            WHERE hdate BETWEEN bdat AND edat
         GROUP BY id#;

      INSERT INTO sbcm_tranches_temp
         SELECT   id#, SUM (total),
                  SUM (total * get_currency_ostat (id#, hdate))
             FROM sbcm_tranches
            WHERE hdate BETWEEN bdat AND edat
         GROUP BY id#;
   END;

   FUNCTION concatfilter (s IN VARCHAR2, prefix IN VARCHAR2)
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (1024);
   BEGIN
      RESULT := s;

      IF (NVL (LENGTH (RESULT), 0) <> 0) AND (LENGTH (prefix) <> 0)
      THEN
         RESULT := RESULT || ' and ' || prefix;
      END IF;

      IF (NVL (LENGTH (RESULT), 0) = 0) AND (LENGTH (prefix) <> 0)
      THEN
         RESULT := prefix;
      END IF;

      RETURN RESULT;
   END;
END;
/


