CREATE OR REPLACE 
PACKAGE sbcm_prolongation
  IS					
  procedure  AddProlongation(
             ContractID IN  SBCM_Contracts.ID%type
						,HDate IN Date
						,NewDate IN Date
            );
  Procedure  DelLastProlongation(ContractID IN SBCM_Prolongations.ID%type);
  procedure auto_Prolongation(ContractID in integer);
END; -- Package spec
/


CREATE OR REPLACE 
PACKAGE BODY             sbcm_prolongation
IS	
procedure  UpdateCloseDate(
               ContractID IN SBCM_Contracts.ID%type
							,NewDate IN Date 
							)
 Is
 begin
   update  SBCM_Contracts 
	 Set
	   CloseDate = NewDate
	 Where 
	     ID = ContractID;	 
 end;
 		
procedure  DelProlongation(ProlongID IN SBCM_Prolongations.ID%type)
 Is
 
 cursor c_pr is
 SELECT  olddate, newdate
  FROM sbcm_prolongations
  where id  = ProlongID;
 
  prlng c_pr%rowtype;
   
 begin
    open c_pr;
    fetch c_pr into prlng;
    close c_pr;
    
   -- if prlng.newdate <>  
   
   Delete 
	   From SBCM_Prolongations
   Where  ID = ProlongID; 
 end;
  
Procedure  DelLastProlongation(ContractID IN SBCM_Prolongations.ID%type)
 Is
  cursor  LastProlongation(ContID SBCM_Contracts.ID%type) is
	Select
	  ID	 
	 ,OldDate From SBCM_Prolongations
	Where
	  ID = 	
	(select
	  Max(ID) From  SBCM_Prolongations
	 Where 
	   ID# = ContID);				
	
	
   p_ID   SBCM_Prolongations.ID%type;	
	 NewDate Date;	 
 begin
 SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
  Open  LastProlongation(ContractID);
	 Fetch  LastProlongation Into p_ID,NewDate;
	Close LastProlongation;	
	DelProlongation(p_ID);
	UpdateCloseDate(
	     ContractID
			,NewDate  
	    );
	commit;		
Exception  
   When  OTHERS  Then
	 begin
	   if LastProlongation%IsOpen  then
		   Close LastProlongation;
		 end if;
		Raise_Application_Error(-20199,'Error :Can not Delete Last Prolongation!');   
	 end;			 
 end;
 					 
Procedure  NewProlongation(
           p_ID#  IN  SBCM_Prolongations.ID#%type
					,p_HDate IN Date
					,p_OldDate IN Date					
					,p_NewDate IN Date  
					)	
 Is
 begin
   Insert Into  SBCM_Prolongations(
	               ID#
								,HDate
								,OldDate
								,NewDate 
	              )
                Values(
								 p_ID#
								,p_HDate
								,p_OldDate
								,p_NewDate  
          			);																
 end;
 --   Adding  New  Prolongation --
procedure  AddProlongation(
             ContractID IN  SBCM_Contracts.ID%type
						,HDate IN Date
						,NewDate IN Date
            )
 Is
   OldDate Date;
 begin
  SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
   OldDate :=SBCM_Stored_Programs.SBCMGetOldDate(
	                                ContractID
																	);   																	
   UpdateCloseDate(
	     ContractID
			,NewDate 
	    );																	
	 NewProlongation(
	     ContractID
			,HDate
			,OldDate
			,NewDate 
	    );
	commit;		
 end;	
 
 function checkProlongDate(ContractID in integer)
 return boolean
 is
  result boolean;
  clsdat Date;
  currdat date;
  preddat date;
 begin
    
    select tek_dat,pred_dat into currdat,preddat
    from sysdat;
    
    clsdat := SBCM_Stored_Programs.SBCMGetOldDate(ContractID);
    
    result := (clsdat = currdat) or 
              ((clsdat > preddat)and (clsdat < currdat));
    
    return result;
 end;	
 
 procedure auto_Prolongation(ContractID in integer)
 is
   TekDat Date;
   PredDat Date;
   OpnDat Date;
   ClsDat Date;
 begin
    select Tek_Dat ,Pred_Dat into
    TekDat,PredDat from sysdat;
    
    select opendate,closedate
    into OpnDat,ClsDat
    from sbcm_contracts
    where id = ContractID;
    
    ClsDat := ClsDat+MONTHS_BETWEEN(ClsDat,OpnDat);
    
    if checkProlongDate(ContractID) then
    
    AddProlongation(
             ContractID
			,TekDat
			,ClsDat
            );
    end if;    
end;
 				    
END;
/


