CREATE OR REPLACE 
PACKAGE BODY       sbcm_report
IS

  procedure report(
                    p_contractid in integer,
                    p_bdate date,
                    p_edate date
                   )
 is
 
  cursor c_currrest is
  select facticaldebt,
         facticaldebt*get_currency_ostat(p_contractid,p_bdate) as facticaldebtE, 
         facticalinterestdebt,
         facticalinterestdebt*get_currency_ostat(p_contractid,p_bdate) as facticalinterestdebtE
  FROM sbcm_contract_state
  where id#=p_contractid;
   
  cursor c_brest is
  SELECT facticaldebt, 
         facticaldebt*get_currency_ostat(p_contractid,hdate) as facticaldebtE,
         facticalinterestdebt,
         facticalinterestdebt*get_currency_ostat(p_contractid,hdate) as facticalinterestdebtE
  FROM SBCM_CONTRACT_HISTORY
  where id#=p_contractid 
  and hdate =(select max(hdate) from SBCM_CONTRACT_HISTORY where hdate<=p_bdate);

  cursor c_erest is
  SELECT facticaldebt, 
         facticaldebt*get_currency_ostat(p_contractid,hdate) as facticaldebtE,
         facticalinterestdebt,
         facticalinterestdebt*get_currency_ostat(p_contractid,hdate) as facticalinterestdebtE
  FROM SBCM_CONTRACT_HISTORY
  where id#=p_contractid 
  and hdate =(select max(hdate) from SBCM_CONTRACT_HISTORY where hdate<=p_edate);
 
  cursor c_tr is
  select sum(TOTAL) as tramt,
         sum(TOTAL*get_currency_ostat(p_contractid,hdate)) as tramtE
  from sbcm_tranches
  where id#=p_contractid
  and hdate between p_bdate and p_edate;
  
  cursor c_pay is
  select sum(FACTICALDEBT) as payamt,
         sum(FACTICALDEBT*get_currency_ostat(p_contractid,hdate)) as payamtE ,
         sum(INTERESTDEBT) as payintamt,
         sum(INTERESTDEBT*get_currency_ostat(p_contractid,hdate)) as payintamtE
  from sbcm_payments
  where id#=p_contractid
  and hdate between p_bdate and p_edate;
  
  cursor c_fil is
      select name  
    from filial
    where id=(select filial from account
    where id=(select contractaccid from sbcm_contract_accounts
    where id#=p_contractid));

  
  
    currrest c_currrest%rowtype;
    brest c_brest%rowtype;
    erest c_erest%rowtype;
    tr c_tr%rowtype;
    pay c_pay%rowtype;
    currdat  date;
    def    boolean;
    contno varchar2(50);
    contaccno varchar2(20);
    branchname varchar2(85):= ' ';
    categoryname varchar2(60);
    balno number;
    Per varchar2(40);
    opendat date;
    closedat date;
    using number;
    
 begin
    def:=false;
    
     balno:= sbcm_stored_programs.get_contract_BalNo(p_contractid);
     Per:= sbcm_stored_programs.get_period(p_contractid,p_edate);
     using:= sbcm_stored_programs.get_contract_curr_using(p_contractid);
     
     open c_fil;
     fetch c_fil into branchname;
     close c_fil;
    
    select contractno,OPENDATE,CLOSEDATE into contno,opendat,closedat
    from sbcm_contracts
    where id=p_contractid;
    
    
    select TRUECATEGORY into categoryname
    from sbcm_categories
    where id=(select clienttype from sbcm_contracts where id=p_contractid);
       
    select acc_no into contaccno
    from account
    where id = (select contractaccid 
    from sbcm_contract_accounts where id#=p_contractid);
    
    select tek_dat 
     into currdat from sysdat;
    
    if  currdat <> p_edate and currdat <> p_bdate then

        open c_brest;
        fetch c_brest into brest;
        close c_brest;

        open c_erest;
        fetch c_erest into erest;
        close c_erest;
        
    end if ;
    
    if currdat = p_bdate  then
    
        open c_currrest;
        fetch c_currrest into brest;
        close c_currrest;
           
    end if;

    if currdat = p_edate  then
    
        open c_currrest;
        fetch c_currrest into erest;
        close c_currrest;
           
    end if;
    

    open c_tr;
    fetch c_tr into tr;
    close c_tr;
    
    open c_pay;
    fetch c_pay into pay;
    close c_pay;
    
    insert into sbcm_deposit_sd1(
                contractno,
                opendat,
                closedat,
                accno, 
                balcn, 
                period,
                valute,
                brest, 
                brestek,
                bintrest,
                bintrestek, 
                TRAMT, 
                tramtek, 
                payamt,
                payamtek, 
                payintamt,
                payintamtek,
                erest, 
                erestek,
                eintrest,
                eintrestek,
                filialname, 
                catname)
   values(contno,
          opendat,
          closedat,
          contaccno,
          balno,
          per,
          using,
          nvl(brest.facticaldebt,0),
          nvl(brest.facticaldebtE,0),
          nvl(brest.facticalinterestdebt,0),
          nvl(brest.facticalinterestdebtE,0),
          nvl(tr.tramt,0),
          nvl(tr.tramtE,0),
          nvl(pay.payamt,0),
          nvl(pay.payamtE,0),
          nvl(pay.payintamt,0),
          nvl(pay.payintamtE,0),
          nvl(erest.facticaldebt,0),
          nvl(erest.facticaldebtE,0),
          nvl(erest.facticalinterestdebt,0),
          nvl(erest.facticalinterestdebtE,0),
          nvl(branchname ,'  '),
          nvl(categoryname,'  '));             
 
 end;
 
 function get_currency_ostat(p_id in integer,p_dat in date)
 return number
 is
 
 cursor c_o is
 select ostat
 from operkurs
 where val_kod=(select val_acc from account
 where id =(select contractaccid from sbcm_contract_accounts
 where id# = p_id))
 and dat =(select max(dat) from operkurs where dat<=p_dat);
 
 result number;
 
 begin
    
    open c_o;
    fetch c_o into result;
    close c_o;
    
    return result;   
 end;
                 
                 
  function Get_DepositBalance(p_ContractID in integer)   
  return number
  is
    result number;
  begin
     
     select bal_cn1 into result
     from account
     where id = (select contractaccid
     from sbcm_contract_accounts where id# = p_ContractID);
     
     return result;
  end;
  
    FUNCTION get_period (p_id IN INTEGER,p_dat in date)
      RETURN VARCHAR2
   IS
      cm       NUMBER;
      result   VARCHAR2 (56);

      CURSOR c_p
      IS
         SELECT bperiod, eperiod, NAME
           FROM sbcm_periods;
   BEGIN
      SELECT (  p_dat/*duedatefirstcontract*/
              - OPENDATE
             )
        INTO cm
        FROM sbcm_contracts
       WHERE id = p_id;

      FOR pr IN c_p
      LOOP
         IF  (cm >= pr.bperiod) AND (cm <= pr.eperiod)
         THEN
            result := pr.NAME;
            EXIT;
         END IF;
      END LOOP;

      RETURN result;
   END;

function get_persons(P_ContractID in integer)
return varchar2
 is
  result varchar2(12);

   cursor c_id is
   select personaltype
   from sbcm_contracts where id = p_contractid;
   
   cursor c_name(p_id in integer) is
   select NAME from sbcm_persons
   where id=p_id;
   pid integer;
begin

   open c_id;
   fetch c_id into pid;
   close c_id;
   
   open c_name(pid);
   fetch c_name into result;
   close c_name;
   return result;
end;
 
 function Get_DepositCurrency(P_ContractID in integer)
 return varchar2
 is
   result varchar2(4);
 begin
    select VAL_NAME into result
    from avalute where
    valute = P_ContractID;
    return result; 
 end;  
         
 function Get_DepositRest(P_ContractID in integer, p_dat in date)
 return number
 is
   result number;
 
  cursor c_currrest is
  select facticaldebt*get_currency_ostat(p_contractid,p_dat) as facticaldebtE 
  FROM sbcm_contract_state
  where id#=p_contractid;
   
  cursor c_brest is
  SELECT facticaldebt*get_currency_ostat(p_contractid,hdate) as facticaldebtE
  FROM SBCM_CONTRACT_HISTORY
  where id#=p_contractid 
  and hdate =(select max(hdate) from SBCM_CONTRACT_HISTORY where hdate<=p_dat);

 begin
    if p_dat = sbop.get_date then
       open c_currrest;
       fetch c_currrest into result;
       close c_currrest;
    else
       open c_brest; 
       fetch c_brest into result;
       close c_brest;
    end if;
    return result;     
 end;
   
 
 function Get_DepositTranche(P_ContractID in integer,p_bdat in date,p_edat in date)
 return number
 is
   result number;

  cursor c_tr is
  select sum(TOTAL*get_currency_ostat(p_contractid,hdate)) as tramtE
  from sbcm_tranches
  where id#=p_contractid
  and hdate between p_bdat and p_edat;
     
 begin
   
     open c_tr;
     fetch c_tr into result;
     close c_tr;
     
     return result;
 end;   
    

 function Get_Depositpayment(P_ContractID in integer,p_bdat in date,p_edat in date)
 return number
 is
   result number;

  cursor c_pay is
  select sum(FACTICALDEBT*get_currency_ostat(p_contractid,hdate)) as payamtE
  from sbcm_payments
  where id#=p_contractid
  and hdate between p_bdat and hdate;
     
 begin
   
     open c_pay;
     fetch c_pay into result;
     close c_pay;
     
     return result;
 end;   
          
 function Get_Depositintpayment(P_ContractID in integer,p_bdat in date,p_edat in date)
 return number
 is
   result number;

  cursor c_pay is
  select sum(INTERESTDEBT*get_currency_ostat(p_contractid,hdate)) as payamtE
  from sbcm_payments
  where id#=p_contractid
  and hdate between p_bdat and hdate;
     
 begin
   
     open c_pay;
     fetch c_pay into result;
     close c_pay;
     
     return result;
 end;   


 function get_depositInterest(P_ContractID in integer)
 return number
 is
   result number;
 begin
    select interest into result
    from sbcm_interests
    where id# = P_ContractID;
    return result;
 end;       
 
 function get_ContractCustomers(P_ContractID in integer)
 return varchar2
 is
  result varchar2(80);
 begin
    select name into result
    from customers
    where id =(select kli_id from account where id=(
    select contractaccid from sbcm_contract_accounts where id#= P_ContractID));
    return result;
 end; 
                   
END;
