/


CREATE OR REPLACE 
PACKAGE BODY                                     sbcm_reserve_cont
IS

   procedure  SetPrimaryReserve(
                 ContractID in integer ,
                 Value in integer 
                 )
   is
   begin
     update sbcm_contracts
     set 
       ReliabilityID = Value
     where 
       ID = ContractID;  
   end;
   
   procedure  SetSecondaryReserve(
                 ContractID in integer ,
                 Value in integer 
                 )
   is
   begin
     update sbcm_contracts
     set 
       OverdueReliabilityID = Value
     where 
       ID = ContractID;  
   end; 

   procedure  ChangePrimaryReserve(
                 ContractID in integer ,
                 HDate in date ,
                 newReserveID in integer ,
                 Amount in number ,
                 TransactionsON in boolean ,                 
                 ReserveOutTransactionID in out integer ,
                 ReserveInTransactionID  in out integer ,
                 commitOnChange in Boolean default FALSE                                    
                 )
   is
   oldReservePercent   number(5,2);
   newReservePercent   number(5,2);
   CreditRest number(17,2);
   AccForOutReserve Account.ID%type;
   ReserveAccID integer;
   ReserveBackAmount number(17,2);
   ReserveForwardAmount number(17,2);
   outTransactionDesc varchar2(64) := 'E??aeoy ae?ueiu? ?uoeeeao acaeaueu? ? ';
   inTransactionDesc  varchar2(64) := 'E??aeoy ae?ueiu? ?uoeeeao a?ou?ueu? ? ';    
   begin
     if  TransactionsON  then
     outTransactionDesc := outTransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);
     CreditRest := sbcm_stored_programs.getfacticaldebt(ContractID);
     oldReservePercent := sbcm_stored_programs.getreliabilitypercent(ContractID);
     newReservePercent := sbcm_stored_programs.getreservepercentbyID(newReserveID);     
     ReserveAccID := sbcm_stored_programs.getreserveaccID(ContractID);
     AccForOutReserve := sbcm_stored_programs.getselectedaccid(ContractID,'outComeAccForReserve');
     ReserveBackAmount := ROUND(CreditRest * oldReservePercent / 100 , 2 ); -- % --
     if  ReserveBackAmount > 0 then
     ReserveOutTransactionID := 
     SB_TRANSACTION.Transaction_Add (
                      DebitID  => ReserveAccID ,
                      CreditID => AccForOutReserve ,
                      DebitAmount => ReserveBackAmount ,
                      CreditAmount=> null ,
                      lAmount  => null ,
                      DebitRate  => 0 ,
                      CreditRate => 0 ,
                      trName => outTransactionDesc ,
                      flags  => 0 ,
                      TransactionDate => HDate
                     );
     end if;
     
     ReserveForwardAmount := ROUND((CreditRest + Amount) * newReservePercent / 100 , 2 ); -- % --
     inTransactionDesc := inTransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);     
     if  ReserveForwardAmount > 0 then
     ReserveOutTransactionID := 
     SB_TRANSACTION.Transaction_Add (
                      DebitID  => AccForOutReserve ,
                      CreditID => ReserveAccID ,
                      DebitAmount => null ,
                      CreditAmount=> ReserveForwardAmount ,
                      lAmount  => null ,
                      DebitRate  => 0 ,
                      CreditRate => 0 ,
                      trName => inTransactionDesc ,
                      flags  => 0 ,
                      TransactionDate => HDate
                     );
     end if;
     
     end if; --TransactionsON
     
     SetPrimaryReserve(ContractID , newReserveID);
     if  commitOnChange  then  commit;  end if;
    
   end;  

   procedure  ChangeSecondaryReserve(
                 ContractID in integer ,
                 HDate in date ,
                 newReserveID in integer ,
                 Amount in number ,
                 TransactionsON in boolean ,                 
                 ReserveOutTransactionID in out integer ,
                 ReserveInTransactionID  in out integer ,
                 commitOnChange in Boolean default FALSE                                    
                 )
   is
   oldReservePercent   number(5,2);
   newReservePercent   number(5,2);
   CreditRest number(17,2);
   AccForOutReserve Account.ID%type;
   ReserveAccID integer;
   ReserveBackAmount number(17,2);
   ReserveForwardAmount number(17,2);
   outTransactionDesc varchar2(96) := 'Y??eeae?eeie? e??aeoy ae?ueiu? ?uoeeeao acaeaueu? ? ';
   inTransactionDesc  varchar2(96) := 'Y??eeae?eeie? e??aeoy ae?ueiu? ?uoeeeao a?ou?ueu? ? ';    
   begin
     if  TransactionsON  then
     outTransactionDesc := outTransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);
     CreditRest := sbcm_stored_programs.getoverduedebt(ContractID);
     oldReservePercent := sbcm_stored_programs.getoverduereliabilitypercent(ContractID);
     newReservePercent := sbcm_stored_programs.getreservepercentbyID(newReserveID);     
     ReserveAccID := sbcm_stored_programs.getoverduereserveaccID(ContractID);
     AccForOutReserve := sbcm_stored_programs.getselectedaccid(ContractID,'outComeAccForExpReserve');
     ReserveBackAmount := ROUND(CreditRest * oldReservePercent / 100 , 2 ); -- % --
     if  ReserveBackAmount > 0 then
     ReserveOutTransactionID := 
     SB_TRANSACTION.Transaction_Add (
                      DebitID  => ReserveAccID ,
                      CreditID => AccForOutReserve ,
                      DebitAmount => ReserveBackAmount ,
                      CreditAmount=> null ,
                      lAmount  => null ,
                      DebitRate  => 0 ,
                      CreditRate => 0 ,
                      trName => outTransactionDesc ,
                      flags  => 0 ,
                      TransactionDate => HDate
                     );
     end if;
     
     ReserveForwardAmount := ROUND((CreditRest + Amount) * newReservePercent / 100 , 2 ); -- % --
     inTransactionDesc := inTransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);     
     if  ReserveForwardAmount > 0 then
     ReserveOutTransactionID := 
     SB_TRANSACTION.Transaction_Add (
                      DebitID  => AccForOutReserve ,
                      CreditID => ReserveAccID ,
                      DebitAmount => null ,
                      CreditAmount=> ReserveForwardAmount ,
                      lAmount  => null ,
                      DebitRate  => 0 ,
                      CreditRate => 0 ,
                      trName => inTransactionDesc ,
                      flags  => 0 ,
                      TransactionDate => HDate
                     );
     end if;
     
     end if; --TransactionsON
     
     SetSecondaryReserve(ContractID , newReserveID);
     if  commitOnChange  then  commit;  end if;
    
   end;  

  procedure ChangeReserve(
            ContractID in integer ,
            HDate in date ,
            newReserveID in integer ,
            newExpiredReserveID in integer ,
            changePReserve in boolean ,
            changeSReserve in boolean ,
            TransactionsON in boolean     
            )
   is
   InTransactionID integer;
   OutTransactionID integer;
   begin
   SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
     if changePReserve then
     ChangePrimaryReserve(
           ContractID ,
           HDate ,
           newReserveID ,
           0 ,
           TransactionsON ,
           InTransactionID ,
           OutTransactionID    
           ); 
     end if;
     if changeSReserve then
     ChangeSecondaryReserve(
           ContractID ,
           HDate ,
           newExpiredReserveID ,
           0 ,
           TransactionsON ,
           InTransactionID ,
           OutTransactionID    
           ); 
     end if;

     commit;
     
   end;
            
   function CorrectReserve(ContractID in Integer)
   return integer  --Error Code   
   is
   
     cursor c_LastTranchDate(ContractID# in Integer) is
     select Max(HDate) as TranchDate
     from sbcm_tranches
     where ID# = ContractID#;  
   
     ReserveAccID Integer;
     ExpenceAccID Integer;
     LoanAmount   Number(18,2);
     ReserveRate  Number;
     
     OverdueReserveAccID Integer;
     OverdueExpenceAccID Integer;
     OverdueLoanAmount   Number(18,2);
     OverdueReserveRate  Number;
     
     LoanCurrency Integer;
     OldRate Operkurs.ostat%type;
     NewRate Operkurs.ostat%type;
     DeltaRate Operkurs.ostat%type;
     DeltaReserve Number(18,2);
     LastTranchDate c_LastTranchDate%rowtype;
     CurrentBankDate Date;
     PrevBankDate Date;
     DebitAccID Integer;
     CreditAccID Integer;
     TempTrID Integer;
     TransactionDesc varchar2(255) := '?uoeeeaoea?ui e?ieayi ?eeiyoeyiae?eeiy?e';          
     Result Integer := 0; -- 0  Succes
     
   begin
   
     LoanCurrency := 
     sbcm_stored_programs.getcontractcurrency(
                           contractid
                           );
                           
     if LoanCurrency = 0 then
        return -64; --  Loan Is In National Currency 
     end if;
           
     select TEK_DAT,PRED_DAT 
     into CurrentBankDate ,PrevBankDate
     from SYSDAT;
                     
     LoanAmount :=
     sbcm_stored_programs.getfacticaldebt(
                           contractid
                           );
     ReserveRate :=
     sbcm_stored_programs.getreliabilitypercent(
                           contractid
                           );    
     ReserveAccID := 
     sbcm_stored_programs.getreserveaccid(
                           contractid
                           );
     ExpenceAccID := 
     sbcm_stored_programs.getselectedaccid(
                           contractid,
                           'outComeAccForReserve'
                           );
                                                           
     /*open c_LastTranchDate(contractid);
     fetch c_LastTranchDate into LastTranchDate;
       if c_LastTranchDate%notfound then
         raise_application_error(-20032,'No Tranches Found');
       end if;
     close c_LastTranchDate;
     */                      
     select Ostat into OldRate
     from Operkurs
     where Dat = PrevBankDate and--LastTranchDate.TranchDate and
           Val_Kod = LoanCurrency;                             
     
     select Ostat into NewRate
     from Operkurs
     where Dat = CurrentBankDate and                             
           Val_Kod = LoanCurrency;                             
     
     DeltaRate := NewRate - OldRate;
     
     DeltaReserve := Round(LoanAmount * DeltaRate * ReserveRate / 100 ,2);
     
     if DeltaReserve > 0 then
        DebitAccID := ExpenceAccID;
        CreditAccID := ReserveAccID; 
     elsif DeltaReserve < 0 then
        DebitAccID := ReserveAccID;
        CreditAccID := ExpenceAccID;         
     else 
        return -32;--Succes But No Transactions                                                     
     end if;
     
     TempTrID :=
     SB_TRANSACTION.Transaction_Add (
                    DebitID  => DebitAccID ,
                    CreditID => CreditAccID ,
                    DebitAmount => DeltaReserve ,
                    CreditAmount=> DeltaReserve ,
                    lAmount  => null ,
                    DebitRate  => 0 ,
                    CreditRate => 0 ,
                    trName => TransactionDesc ,
                    flags  => 0 ,
                    TransactionDate => CurrentBankDate
                   );
   
                                  
     return Result; -- Succes Transaction Processed
          
   end;  
   
   function CorrectReserves
   return Integer
   is
   
     cursor c_AllActiveCredits is
     select ID 
     from SBCM_Contracts
     where TYPE# = 1;
     
     TempResult Integer;
      
     Result Integer := 0;
   begin
     for AllActiveCredits in c_AllActiveCredits
     loop
     
       TempResult :=
       CorrectReserve(AllActiveCredits.ID);
       if TempResult = 0 then
         Result := Result + 1;
       end if;
        
     end loop;
     
     commit work;
     
     return Result;
   end;  
    
END;
/


