  return  VarChar2;
  function  SBCMGetAccName(AccID IN Account.ID%type) return VarChar2;
  function  SBCMGetOldDate(ContractID IN SBCM_Contracts.ID%type)
  return Date;
  procedure  AddMovieName(
            p_TypeID IN SBCM_MOVIE_NAMES.TypeID%type					 	
           );
  procedure  DelMovieName(
            p_TypeID IN  SBCM_Movie_Names.TypeID%type  
           );
