  return  Account.ID%type;
  Function GetContractAccID(ContractID IN SBCM_Contracts.ID%type)
  return  Account.ID%type;
  Function GetInterestAccID(ContractID IN SBCM_Contracts.ID%type)
  return  Account.ID%type;
  Function GetOverdueAccID(ContractID IN SBCM_Contracts.ID%type)
  return  Account.ID%type;
  Function GetOverdueInterestAccID(ContractID IN SBCM_Contracts.ID%type)
  return  Account.ID%type;
  Function GetReserveAccID(ContractID IN SBCM_Contracts.ID%type)
  return  Account.ID%type;
  Function  GetFacticalDebt(ContractID IN SBCM_Contracts.ID%type)
  return  Number;
