function  GetSelectedAccID(
           ContractID IN SBCM_Contracts.ID%type
					,SettingName IN SBCM_Movie_Names.Name%type 
          ) return Account.ID%type
 Is
   CategoryID Number;
	 p_ParentID Number;
	 p_CurrencyID Number;
	 brid integer;
	 Result Account.ID%type;
 begin 
   p_CurrencyID :=GetContractCurrency(ContractID);
   CategoryID :=GetClientCategoryFromID(ContractID);

   select branchid into brid
   from sbcm_contracts where id =ContractID;
   

	 p_ParentID :=GetMovieIDByName(CategoryID,SettingName);
	 --Result :=GetAccIDFromSettings(ParentID,CurrencyID);
	 
	 select accid into Result
	 from sbcm_settings
	 where parentid = p_ParentID
	 and CurrencyID = p_CurrencyID
	 and branchid = brid;
	 
	 
	 if  Result is Null  then
	   RAISE_APPLICATION_ERROR(-20076,'Selected AccID  Not Found!^');
	 end if; 
	 return Result;
	 	 
 end;	

 				
