procedure DisableCalculation(
             ContractID IN SBCM_Contracts.ID%type
            )
 Is
 begin
 SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
   Update SBCM_Contract_State
	 Set
	   CalculationEnabled = 0
	 Where  ID# = ContractID;
	 commit; 	 
 end;						
procedure EnableCalculation(
             ContractID IN SBCM_Contracts.ID%type
            )
 Is
 begin
 SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
   Update SBCM_Contract_State
	 Set
	   CalculationEnabled = 1
	 Where  ID# = ContractID;
	 commit; 	 
 end;						

Function  CheckContractState(ContractID IN SBCM_Contracts.ID%type)
  return Integer
 Is
   --CloseDate Date;
   LastProcessDate Date;
   CurrentDate Date;
   Result Integer :=-9;  -- S_OK
 Begin
    CurrentDate :=GetBankDate;
    LastProcessDate :=GetLastProcessDate(ContractID);
    --CloseDate :=SBCMGetOldDate(ContractID); 
    if   not IsCalculationEnabled(ContractID)  then
      Result :=-11;  --S_Calculated
    elsif  LastProcessDate=CurrentDate then    
      Result :=-10;  --S_Disabled     
    -- elsif  CloseDate>=CurrentDate then   
    --  Result :=-10;  --S_Overdue    
    end if;  
    return Result;    
 End;   
Procedure CloseContract(ContractID IN SBCM_Contracts.ID%type)
Is
Begin
SB_ACA.CheckObjectAccess('CREDITMANAGER','delete');  --adm
  update SBCM_Contracts
	set
	  Type#=(
            Select ID 
						 From SBCM_Contract_Types
						 Where Name='ClosedCredit' 		 
	            	)
		Where ID=ContractID;						
	commit;							
End;


Function  GetTypeIDFromName(p_Name IN VarChar2)
 return Integer
Is
  Result Integer;
begin
  Select  ID
    Into Result  
  From 
    SBCM_Contract_Types
  Where  upper(Name)=p_Name;
  
  return Result;  
end; 

function  GetBalanceRest(ContractID IN SBCM_Contracts.ID%type)
return 
  Number
is
  FacticalDebt  Number(18,2);
  OverdueDebt   Number(18,2);
  InterestAccID Integer;  
    
  Result  Number(18,2);
  
begin
  FacticalDebt := GetFacticalDebt(ContractID);
  OverdueDebt   := GetOverdueDebt(ContractID);
  if  FacticalDebt <> 0  then
    InterestAccID := GetInterestAccID(ContractID);
   else
    InterestAccID := GetOverdueInterestAccID(ContractID);  
  end if;
  if (not (InterestAccID is null))or(InterestAccID <> -1) then
    Select
      OSTAT Into Result
     From Archost 
      Where DatDate = (Select TEK_DAT from SysDat) and
            Acc_ID = InterestAccID; 
  else
    Result := 0;                  
  end if;  
 return Result; 
end;
  
function  ContractNumAsVarchar2(ContractID IN SBCM_Contracts.ID%type)
return 
  Varchar2
is
  Result Varchar2(256);
begin
  Select  
    ContractNo
    Into Result 
    From
      SBCM_Contracts
     Where ID = ContractID;
     
  return Result;    
end;

