procedure StateHistory_Add(
                 ContractID IN Integer
               , HDate_ IN Date
               , PrimaryReservePercent_ IN Number
               , OverdueReservePercent_ IN Number
               , PrimaryDebtRest_ IN Number
               , PrimaryPercentRest_ IN Number
               , OverdueDebtRest_ IN Number
               , OverduePercentRest_ IN Number
               )
Is
Begin
  Insert Into  SBCM_State_History(
                 ID#
               , HDate
               , PrimaryReservePercent
               , OverdueReservePercent
               , PrimaryDebtRest
               , PrimaryPercentRest
               , OverdueDebtRest
               , OverduePercentRest
              )
          Values                 (
                 ContractID
               , HDate_
               , PrimaryReservePercent_
               , OverdueReservePercent_
               , PrimaryDebtRest_
               , PrimaryPercentRest_
               , OverdueDebtRest_ 
               , OverduePercentRest_             
              );    
               
End;               
procedure   MarkStateHistory
Is              
   Contracts SBCM_EXPORTS.AllContracts%rowtype;
   BankDate  Date;    
Begin
  BankDate := GetBankDate;
  for Contracts IN SBCM_EXPORTS.AllContracts
  loop
   StateHistory_Add(
          Contracts.ID
        , BankDate 
        , Contracts.ReliabilityID
        , Contracts.OverdueReliabilityID
        , Contracts.FacticalDebt
        , Contracts.FacticalInterestDebt
        , Contracts.OverdueDebt
        , Contracts.OverdueInterestDebt   
        ); 
  end loop;
    
End;                

