function Get_DepositCat(p_contractid in integer) 
return number
is
result number;
 
 cursor c_cat is
 select id from sbcm_persons
 where name=(select TRUECATEGORY from sbcm_categories
 where id=(select clienttype from sbcm_contracts where id=p_contractid));
 
begin
  
  open c_cat;
  fetch c_cat into result;
  close c_cat;
  
  return nvl(result,1);

end;

   FUNCTION get_period (p_id IN INTEGER,p_dat in date)
      RETURN VARCHAR2
   IS
      cm       NUMBER;
      result   VARCHAR2 (56);

      CURSOR c_p
      IS
         SELECT bperiod, eperiod, NAME
           FROM sbcm_periods;
   BEGIN
      SELECT (  closedate
              - p_dat
             )
        INTO cm
        FROM sbcm_contracts
       WHERE id = p_id;

      FOR pr IN c_p
      LOOP
         IF  (cm >= pr.bperiod) AND (cm <= pr.eperiod)
         THEN
            result := pr.NAME;
            EXIT;
         END IF;
      END LOOP;

      RETURN result;
   END;

   function get_contract_curr_using(p_contractid in integer)
   return number
   is
   result number;
   begin
      select using into result 
      from avalute
      where valute=(
      select val_acc from account where id=(
      select contractaccid from sbcm_contract_accounts where id#=p_contractid));
      return result;
   end;

   function get_contract_BalNo(p_contractid in integer)
   return number
   is
   result number;
   begin
      select bal_cn1 into result
       from account
      where id=(select contractaccid from sbcm_contract_accounts where id#=p_contractid);
      return result;
   end;
   
   function get_contractFilial(p_id in integer) 
   return number
   is
   result number;
   
   cursor c_fil is
   select branchid from sbcm_contracts where id=p_id;
   
   begin
      
      open c_fil;
      fetch c_fil into result;
      close c_fil;
      
      return result;
   end;
   
   function Get_ContactAccountByID(p_contractid in integer)
   return varchar2
   is
     result varchar2(25);
     AccID integer;
     
   begin
       select contractaccid into AccID 
         from sbcm_contract_accounts 
         where id# = p_contractid;
         
       result := Get_ContractAccount(AccID);
       
       return result;
   end;
   
   function Get_ContractIntPayDate(p_contractid in integer)
   return date
   is
     result date;
     
     cursor c_deptype is
     select nvl(dateinterval,0) as dateinterval
     from sbcm_deposit_types
     where id = (select contracttype  from sbcm_contracts where id = p_contractid);
     
     
     deptype c_deptype%rowtype;
     LastCaptDate date;
     
     
    begin
       
       select STOPCALCULATIONDATE into LastCaptDate
        from sbcm_contract_state
        where id#  = p_contractid;
        
       open c_deptype;
       fetch c_deptype into deptype;
       close c_deptype;
       
       if deptype.dateinterval > 0 then
           result := LastCaptDate+deptype.dateinterval;     
       else
           select closedate into result
           from sbcm_contracts where id =p_contractid;
       end if;
       
       return result;    
    end;
    
    function Get_ContractCustomerID(p_contractid in integer)
    return integer
    is
      result integer;
      cursor c_cust is
      select kli_id from account
      where id = (select contractaccid from sbcm_contract_accounts
      where id#=p_contractid);
      
    begin
       open c_cust;
       fetch c_cust into result;
       return nvl(result,0);
    end;  
    
    function get_customername(p_accid in integer)
    return varchar2
    is
     result varchar2(100);
    begin
      select name into result
      from customers
      where id = (select kli_id from account where id = p_accid);
      return result;
    end; 
     
    function get_CustomerNameByID(p_id in integer)
    return varchar2
    is
     result varchar2(100);
    begin
      select name into result
      from customers
      where id = p_id;
      return result;
    end; 

END;
/


