procedure  SBDMSetTotalPercents(
               ContractID IN SBCM_Contracts.ID%type
              ,Interest   IN Number 
              )
Is
begin
  update sbcm_contract_state 
  set
    OverdueInterestDebt = OverdueInterestDebt + Interest
  where
    ID# = ContractID;       
end;
              
procedure  CloseDeposit(ContractID in sbcm_contracts.ID%type)
is

cursor c_check is
  select facticaldebt,
         facticalinterestdebt
  from sbcm_contract_state
where id# =  ContractID;

checkrest c_check%rowtype;
         
begin
SB_ACA.CheckObjectAccess('DEPOSITMANAGER','delete');  --adm

open c_check;
fetch c_check into checkrest;
close c_check;

if (checkrest.facticaldebt <> 0) or (checkrest.facticalinterestdebt <> 0) then
    Raise_application_error(-20007,'?aeuuu ieai io?aaeeyie aaueaia? ieiac!');
end if;

  update sbcm_contracts
	set 
	  Type# = (
            Select ID 
						 From SBCM_Contract_Types
						 Where Name='ClosedDeposit' 		 
	            	)
	where ID = ContractID;	
	commit;
end;

