function  GetCashSymbolIfExsist(
                  operation in varchar2 ,
                  AccID in integer
                 )
return integer
is
 Result varchar2(8);
 IsCashAccount integer; 
begin
  
  select cashincoming 
  into iscashaccount
  from bal_spr1 b
  where b.bal_cn = (
  select Bal_cn1 
  from account
  where ID = AccID
  );
  
  if iscashaccount = 1 then
    Result := GetReference(operation);
    return TO_NUMBER(Result);
  else
    return null;  
  end if;   
end;                 

function  ReserveInNational(
                 HDate  in date   ,
                 Amount in number ,                  
                 ContractID   in integer ,
                 ReservePercent in number  
                 )
return number                 
is
  Result number(18,2);
  ConvertReserveToNational boolean;
  CurrencyRate number(7,2); 
  ContractAccID integer;
begin
 ConvertReserveToNational := GetReference('cmrReserveInNational') = 'ON';
 if ConvertReserveToNational then
 
 select ContractAccID 
 into ContractAccID 
 from sbcm_contract_accounts 
 where ID# = ContractID;
 
 select OSTAT 
 into CurrencyRate
 from Operkurs
 where 
 DAT = HDate and 
 VAL_KOD = 
         (select VAL_ACC
          from Account 
          where 
          ID = ContractAccID     
         );
         
 Result := ROUND(((CurrencyRate * Amount) * ReservePercent) / 100 ,2);
 else
 Result := ROUND((Amount * ReservePercent) / 100 ,2);           
 end if;
  
 return Result;
end;                 

