   FUNCTION get_period (p_id IN INTEGER,p_dat in date)
      RETURN VARCHAR2
   IS
      cm       NUMBER;
      result   VARCHAR2 (56);

      CURSOR c_p
      IS
         SELECT bperiod, eperiod, NAME
           FROM sbcm_periods;
   BEGIN
      SELECT (  closedate
              - p_dat
             )
        INTO cm
        FROM sbcm_contracts
       WHERE id = p_id;

      FOR pr IN c_p
      LOOP
         IF  (cm >= pr.bperiod) AND (cm <= pr.eperiod)
         THEN
            result := pr.NAME;
            EXIT;
         END IF;
      END LOOP;

      RETURN result;
   END;

