CREATE OR REPLACE 
PACKAGE sbcm_sys
  IS
  PROCEDURE create_arch (newdate DATE);
END;
/


CREATE OR REPLACE 
PACKAGE BODY       sbcm_sys
IS
   PROCEDURE create_arch (newdate DATE)
   IS
   BEGIN
      UPDATE sbcm_contract_history PARTITION (prev_state)
         SET partkey = 2;

      UPDATE sbcm_contract_history PARTITION (curr_state)
         SET partkey = 1;

      INSERT INTO sbcm_contract_history PARTITION (curr_state)
         SELECT id#, newdate, facticaldebt, overduedebt, facticalinterestdebt,
                overdueinterestdebt, closedate, stopcalculationdate,
                lastprocessdate, calculationenabled, reguiredamountdec,
                reguiredpercentdec, residuaryamount, lastfacticaldebt,
                lastoverduedebt, 0
           FROM sbcm_contract_history PARTITION (prev_state);

      UPDATE sbcm_contract_interests PARTITION (prev_state)
         SET partkey = 2;

      UPDATE sbcm_contract_interests PARTITION (curr_state)
         SET partkey = 1;

      INSERT INTO sbcm_contract_interests PARTITION (curr_state)
         SELECT id#, newdate, interest, overdureinterest, intprecision,
                dueintprecision, inttrid, dueinttrid, withdrawtrid, 0
           FROM sbcm_contract_interests PARTITION (prev_state);
   END;
END;
/


