CREATE OR REPLACE 
PACKAGE sbconfig
  IS	

	type t_cfg_section is record (
		ID integer,
		Ident varchar2(32)
	);
	
	subtype t_str_array is sbutil.t_str_array;

	type t_cfg_sections is 
		ref cursor return t_cfg_section;
		
	subtype t_cfg_value is CONFIG_VALUES%rowtype;
	
	type t_cfg_values is
		ref cursor return t_cfg_value;
		
	DefaultFileID integer;
	DefaultFileName varchar2(32);

  function GetSectionID(
		AName varchar2,
		FileID integer default null)
	return integer;
  function SectionExists(
		Section varchar2,
		FileID integer default null)
	return boolean;
  function ValueExists(
		Section varchar2,
		ValueName varchar2,
		FileID integer default null)
	return boolean;
  procedure WriteValue(
		Section varchar2, 
		AName varchar2,
		AValue varchar2,
		FileID integer default null);
  procedure CloseFile;
  function OpenFile(AName varchar2)
		return integer;
  function ReadSectionValues(
		Ident varchar2, 
		FileID integer default null)
	return t_cfg_values;
  procedure EraseSection(
		Ident varchar2, 
		FileID integer default null);
  function CreateSection(
		SectionName varchar2, 
		FileID integer default null
	)
		return integer;
  function ReadSections
		return t_cfg_sections;
  function ReadSection(
		Ident varchar2,
		FileID integer default null)
	return t_cfg_values;
  function ReadValue(
		Section varchar2, 
		AName varchar2,
		DefaultValue varchar2 default null,
		FileID integer default null
	)
		return varchar2;
  function GetSectionName(SectionID integer)
		return varchar2;
  procedure EraseFile(FileID integer default null);
END; -- Package spec
/


CREATE OR REPLACE 
PACKAGE BODY       sbconfig
IS
	SectionSeparator constant char := '\';
	
	function SetupFileID(PassedFileID integer)
		return integer
	as
	begin
		if PassedFileID is null then
			-- DefaultFileID MAY also be null
			return DefaultFileID;
		else
			return PassedFileID;
		end if;
	end;

	function GetSectionID(
		AName varchar2,
		FileID integer default null)
	return integer
	is
		s_count integer;
		sections t_str_array;
		rown binary_integer;
		section varchar2(64);
		Result integer := 0;
		s_index integer := 0; 
	begin
		sections := sbutil.comma_to_array(AName, s_count, SectionSeparator);
		rown := sections.FIRST;
		loop
			exit when rown is null;
			section := sections(rown);
			
			begin
				select ID
					into Result
					from CONFIG_SECTIONS
				where
					(ParentID = Result)
					and (Name = section);
			exception
				when NO_DATA_FOUND then
					raise_application_error(sbdecls.Error_InvalidParameters, 'Invalid section name: '||AName||'. Stop in subsection "'||section||'". Index: '||to_char(s_index)||'.');
			end;
			--dbms_output.put_line('subsection passed: '||section);
			s_index := s_index + 1;
			rown := sections.NEXT(rown);
		end loop;
		return Result;
	end;
	
	function ReadValue(
		Section varchar2, 
		AName varchar2,
		DefaultValue varchar2 default null,
		FileID integer default null
	)
		return varchar2
	is
		Result varchar2(1024);
		ASectionID integer := GetSectionID(Section);
	begin
		--dbms_output.put_line(substr('Retreived section id: '||to_char(ASectionID),1,255));
		begin
			select value
				into Result
				from CONFIG_VALUES
			where 
				(SectionID = ASectionID)
				and (Name = AName);
		exception
			when NO_DATA_FOUND then
				Result := DefaultValue;
		end;
		return Result; 
	end;
	
	function ValueExists(
		Section varchar2,
		ValueName varchar2,
		FileID integer default null)
	return boolean
	as
		ValueCount integer;
	begin
		select count(*)
			into ValueCount
			from CONFIG_VALUES
		where
			(SectionID = GetSectionID(Section))
			and (Name = ValueName);
		return ValueCount <> 0;		
	end;
	
	function SectionExists(
		Section varchar2,
		FileID integer default null)
	return boolean
	as
		SectionID integer;
	begin
		SectionID := GetSectionID(Section);
		return TRUE;
	exception
		when OTHERS then
			if SQLCODE = sbdecls.Error_InvalidParameters then
				return FALSE; 				
			end if;
	end;
	
	function CreateSection(
		SectionName varchar2, 
		FileID integer default null
	)
		return integer
	as
		AFileID integer := SetupFileID(FileID);
		scount integer;
		sections t_str_array;
		section varchar2(64);
		rown binary_integer;
		Result integer := 0;
	begin
		sections := sbutil.comma_to_array(SectionName, scount, '\');
		
		rown := sections.FIRST;
		loop
			exit when rown is null;
			section := sections(rown);
			
			select count(*)
				into SCount
				from CONFIG_SECTIONS
			where
				(ParentID = Result)
				and (Name = section);
				
			if SCount = 0 then
				-- subsection not found
				-- insert new subsection
				insert into CONFIG_SECTIONS (
					Name, ParentID, FileID
				)
				values (
					section, Result, AFileID
				);
				-- get new subsection id
				select CONFIG_SECTIONS_ID_GEN.currval
					into Result
					from dual;
			else
				-- section found. retreive id
				select ID
					into Result
					from CONFIG_SECTIONS
				where
					(ParentID = Result)
					and (Name = section);
			end if;
			 
			--dbms_output.put_line('subsection passed: '||section);
			rown := sections.NEXT(rown);
		end loop;
		return Result;
	end;
		
	procedure WriteValue(
		Section varchar2, 
		AName varchar2,
		AValue varchar2,
		FileID integer default null)
	as
		Result varchar2(256);
		SCount integer;
		ASectionID integer;
	begin
		ASectionID := CreateSection(Section);
		
		update CONFIG_VALUES
		set
			Value = AValue
		where
			(SectionID = ASectionID)
			and (Name = AName);
			
		if SQL%rowcount = 0 then
			insert into CONFIG_VALUES (SectionID, Name, Value)
			values (ASectionID, AName, AValue);
		end if;
	end;
	
	function ReadSection(
		Ident varchar2,
		FileID integer default null)
	return t_cfg_values
	as
		AFileID integer := SetupFileID(FileID);
		ASectionID integer := GetSectionID(Ident, AFileID);
		Result t_cfg_values;
	begin
		--dbms_output.put_line(substr('Value of ASectionID='||ASectionID,1,255));
		--dbms_output.put_line(substr('Value of AFileID='||AFileID,1,255));
		open Result for
			select *
				from CONFIG_VALUES
				where 
					SectionID = ASectionID;
					
		return Result;
	end;
	
	function OpenFile(AName varchar2)
		return integer
	as
	begin
		-- temporary
		CloseFile();
		
		if DefaultFileID is not null then
			raise_application_error(
				sbdecls.Error_AlreadyInitialized,
				'Already assigned to INI file. Call CloseFile then retry'
			);
		end if;
		
		select ID
			into DefaultFileID
			from CONFIG_FILES
			where Name = AName;
			
		DefaultFileName := AName;
		
		return DefaultFileID;
		
	exception
		when NO_DATA_FOUND then
			raise_application_error(sbdecls.Error_InvalidParameters,
			'SBCONFIG::OpenFile: Invalid file name: "'||AName||'"');	
	end;
	
	procedure CloseFile
	as
	begin
		DefaultFileID := null;
		DefaultFileName := null;
	end;
	
	procedure EraseFile(FileID integer default null)
	as
		AFileID integer := SetupFileID(FileID);
	begin
		delete from config_sections
		where FileID = AFileID;
	end;
	
	function ReadSectionValues(
		Ident varchar2, 
		FileID integer default null)
	return t_cfg_values
	as
		AFileID integer := SetupFileID(FileID);
		Result t_cfg_values;
	begin
		open Result for
			select * from CONFIG_VALUES
				where SectionID = GetSectionID(Ident, AFileID);
		return Result;  
	end;
	
	procedure EraseSection(
		Ident varchar2, 
		FileID integer default null)
	as
		SectionID integer := GetSectionID(Ident, SetupFileID(FileID));
	begin
		delete from CONFIG_SECTIONS
		where ID = SectionID;
	end;
	
	function GetSectionName(SectionID integer)
		return varchar2
	as
		Result varchar(256);
		AParentID integer;
	begin
		Result := '';
		AParentID := SectionID;
		loop
			select Name || '\' || Result, ParentID
				into Result, AParentID
				from CONFIG_SECTIONS
			where ID = AParentID;
			exit when AParentID = 0; 
		end loop;
		return substr(Result, 1, Length(Result)-1);
	end;
	
	function ReadSections
		return t_cfg_sections
	as
		Result t_cfg_sections;
	begin
		open Result for
			select ID, GetSectionName(ID) as Name
				from CONFIG_SECTIONS
				order by ParentID;
		return Result;
	end;	
	
END;
/


