CREATE OR REPLACE 
PACKAGE sbcorrection
  IS
	
	subtype t_acc_balance is SBOP.t_acc_balance;
  function check_account_balance(AccID integer, ErrorSet integer)
		return boolean;
  function calc_account_balance(AccID integer)
		return t_acc_balance;
  procedure correct_account_balance(AccID integer);
END;
/


CREATE OR REPLACE 
PACKAGE BODY       sbcorrection
IS

	function calc_account_balance(AccID integer)
		return t_acc_balance
	as
		PrevDate date;
		Result t_acc_balance;
		DebitTurnover number;
		DebitLTurnover number;
		CreditTurnover number;
		CreditLTurnover number;
	begin
	  select pred_dat
			into PrevDate
			from sysdat;
			
		Result := SBOP.get_account_balance(AccID, PrevDate);
		
		select sum(ammount), sum(lammount)
			into DebitTurnover,DebitLTurnover
			from provdoc
		where
			DEBT = AccID;
			
		if DebitTurnover is null then
			DebitTurnover := 0;
			DebitLTurnover := 0;
		end if;

		select sum(Ammount_C),  sum(lammount)
			into CreditTurnover,CreditLTurnover
			from provdoc
		where
			KREDIT = AccID;
			
		if CreditTurnover is null then
			CreditTurnover := 0;
			CreditLTurnover := 0;
		end if;
		
		Result.amount := Result.amount - DebitTurnover + CreditTurnover;
		Result.lamount := Result.lamount - DebitLTurnover + CreditLTurnover;
		Result.d_turnover := DebitTurnover;
		Result.d_l_turnover := DebitLTurnover;
		Result.c_turnover := CreditTurnover;
		Result.c_l_turnover := CreditLTurnover;
		
		return Result;
	end;

	function check_account_balance(AccID integer, ErrorSet integer)
		return boolean
	as
		FacticalBalance t_acc_balance;
		ActualBalance t_acc_balance;
		Result boolean;
	begin
		FacticalBalance := SBOP.get_account_balance(AccID);
		ActualBalance := calc_account_balance(AccID);
		Result :=
					(FacticalBalance.amount 			= ActualBalance.amount)
			and (FacticalBalance.lamount 			= ActualBalance.lamount)
			and (FacticalBalance.d_turnover 	= ActualBalance.d_turnover)
			and (FacticalBalance.d_l_turnover = ActualBalance.d_l_turnover)
			and (FacticalBalance.c_turnover 	= ActualBalance.c_turnover)
			and (FacticalBalance.c_l_turnover = ActualBalance.c_l_turnover);
			
		return Result;
	end;
	
	procedure correct_account_balance(AccID integer)
	as
		ActualBalance t_acc_balance;
	begin
		ActualBalance := calc_account_balance(AccID);
		update tenostat
		set
			ostat = ActualBalance.amount,
			pok_ostat = ActualBalance.lamount,
			obr_d = ActualBalance.d_turnover,
			pok_obr_d = ActualBalance.d_l_turnover,
			obr_k = ActualBalance.c_turnover,
			pok_obr_k = ActualBalance.c_l_turnover
		where
			acc_id = AccID;
	end;
	
END;
/


