	Error_ChildTransaction					constant integer := -20023;
	Error_MessageNotFound						constant integer := -20024;
	Error_DataCorrupted							constant integer := -20025;
  Error_ProfitClosingSettings     constant integer := -20026;
	Error_InternalError							constant integer := -20027;
	Error_AccessDenied							constant integer := -20028;
	Error_SessionNotFound						constant integer := -20029;
	  
  /* Legal values for bal_spr1.TypeID */
  atActive                       	constant integer := 1;
  atPassive                      	constant integer := 2;
  atActivePassive                	constant integer := 3;

	/* ************************* */
  /* Flags for TRANSACTION_ADD */
	/* ************************* */

  /* if atfNoAdd set, routine just checks the limit conditions,
     do not actually adds the transaction
   */
  atfNoAdd                       	constant integer := 1;

	/* do not add child transactions 
	 */
  atfNoAddChild										constant integer := 2;

	/* do not control acc's balances 
	 */				        
  atfNoControl											constant integer := 4;

	/* commit transaction imediately
     if not prohibited by security permissions
	*/
	atfCommitImmediate							constant integer := 8;
	
	atfTemporary										constant integer := 16;

	/* **************************** */
  /* Flags for TRANSACTION_DELETE */
	/* **************************** */
	
	dtfDontUpdateRest               constant integer := 1;

	/* *************** */
  /* Other constants */
  /* *************** */

  /* Used in Round_Currency */
  CurrencyDecimals               	constant integer := 2;
	
	/* Transaction status */
	
	tsDelayed 		constant integer := 1;
	tsCommited 		constant integer := 2;
	tsRejected 		constant integer := 3; -- This means that tsDelayed is set too
	tsTemporary   constant integer := 4;

	/* Common declarations */
	
	CRLF constant varchar2(2) := '
';

	DCRLF constant varchar2(8) := CRLF||CRLF;
	
END; -- Package spec
/


