CREATE OR REPLACE 
PACKAGE sbinstall
  IS

	type t_users_list is ref cursor;

  function get_task_id (TaskName varchar2)
		return integer;
		
  procedure del_task_query(QueryID integer);
	
  function add_task_query(
			TaskID integer, 
			Name varchar2, 
			Metrica integer, 
			code varchar2,
			OperationCode integer)
		return integer;
		
  procedure execute_task_query(
		QueryID integer, 
		sParams varchar2, 
		IgnoreErrors boolean);

  procedure build_install_script(
		Delimiter char default ';',
		CreateMode boolean default True,
		ObjOwner varchar2 default user);
		
  function get_users_list(configured boolean)
		return t_users_list;
  procedure execute_task(
    task_name varchar2, 
    ParamStr varchar2, 
    IgnoreErrors boolean);
  procedure upd_task_query(
		QueryID integer, 
		NewName varchar2, 
		NewMetrica varchar2, 
		NewCode varchar2,
		NewOperationCode integer);
  procedure del_task_actions(ATaskID integer);
END;
/


CREATE OR REPLACE 
PACKAGE BODY       sbinstall
IS

  /* Legal values for INSTALLATION_ACTIONS.OperationType */
  Task_ExecSQL constant integer := 1;
  Task_ExecTask constant integer := 2;

	subtype t_params is sbutil.t_params;
	subtype t_param_value is sbutil.t_param_value;
	
	Merr_TaskQueryNotFound constant varchar2(41) := 
		'Task with specified ID could not be found';
		
	CRLF constant varchar2(2) := sbdecls.CRLF;

	DCRLF constant varchar2(8) := CRLF||CRLF;
	
	function get_task_id (TaskName varchar2)
		return integer
	as
		Result integer;
	begin
		select id into Result
			from INSTALLATION_TASKS
			where name = TaskName;
		return Result;
	exception
		when NO_DATA_FOUND then
			raise_application_error(sbdecls.Error_InvalidParameters, 'SBInstall.get_task_id: Task "'||TaskName||'" could not be found');
	end;

  function add_task_query(
			TaskID integer, 
			Name varchar2, 
			Metrica integer, 
			code varchar2,
			OperationCode integer)
		return integer
	as
		Result integer;
	begin
		insert into INSTALLATION_ACTIONS (
			Task_ID, metrica, Name, code, OperationCode)			
		values (
			TaskID,  Metrica, Name, Code, OperationCode)
		returning ID into Result;
		return Result;
	end;

	procedure upd_task_query(
		QueryID integer, 
		NewName varchar2, 
		NewMetrica varchar2, 
		NewCode varchar2,
		NewOperationCode integer)
	as
	begin
		update INSTALLATION_ACTIONS
		set
			Metrica = NewMetrica,
			Name = NewName,
			Code = NewCode,
			OperationCode = NewOperationCode
		where
			ID = QueryID;
		if SQL%rowcount = 0 then
			raise_application_error(sbdecls.Error_InvalidParameters, Merr_TaskQueryNotFound);
		end if;
	end;
	
	procedure del_task_actions(ATaskID integer)
	as
	begin
		delete from INSTALLATION_ACTIONS
		where Task_ID = ATaskID;
	end;

	procedure del_task_query(QueryID integer)
	as
	begin
		delete from INSTALLATION_ACTIONS
		where
			ID = QueryID;
		if SQL%rowcount = 0 then
			raise_application_error(sbdecls.Error_InvalidParameters, Merr_TaskQueryNotFound);
		end if;
	end;

	function parse_task_query(
		Query in varchar2, 
		params t_params)
		return varchar2
	as
	begin
		return sbutil.expand_macroses(Query, params);
	end;

	/* Should be renamed to execute_task_action */
	procedure execute_task_query(
		QueryID integer, 
		sParams varchar2, 
		IgnoreErrors boolean)
	as
		Query varchar2(2000);
		params sbutil.t_params;
		ParamCount binary_integer;
		cur integer;
		rp integer;
	begin
		select code into Query
			from INSTALLATION_ACTIONS
			where ID = QueryID;
      
--		dbms_output.put_line(SUBSTR('Executing task: '||TO_CHAR(QueryID)||'code: '||Query,1,255));
		params := sbutil.comma_to_params(sParams, ParamCount);
		Query := parse_task_query(Query, params);
		
    --raise_application_error(-20001, Query);

--		dbms_output.put_line(substr('Value of Query='||Query,1,255));

		cur := dbms_sql.open_cursor;
		dbms_sql.parse(cur, Query, dbms_sql.v7);
		rp := dbms_sql.execute(cur);
		dbms_sql.close_cursor(cur);
	exception
    when OTHERS then
      raise_application_error(
        sbdecls.Error_InvalidParameters,
				'Error #'||TO_CHAR(SQLCODE)||', Message: '||SQLERRM||', on query: '||Query);
	end;
  
	procedure build_install_subscript(
		ObjType varchar2, 
		ObjOwner varchar2, 
		CreateMode boolean,
		Delimiter char)
	is
	  cursor c_objects(ObjType varchar2, ObjOwner varchar2)
  	is
    	select * from sys.all_objects
	    where (object_type = ObjType) and (OWNER = ObjOwner);
		Result varchar2(32767);
	begin
		--dbms_output.put_line('/* Creating '||lower(ObjType)||'''s synonyms */'||DCRLF);
		--dbms_output.new_line;

  	for obj in c_objects(ObjType, user)
	  loop
			if CreateMode then
				Result := 'CREATE ';
			else
				Result := 'DROP ';
			end if; 
  	  Result :=
				Result || 
      	'$(PublicPrefix) SYNONYM $(UserNamePrefix).' || obj.OBJECT_NAME;
			if CreateMode then
  	    Result := Result || ' FOR ' || ObjOwner || '.' || obj.OBJECT_NAME;
			end if;
			Result := Result || CRLF || Delimiter || CRLF;
			--dbms_output.put_line(Result);
	  end loop;
		--dbms_output.put_line(CRLF);
	end;
	
	procedure build_install_script(
		Delimiter char default ';',
		CreateMode boolean default True,
		ObjOwner varchar2 default user)
	is
	begin
	
		--dbms_output.put_line('/* SmartBank Schema Installation Script */');
		--dbms_output.put_line('/* Build by SBInstall package */');
		--dbms_output.put_line('/* User: '||user||', Date: '||TO_CHAR(sysdate)||' */'||DCRLF);
		
		build_install_subscript('TABLE', ObjOwner, CreateMode, Delimiter);
		build_install_subscript('VIEW', ObjOwner, CreateMode, Delimiter);
		build_install_subscript('PACKAGE', ObjOwner, CreateMode, Delimiter);
		build_install_subscript('FUNCTION', ObjOwner, CreateMode, Delimiter);
--		build_install_subscript('PACKAGE BODY', ObjOwner, CreateMode, Delimiter);
	end;
	
	function get_users_list(configured boolean)
		return t_users_list
	is
		Result t_users_list;
		Query varchar2(1024) := 'select * from sys.all_users'||CRLF;
	begin
		if not configured then
			Query := Query || 'where not (USER_ID in (select ID from user$))' || CRLF;
		end if;
		Query := Query || 'ORDER BY USER_ID desc';		
		open Result for Query;
		return Result;
	end;
  
  procedure execute_task(
    task_name varchar2, 
    ParamStr varchar2, 
    IgnoreErrors boolean)
  as
    cursor c_TaskActions is
      select * from INSTALLATION_ACTIONS
      where TASK_ID = (
        select ID from INSTALLATION_TASKS
        where NAME = task_name
      )
      order by Metrica;
    action c_TaskActions%rowtype;
  begin
		--dbms_output.put_line('Executing task: '||task_name);
    for action in c_TaskActions
    loop
      if action.OperationCode = Task_ExecTask then
        execute_task(action.Code, ParamStr, IgnoreErrors);              
      elsif action.OperationCode = Task_ExecSQL then
        execute_task_query(action.ID, ParamStr, IgnoreErrors);
      else
        raise_application_error(
          sbdecls.Error_DataCorrupted, 
          'Unknown operation code');
      end if;
    end loop;
  end;

END;
/


