    /*        open c_UserIdBySysID(uid);
			fetch c_UserIdBySysID into SavedUserID;
			if c_UserIdBySysID%NotFound then
				SavedUserID := -1;
			end if;
			close c_UserIdBySysID;
			
			if SavedUserID = -1 then
				raise_application_error(
					sbdecls.Error_InternalError,
					'Failed to retreive user''s ID by system ID'
				);
			end if;
			*/
		end if;
		return SavedUserID;
	end;
	
	function UserSID(AUserID integer default null)
		return integer
	as
