  begin
  select   VALUE,  Description
    into v_PSW_LENGTH,v_Description
    from settings where upper(name)='PASSWORD_LENGTH';

   if length(NoCryptedPsw) < v_PSW_LENGTH then
    raise_application_error(-20001,v_Description); end if;
    
    ExecuteableQuery := 'alter user '||UserName
    ||' identified by '||NewPsw;
    execute immediate ExecuteableQuery;
end;
  
