CREATE OR REPLACE 
PACKAGE sbmf
is

 csUncalculated   constant   SB_ASSETS.status%type :=1;
 csCalculated     constant   SB_ASSETS.status%type :=2;
 csDisabled       constant   SB_ASSETS.status%type :=3;
 
 subtype t_char is varchar(1);

  function execute_group(
                OperationMode t_char
               ,v_ID number
               ,v_Name varchar
               ,v_Amort Sb_GROUPS.amort%type
               ,v_TaxAmort Sb_GROUPS.taxamort%type
               ,v_selfaccountid number
               ,v_debtaccountid number
               ,v_creditaccountid number
               ,v_extraaccountid number) return number;
  function execute_asset
                 (
                  OperationMode t_char
                 ,v_id SB_ASSETS.id%type 
                 ,v_groupid SB_ASSETS.id%type 
                 ,v_departmentid SB_ASSETS.departmentid%type 
                 ,v_name SB_ASSETS.name%type 
                 ,v_inventar SB_ASSETS.name%type 
                 ,v_inventardate SB_ASSETS.inventardate%type 
                 ,v_producer SB_ASSETS.producer%type 
                 ,v_efficiency SB_ASSETS.efficiency%type 
                 ,v_amortization SB_ASSETS.amortization%type 
                 ,v_historicalcost SB_ASSETS.historicalcost%type 
                 ,v_balancecost SB_ASSETS.balancecost%type 
                 ,v_accrualwear SB_ASSETS.accrualwear%type 
                 ,v_lastwear SB_ASSETS.lastwear%type 
                 ,v_taxamortization SB_ASSETS.taxamortization%type 
                 ,v_taxbalancecost SB_ASSETS.taxbalancecost%type 
                 ,v_taxaccrualwear SB_ASSETS.taxaccrualwear%type 
                 ,v_taxlastwear SB_ASSETS.taxlastwear%type 
                 ) return SB_ASSETS.id%type;
END;
/


CREATE OR REPLACE 
PACKAGE BODY sbmf
IS

function SetStatus(
                  v_historicalcost SB_ASSETS.historicalcost%type 
                 ,v_balancecost SB_ASSETS.balancecost%type 
                 ,v_accrualwear SB_ASSETS.accrualwear%type    
                  ) return SB_ASSETS.status%type
is
  Result SB_ASSETS.status%type; 
begin

 if (v_accrualwear = 0) or (v_historicalcost = v_balancecost) then
  Result :=csUncalculated; 
 end if; 
 
 if (v_historicalcost <> 0) and  (v_balancecost <> 0) and (v_accrualwear <> 0) then
  Result :=csCalculated; 
 end if;  
 
 if (v_historicalcost = v_accrualwear) or (v_balancecost = 0) then 
  Result :=csDisabled;  
 end if;  
 
 return result;
 
end;                      

function execute_group(
                OperationMode t_char
               ,v_ID number
               ,v_Name varchar
               ,v_Amort Sb_GROUPS.amort%type
               ,v_TaxAmort Sb_GROUPS.taxamort%type
               ,v_selfaccountid number
               ,v_debtaccountid number
               ,v_creditaccountid number
               ,v_extraaccountid number) return number
is
 Result number;
begin
 if OperationMode = 'I' then
  Insert into SB_GROUPS
                      ( ID
                       ,name
                       ,amort
                       ,taxamort
                       ,selfaccountid
                       ,debtaccountid
                       ,creditaccountid
                       ,extraaccountid)
                       
  Values               (SEQ_SB_GROUPS.NEXTVAL
                       ,v_name
                       ,v_amort
                       ,v_taxamort
                       ,v_selfaccountid
                       ,v_debtaccountid
                       ,v_creditaccountid
                       ,v_extraaccountid)
   returning ID into Result;                    
  commit;  
                     
 else
 
  Update SB_GROUPS set
            name = v_name
           ,amort = v_amort
           ,taxamort = v_taxamort
           ,selfaccountid = v_selfaccountid
           ,debtaccountid = v_debtaccountid
           ,creditaccountid = v_creditaccountid
           ,extraaccountid = v_extraaccountid
           
  Where    ID = v_ID;     
  Result :=v_ID;   
  commit;                    
 end if;
 Return Result;
end;               
   
function execute_asset
                 (
                  OperationMode t_char
                 ,v_id SB_ASSETS.id%type 
                 ,v_groupid SB_ASSETS.id%type 
                 ,v_departmentid SB_ASSETS.departmentid%type 
                 ,v_name SB_ASSETS.name%type 
                 ,v_inventar SB_ASSETS.name%type 
                 ,v_inventardate SB_ASSETS.inventardate%type 
                 ,v_producer SB_ASSETS.producer%type 
                 ,v_efficiency SB_ASSETS.efficiency%type 
                 ,v_amortization SB_ASSETS.amortization%type 
                 ,v_historicalcost SB_ASSETS.historicalcost%type 
                 ,v_balancecost SB_ASSETS.balancecost%type 
                 ,v_accrualwear SB_ASSETS.accrualwear%type 
                 ,v_lastwear SB_ASSETS.lastwear%type 
                 ,v_taxamortization SB_ASSETS.taxamortization%type 
                 ,v_taxbalancecost SB_ASSETS.taxbalancecost%type 
                 ,v_taxaccrualwear SB_ASSETS.taxaccrualwear%type 
                 ,v_taxlastwear SB_ASSETS.taxlastwear%type 
                 ) return SB_ASSETS.id%type
is
 Result SB_ASSETS.id%type; 
 AssetStatus SB_ASSETS.status%type;
begin
 AssetStatus :=SetStatus(v_historicalcost, v_balancecost, v_accrualwear);
 if OperationMode = 'I' then
   Insert into SB_ASSETS
                ( id  
                 ,groupid  
                 ,departmentid  
                 ,name  
                 ,inventar  
                 ,inventardate  
                 ,producer  
                 ,efficiency  
                 ,amortization  
                 ,historicalcost  
                 ,balancecost  
                 ,accrualwear  
                 ,lastwear 
                 ,taxamortization 
                 ,taxbalancecost  
                 ,taxaccrualwear  
                 ,taxlastwear
                 ,Status)
                   
   Values       ( SEQ_SB_ASSETS.NEXTVAL 
                 ,v_groupid  
                 ,v_departmentid  
                 ,v_name  
                 ,v_inventar 
                 ,v_inventardate  
                 ,v_producer  
                 ,v_efficiency  
                 ,v_amortization 
                 ,v_historicalcost 
                 ,v_balancecost  
                 ,v_accrualwear  
                 ,v_lastwear  
                 ,v_taxamortization  
                 ,v_taxbalancecost  
                 ,v_taxaccrualwear  
                 ,v_taxlastwear
                 ,AssetStatus
                 )
   Returning ID Into Result;
  commit;
 else
   Update SB_ASSETS Set
                  groupid = v_groupid  
                 ,departmentid = v_departmentid  
                 ,name = v_name  
                 ,inventar = v_inventar  
                 ,inventardate = v_inventardate  
                 ,producer = v_producer  
                 ,efficiency = v_efficiency 
                 ,amortization = v_amortization 
                 ,historicalcost = v_historicalcost  
                 ,balancecost = v_balancecost  
                 ,accrualwear = v_accrualwear 
                 ,lastwear = v_lastwear 
                 ,taxamortization = v_taxamortization
                 ,taxbalancecost = v_taxbalancecost  
                 ,taxaccrualwear = v_taxaccrualwear 
                 ,taxlastwear = v_taxlastwear
                 ,status = AssetStatus
   Where          id = v_id;
   Result :=v_id;
  commit;   
 end if;
 return Result; 
end;     


END;
/


