CREATE OR REPLACE 
PACKAGE sbmsg
  IS
	
	function get_message(MsgID integer)
		return varchar2;
	function get_message(MsgName varchar2)
		return varchar2;
	
  function format_msg(Message varchar2, ParamStr varchar2)
		return varchar2;
  function get_error(
		ErrorCode integer, 
		Message out varchar2)
	return boolean;
  function Get_UserMessage
  return varchar2;
END; -- Package spec
