		dbms_output.put_line('===end=of==params=dump====');
*/		
        null;
	end;

	function get_client_link(
		v_sid# integer, 
		v_client# integer)
	return integer
	as
		Result integer;
	begin
		select id into result
			from SECURITY_sid_client_link
			where (sid# = v_sid#) and (client# = v_client#);
		return result;
	exception
	when NO_DATA_FOUND then
		return -1;
	end;

	function link_add(sid# integer, user# t_user)
	return integer
	as
		Result integer;
	begin
		insert into SECURITY_sid_client_link (
			sid#, client#)
		values (
			sid#, user#)
		returning ID into Result;
		return Result;
	end;

	procedure link_access_add(link# integer, access# integer)
	as
		AccessID integer;
	begin
		insert into SECURITY_sid_link_access (
			link#, access#)
		values (
			link#, access#)
		returning ID into AccessID;
--		dbms_output.put_line('Created AccessID: '||TO_CHAR(AccessID));
	end;
	
	procedure link_access_remove(link# integer)
	as
	begin
		delete from SECURITY_sid_link_access
		where ID = link#;
	end;

	procedure access_user_grant(
		sid t_sid, 
		user_id t_user, 
		access_id t_access)
	as
		LinkID integer;
	begin
--		dbms_output.put_line('grant_user_access called');
		DumpGrantUserAccessParams(sid, user_id, access_id, null);

		LinkID := get_client_link(sid, user_id);
		if LinkID = -1 then
--			dbms_output.put_line('creating access link');
			LinkID := link_add(sid, user_id);
		end if;
--		dbms_output.put_line('LinkID: '||TO_CHAR(LinkID));
		link_access_add(LinkID, access_id);
	end;

  procedure access_user_grant(
		sid t_sid,
		user_id t_user,
		access_name t_access_name)
	as
	begin
--		dbms_output.put_line('grant_user_access-2 called');
		DumpGrantUserAccessParams(
			sid, user_id, null, access_name
		);
		access_user_grant(sid, user_id, get_access_id(access_name));
	end;

	procedure access_user_revoke(
		sid t_sid,
		user_id t_user,
		access_id t_access)
	as
		cursor c_sid_link_access
		is
			select *
  		from SECURITY_sid_link_access
  		where 
  			link# = (
  				select ID  
  					from SECURITY_sid_client_link
  					where (sid# = sid) and (client# = user_id))
  			and (access# = access_id)
		for update;
	begin
--		dbms_output.put_line('revoke_user_access called');
		DumpGrantUserAccessParams(sid, user_id, access_id, null);
		
		for la in c_sid_link_access
		loop
			link_access_remove(la.ID);
		end loop;
	end;

	procedure access_user_revoke(
		sid t_sid,
		user_id t_user,
		access_name t_access_name)
	as
	begin
--		dbms_output.put_line('revoke_user_access-2 called');
--		DumpGrantUserAccessParams(sid, user_id, null, access_name);
		access_user_revoke(sid, user_id, get_access_id(access_name)); 
	end;

	function access_reg(
		name t_access_name,
		description varchar2
	)
		return t_access
	as
		Result t_access;
	begin
		insert into SECURITY_access$ (
			name, description)
		values (
			name, description
		)
		returning ID into Result;
		return Result;
	end;

	procedure access_unreg(
		access_id t_access
	)
	as
	begin
--		dbms_output.put_line('unreg_access called');
		delete from SECURITY_access$
		where ID = access_id;
	end;
 
	procedure access_unreg(
		access_name t_access_name
	)
	as
	begin
--		dbms_output.put_line('unreg_access-2 called');
		delete from SECURITY_access$
		where name = access_name;
	end;

	function get_object_type(sid# t_sid)
		return t_object_type
	as
		Result t_object_type;
	begin
		select type# into Result
			from SECURITY_sid$
			where id = sid#;
		return Result;
	exception
		when NO_DATA_FOUND then
			invalid_sid;
	end;

	procedure link_remove(link# integer)
	as
	begin
		delete from SECURITY_sid_client_link
		where ID = link#;
		if SQL%rowcount = 0 then
			raise_application_error(sbdecls.Error_InvalidParameters, Merr_InvalidSecurityLink);
		end if;
	end;

	function build_default(sid t_sid)
		return boolean
	as
		obj_type integer;
		LinkID integer;
		cursor c_client is
			select ID, sid, client#
			from security_default_user
			where objtype# = obj_type;
		client c_client%rowtype;
		Result boolean := FALSE;
	begin
--		dbms_output.put_line(substr('build_default_security called',1,255));
		select type# into obj_type
			from SECURITY_sid$
			where id = sid;
		delete from SECURITY_sid_client_link
			where sid# = sid;

		for client in c_client 
		loop
--			dbms_output.put_line(substr('Value of client.client#='||client.client#,1,255));
--			dbms_output.put_line(substr('Value of sid='||sid,1,255));

			insert into SECURITY_sid_client_link (
				sid#, client#)
			values (
				sid, client.client#);

			select sid_client_link_id_gen.currval
				into LinkID
				from dual;

--			dbms_output.put_line(substr('Value of LinkID='||LinkID,1,255));

			insert into SECURITY_sid_link_access (
				link#, access#)
			select LinkID, access#
				from security_default_access
				where link# = client.ID;

--			dbms_output.put_line(substr(TO_CHAR(SQL%rowcount)||' row(s) appended',1,255));

			Result := TRUE;

		end loop;

		return Result;

	end;

	function get_type_id (type_name varchar2)
		return t_object_type
	as
		Result integer;
	begin
		select id into Result
			from security_object_type
			where name = type_name;
		return Result;		
	end;

  function get_user_id
  return integer
  as
    Result integer;
		UserID integer;
  begin
		/*UserID := sbutil.get_user_id;
		select id into Result
			from security_clients$
			where SysID = UserID;
		return Result;
		*/
		return uid;
  end;

	function group_add(name varchar2, description varchar2)
		return t_user
	as
		Result integer;
	begin
--		dbms_output.put_line(substr('group_add called. name='||name,1,255));

		insert into security_clients$ (name, description, flags, type#, sid#)
		values (name, description, 0, SecurityClientType_Group, null)
        returning ID into Result; 

		client_sid_set(
			Result, 
			sid_create(
				GetLoggedUser, 
				Result, 
				get_type_id('Group')
			)
		);
			
		return Result;	
	end;
    
  procedure group_edit(GroupID integer, NewName varchar2, NewDescription varchar2)
  as
  begin
--    dbms_output.put_line(substr('group_edit called. ID='||TO_CHAR(GroupID)||', Name='||NewName,1,255));

    update security_clients$ 
    set 
      name = NewName,
			description = NewDescription
    where
      ID = GroupID;
  end;
  
  procedure group_delete(GroupID integer)
  as
  begin
--    dbms_output.put_line(substr('group_delete called. ID='||TO_CHAR(GroupID),1,255));
		client_sid_set(GroupID, null);
		sid_try_delete(client_sid_get(GroupID));
    delete from security_clients$
    where
        ID = GroupID;
  end;
  
  function build_create_user_params(UserID integer, Password varchar2)
    return varchar2
  is
    UserName varchar2(64);
  begin
    select name
      into UserName 
      from user$
    where ID = UserID;
    return 'PublicPrefix=,UserName='||UserName||',UserNamePrefix='||UserName||',Password='||Password;
  end;

  procedure user_create_repository(UserID integer, Password varchar2)
  as
  begin
    --dbms_output.put_line('user_create_repository in execution. UserID='||TO_CHAR(UserID));
    sbinstall.execute_task(
      'user_create',
      build_create_user_params(UserID, Password),
      False);
  end;
	
	procedure user_drop_repository(UserID integer)
	as
	begin
--		dbms_output.put_line('user_drop_repository in execution. UserID='||TO_CHAR(UserID));
    sbinstall.execute_task(
      'user_delete',
      'UserName='||GetUserName(UserID),
      False);
	end;
	
	procedure user_recreate_repository(UserID integer)
	as
		cursor c_user_objects(UserID integer)
		is
			select * from all_objects
			where owner = (
				select username from ALL_USERS
				where user_id = (
					select SysID from security_clients$ where ID = UserID
				)			
			);
		DropCmd varchar2(128);
		c integer;
		rown integer;
	begin
		for r_user_object in c_user_objects(UserID)
		loop
			DropCmd := 'DROP ' || r_user_object.object_type || ' ' || r_user_object.owner || '.' || r_user_object.object_name;
			--dbms_output.put_line(DropCmd);
			c := dbms_sql.open_cursor();
			dbms_sql.parse(c,DropCmd,dbms_sql.NATIVE);
			rown := dbms_sql.execute(c);
			dbms_sql.close_cursor(c);
		end loop;		
    sbinstall.execute_task(
      'user_add',
      build_create_user_params(UserID, ''),
      False);
	end;
-------------------------------------------------  
  function user_add(
      UserName varchar2, 
   	  Description varchar2,
      DefaultGroupID integer,
      Password varchar2,
      CreateUser boolean default True,
      CreateRepository boolean default True,
   	  GroupIDs varchar2 default null,
      RightIDs varchar2 default null,
      v_Filial number default 0)
    return t_user 
  as
    Result t_user;
		RightsSID t_sid;
		SysUserID integer;
  begin
		access_check('Right_SecurityUserAdd');
		
--    dbms_output.put_line(substr('user_add called. Name='||UserName,1,255));
    insert into security_clients$ (
      name, description, flags, type#, Group# , filialID)
    values (
      UserName, description, 0, SecurityClientType_User, null , v_Filial 
		)
    returning ID into Result;
		
		RightsSID :=
			sid_create(
				Result, 
				DefaultGroupID, 
				get_type_id('User')
			);
		client_sid_set(
			Result,
			RightsSID
		);
		
--    if CreateUser then
      user_create_repository(Result, Password);
			
	select user#	into SysUserID from sys.user$ 	where	upper(name)=upper(UserName);
	update security_clients$ set SysID = SysUserID	where ID = Result; 
--      end if;
			
			user_set_password(Result, Password);
			
			if GroupIDs is not null then
				group_membership_array(Result, GroupIDs);
			end if;
			
			if RightIDs is not null then
				sid_rights_array(RightsSID, Result, RightIDs);
			end if; 
			
			user_recreate_repository(Result);
  		
    return Result;
  end;
---------------------------------------------
	procedure user_edit(
	  UserID integer
	, UserName varchar2
	, NewDescription varchar2
	, v_Filial number)
	as
	begin
		update security_clients$
		set
			Name = UserName,
			Description = NewDescription,
   filialID=v_filial
		where
			ID = UserID;
	end;
---------------------------------------------
  procedure user_delete(UserID integer)
  as
  begin
		access_check('Right_SecurityUserDrop');
--    dbms_output.put_line(substr('user_delete called. ID='||TO_CHAR(UserID),1,255));
		user_drop_repository(UserID);
    delete from security_clients$
    where
      ID = UserID;
  end;
	
	procedure user_set_password(UserID varchar2, NewPassword varchar2)
	as
	begin
		access_check('Right_SecurityUserSetPassword');
--		dbms_output.put_line('user_set_password in execution');
		sbinstall.execute_task(
			'user_set_password', 
			'UserName='||GetUserName(UserID)||',NewPassword='||NewPassword,
			False
		);
	end;
	
	procedure exec_sql(Query varchar2)
	as
		GrantQuery varchar2(128);
		c integer;
		rown integer;
	begin
		c := dbms_sql.open_cursor();
		begin
	    dbms_sql.parse(c, Query, dbms_sql.NATIVE);
  	  rown := dbms_sql.execute(c);
		exception
			when OTHERS then
				dbms_sql.close_cursor(c);
				raise_application_error(
					sbdecls.Error_InvalidParameters,
					'Error during query execution. Query: '
					||Query
					||', Error code: '
					||TO_CHAR(SQLCODE)
					||', Error message: '
					||SQLERRM);
		end;
		dbms_sql.close_cursor(c);
	end;
	
	procedure user_role_add(UserName varchar2, RoleName varchar2)
	as
	begin
		exec_sql('grant '||RoleName||' to '||UserName);
	end;
	
	procedure user_role_revoke(UserName varchar2, RoleName varchar2)
	as
	begin
		exec_sql(
'declare
  c integer;
  rown integer;
begin
  c := dbms_sql.open_cursor();
  dbms_sql.parse(c, ''revoke '||RoleName||' from '||UserName||''', dbms_sql.NATIVE);
  rown := dbms_sql.execute(c);
  dbms_sql.close_cursor(c);
end;');
	end;
	
	procedure group_membership_add(ClientID integer, GroupID integer)
	as
		UserName varchar2(64);
	begin
		access_check('Right_SecurityUserEdit');	
		
	/*	dbms_output.put_line(
			'group_membership_add. ClientID: '
			||TO_CHAR(ClientID)
			||', GroupID: '
			||TO_CHAR(GroupID));*/
			
		if client_is_user(ClientID) then
  		UserName := GetUserName(ClientID);
  		-- assign roles
  		for gr in c_group_roles(GroupID)
  		loop
  --			dbms_output.put_line('Assigning role, UserName: '||UserName||', Role: '||gr.Name);
  			user_role_add(UserName, gr.Name);
  		end loop;
		end if;
		
/*
		dbms_output.put_line(
			'Adding group membership, ClientID: '
			||TO_CHAR(ClientID)
			||', GroupID: '
			||TO_CHAR(GroupID));
*/			
  
  	insert into security_group_membership (
  		client#, group#)
  	values (
  		ClientID, GroupID);
			
	end;
	
	procedure group_membership_add(ClientID integer, GroupName varchar2)
	as
		cursor c_group_id
		is
			select ID from group$
			where name = GroupName;
		GroupID integer;
		NotFound boolean;
	begin

	/*	dbms_output.put_line(
			'group_membership_add. ClientID: '
			||TO_CHAR(ClientID)
			||', GroupName: '
			||GroupName);*/
	
		open c_group_id;
		fetch c_group_id into GroupID;
		NotFound := c_group_id%notfound;
		close c_group_id;
		
		if NotFound then
			raise_application_error(
				sbdecls.Error_InvalidParameters, 
				'Group not found: "'||GroupName||'"');
		end if;
		
		group_membership_add(ClientID, GroupID);
		
	end;
	
	procedure group_membership_revoke(ClientID integer, GroupID integer)
	as
	begin

/*
		dbms_output.put_line(
			'group_membership_revoke. ClientID: '
			||TO_CHAR(ClientID)
			||', GroupID: '
			||TO_CHAR(GroupID));
*/
		for gr in c_group_roles(GroupID)
		loop
			user_role_revoke(GetUserName(ClientID), gr.Name);
		end loop;
		delete from security_group_membership
		where (client# = ClientID) and (group# = GroupID); 
	end;
	
	procedure group_membership_clear(ClientID integer)
	as
		cursor c_client_groups
		is
			select group# 
				from security_group_membership
			where
				client# = ClientID; 
	begin

	/*	dbms_output.put_line(
			'group_membership_clear. ClientID: '
			||TO_CHAR(ClientID));*/

		for r_group in c_client_groups
		loop
			begin
				group_membership_revoke(ClientID, r_group.group#);
			exception
				when OTHERS then
					if SQLCODE = -20018 /* Role %s is not granted to %s */ then
						null;
					else
						raise;
					end if;
			end;
		end loop;		
	end;
	
	procedure group_membership_array(ClientID integer, arr varchar2)
	as
		GroupCount integer;
		GroupIDs t_str_array := sbutil.comma_to_array(arr,GroupCount);
		Ind BINARY_INTEGER := GroupIDs.FIRST;
	begin

	/*	dbms_output.put_line(
			'group_membership_array. ClientID: '
			||TO_CHAR(ClientID)
			||', arr: '
			||arr);*/
		
		-- clear all group membership info
		group_membership_clear(ClientID);
		
		-- add new group membership
		loop
			exit when Ind is null;
			group_membership_add(ClientID, TO_NUMBER(GroupIDs(Ind)));
			Ind := GroupIDs.NEXT(Ind);
		end loop;
				
	end;
	
	procedure group_roles_array(group# integer, arr varchar2)
	as
		RCount integer;
		Roles t_str_array := sbutil.comma_to_array(arr, RCount);
		Ind binary_integer := Roles.FIRST;
	begin
--		dbms_output.put_line('group_roles_array');
		delete from security_group_roles
		where GroupID = group#;
		
		loop
			exit when Ind is null;
			insert into security_group_roles (GroupID, RoleID)
			values (group#, TO_NUMBER(Roles(Ind)));
			Ind := Roles.NEXT(Ind);
		end loop;
	end;
	
	function group_is_member(client# integer, group# integer)
		return boolean
	is
		cursor c_group_member(clientID integer, groupID integer)
		is
			select count(*) as c 
			  from security_group_membership
			where (client# = clientID) and (group# = groupID);
		r c_group_member%rowtype;
		Result boolean; 
	begin
		open c_group_member(client#, group#);
		fetch c_group_member into r;
		Result := c_group_member%Found;
		close c_group_member;
		
		if Result then
			Result := r.c <> 0;
		end if;
		
		return Result;		
	end;
	
	procedure sid_rights_array(
		sid integer, 
		ClientID integer, 
		arr varchar2)
	as
		RCount integer;
		Rights t_str_array := sbutil.comma_to_array(arr, RCount);
		Ind binary_integer := Rights.FIRST;
	begin
	
	--	dbms_output.put_line('sid_rights_array: ClientID='||TO_CHAR(sid)||', ClientID='||TO_CHAR(ClientID)||', Arr='||Arr);
		delete from security_sid_link_access
		where link# in (
			select ID
			from security_sid_client_link
			where (sid# = sid) and (client# = clientID)
		);
		
		loop
			exit when Ind is null;
			
			access_user_grant(sid, clientID, TO_NUMBER(Rights(Ind)));
			
			Ind := Rights.NEXT(Ind);
		end loop;
		
	end;
	
	procedure sid_try_delete(sid# integer)
	as
	begin
		delete from security_sid$
		where ID = sid#;
	exception
		when OTHERS then
		 null;	--dbms_output.put_line('Cannot delete SID.'||SQLERRM);
	end;
	
	procedure access_denied
	is
	begin
  /*	raise_application_error(
  		sbdecls.Error_AccessDenied, 
  		'Access is denied');*/  --adm
     null; --dbms_output.put('');
	end;

	function access_check(
		client# integer, 
		sid# integer, 
		access# integer)
	return boolean
	is
		cursor c_access_check(
  		clientID integer, 
  		sid integer, 
  		accessID integer) 
		is
			select count(*) as c
			from SECURITY_sid_link_access
			where link# = (
  			select ID
  			from SECURITY_sid_client_link
  			where (sid# = sid) and (client# = clientID)
			)
			and access# = accessID;
		cursor c_containing_groups(ClientID integer)
		is
			select * from security_group_membership
			where
				client# = ClientID;
		r c_access_check%rowtype;
		PassStatus varchar2(6);
		sid_to_check t_sid;
		Result boolean;
	begin
		DumpGrantUserAccessParams(sid#, client#, access#, null);
		
		if (sid# is null) and (client# <> -1) then
			-- get the client's "Rights" sid
			sid_to_check := sblogin.UserSID(client#);
		else
			sid_to_check := sid#;
		end if;
		
--		dbms_output.put_line('access_check: client#='||TO_CHAR(client#)||', sid_to_check='||TO_CHAR(sid_to_check)||', access#='||TO_CHAR(access#));

		open c_access_check(client#, sid_to_check, access#);
		fetch c_access_check into r;
		Result := c_access_check%found;
		close c_access_check;
		
		if Result then
			Result := r.c <> 0;
		end if;
		
		if not Result then
			for r_containing_group in c_containing_groups(client#)
			loop
				-- Do not pass "sid_to_check" here
				Result := access_check(r_containing_group.group#, sid#, access#);
			end loop;
		end if;
		
/*
		if Result then
			PassStatus := 'passed';
		else
			PassStatus := 'failed';
		end if;
*/		
--		dbms_output.put_line('Security check '||PassStatus);
		
		return Result;
	end;
	
	function access_check(
		SAccessArr varchar2,
		client# integer default sblogin.UserID,
		sid# integer default null)
	return boolean
	is
		subtype t_str_array is sbutil.t_str_array;
		AccessArr t_str_array;
		AccessCount integer;
		Ind integer := 1;
		Result boolean := True;
		ASid# integer := sid#;
	begin
--		if ASid# is null then
--			Asid# := sblogin.usersid(client#);
			--sblogin.UserSID
--		end if; 
--		dbms_output.put_line('SID: '||TO_CHAR(sid#));
		AccessArr := sbutil.comma_to_array(SAccessArr,AccessCount);
		loop
			exit when Ind > AccessCount;
			if not access_check(client#, sid#, get_access_id(AccessArr(Ind))) then
				Result := False;
				exit;
			end if;
			Ind := Ind + 1;
		end loop;
		return Result;
	end;
	
	procedure access_check(
		SAccessArr varchar2,
		client# integer default sblogin.UserID,
		sid# integer default null)
	is
	begin
		--dbms_output.put_line('SID: '||TO_CHAR(sid#));
		if not access_check(SAccessArr, client#, sid#) then
			--dbms_output.put_line('SBSEC.access_check: Access check not passed. Raising exception.');
			access_denied();
		else
			null; --dbms_output.put_line('SBSEC.access_check: Access check passed');
		end if;
	end;
	
	function access_check_int(
		client# integer,
		sid# integer,
		Access# integer)
	return integer
	as
	begin
		if access_check(client#, sid#, Access#) then
			return 1;
		else
			return 0;
		end if;
	end;
	
	-- Checks user's right for requested access
	-- Recursive scans user's groups and its access rights
	function right_check(
		AccessName varchar2,
		user# integer default sblogin.UserID)
	return boolean
	as
		Passed boolean;
		cursor c_UserGroups(User# integer)
		is
			select group# 
				from security_group_membership
			where
				client# = User#;
	begin
		Passed := access_check(AccessName, User#);
		if not Passed then	-- check using client's sid
  		-- recurse to group's access
  		for r in c_UserGroups(User#)
  		loop
				Passed := access_check(AccessName, r.group#, client_sid_get(r.group#));
				exit when Passed;
  		end loop;
			return Passed;
		else
			return True;
		end if;
	end;
	
	procedure right_check(
		AccessName varchar2,
		user# integer default sblogin.UserID)
	is
	begin

/*		dbms_output.put_line('Right check request');
		dbms_output.put_line(SUBSTR('Requested access: '||AccessName, 1, 255));
		dbms_output.put_line('UserID: '||TO_CHAR(user#));
*/		
		if not right_check(AccessName, user#) then
			access_denied();
		end if;
		
	end;
	
	function client_sid_get(clientID integer)
		return t_sid
	as
  	cursor c_user_sid(UserID integer)
  	is
  		select sid#
  			from security_clients$
  		where
  			ID = UserID;
		Result integer;
	begin
	/*	open c_user_sid(ClientID);
		fetch c_user_sid into Result;
		if c_user_sid%NotFound then
			Result := -1;
		end if;
		close c_user_sid;
		
		if Result = -1 then
			raise_application_error(
				sbdecls.Error_DataCorrupted,
				'Failed to retreive user''s sid. UserID='||TO_CHAR(ClientID)
			);
		end if;
		
		return Result; */
		return uid;
	
	
	end;
	
	procedure client_sid_set(clientID integer, SID t_sid)
	as
	begin
		update security_clients$
		set
			sid# = sid
		where
			ID = clientID;
	end;
	
	function client_id_get(name varchar2)
		return integer
	is
		cursor c_UserID(ClientName varchar2)
		is
			select ID
			from security_clients$
			where name = ClientName;
		Result integer;
	begin
		open c_UserID(Name);
		fetch c_UserID into Result;
		if c_UserID%NotFound then
			raise_application_error(
				sbdecls.Error_InvalidParameters, 
				'Failed to retreive user ID: Name="'||name||'"');
		end if;
		close c_UserID;
		return Result;
	end;
	
	function client_type_get(ClientID integer)
		return integer
	is
		cursor c_client_type(ClientID integer)
		is
			select type# from security_clients$
			where ID = ClientID;
		Result integer;
	begin
		open c_client_type(ClientID);
		fetch c_client_type into Result;
		if c_client_type%NotFound then
			raise_application_error(
				sbdecls.Error_InvalidParameters, 
				'Client not found. ID='||TO_CHAR(ClientID)
			);
		end if;
		close c_client_type;
		
		return Result;		
	end;
	
	function client_is_user(ClientID integer)
		return boolean
	is
	begin
		return client_type_get(ClientID) = SecurityClientType_User;
	end;
	
	function client_is_group(ClientID integer)
		return boolean
	is
	begin
		return client_type_get(ClientID) = SecurityClientType_Group;
	end;
	
	function module_get_sid(ModuleName varchar2)
		return t_sid
	as
		cursor c_module_sid(ModuleName varchar2)
		is
			select SID#
			from MODULES
			where Name = ModuleName;
		Result t_sid;
	begin
		open c_module_sid(ModuleName);
		fetch c_module_sid into Result;
		if c_module_sid%NotFound then
			Result := null;
		end if;
		close c_module_sid;
		if Result is null then
			Result := -1;
		end if;
		return Result;
	end;
	
END;
/


