CREATE OR REPLACE 
PACKAGE BODY sbop1 
is

	/* *********************************************** */
  /*         SmartBank Operation Day package         */
	/*  Copyright 2002, Smart Systems Technoogy, Ltd.  */
  /* *********************************************** */
	
	/* Error messages */

	Message_NoMultyCurrencyError constant varchar2(64) := 
		'Multy currency transactions are not enabled';

	Message_NullAmountsError constant varchar2(64) := 
		'Amount or LAmount must be non-zero';

	Merr_DebitAccountArested constant varchar2(64) :=
	 'Debit account are under arest';

	Merr_CreditAccountArested constant varchar2(64) :=
		'Credit account are under arest';

	Merr_InsufficientParameters constant varchar2(64) :=
		'One of amounts must be not null';
		
	/* variables & constants */  
		
	TrDestinationFormatDebit varchar2(1024) := 
		SBMSG.get_message('SBOP.AddTransaction.MultyCurrencyDestinationFormat_Debit');
		
	TrDestinationFormatCredit varchar2(1024) := 
		SBMSG.get_message('SBOP.AddTransaction.MultyCurrencyDestinationFormat_Credit');

	/* Functions */

  function get_date
    return sysdat.tek_dat%type
  as
    currdate   sysdat.tek_dat%type;
  begin
    select tek_dat
      into currdate
      from sysdat;

    return currdate;
  end;

	procedure add_std_transaction (
    DebitID             integer,
    CreditID            integer,
    DAmount        			number,
		CAmount							number,
    LAmount             number,
    DebitRate           number,
    CreditRate          number,
    TrName              varchar2,
    Flags               integer default 0,
		InBalanceChar				integer,
		OutBalanceChar			integer,
    Result    in out    integer,
		TransactionID in		integer default null
  )
  as
    DebitCurrency       account.val_acc%type;
    CreditCurrency      account.val_acc%type;
    DebitORate          number (11, 2);
    CreditORate         number (11, 2);
    DebitAmount         tenostat.ostat%type;
    CreditAmount        tenostat.ostat%type;
    DebitLAmount        tenostat.pok_ostat%type;
    CreditLAmount       tenostat.pok_ostat%type;
    CurrencyRate        number (11, 2);
    CurrentDate         date;
    DebitLimit          account.limit%type;
    CreditLimit         account.limit%type;
    DebitAccType        bal_spr1.TypeID%type;
    CreditAccType       integer;
    DebetCID            integer;
    CreditCID           integer;
    Debit_DTurnover     tenostat.obr_d%type;
    Debit_DLTurnover    tenostat.pok_obr_d%type;
    Debit_CTurnover     tenostat.obr_k%type;
    Debit_CLTurnover    tenostat.pok_obr_k%type;
    Credit_DTurnover    tenostat.obr_d%type;
    Credit_DLTurnover   tenostat.pok_obr_d%type;
    Credit_CTurnover    tenostat.obr_k%type;
    Credit_CLTurnover   tenostat.pok_obr_k%type;
    Debit_SID           integer;
    Credit_SID          integer;
    TrDebitAmount       number (15, 2);
		TrCreditAmount      number (15, 2);
    TrLAmount           number (15, 2);
		ATransactionID 		  integer := TransactionID;
  begin
		if ATransactionID is null then
			select tr_seg_PROVARCH.nextval
				into ATransactionID
			from dual;
		end if;
	
    /* get accounts' data */
    select val_acc, limit, bal_cn1
      into DebitCurrency, DebitLimit, Debit_SID
      from account
     where id = DebitID;

    select val_acc, limit, bal_cn1
      into CreditCurrency, CreditLimit, Credit_SID
      from account
     where id = CreditID;

    /* get account's states */
    select ostat, pok_ostat, obr_d, pok_obr_d,
           obr_k, pok_obr_k
      into DebitAmount, DebitLAmount, Debit_DTurnover, Debit_DLTurnover,
           Debit_CTurnover, Debit_CLTurnover
      from tenostat
     where acc_id = DebitID;

    select ostat, pok_ostat, obr_d, pok_obr_d,
           obr_k, pok_obr_k
      into CreditAmount, CreditLAmount, Credit_DTurnover, Credit_DLTurnover,
           Credit_CTurnover, Credit_CLTurnover
      from tenostat
     where acc_id = creditid;

    /* get account's flags (active, passive, etc.) */
    select TypeID
      into DebitAccType
      from bal_spr1
     where bal_cn = Debit_SID;

    select TypeID
      into CreditAccType
      from bal_spr1
     where bal_cn = Credit_SID;

    CurrentDate := get_date;

    if  (TrDebitAmount = 0) and (TrLAmount = 0)
    then
      raise_application_error (
        sbdecls.Error_NullAmounts,
        Message_NullAmountsError
      );
    end if;

    /* Check arest flags */
    if    sbutil.get_account_flag (DebitID, 'Arested')
       or sbutil.get_account_flag (DebitID, 'DebitArested')
    then
      raise_application_error (
        sbdecls.Error_DebitAccountArested,
        Merr_DebitAccountArested
      );
    end if;

    if    sbutil.get_account_flag (CreditID, 'Arested')
       or sbutil.get_account_flag (CreditID, 'CreditArested')
    then
      raise_application_error (
        sbdecls.Error_CreditAccountArested,
        Merr_CreditAccountArested
      );
    end if;

    /* get rates of account's currencies */

    select ostat
      into DebitORate
      from operkurs
     where (dat = CurrentDate) and (val_kod = DebitCurrency);

    select ostat
      into creditorate
      from operkurs
     where (dat = CurrentDate) and (val_kod = CreditCurrency);

    /* round policy */
    TrDebitAmount := sbutil.Round_Currency (DAmount);
		TrCreditAmount := sbutil.Round_Currency (CAmount); 
    TrLAmount := sbutil.Round_Currency (LAmount);

		if TrLAmount is null then
			if TrDebitAmount is not null then
				TrLAmount := TrDebitAmount * DebitORate;
			elsif TrCreditAmount is null then
				raise_application_error(
					sbdecls.Error_InsufficientParameters,
					Merr_InsufficientParameters
				);
			else
				TrLAmount := TrCreditAmount * CreditORate;
			end if;
		end if;

		if TrDebitAmount is null then
			TrDebitAmount := TrLAmount / DebitORate;
		end if;

		if TrCreditAmount is null then
			TrCreditAmount := TrLAmount / CreditORate;
		end if;

    /* check account's balance & limit conditions
        and raise an exception if they are violated */

/*
    if not (   sbutil.get_account_flag (DebitID, 'Overdraft')
            or (DebitAccType = sbdecls.atActive)
            or (DebitAccType = sbdecls.atActivePassive)
            or (  DebitAmount
                - DebitLimit >= TrDebitAmount
               )
           )
    then
      raise_application_error (
        sbdecls.Error_DebitBalanceViolation,
           'Amount or limit condition on debet account is not enought for transaction. '
        || 'Balance: '
        || DebitAmount
        || ', localized balance: '
        || DebitLAmount
        || '. Required: '
        || TrDebitAmount
        || ', '
        || TrLAmount
      );
    end if;
*/

/*
   if not (   sbutil.get_account_flag (CreditID, 'Overdraft')
            or (CreditAccType = sbdecls.atPassive)
            or (CreditAccType = sbdecls.atActivePassive)
            or (  CreditAmount
                - CreditLimit <= -TrCreditAmount
               )
           )
    then
      raise_application_error (
        sbdecls.Error_CreditBalanceViolation,
           'Amount or limit condition on credit account is not enought for transaction. '
        || 'Balance: '
        || CreditAmount
        || ', localized balance: '
        || CreditLAmount
        || '. Required: '
        || TrCreditAmount
        || ', '
        || TrLAmount
      );
    end if;
*/

    /* All checks passed, values accepted. Processing... :) */

    /*  if atfNoAdd flags is fired,
        we will not actually add transaction,
        & value returned in "Result" will -1
    */

    if BitAnd (Flags, sbdecls.atfNoAdd) = 0
    then
      /* Add in PROVARCH */

      insert into provarch
                  (ID,
									 dat, debt, kredit, val_acc,
                   currencyid_c, ammount, lammount, tim, rate_d,
                   rate_c, ammount_c, Kassa_B, Kassa_Z, name)
           values (ATransactionID,
					 				 CurrentDate, DebitID, CreditID, DebitCurrency,
                   CreditCurrency, TrDebitAmount, TrLAmount, SYSDATE, DebitRate,
                   CreditRate, TrCreditAmount, InBalanceChar, OutBalanceChar, TrName)
					returning ID into Result;

      /* add transaction into provdoc */

      Debit_DTurnover :=   Debit_DTurnover
                         + TrDebitAmount;
      Debit_DLTurnover :=   Debit_DLTurnover
                          + TrLAmount;
      Credit_CTurnover :=   Credit_CTurnover
                          + TrCreditAmount;
      Credit_CLTurnover :=   Credit_CLTurnover
                           + TrLAmount;

      update tenostat
         set ostat =   DebitAmount
                     - TrDebitAmount,
             pok_ostat =   DebitLAmount
                         - TrLAmount,
             datdate = CurrentDate,
             obr_d = Debit_DTurnover,
             pok_obr_d = Debit_DLTurnover
       where acc_id = DebitID;

      update tenostat
         set ostat =   CreditAmount
                     + TrCreditAmount,
             pok_ostat =   CreditLAmount
                         + TrLAmount,
             datdate = CurrentDate,
             obr_k = Credit_CTurnover,
             pok_obr_k = Credit_CLTurnover
       where acc_id = CreditID;
    else
      Result := -1;    /* Transaction not actually added - result undefined */
    end if;                                    /* if bitand ... atfNoAdd ... */
  end;

	procedure add_std_LazyTransaction (
    DebitID             integer,
    CreditID            integer,
    DAmount    					number,
		CAmount							number,
    LAmount             number,
    DebitRate           number,
    CreditRate          number,
    TrName              varchar2,
    Flags               integer default 0,
  	InBalanceChar				integer,
  	OutBalanceChar			integer,
    Result    in out    integer
  )
  as
    DebitCurrency       account.val_acc%type;
    CreditCurrency      account.val_acc%type;
    DebitORate          number (11, 2);
    CreditORate         number (11, 2);
    DebitAmount         tenostat.ostat%type;
    CreditAmount        tenostat.ostat%type;
    DebitLAmount        tenostat.pok_ostat%type;
    CreditLAmount       tenostat.pok_ostat%type;
    CurrencyRate        number (11, 2);
    CurrentDate         date;
    DebitLimit          account.limit%type;
    CreditLimit         account.limit%type;
    DebitAccType        bal_spr1.TypeID%type;
    CreditAccType       integer;
    DebetCID            integer;
    CreditCID           integer;
    Debit_DTurnover     tenostat.obr_d%type;
    Debit_DLTurnover    tenostat.pok_obr_d%type;
    Debit_CTurnover     tenostat.obr_k%type;
    Debit_CLTurnover    tenostat.pok_obr_k%type;
    Credit_DTurnover    tenostat.obr_d%type;
    Credit_DLTurnover   tenostat.pok_obr_d%type;
    Credit_CTurnover    tenostat.obr_k%type;
    Credit_CLTurnover   tenostat.pok_obr_k%type;
    Debit_SID           integer;
    Credit_SID          integer;
    TrDebitAmount       number (15, 2);
	TrCreditAmount      number (15, 2);
    TrLAmount           number (15, 2);
  begin
    /* get accounts' data */
    select val_acc, limit, bal_cn1
      into DebitCurrency, DebitLimit, Debit_SID
      from account
     where id = DebitID;

    select val_acc, limit, bal_cn1
      into CreditCurrency, CreditLimit, Credit_SID
      from account
     where id = CreditID;

    /* get account's states */
    select ostat, pok_ostat, obr_d, pok_obr_d,
           obr_k, pok_obr_k
      into DebitAmount, DebitLAmount, Debit_DTurnover, Debit_DLTurnover,
           Debit_CTurnover, Debit_CLTurnover
      from LazyRest
     where acc_id = DebitID;

    select ostat, pok_ostat, obr_d, pok_obr_d,
           obr_k, pok_obr_k
      into CreditAmount, CreditLAmount, Credit_DTurnover, Credit_DLTurnover,
           Credit_CTurnover, Credit_CLTurnover
      from LazyRest
     where acc_id = creditid;

    /* get account's flags (active, passive, etc.) */
    select TypeID
      into DebitAccType
      from bal_spr1
     where bal_cn = Debit_SID;

    select TypeID
      into CreditAccType
      from bal_spr1
     where bal_cn = Credit_SID;

    CurrentDate := sbop.get_date;

    if  (TrDebitAmount = 0) and (TrLAmount = 0)
    then
      raise_application_error (
        sbdecls.Error_NullAmounts,
        Message_NullAmountsError
      );
    end if;

    /* Check arest flags */
    if    sbutil.get_account_flag (DebitID, 'Arested')
       or sbutil.get_account_flag (DebitID, 'DebitArested')
    then
      raise_application_error (
        sbdecls.Error_DebitAccountArested,
        Merr_DebitAccountArested
      );
    end if;

    if    sbutil.get_account_flag (CreditID, 'Arested')
       or sbutil.get_account_flag (CreditID, 'CreditArested')
    then
      raise_application_error (
        sbdecls.Error_CreditAccountArested,
        Merr_CreditAccountArested
      );
    end if;

    /* get rates of account's currencies */

    select ostat
      into DebitORate
      from operkurs
     where (dat = CurrentDate) and (val_kod = DebitCurrency);

    select ostat
      into CreditORate
      from operkurs
     where (dat = CurrentDate) and (val_kod = CreditCurrency);

    /* round policy */
    TrDebitAmount := sbutil.Round_Currency (DAmount);
		TrCreditAmount := sbutil.Round_Currency (CAmount); 
    TrLAmount := sbutil.Round_Currency (LAmount);

		if TrLAmount is null then
			if TrDebitAmount is not null then
				TrLAmount := TrDebitAmount * DebitORate;
			elsif TrCreditAmount is null then
				raise_application_error(
					sbdecls.Error_InsufficientParameters,
					Merr_InsufficientParameters
				);
			else
				TrLAmount := TrCreditAmount * CreditORate;
			end if;
		end if;

		if TrDebitAmount is null then
			TrDebitAmount := TrLAmount / DebitORate;
		end if;

		if TrCreditAmount is null then
			TrCreditAmount := TrLAmount / CreditORate;
		end if;

    /* check account's balance & limit conditions
        and raise an exception if they are violated */

/*
    if not (   sbutil.get_account_flag (DebitID, 'Overdraft')
            or (DebitAccType = sbdecls.atActive)
            or (DebitAccType = sbdecls.atActivePassive)
            or (  DebitAmount
                - DebitLimit >= TrDebitAmount
               )
           )
    then
      raise_application_error (
        sbdecls.Error_DebitBalanceViolation,
           'Amount or limit condition on debet account is not enought for transaction. '
        || 'Balance: '
        || DebitAmount
        || ', localized balance: '
        || DebitLAmount
        || '. Required: '
        || TrDebitAmount
        || ', '
        || TrLAmount
      );
    end if;
*/

/*
   if not (   sbutil.get_account_flag (CreditID, 'Overdraft')
            or (CreditAccType = sbdecls.atPassive)
            or (CreditAccType = sbdecls.atActivePassive)
            or (  CreditAmount
                - CreditLimit <= -TrCreditAmount
               )
           )
    then
      raise_application_error (
        sbdecls.Error_CreditBalanceViolation,
           'Amount or limit condition on credit account is not enought for transaction. '
        || 'Balance: '
        || CreditAmount
        || ', localized balance: '
        || CreditLAmount
        || '. Required: '
        || TrCreditAmount
        || ', '
        || TrLAmount
      );
    end if;
*/

    /* All checks passed, values accepted. Processing... :) */

    /*  if atfNoAdd flags is fired,
        we will not actually add transaction,
        & value returned in "Result" will -1
    */

    if BitAnd (Flags, sbdecls.atfNoAdd) = 0  then
      /* Add in LazyRest */

      insert into LazyTransaction
                  (dat, debt, kredit, val_acc,
                   currencyid_c, ammount, lammount, tim, rate_d,
                   rate_c, ammount_c, Kassa_B, Kassa_Z, name)
      values (CurrentDate, DebitID, CreditID, DebitCurrency,
                   CreditCurrency, TrDebitAmount, TrLAmount, SYSDATE, DebitRate,
                   CreditRate, TrCreditAmount, InBalanceChar, OutBalanceChar, TrName)
			returning ID into Result;

      /* add transaction into LazyTransaction */

      Debit_DTurnover   :=   Debit_DTurnover     + TrDebitAmount;
      Debit_DLTurnover  :=   Debit_DLTurnover    + TrLAmount;
      Credit_CTurnover  :=   Credit_CTurnover    + TrCreditAmount;
      Credit_CLTurnover :=   Credit_CLTurnover   + TrLAmount;

      update LazyRest set 
             ostat     =   DebitAmount  - TrDebitAmount,
             pok_ostat =   DebitLAmount - TrLAmount,
             datdate   =   CurrentDate,
             obr_d     =   Debit_DTurnover,
             pok_obr_d =   Debit_DLTurnover
       where acc_id = DebitID;

      update LazyRest set 
             ostat     =   CreditAmount  + TrCreditAmount,
             pok_ostat =   CreditLAmount + TrLAmount,
             datdate   =   CurrentDate,
             obr_k     =   Credit_CTurnover,
             pok_obr_k =   Credit_CLTurnover
       where acc_id = CreditID;
    else
      Result := -1;    /* Transaction not actually added - result undefined */
    end if;                                   /* if bitand ... atfNoAdd ... */
  end;

  procedure add_transaction (
    DebitID            integer,
    CreditID           integer,
    DebitAmount        number,
		CreditAmount       number,
    LAmount            number,
    DebitRate          number,
    CreditRate         number,
    TrName             varchar,
    Flags              integer,
		InBalanceChar	in	 integer,
		OutBalanceChar in  integer,
    Result       out   integer,
		TransactionID			 integer default null
  )
  as
    Debit             integer;
    Credit            integer;
    CurrentDate       sysdat.tek_dat%type;
    DebitCurrency     account.val_acc%type;
    CreditCurrency    account.val_acc%type;
    DebitTrRate        operkurs.ostat%type;
    CreditTrRate       operkurs.ostat%type;
    DebitORate        operkurs.ostat%type;
    CreditORate       operkurs.ostat%type;
    RegSDebit         avalute.sdebet%type;
    RegSCredit        avalute.scredit%type;
    ChildTrName       provdoc.name%type;
    ParentID          number;
    DeltaRate         number;
    DebitDeltaRate    number;
    CreditDeltaRate   number;
--		params						t_params := t_params();
  begin
    select tek_dat
      into currentdate
      from sysdat;

    select val_acc
      into DebitCurrency
      from account
     where id = DebitID;

    select val_acc
      into CreditCurrency
      from account
     where id = CreditID;

    select ostat
      into DebitORate
      from operkurs
     where (dat = CurrentDate) and (val_kod = DebitCurrency);

    select ostat
      into CreditORate
      from operkurs
     where (dat = CurrentDate) and (val_kod = CreditCurrency);

    Result := 0;
		
		if DebitRate = 0 then
			DebitTrRate := DebitORate;
	    DebitDeltaRate := 0;
		else   
			DebitTrRate := DebitRate;
	    DebitDeltaRate :=  DebitRate - DebitORate;
		end if;
		
		if CreditRate = 0 then
			CreditTrRate := CreditORate;
	    CreditDeltaRate := 0;
		else  
			CreditTrRate := CreditRate;
	    CreditDeltaRate := CreditRate - CreditORate;
		end if;
		
    if BitAnd (Flags, sbdecls.atfCommitImmediate) = 0
		then
			/* add delayed transaction. 
			 There are no additional child transaction possible */
      add_std_lazytransaction (
        DebitID, CreditID, DebitAmount, CreditAmount, LAmount,
        DebitTrRate, CreditTrRate, TrName, Flags,
    	  InBalanceChar, OutBalanceChar, Result);
		else
      add_std_transaction (
        DebitID, CreditID, DebitAmount, CreditAmount, LAmount,
        DebitTrRate, CreditTrRate, TrName, Flags,
  			InBalanceChar, OutBalanceChar, Result, TransactionID);
      if DebitCurrency = CreditCurrency then
        return;
      end if;
			
			/* calculation of child transaction is only enabled if
			 immediate commit flag is set, because rate may not be set
			 for delayed transaction */
  
      ParentID := Result;
  
      if  (DebitCurrency <> 0) and (CreditCurrency <> 0)
      then
  			raise_application_error(
  				sbdecls.Error_DifferentCurrencies, 
  				'Transactions between accounts having different currencies - not implemented');
      end if;
  
      if  (DebitCurrency = 0) and (CreditDeltaRate <> 0.0)
      then
  	    select SDebet, SCredit
    	    into RegSDebit, RegSCredit
      	  from avalute
  	     where valute = CreditCurrency;
  
  	    if (RegSDebit is null) or (RegSCredit is null) then
    	    raise_application_error(
  					sbdecls.Error_NoMultiCurrencyEnabled, 
  					Message_NoMultyCurrencyError);
  	    end if;
  
        DeltaRate := CreditDeltaRate * CreditAmount;
  
        if CreditDeltaRate > 0.0
        then
          Debit := DebitID;
          Credit := RegSCredit;
        else
          Debit := RegSDebit;
          Credit := DebitID;
          DeltaRate := -DeltaRate;
        end if;
      else
        if  (CreditCurrency = 0) and (DebitDeltaRate <> 0.0)
        then
          select SDebet, SCredit
            into RegSDebit, RegSCredit
            from avalute
           where valute = DebitCurrency;
  
  		    if (RegSDebit is null) or (RegSCredit is null) then
    		    raise_application_error(
  						sbdecls.Error_NoMultiCurrencyEnabled, 
  						Message_NoMultyCurrencyError);
  		    end if;
  
          DeltaRate := DebitDeltaRate * DebitAmount;
  
          if DebitDeltaRate > 0.0
          then
            Debit := RegSDebit;
            credit := CreditID;
          else
            Debit := CreditID;
            Credit := RegSCredit;
            DeltaRate := -DeltaRate;
          end if;
        else
          return; /* no additional transaction required */
        end if;
      end if;
  
      ChildTrName :='';
  		
      add_std_transaction (
        Debit,
        Credit,
        DeltaRate,
        DeltaRate,
        DeltaRate,
  			0,
  			0,
        ChildTrName,
        Flags,
  			0,
  			0,
        Result
      );
      
		end if;

    commit;
  end;

  function add_account (
    customerid   in   number,
    op_id        in   number,
    accno        in   varchar,
    currencyid        integer,
    name         in   varchar,
    open_dat     in   date,
    balcn             integer,
    limit             number default 0,
    close_dat         date default null,
    bal_cn2           integer default 0,
    bal_cn3           integer default 0,
    bal_cn4           integer default 0,
    filial            number default 0,
    sim_otcet         number default 0,
    typeacc           varchar default '',
    old_acc_no        varchar default 0,
    pair_acc          number default 0,
    insider           varchar default 0
  )
    return integer
  is
    resultid   integer;
  begin
    insert into account
                (kli_id, op_id, acc_no, val_acc, name, open_dat, close_dat,
                 bal_cn1, bal_cn2, bal_cn3, bal_cn4, filial, sim_otcet,
                 tipacc, limit, old_acc_no, pair_acc, insider)
         values (customerid, op_id, accno, currencyid, name, open_dat, null,
                 balcn, bal_cn2, bal_cn3, bal_cn4, filial, sim_otcet,
                 typeacc, limit, old_acc_no, pair_acc, insider);

    /* TODO: add multythread synchronization -
           create transaction */
    select tr_seg_account.currval
      into resultid
      from DUAL;

    return resultid;
  end;

  procedure add_archost (acc_id in number, datdate in date)
  as
  begin
    insert into archost(
			acc_id, ostat, pok_ostat, datdate, obr_d, obr_k, pok_obr_d,pok_obr_k)
    values (
			acc_id, 0,0, datdate, 0, 0, 0, 0);
  end;

  procedure add_customer (
    op_id          number,
    open_dat       date,
    name           varchar2,
    close_dat      date default null,
    nerezident     integer default 0,
    prinad_kod     number default 0,
    short_name     varchar default '',
    group_klie     number default 0,
    vid_sob        number default 0,
    org_sob        number default 0,
    sfera_dey      number default 0,
    otrasl         number default 0,
    nalog_kod      number default 0,
    kod_okpro      number default 0,
    inn            number default 0,
    dat_nal        date default null,
    dat_ustav      date default null,
    bik            number default 0,
    otv_lico       varchar default ' ',
    otv_passport   varchar default ' ',
    otv_issued     varchar default ' ',
    otv_isdate     date default null
  )
  is
  begin
    insert into customers
                (op_id, open_dat, close_dat, nerezident, prinad_kod, name,
                 short_name, group_klie, vid_sob, org_sob, sfera_dey, otrasl,
                 nalog_kod, kod_okpro, inn, dat_nal, dat_ustav, bik,
                 otv_lico, otv_passport, otv_issued, otv_isdate)
    values (
			op_id, open_dat, close_dat, nerezident, prinad_kod, name, short_name, 
			group_klie, vid_sob, org_sob, sfera_dey, otrasl, nalog_kod, kod_okpro,
      inn, dat_nal, dat_ustav, bik, otv_lico, otv_passport, otv_issued, 
			otv_isdate);
  end;

  procedure add_tenostat (acc_id in number, datdate in date)
  as
  begin
    insert into tenostat(
			acc_id, ostat, pok_ostat, datdate, obr_d, obr_k, pok_obr_d, pok_obr_k)
    values (
			acc_id, 0, 0, datdate, 0, 0, 0, 0);
  end;

  procedure close_customer (
    v_id                number,
    currentdate         date default null,
    result        out   number
  )
  as
  begin
    update account
       set close_dat = currentdate
     where kli_id = v_id;

    update customers
       set close_dat = currentdate
     where id = v_id;
  end;

  procedure del_std_transaction (TransactionID integer)
  as
    Tr            provdoc%rowtype;
    AddTrResult   integer;
  begin
    select *
      into Tr
      from provdoc
     where ID = TransactionID;
		 
    add_std_transaction(
      tr.debt,
      tr.kredit,
      -tr.Ammount,
      -tr.ammount_c,
      -tr.LAmmount,
      0,
      0,
      'temporary transaction',
      0,
			0,
			0,
      AddTrResult
    );

    delete from provarch
      where ID in (TransactionID, AddTrResult);
  end;

  procedure del_transaction (TransactionID integer)
  as
		ParentID integer;
    ChildID  integer;
		TransactionStatus integer;

    cursor c_remainder
    is
      (select id
         from provdoc
        where parentid = TransactionID);
				
		cursor c_delayed_transaction
		is
			select * from LAZYTRANSACTION
			where ID = TransactionID;
			
		DelayedTransaction c_delayed_transaction%rowtype;
  begin
		select status
			into TransactionStatus 
			from TODAY_TRANSACTIONS
		where
			ID = TransactionID;
			
		if (TransactionStatus = sbdecls.tsDelayed) or (TransactionStatus = sbdecls.tsRejected) then
		
			open c_delayed_transaction;
			fetch c_delayed_transaction into DelayedTransaction; 
		
			delete from LAZYTRANSACTION
			where ID = TransactionID;
			
			update LAZYREST
			set
			  ostat = ostat + DelayedTransaction.Ammount,
				pok_ostat = pok_ostat + DelayedTransaction.LAmmount,
				obr_d = obr_d - DelayedTransaction.Ammount,
				pok_obr_d = pok_obr_d - DelayedTransaction.LAmmount
			where
			  ID_NUMBER = TransactionID;  
		
			update LAZYREST
			set
			  ostat = ostat - DelayedTransaction.Ammount,
				pok_ostat = pok_ostat - DelayedTransaction.LAmmount,
				obr_k = obr_k - DelayedTransaction.Ammount,
				pok_obr_k = pok_obr_k - DelayedTransaction.LAmmount
			where
			  ID_NUMBER = TransactionID;  

		else
  	
  		-- retreive ParentID is present
  		select ParentID
  			into ParentID 
  			from provdoc
  		where ID = TransactionID;
  		
  		if ParentID is not null then
  			raise_application_error(
  				sbdecls.Error_ChildTransaction, 
  				'Unable to delete child transaction - delete parent first. ChildID: '
  					||TO_CHAR(TransactionID)
  					||', ParentID: '
  					||TO_CHAR(ParentID));
  		end if;
  	
  		-- delete specified transaction
      del_std_transaction (TransactionID);
  
  		-- delete childs if present
      open c_remainder;
      loop
        fetch c_remainder into ChildID;
        exit when c_remainder%notfound;
        del_std_transaction(ChildID);
      end loop;
  
  		close c_remainder;
		end if;
		--commit;
  end;

  procedure upd_account (
    v_id                integer, -- ID
    v_customerid   in   number, -- KLI_ID
    v_op_id        in   number, -- OP_ID
    v_accno        in   varchar, -- ACC_NO
    v_currencyid        integer, -- VAL_ACC
    v_name         in   varchar, -- NAME
    v_open_dat     in   date, -- OPEN_DAT
    v_balcn             integer, -- BAL_CN1
    v_limit             number default 0, -- LIMIT
    v_close_dat         date default null,
    v_bal_cn2           integer default 0,
    v_bal_cn3           integer default 0,
    v_bal_cn4           integer default 0,
    v_filial            number default 0,
    v_sim_otcet         number default 0,
    v_typeacc           varchar default '', --TIPACC
    v_old_acc_no        varchar default 0,
    v_pair_acc          number default 0,
    v_insider           varchar default 0
  )
  is
  begin
    update account
       set kli_id = v_customerid,
           op_id = v_op_id,
           acc_no = v_accno,
           val_acc = v_currencyid,
           name = v_name,
           open_dat = v_open_dat,
           close_dat = v_close_dat,
           bal_cn1 = v_balcn,
           bal_cn2 = v_bal_cn2,
           bal_cn3 = v_bal_cn3,
           bal_cn4 = v_bal_cn4,
           filial = v_filial,
           sim_otcet = v_sim_otcet,
           tipacc = v_typeacc,
           limit = v_limit,
           old_acc_no = v_old_acc_no,
           pair_acc = v_pair_acc,
           insider = v_insider
     where id = v_id;

    commit;
  end;

  procedure upd_customer (
    v_id             integer,
    v_op_id          number,
    v_open_dat       date,
    v_name           varchar,
    v_close_dat      date default null,
    v_nerezident     integer default 0,
    v_prinad_kod     number default 0,
    v_short_name     varchar default '',
    v_group_klie     number default 0,
    v_vid_sob        number default 0,
    v_org_sob        number default 0,
    v_sfera_dey      number default 0,
    v_otrasl         number default 0,
    v_nalog_kod      number default 0,
    v_kod_okpro      number default 0,
    v_inn            number default 0,
    v_dat_nal        date default null,
    v_dat_ustav      date default null,
    v_bik            number default 0,
    v_otv_lico       varchar default ' ',
    v_otv_passport   varchar default ' ',
    v_otv_issued     varchar default ' ',
    v_otv_isdate     date default null
  )
  is
  begin
    update customers
       set op_id = v_op_id,
           open_dat = v_open_dat,
           close_dat = v_close_dat,
           nerezident = v_nerezident,
           prinad_kod = v_prinad_kod,
           name = v_name,
           short_name = v_short_name,
           group_klie = v_group_klie,
           vid_sob = v_vid_sob,
           org_sob = v_org_sob,
           sfera_dey = v_sfera_dey,
           otrasl = v_otrasl,
           nalog_kod = v_nalog_kod,
           kod_okpro = v_kod_okpro,
           inn = v_inn,
           dat_nal = v_dat_nal,
           dat_ustav = v_dat_ustav,
           bik = v_bik,
           otv_lico = v_otv_lico,
           otv_passport = v_otv_passport,
           otv_issued = v_otv_issued,
           otv_isdate = v_otv_isdate
     where id = v_id;
  end;

  procedure close_account (accid integer, doclose integer)
  is
    accstate         tenostat%rowtype;
    closedatevalue   sysdat.tek_dat%type;
  begin
    select *
      into accstate
      from tenostat
     where acc_id = accid;

    if    accstate.ostat <> 0
       or accstate.pok_ostat <> 0
    then
      raise_application_error (
        sbdecls.Error_AccountBalanceNotZero,
           'Account balance and localized balance must be zero before '
        || 'closing account. State dump: balance: '
        || accstate.ostat
        || '; localized balance: '
        || accstate.pok_ostat
        || '.'
      );
    end if;

    if doclose = 1
    then
      closedatevalue := get_date;
    else
      closedatevalue := null;
    end if;

    update account
       set close_dat = closedatevalue
     where id = accid;
  end;

  function add_temp_transaction (
    TempID             integer,
    DebitID            integer,
    CreditID           integer,
    DebitAmount        number,
		CreditAmount			 number,
    LAmount            number,
    DebitRate          number,
    CreditRate         number,
    TrName             varchar,
    Flags              integer,
		TransactionID			 integer default null
  )
		return integer
  as
		Result integer;
		ATransactionID integer := TransactionID;
  begin
		if TransactionID is null then
			select tr_seg_PROVARCH.nextval
				into ATransactionID
			from dual;
		end if;
		
    insert into TempTranz (
			ID,
      DebitID, CreditID, DebitAmount, CreditAmount, LAmount, 
			DebitRate, CreditRate, TrName, Flags, TempID)   
    values (
			ATransactionID,
      DebitID, CreditID, DebitAmount, CreditAmount, LAmount,    
      DebitRate, CreditRate, TrName, Flags, TempID)
		returning ID into Result;
		return Result;
  end;

  function apply_temp_transaction(
    Temp temptranz%rowtype)
  return integer
  as
    Result integer;
  begin
    add_transaction(
      Temp.DebitID,
      Temp.CreditID,
      Temp.DebitAmount,
      Temp.CreditAmount,
      Temp.LAmount,
      Temp.DebitRate,
      Temp.CreditRate,
      Temp.TrName,
      Temp.flags,
			0,--Temp.InBalanceChar,
			0,--Temp.InBalanceChar,
      Result,
			Temp.ID
    );
    update temptranz
    set
      Applied = 1
    where ID = Temp.ID;
    return Result;
  end;

  function apply_temp_transaction(
    TempTrID integer)
  return integer
  as
    Temp temptranz%rowtype;
  begin
    select *
    	into temp 
    	from temptranz
    where ID = TempTrID;
		dbms_output.put_line(substr('Value of temp transaction=('||temp.debitamount||' '||temp.creditamount||' '||temp.lamount, 1,255));
    return apply_temp_transaction(Temp);
  end;

  function commit_temp_transactions (
    ATempID integer)
  return integer
  as
    Temp TempTranz%rowtype;
    TrResult integer;
    Result integer;
    cursor Transactions
    is
      select * from TempTranz
      where TempID = ATempID;
  begin
    Result := 0;
    for Temp in Transactions
    loop
			dbms_output.put_line('applying temp transaction #'||Temp.ID);
      TrResult := apply_temp_transaction(Temp.ID);
      Result := Result + 1;
    end loop;
    return Result;
  end;

  function cancel_temp_transaction(
    ATempID integer)
  return integer  -- number of commited transactions         
  as
  begin
    delete from temptranz
    where TempID = ATempID;
    return SQL%rowcount;
  end;

  function gen_temp_id
  return integer
  as
  begin
    return sbutil.gen_unique_id();    
  end;

	procedure set_acc_sid(acc_id integer, sid sbsec.t_sid)
	as
	begin
		update account
		set
			sid# = sid
		where
			id = acc_id;
		if SQL%rowcount = 0 then
			raise_application_error(sbdecls.Error_InvalidParameters, 'Invalid acount id specified');
		end if;
	end;
	
	function get_account_balance(AccID integer)
		return t_acc_balance
	as
		Result t_acc_balance;
	begin
		select ostat, pok_ostat, obr_d, pok_obr_d,obr_k, pok_obr_k
			into Result
			from tenostat
		where acc_id = AccID;
		return Result;
	exception
		when NO_DATA_FOUND then
			raise_application_error(
				sbdecls.Error_DataCorrupted,
				'get_account_balance: AccID: '||TO_CHAR(AccID));  
	end;
	
	function get_archive_date(AccID integer, TargetDate date)
		return date
	as
		Result date;
	begin
		select Max(datdate)
			into Result
			from archost
		where (acc_ID = AccID) and (datdate <= TargetDate);
		if Result is null then
			raise NO_DATA_FOUND;
		end if;
		return Result;
	exception
		when NO_DATA_FOUND then
			raise_application_error(
				sbdecls.Error_InvalidParameters,
				'get_archive_date: No entry found for account (id='
					||to_char(AccID)
					||'; maxdate='
					||to_char(TargetDate)
					||')');
	end;
	
	function get_archive_id(
		AccID integer, 
		TargetDate date, 
		RaiseErrors boolean default True
	)
		return integer
	as
		Result integer;
		ArchiveDate date;
	begin
		ArchiveDate := 
			get_archive_date(
				AccID, 
				TargetDate);
		select ID_NUMBER
			into Result
			from archost
		where
			(acc_ID = AccID)
			and (datdate = ArchiveDate);
		return Result;
	exception
		when OTHERS then
			if (not RaiseErrors) and (SQLCODE = sbdecls.Error_InvalidParameters) then
				return -1;
			else
				raise;
			end if; 
	end; 
	
	function get_account_balance(AccID integer, TargetDate date)
		return t_acc_balance
	as
		ArchiveID integer;
		Result t_acc_balance;
	begin
		ArchiveID := get_archive_id(AccID, TargetDate, False);
		if ArchiveID <> -1 then
			select ostat, pok_ostat, obr_d, pok_obr_d, obr_k, pok_obr_k
				into Result
				from archost
			where
				ID_NUMBER = ArchiveID;
		end if;
		return Result;
	end;
	
	function get_currency_rate(CurrencyID integer, ArchiveDate date)
		return number
	is
		Result number;
	begin
		select OSTAT
			into Result
			from OPERKURS
		where 
			(VAL_KOD = CurrencyID) 
			and (
				DAT = (
					select Max(DAT) from operkurs where DAT <= ArchiveDate
				));
		return Result;
	exception
		when NO_DATA_FOUND then
			raise_application_error(
				sbdecls.Error_NoRateForDateSpecified, 
				'Rate for specified date not found. CurrencyID='||TO_CHAR(CurrencyID)||', Date='||TO_CHAR(ArchiveDate));
	end;
	
	function lazy_make_temp_transactions(OverloadIDsStr varchar2)
		return integer
	is	
		subtype t_str_array is sbutil.t_str_array;
		TrCount integer;
		OverlappedIDs t_str_array;
		OverlappedTransaction LAZYTRANSACTION%rowtype;
		ind integer;
		TempID integer;
		ATempTrID integer;
		cursor c_overlapped_transaction(TransactionID integer)
		is
			select * from LAZYTRANSACTION
			where ID = TransactionID
		for update;
	begin
		OverlappedIDs := sbutil.comma_to_array(OverloadIDsStr, TrCount);
		TempID := gen_temp_id;
		for ind in 1..OverlappedIDs.COUNT
		loop
			open c_overlapped_transaction(OverlappedIDs(ind));
			fetch c_overlapped_transaction into OverlappedTransaction;
			close c_overlapped_transaction;
			
			ATempTrID :=
  			add_temp_transaction(TempID, OverlappedTransaction.debt, OverlappedTransaction.KREDIT,
  				OverlappedTransaction.ammount, OverlappedTransaction.ammount_c, OverlappedTransaction.lammount,
  				OverlappedTransaction.rate_d, OverlappedTransaction.Rate_C, OverlappedTransaction.name, 
					sbdecls.atfCommitImmediate, OverlappedTransaction.ID);

			update LAZYTRANSACTION
			set
				TempTrID = ATempTrID
			where
				ID = OverlappedTransaction.ID;  
			
		end loop;
		return TempID;
	end;  
	
	function lazy_commit_temp_transactions(
		ATempID integer, 
		ApplyTransactions boolean default True)
			return integer
	is
		cursor c_overlapped_transactions
		is
			select * from LAZYTRANSACTION
			where
				TempTrID in (
					select ID 
						from TEMPTRANZ 
					where 
						TempID = ATempID)
		for update;
		OverlappedTransaction c_overlapped_transactions%rowtype;
		TrID integer;
		counter integer := 0;
	begin
		for OverlappedTransaction in c_overlapped_transactions
		loop
			TrID := apply_temp_transaction(OverlappedTransaction.TempTrID);
		  delete from LAZYTRANSACTION 
			where ID=OverlappedTransaction.ID;
			counter := counter + 1;
		end loop;
		return counter; 
	end;
	
	procedure lazy_reject_transaction(TransactionID integer, Reason varchar2)
	is
	begin
		update LAZYTRANSACTION
		set
			Rejected = 1,
		  RejectReason = Reason
		where
			ID = TransactionID;
	end;
	
	function get_transaction_status(TransactionID integer)
		return integer
	is
		cursor c_transaction_status
		is
			select status
			from today_transactions
			where ID = TransactionID;
		Result integer;
	begin
		open c_transaction_status;
		fetch c_transaction_status into Result;
		close c_transaction_status;
		return Result; 
	end;
	
end;
/


