      into CustomerID
      from CustInfo;

    delete from CUSTINFO
          where Id = v_id;

    select count(*)
      into CustInfoCount
      from CustInfo
    where IDCust = CustomerID;

    return CustInfoCount;
  end;
  
  procedure upd_tenostat(
    v_acc_id integer,
    v_LastOpDate date, 
    Amount number,
    LAmount number,
    DebitTurnover number,
    DebitLTurnover number,
    CreditTurnover number,
    CreditLTurnover number)
  as
  begin
    update tenostat
    set
        OSTAT = Amount,
        POK_OSTAT = LAmount,
        DatDate = v_LastOpDate,
        OBR_D = DebitTurnover,
        POK_OBR_D = DebitLTurnover,
        OBR_K = CreditTurnover,
        POK_OBR_K = CreditLTurnover
    where
        acc_id = v_acc_id;
