  procedure consbalance (balcn number, ondate date, result out number) as
    currentdate   date;
  begin
    select tek_dat
      into currentdate
      from sysdat;

    if currentdate = ondate
    then
      select SUM (t.pok_ostat)
        into result
        from account a, tenostat t
       where a.id = t.acc_id
         and a.bal_cn1 = balcn
         and t.datdate >= ondate
         and t.datdate <=   ondate
                          + 1;
    elsif currentdate <> ondate
    then
      select SUM (t.pok_ostat)
        into result
        from account a, archost t
       where a.id = t.acc_id
         and a.bal_cn1 = balcn
         and t.datdate >= ondate
         and t.datdate <=   ondate
                          + 1;
    end if;
  end;

  procedure consturnover (
    balcn                number, -- { Number of Balance }
    fromdate             date, -- { On Required Date}
    todate               date, -- { On Required Date}
    debt_or_cred         number, -- { Turnover of Debit or Credit}
    result         out   number
  )
  as
    currentdate   date;
  begin
    select tek_dat
      into currentdate
      from sysdat;

    if  currentdate = fromdate and currentdate = todate
    then
      if debt_or_cred = 0
      then
        select SUM (t.pok_obr_d)
          into result
          from account a, tenostat t
         where a.id = t.acc_id
           and a.bal_cn1 = balcn
           and t.datdate >= fromdate
           and t.datdate <= todate;
      elsif debt_or_cred = 1
      then
        select SUM (t.pok_obr_k)
          into result
          from account a, tenostat t
         where a.id = t.acc_id
           and a.bal_cn1 = balcn
           and t.datdate >= fromdate
           and t.datdate <= todate;
      else
        commit;
      end if;
    else
      if debt_or_cred = 0
      then
        select SUM (t.pok_obr_d)
          into result
          from account a, archost t
         where a.id = t.acc_id
           and a.bal_cn1 = balcn
           and t.datdate >= fromdate
           and t.datdate <= todate;
      elsif debt_or_cred = 1
      then
        select SUM (t.pok_obr_k)
          into result
