--  Procedure SMART.GETCURRENCYRATE
Procedure getcurrencyrate (
    currencyid          integer,
    currentdate         date default null,
    rate          out   number
  )
  is
    curdate   date;
begin
 if currentdate is null then 
  select tek_dat into curdate from sysdat;
 else
  select MAX (dat) into curdate from operkurs where dat <= currentdate;
 end if;
 select o.ostat into rate from operkurs o
  where o.val_kod = currencyid and o.dat = curdate;
end;
