  procedure setaccountturnover (
    accid                 number,
    dturnover    in out   number,
    dlturnover   in out   number,
    cturnover    in out   number,
    clturnover   in out   number
  )
  is
  begin
    update tenostat
       set obr_d = dturnover,
           pok_obr_d = dlturnover,
           obr_k = cturnover,
           pok_obr_k = clturnover
     where acc_id = accid;

    commit;
  end;
