      elsif  debt_or_cred = 1 and baltype = 1 then
       select SUM (t.pok_obr_k) into result from account a, tenostat t
        where a.id = t.acc_id
         and a.val_acc = currency
         and a.acc_no = accno
         and t.datdate >= fromdate
         and t.datdate <= todate;
     end if;
    else
     if  debt_or_cred = 0 and baltype = 0 then
