  )
  as
    currentdate   date;
  begin
    select tek_dat
      into currentdate
      from sysdat;

    if  currentdate = fromdate and currentdate = todate
    then
      if debt_or_cred = 0
      then
        select SUM (t.pok_obr_d)
          into result
          from account a, tenostat t
         where a.id = t.acc_id
           and a.bal_cn1 = balcn
