  procedure consbalance (balcn number, ondate date, result out number)
  as
    currentdate   date;
  begin
    select tek_dat
      into currentdate
      from sysdat;

    if currentdate = ondate
    then
      select SUM (t.pok_ostat)
        into result
        from account a, tenostat t
       where a.id = t.acc_id
         and a.bal_cn1 = balcn
         and t.datdate >= ondate
         and t.datdate <=   ondate + 1;
    elsif currentdate <> ondate
    then
      select SUM (t.pok_ostat)
        into result
        from account a, archost t
       where a.id = t.acc_id
         and a.bal_cn1 = balcn
         and t.datdate >= ondate
         and t.datdate <=   ondate
                          + 1;
    end if;
  end;

