procedure DelCursor(str varchar2) 
is
cProvarch DynCursor;
begin
 open cProvarch for str; 
  LOOP
   FETCH cProvarch INTO rProvarch;
   EXIT WHEN cProvarch%NOTFOUND;
    SB_TRANSACTION.transaction_delete(rProvarch.id);
  END LOOP;
 CLOSE cProvarch;
end;
