RatesNotChange constant  varchar2(128)  := 'Ку?сла? дяйишмямишди';
TriggerProvarch constant  varchar2(24):= 'BI_PROVARCH_OPID';
TruggerLazy constant  varchar2(32):='BI_LAZYTRANSACTION_OP_ID';
