CREATE OR REPLACE 
PACKAGE BODY       sburep_public
IS

	CustomQueryPart_Balance constant varchar2(43) := 'select id from account where ((bal_cn1 in (';
	CustomQueryPart_Account constant varchar2(42) := 'select id from account where ((acc_no in (';

	function ExecQuery(Query varchar2)
		return number
	is
		Result number;
		type t_c_balance is ref cursor;
		c_balance t_c_balance;
	begin
--		dbms_output.put_line(Query);
		
		raise_application_error(-20001, Query);
		open c_balance for Query;
			fetch c_balance into Result;
		close c_balance;
		
		return Result;							  	
	end;
	
	function ExecStdQuery(
			CurrencyID integer, 
			TargetDate date, 
			params varchar2, 
			LFrag varchar2, 
			CustomQueryPart varchar2)
		return number
	is
		Query varchar2(1024) := 
			'select sum(ostat) as balance '||
			'from archost where (datdate = ''';
		SCurrencyID_Frag varchar2(32) := '';
	begin
		if CurrencyID <> -1 then
			SCurrencyID_Frag := ' and (val_acc = '||TO_CHAR(CurrencyID)||')';
		end if;
		Query := Query || TO_CHAR(TargetDate) || ''') and (acc_id in ('||CustomQueryPart||params||'))'||SCurrencyID_Frag||')))';
		return ExecQuery(Query);
	end;

  function balance(
			CurrencyID integer,
			TargetDate date, 
			params varchar2)
  	return number
  is
  begin
		return ExecStdQuery(CurrencyID, TargetDate, params, '', CustomQueryPart_Balance);
  end;

  function lbalance(
			CurrencyID integer, 
			TargetDate date, 
			params varchar2)
  	return number
  is
  begin
		return ExecStdQuery(CurrencyID, TargetDate, params, 'pok', CustomQueryPart_Balance);
  end;
  
  function acc_balance(
			CurrencyID integer, 
			TargetDate date, 
			params varchar2)
  	return number
  is
  begin
		return ExecStdQuery(CurrencyID, TargetDate, params, '', CustomQueryPart_Account);		
  end;
  
  function acc_lbalance(
			CurrencyID integer, 
			TargetDate date, 
			params varchar2)
  	return number
  is
  begin
		return ExecStdQuery(CurrencyID, TargetDate, params, 'pok', CustomQueryPart_Account);		
  end;
	
