CREATE OR REPLACE 
PACKAGE sburep_utl
  IS
	
	/*
	|| SmartBank Universal Report Package's Utility Package
	 */
	
  function add_cursor_query(
			name varchar2,
			description varchar2, 
			flags varchar2, 
			Query varchar2)
		return integer;
  function call_macro_function(
			name varchar2, 
			CurrencyID integer, 
			TargetDate date, 
			params sbutil.t_str_array)
		return number;
  procedure del_cursor_query(QueryID integer);
  function find_ch_pos(
			Ch1 char, 
			ch2 char, 
			text varchar2, 
			Result out char, 
			StartPosition integer)
		return integer;
  function prepare_cursor_query(QueryID integer, ParamStr varchar2)
		return varchar2;
  function prepare_cursor_query(Name varchar2, ParamStr varchar2)
		return varchar2;
  procedure upd_cursor_query(
		QueryID integer, 
		v_name varchar2,
		v_description varchar2,  
		v_flags varchar2, 
		v_Query varchar2);
END; -- Package spec
/


CREATE OR REPLACE 
PACKAGE BODY       sburep_utl
IS

  ParamsCommaChar constant varchar2(1) := ';'; 

	function find_ch_pos(
			Ch1 char, 
			ch2 char, 
			text varchar2, 
			Result out char, 
			StartPosition integer)
		return integer
	is
		p1 integer;
		p2 integer;
	begin
		p1 := instr(text, ch1, StartPosition);
		p2 := instr(text, ch2, StartPosition);
		
		if (p1 = 0) and (p2 = 0) then
			Result := '+';
		end if;
		
		if (p2 <> 0) and (p2 < p1) then
			p1 := p2;
			Result := ch2;
		else
			Result := ch1;
		end if;
		
		return p1;
	end;
	
	function call_macro_function(
			name varchar2, 
			CurrencyID integer, 
			TargetDate date, 
			params sbutil.t_str_array)
		return number
	is
		type t_cursor is ref cursor;
		c t_cursor;
		Result number;
		ParsedParams varchar2(1024);
		Query varchar2(1024);
	begin 
		ParsedParams := sbutil.array_to_comma(params);

		Query := 
			'select sburep_public.'
				||name
				||'('
				||TO_CHAR(CurrencyID)
				||', '''
				||TO_CHAR(TargetDate)
				||''', '''
				||ParsedParams
				||''') as Value from dual';
				 
		open c for Query;
			fetch c into Result;
		close c;
		
		if Result is null then
			Result := 0;
		end if;
		
		return Result;
	end;
	
	function add_cursor_query(
			name varchar2,
			description varchar2, 
			flags varchar2, 
			Query varchar2)
		return integer
	is
		Result integer;
	begin
		insert into UREP_CURSORS (
			Name, Description, Flags, Query
		)
		values (
			Name, Description, Flags, Query
		)
		returning ID into Result;
		return Result;
	end;
	
	procedure upd_cursor_query(
		QueryID integer, 
		v_name varchar2,
		v_description varchar2,  
		v_flags varchar2, 
		v_Query varchar2)
	is
	begin
		update UREP_CURSORS
		set
			Name = v_name,
			Description = v_description, 
			Flags = v_Flags,
			Query = v_Query
		where
			ID = QueryID;
	end;
	
	procedure del_cursor_query(QueryID integer)
	is
	begin
		delete from UREP_CURSORS
		where ID = QueryID;
	end;
	
	function get_cursor_query(QueryID integer)
		return varchar2
	is
		Result varchar2(2048);
	begin
		select Query
			into Result 
			from UREP_CURSORS
		where ID = QueryID;
		return Result;
	exception
		when NO_DATA_FOUND then
			raise_application_error(
				sbdecls.Error_InvalidParameters, 
				'Invalid query ID');
	end;
	
	function prepare_cursor_query(QueryID integer, ParamStr varchar2)
		return varchar2
	is
		PCount integer;
	begin
		return sbutil.expand_macroses(
		  get_cursor_query(QueryID),
			sbutil.comma_to_params(ParamStr,PCount,ParamsCommaChar)
		);		
	end;
	
	function prepare_cursor_query(Name varchar2, ParamStr varchar2)
		return varchar2
	is
		cursor c_cursor_id(CName varchar2)
		is
			select ID 
				from UREP_CURSORS
			where
				Name = CName;
		QueryID integer;
		NotFound boolean;
	begin
		open c_cursor_id(Name);
		fetch c_cursor_id into QueryID;
		NotFound := c_cursor_id%notfound;
		close c_cursor_id;
		if NotFound then
			raise_application_error(
				sbdecls.Error_InvalidParameters, 
				'Query named "'||Name||'" could not be found');
		end if;
		return prepare_cursor_query(QueryID, ParamStr);
	end;

END;
/


