CREATE OR REPLACE 
PACKAGE BODY       sd_form
IS
   FUNCTION sysdat
      RETURN DATE
   IS
      dat   DATE;
   BEGIN
      SELECT MAX (tek_dat)
        INTO dat
        FROM sysdat;

      RETURN dat;
   END;

   PROCEDURE set_dates (
      
--      fdate#       IN   varchar2,
      ldate#       IN   VARCHAR2,
      firstdate#   IN   VARCHAR2,
      lastdate#    IN   VARCHAR2
   )
   IS
      fdate#   DATE;
   BEGIN
      SELECT MAX (dat)
        INTO fdate#
        FROM operkurs
       WHERE dat < TO_DATE (firstdate#);

      UPDATE sd_dates
         SET fdate = fdate#,
             
--             ldate = To_Date(ldate#), ---Not work
             lastdate = TO_DATE (lastdate#),
             firstdate = TO_DATE (firstdate#)
       WHERE ROWNUM = 1;

      COMMIT;
   END;

   FUNCTION get_fdate
      RETURN DATE
   IS
      dat   DATE;
   BEGIN
      SELECT MAX (fdate)
        INTO dat
        FROM sd_dates;

      RETURN dat;
   END;

   FUNCTION get_ldate
      RETURN DATE
   IS
      dat   DATE;
   BEGIN
      SELECT MAX (ldate)
        INTO dat
        FROM sd_dates;

      
--        WHERE ROWNUM = 1; 

      RETURN dat;
   END;

   FUNCTION get_firstdate
      RETURN DATE
   IS
      dat   DATE;
   BEGIN
      SELECT MAX (firstdate)
        INTO dat
        FROM sd_dates;

      RETURN dat;
   END;

   FUNCTION get_lastdate
      RETURN DATE
   IS
      dat   DATE;
   BEGIN
      SELECT MAX (lastdate)
        INTO dat
        FROM sd_dates;

      RETURN dat;
   END;

   PROCEDURE get_fcource (fcource OUT NUMBER, lastcource OUT NUMBER)
   IS
   BEGIN
      SELECT ostat
        INTO fcource
        FROM operkurs
       WHERE dat = sd_form.get_fdate AND val_kod = 1;

      SELECT ostat
        INTO lastcource
        FROM operkurs
       WHERE dat = sd_form.get_lastdate AND val_kod = 1;
   END;

   FUNCTION separate_dates (param1 IN DATE, param2 DATE)
      RETURN varchar
   IS
      minres          INTEGER;
      invalidnumber   EXCEPTION;
      PRAGMA EXCEPTION_INIT (invalidnumber,  -20100);
   BEGIN
      minres :=   param1
                - param2;

                      
if minres <= 30 then RETURN '1';  
elsif 
 minres > 30 and minres <= 95 then RETURN '3'; 
elsif 
 minres > 95 and minres <= 180 then RETURN '6'; 
elsif 
 minres > 180 and minres <= 270 then RETURN '9'; 
elsif 
 minres > 270 and minres <=365 then RETURN '12'; 
elsif 
 minres > 365 then RETURN '18';
end if;                
                
                
                
                
/*      IF minres <= 0
      THEN
         raise_application_error (-20100, 'Invalid Number');
      END IF;

      IF minres <= 30 --- 1 month
      THEN
         RETURN '1 month';
      ELSIF minres between 30 and 91--(30 < minres) AND (minres <= 90) --- 1--3 month
      THEN
         RETURN '1-3 month';
      ELSIF minres between 91 and 181 -- (90 < minres) AND (minres <= 180) --- 3--6 month
      THEN
         RETURN '3-6 month';
      ELSIF minres between 181 and 271 -- (180 < minres) AND (minres <= 270) --- 6--9 month
      THEN
         RETURN '6-9 month';
      ELSIF minres between 271 and 361-- (270 < minres) AND (minres <= 360) --- 9 month --1 year 
      THEN
         RETURN '9 month- 1 year';
      ELSIF minres between 361 and 1801 -- (360 < minres) AND (minres <= 1800) --- 1 year --5 year 
      THEN
         RETURN '1-5 year';
      ELSIF (1800 < minres) --- 5-> year 
      THEN
         RETURN '5> years';
      END IF; */

      DBMS_OUTPUT.put_line (TO_CHAR (minres));
   EXCEPTION
      WHEN invalidnumber
      THEN
         BEGIN
            DBMS_OUTPUT.put_line (   'must bo positive'
                                  || TO_CHAR (minres));
            RETURN '0';
         END;
   END;
   

function get_rate(dat# in date, valute in integer) return number
is
value number;
begin
     select ostat 
        into value
        from operkurs   
        where dat = (select max(dat) from operkurs where dat <= dat#)
        and val_kod = valute;
 return value;       
end; 


   
   function rate_difference(valute in number,
                            startdat IN date, 
                            enddat IN date, 
                            startostat in Number,
                            obr_d in number,
                            obr_k in number,
                            endostat number)
             return number
   is
     start_rate Number;
     end_rate Number;
   begin
   if valute = 0 then return 0;
     else
     start_rate := get_rate(startdat, valute);
     end_rate := get_rate(enddat, valute);
     
     return (startostat*start_rate)-(obr_d*end_rate)+(obr_k*end_rate)-(endostat*end_rate);     
    end if;     
   end;          
                
   
   
END;
/


