CREATE OR REPLACE 
PACKAGE BODY       sms_banking
IS

   PROCEDURE addSMSToInbox
    ( vSender IN varchar2, 
      vBody IN varchar2,
      vSendtime IN date)
    IS
   BEGIN 
       insert into SMS_INBOX (sender, smsbody, sendtime)
       values (vSender, vBody, vSendtime);
       commit;
   EXCEPTION
      WHEN others THEN
          dbms_output.put_line(sqlerrm) ;
   END;

   PROCEDURE addSMSToOutbox
    ( vRecipient IN varchar2, 
      vBody IN varchar2)
    IS
   BEGIN 
       insert into SMS_OUTBOX (recipient, smsbody)
       values (vRecipient, vBody);
       commit;
   EXCEPTION
      WHEN others THEN
          dbms_output.put_line(sqlerrm) ;
   END;

   function ParcingOstatDate(vBody IN VARCHAR2, vostat_date OUT date)
   return  boolean DETERMINISTIC
   is
     ostat_date date;
     beg_pos number; 
   begin

     beg_pos := instr(vBody, '/');
     ostat_date := to_date(substr(vBody, beg_pos+1,Length(vBody)), 'ddmmyy');
     vostat_date := ostat_date;
     return true;
     exception when others then
        return false; 
   end;

   function ParcingObrDate(vBody IN VARCHAR2, vBal_cn OUT number, vDate OUT date)
   return  boolean 
   is
     cursor c_data(vbal_cn in varchar2) is
       select max(sbc.bal_cn) bal_cn
       from sms_dictionary sd, sms_bal_cn sbc
       where upper(sd.prefix) = upper(vbal_cn)
       and sbc.dict_id = sd.id;

     obr_date date;
     r_data c_data%rowtype;
     prefix varchar2(10);
     beg_pos number := instr(vBody, '/')+1;
     buf varchar2(1000) := subStr(vBody, beg_pos, Length(vBody));
   begin

     beg_pos := instr(buf, '/');
     prefix := substr(buf, 1, beg_pos-1);

     open c_data(prefix);
     fetch c_data into r_data;
     close c_data;
     
     if r_data.bal_cn > 0 then
       vBal_cn := r_data.bal_cn;
     else raise NO_DATA_FOUND; end if;
     
--     vBal_cn := bal_cn;
     obr_date := to_date(substr(buf, beg_pos+1, Length(buf)), 'ddmmyy');
     vDate := obr_date;
     return true;
--     exception when others then
--        return false;
   end;
   
   function ExtractUserID(vBody IN VARCHAR2)
   return  number DETERMINISTIC
   is
     beg_pos number; 
   begin      
     beg_pos := instr(vBody, '/');
     
     if beg_pos = 0 then 
         return to_number(trim(vBody)); -- if vBody = parasha (exmp: 'asas') then error
     else 
         return to_number(substr(vBody, 1, beg_pos-1));
     end if;
         
     exception when others then
         return 0;     
   end;   
   
   function CheckSender(vKli_id IN VARCHAR2, vPhoneNum IN VARCHAR2)
   return boolean
   is
   
   cursor c_sms_customers is
     select * from sms_customers
        where kli_id = vKli_id
          and phonenumber = vPhoneNum; 
        
    r_sms_customers c_sms_customers%rowtype;
    r_count number;    
    kli_id number;
   begin
   
     open c_sms_customers;
     fetch c_sms_customers into r_sms_customers;
     r_count := c_sms_customers%rowcount;
     close c_sms_customers;
     
     if r_count > 0  then 
       return true; 
     else 
       return false;
     end if; 
          
   end;

   function GetPhoneNum(vKli_id IN VARCHAR2)
   return varchar2
   is
   
   cursor c_sms_customers is
     select * from sms_customers
        where kli_id = vKli_id; 
        
    r_sms_customers c_sms_customers%rowtype;   
    kli_id number;
   begin
     open c_sms_customers;
     fetch c_sms_customers into r_sms_customers;
     close c_sms_customers;
     if r_sms_customers.kli_id > 0 then return r_sms_customers.phonenumber; 
     else return '';
     end if;      
   end;
   
   function GetKliOstat(vKli_id IN number, vDate IN date := sbop.get_date)
   return VARCHAR2
   is
     cursor c_ostat is 
        SELECT dict.NAME||' '|| TRIM(TO_CHAR (ABS(arch.ostat), '99G999G999G999G999G999D99MI')) || ' '
             || val.val_name AS ostat
          FROM archost arch, ACCOUNT acc, customers cust, avalute val, sms_dictionary dict,
           sms_bal_cn bal
         WHERE cust.ID = acc.kli_id
           AND arch.acc_id = acc.ID
           AND arch.datdate = (select max(dat) from operkurs
                               where dat <= vDate)
           AND val.valute = acc.val_acc
           AND cust.ID = vKli_id
           AND dict.ID = bal.dict_id
           AND bal.bal_cn = acc.bal_cn1
         ORDER BY dict.prefix  ;
     r_ostat c_ostat%rowtype;
     v_res_body VARCHAR2(1024);     
   begin
     open c_ostat;
     loop
     fetch c_ostat into r_ostat;
     exit when c_ostat%NOTFOUND;
     v_res_body := v_res_body||r_ostat.ostat||' ';--||CHR(13);
     end loop;
     close c_ostat;  
     return v_res_body;   
   end;
   
   function GetBalCNObr(vKli_id IN number,vBal_cn number, vDate IN date := sbop.get_date)
   return boolean
   is
   
    cursor c_obr(v_acc number) is
        SELECT sdict.name||CHR(13)||'Evl.qal.:'||TRIM(TO_CHAR (ABS(arch.ostat), '99G999G999G999G999G999D99MI')) || ''
               || val.val_name AS obr
          FROM archost arch, ACCOUNT acc,  avalute val, sms_dictionary sdict, sms_bal_cn sbal
         WHERE arch.acc_id = acc.ID
           AND arch.datdate = (select max(dat) from operkurs
                               where dat <= vDate-1)
           AND val.valute = acc.val_acc
           and acc.id = v_acc
           and sbal.bal_cn = acc.bal_cn1
           and sdict.id = sbal.dict_id
        UNION ALL
        SELECT 'Cem.med.:' || TRIM(TO_CHAR (ABS(arch.obr_k), '99G999G999G999G999G999D99MI'))||' '||
               'Cem.mex.:' || TRIM(TO_CHAR (ABS(arch.obr_d), '99G999G999G999G999G999D99MI'))||' '||
               'Qal.:'|| TRIM(TO_CHAR (ABS(arch.ostat), '99G999G999G999G999G999D99MI')) || '' || val.val_name  obr
          FROM archost arch, ACCOUNT acc,  avalute val
         WHERE arch.acc_id = acc.ID
           AND arch.datdate = (select max(dat) from operkurs
                               where dat <= vDate)
           AND val.valute = acc.val_acc
           and acc.id = v_acc;
           
     cursor c_acc is
        select id from account where bal_cn1= vBal_cn and kli_id = vKli_id;
        
        
     r_obr c_obr%rowtype;
     r_acc c_acc%rowtype;
     v_res_body VARCHAR2(32676);
     
   begin
   
     open c_acc;
     loop
      fetch c_acc into r_acc;
      exit when c_acc%notfound;

      open c_obr(r_acc.id);
      loop
         fetch c_obr into r_obr;
         exit when c_obr%NOTFOUND;
         v_res_body := v_res_body||r_obr.obr||' ';
      end loop;
      close c_obr;

      if v_res_body is not null then
       PrepareKliSMS(vKli_id, v_res_body);--Send Message's
      end if;

      v_res_body := '';
     end loop;
     close c_acc;

     return true;
     
     exception when others then dbms_output.put_line(sqlerrm);
       return false;
   end;

   
   function GetAccOstat(vAcc_id IN number)
   return VARCHAR2
   is
     cursor c_ostat is 
        SELECT dict.name||' '|| TRIM(TO_CHAR (ABS(arch.ostat), '99G999G999G999G999G999D99MI')) || ' '
             || val.val_name AS ostat
          FROM tenostat arch, ACCOUNT acc, avalute val, sms_dictionary dict,
           sms_bal_cn bal
         WHERE arch.acc_id = acc.ID
           AND val.valute = acc.val_acc
           AND dict.ID = bal.dict_id
           AND bal.bal_cn = acc.bal_cn1
           and acc.id = vAcc_id;
     r_ostat c_ostat%rowtype;
     v_res_body VARCHAR2(1024);     
   begin
     open c_ostat;
     loop
     fetch c_ostat into r_ostat;
     exit when c_ostat%NOTFOUND;
     v_res_body := v_res_body||r_ostat.ostat||CHR(13);  
     end loop;
     close c_ostat;  
     return v_res_body;
   end;
   
   FUNCTION inStrCount
     (str IN VARCHAR2, sub IN VARCHAR2)
   return integer DETERMINISTIC
   IS
     cnt integer := 0;
     pos integer := 0;
     buf varchar2(1000) := str||' ';
   BEGIN

     loop
      pos := inStr(buf, sub);
      exit when pos = 0;
      cnt := cnt+1;
      buf := substr(buf, pos+1, Length(buf) );
     end loop;
     return cnt;
   exception when others then
      dbms_output.put_line(sqlerrm);
      return 0;
   END;
   
   PROCEDURE PrepareSMS
    ( vSender in varchar2, vBody in varchar2 )
    IS
     vKli_id number;
     vDate date;
     retBody varchar2(1024);
     vBal_cn number;
     body_type integer := inStrCount(vBody, '/');
   BEGIN 

     vKli_id := ExtractUserID(vBody);
      
     --Checking user
     if  vKli_id = 0 then
        RAISE_APPLICATION_ERROR(-20001,'User not found');
     end if;   
--     if not CheckSender(vKli_id, vSender) then
--         RAISE_APPLICATION_ERROR(-20003,'User with phone num incorrect');
--     end if;


     ---------SMS formats---------
     --1)-- "5"--qaliq --current date
     --2)-- "5/ddmmyy"--qaliq by date
     --3)-- "5/prefix/ddmmyy"--oborot
     -----------------------------
     case  body_type
       when 0 then retBody := GetKliOstat(vKli_id);
       when 1 then if ParcingOstatDate(vBody, vDate) then
                      retBody := GetKliOstat(vKli_id, vDate);
                   end if;
       when 2 then if ParcingObrDate(vBody, vBal_cn, vDate) then
                      if GetBalCNObr(vKli_id, vBal_cn, vDate) then
                        return;
                      end if;
                   end if;
       else dbms_output.put_line('Not in love. ');
     end case;

    if (vSender is not null)  and (trim(retBody) is not null)  then
     
        PrepareKliSMS(vKli_id, retBody);
     else 
       RAISE_APPLICATION_ERROR(-20002, 'Sender or body is null!');   
     end if;   
     
   EXCEPTION
      when sender_or_body_is_null then
          raise;
      when user_not_found  then
          raise;  
      when user_phonenumber_incorrect then
          raise;   
      WHEN others THEN
          dbms_output.put_line('err:'||sqlerrm) ;
   END;
   

   

   PROCEDURE DeleteOutbox
    ( vID in varchar2 )
    IS
   BEGIN 
      delete from SMS_OUTBOX where id = vID;
      commit;
   EXCEPTION
      WHEN others THEN
          dbms_output.put_line(sqlerrm) ;
   END; 
   
   function CheckBelongsCustID (uid number)
   return boolean
   is 
   cursor c_custs(v_uid in number) is 
      select kli_id from sms_customers 
          where kli_id = v_uid;
   r_custs c_custs%rowtype;   
   begin
     
     open c_custs(uid);
     fetch c_custs into r_custs;
     close c_custs;
     if r_custs.kli_id = uid then
     return true;
     else 
     return false;
     end if;
     
   exception 
     when others then
         dbms_output.put_line(sqlerrm);
         return false;
   end;


   function CheckBelongsAccID (accid number)
   return boolean
   is
   cursor c_acc is
      select bal_cn1 from account
          where id = accid;
   r_acc c_acc%rowtype;
   begin

     open c_acc;
     fetch c_acc into r_acc;
     close c_acc;

     if r_acc.bal_cn1 > 0 then
       
       return CheckBelongsBalCN(r_acc.bal_cn1);
     else
       return false;
     end if;

   exception
     when others then
         dbms_output.put_line(sqlerrm);
         return false;
   end;
   
   function CheckBelongsBalCN (balcn number)
   return boolean
   is
   cursor c_balspr is
      select bal_cn from sms_bal_cn
          where bal_cn = balcn;
   r_balspr c_balspr%rowtype;
   begin

     open c_balspr;
     fetch c_balspr into r_balspr;
     close c_balspr;
     if r_balspr.bal_cn = balcn then
     return true;
     else
     return false;
     end if;

   exception
     when others then
         dbms_output.put_line(sqlerrm);
         return false;
   end;
   
   procedure PrepareKliSMS(v_kli_id number, v_body varchar2)
   is
     cursor c_numbers is 
       select phonenumber, status from sms_customers
       where kli_id = v_kli_id;
     r_numbers c_numbers%rowtype;   
   begin
   
     open c_numbers;
     loop
       fetch c_numbers into r_numbers; 
       exit when c_numbers%NOTFOUND;
       if r_numbers.status = 1 then
          addSMSToOutbox(r_numbers.phonenumber, v_body);
       end if;
     end loop;
     close c_numbers;      
   
     exception 
        when others then dbms_output.put_line(sqlerrm);
   end;
   
   
   procedure CheckAccount (DebitID in number,
                           CreditID in number,
                           DebitAmount in number,
                           CreditAmount in number,
                           acctype number default 0)--acctype 0-Debt 1 kredit
   is 
   
   cursor c_debt is
      select acc.kli_id, av.val_name from account acc, avalute av
      where id = DebitID
      and av.valute = acc.val_acc;
      
   cursor c_credit is
      select acc.kli_id, av.val_name from account acc, avalute av
      where id = CreditID
      and av.valute = acc.val_acc;
      
      
   r_debt c_debt%rowtype;
   r_credit c_credit%rowtype;
   
--   v_type varchar2(30) := 'Medaxil - ';
   begin

     open c_debt;
     fetch c_debt into r_debt;
     close c_debt;
     
     if CheckBelongsCustID(r_debt.kli_id) and CheckBelongsAccID(DebitID)  then
        prepareKliSMS(r_debt.kli_id,
                       'Mexaric - '
                       ||TRIM(TO_CHAR (ABS(DebitAmount), '99G999G999G999G999G999D99MI'))
                       ||' '||r_debt.val_name
                       ||' '
                       ||'Qaliq - '||GetAccOstat(DebitID));
     end if;
     
     open c_credit;
     fetch c_credit into r_credit;
     close c_credit;

     if CheckBelongsCustID(r_credit.kli_id) and CheckBelongsAccID(CreditID)  then
        prepareKliSMS(r_credit.kli_id,
                       'Medaxil - '
                       ||TRIM(TO_CHAR (ABS(CreditAmount), '99G999G999G999G999G999D99MI'))
                       ||' '||r_credit.val_name
                       ||' '
                       ||'Qaliq - '||GetAccOstat(CreditID));
     end if;

   exception
     when others then
         dbms_output.put_line(sqlerrm);
   end; 
      
       
END;
/


