/


CREATE OR REPLACE 
PACKAGE BODY sw_convertfile
IS
PROCEDURE convert_fileFI(DIR VARCHAR2, FILE_NAME VARCHAR2)
IS
 end_of_file boolean := false;

 FILE_HANDLE UTL_FILE.FILE_TYPE;
 STRLINE   VARCHAR2(32600);
 V_BIC       VARCHAR2(11);
 V_bname     VARCHAR2(106);
 V_branch     VARCHAR2(71);
 V_city      VARCHAR2(36);
 V_banking   VARCHAR2(53);
 V_banking_  VARCHAR2(48);
 V_address   VARCHAR2(141);
 V_codezip   VARCHAR2(106);
 V_country   VARCHAR2(71);
 V_pob       VARCHAR2(36);
 V_city2     VARCHAR2(106);
 V_country2  VARCHAR2(78);

 startpos  integer;
BEGIN
    FILE_HANDLE:=UTL_FILE.FOPEN(DIR,FILE_NAME,'R');
    WHILE NOT END_OF_FILE 
    LOOP   
        UTL_FILE.get_line(FILE_HANDLE,STRLINE);
        startpos:=4;       
        V_BIC := trim(SUBSTR(STRLINE,startpos,11));
--        dbms_output.put_line(V_BIC);            

