PROCEDURE convert_fileCT(DIR VARCHAR2, FILE_NAME VARCHAR2)
IS
 end_of_file boolean := false;

 FILE_HANDLE UTL_FILE.FILE_TYPE;
 STRLINE   VARCHAR2(1000);
 V_bname     VARCHAR2(71);
 V_SHname     VARCHAR2(71);
 startpos  integer;
BEGIN
    FILE_HANDLE:=UTL_FILE.FOPEN(DIR,FILE_NAME,'R');
    WHILE NOT END_OF_FILE 
    LOOP   
        UTL_FILE.get_line(FILE_HANDLE,STRLINE);
        startpos:=4;       
        V_SHname := trim(SUBSTR(STRLINE,startpos,2));
        dbms_output.put_line(V_SHname);
        startpos:=6;        
        V_BNAME := trim(SUBSTR(STRLINE,startpos,71));
        dbms_output.put_line(V_Bname);
        INSERT INTO SWIFTCOUNTRY
         (name,SHORTNAME)
        VALUES(V_BNAME,V_SHname);
        
    END LOOP;
  	UTL_FILE.FCLOSE (FILE_HANDLE);
    
    COMMIT;
    EXCEPTION WHEN  
     NO_DATA_FOUND 
    THEN 
     END_OF_FILE:=TRUE; 
END;

PROCEDURE convert_fileCU(DIR VARCHAR2, FILE_NAME VARCHAR2)
IS
 end_of_file boolean := false;

 FILE_HANDLE UTL_FILE.FILE_TYPE;
 STRLINE    VARCHAR2(1000);
 V_CURRENCY VARCHAR2(3);
 V_NAME     VARCHAR2(71);
 V_CODE     NUMBER(1);
 V_SHORTCOUNTRY  VARCHAR2(2);
 V_COUNTRY  VARCHAR2(200);
 startpos  integer;
BEGIN
    FILE_HANDLE:=UTL_FILE.FOPEN(DIR,FILE_NAME,'R');
    WHILE NOT END_OF_FILE 
    LOOP   
        UTL_FILE.get_line(FILE_HANDLE,STRLINE);
        
        startpos:=4;       
        V_CURRENCY := trim(SUBSTR(STRLINE,startpos,3));
        dbms_output.put_line(V_CURRENCY);
       
        startpos:=7;        
        V_NAME := trim(SUBSTR(STRLINE,startpos,70));
        dbms_output.put_line(V_NAME);

        startpos:=77;        
        V_CODE := TO_NUMBER(trim(SUBSTR(STRLINE,startpos,1)));
        dbms_output.put_line(TO_CHAR(V_CODE));

        startpos:=78;        
        V_SHORTCOUNTRY := trim(SUBSTR(STRLINE,startpos,2));
        dbms_output.put_line(V_SHORTCOUNTRY);

        startpos:=80;        
        V_COUNTRY := trim(SUBSTR(STRLINE,startpos,200));
        dbms_output.put_line(V_COUNTRY);
        dbms_output.put_line('--------------------- ');

        INSERT INTO SWIFTCURRENCY
            (CURRENCY,NAME,CODE,SHORTCOUNTRY,COUNTRY)
        VALUES
            (V_CURRENCY,V_NAME,V_CODE,V_SHORTCOUNTRY,V_COUNTRY);
        
    END LOOP;
  	UTL_FILE.FCLOSE (FILE_HANDLE);
    
    COMMIT;
    EXCEPTION WHEN  
     NO_DATA_FOUND 
    THEN 
     END_OF_FILE:=TRUE; 
END;

END;
