CREATE OR REPLACE 
PACKAGE BODY       swift_pack
IS
   --NEW REFERENCE
   function SwiftNewReference(val_cod integer) return varchar2
   is      newref integer;
           valname varchar2(3);
           result varchar2(16);
   begin
       select swift_reference.NEXTVAL into newref from dual;
       select val_name into valname from avalute where valute=val_cod; 
       result:=to_char(sbop.get_date,'yymmdd')||valname||newref;
       return result; 
   end;
   --Delete From Swlift Table 
   procedure SwiftInDelete(v_id integer)
   is RwCount integer;     
   Begin
     select count(*) into RwCount from swift_in;    
     if RwCount >0 then
        delete from swift_in where id = v_id;       
        commit;
     end if;
   end;
   --Update Swift Config
   procedure ChangeConfig(action integer,v_value Varchar2)
   is 
   ChInDir constant integer  :=1;
   ChOutDir constant integer :=2;
   ChArchiveDir constant integer :=3;
   ChAccount constant integer :=4;
   ChCommision constant integer :=5;
   begin
         if action = ChInDir then
            update SwiftConfig set SwInDir = v_value;
      elsif action = ChOutDir then        
            update SwiftConfig set SwOutDir = v_value;
      elsif action = ChArchiveDir then        
            update SwiftConfig set SwArchiveDir = v_value;
      elsif action = ChAccount then        
            update SwiftConfig set SwAccount = v_value;
      elsif action = ChCommision then        
            update SwiftConfig set CommisionId = to_number(v_value,'999999');
      end if;
      commit;      
   end;
   --Change Transaction Accounts 
   procedure ChangeAccount(v_valute integer,v_acc_id varchar2)
   is
   begin
      delete from SwiftAccounts where valute = v_valute; 
      insert into SwiftAccounts (valute,acc_id) values (v_valute,v_acc_id);
      commit;     
   end;
   --
END;
/


