CREATE OR REPLACE 
PACKAGE BODY       swiftcontrol
IS
   --NEW REFERENCE
   FUNCTION swiftnewreference (val_cod INTEGER)
      RETURN VARCHAR2
   IS
      newref    INTEGER;
      valname   VARCHAR2 (3);
      result    VARCHAR2 (16);
   BEGIN
      SELECT swift_reference.NEXTVAL
        INTO newref
        FROM DUAL;

      SELECT val_name
        INTO valname
        FROM avalute
       WHERE valute = val_cod;

      result :=    TO_CHAR (sbop.get_date, 'yymmdd')
                || valname
                || newref;
      RETURN result;
   END;

   --Delete From Swlift Table 
   PROCEDURE swiftindelete (v_id INTEGER)
   IS
      rwcount   INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO rwcount
        FROM swift_out;

      IF rwcount > 0
      THEN
         DELETE FROM swift_out
               WHERE id = v_id;

         COMMIT;
      END IF;
   END;

   --Update Swift Config
   PROCEDURE changeconfig (action INTEGER, v_value VARCHAR2)
   IS
      chindir        CONSTANT INTEGER := 1;
      choutdir       CONSTANT INTEGER := 2;
      charchivedir   CONSTANT INTEGER := 3;
      chaccount      CONSTANT INTEGER := 4;
      chcommision    CONSTANT INTEGER := 5;
   BEGIN
      IF action = chindir
      THEN
         UPDATE swiftconfig
            SET swindir = v_value;
      ELSIF action = choutdir
      THEN
         UPDATE swiftconfig
            SET swoutdir = v_value;
      ELSIF action = charchivedir
      THEN
         UPDATE swiftconfig
            SET swarchivedir = v_value;
      ELSIF action = chaccount
      THEN
         UPDATE swiftconfig
            SET swaccount = v_value;
      ELSIF action = chcommision
      THEN
         UPDATE swiftconfig
            SET commisionid = TO_NUMBER (v_value, '999999');
      END IF;

      COMMIT;
   END;

   --Change Transaction Accounts 
   PROCEDURE changeaccount (v_valute INTEGER, v_acc_id VARCHAR2)
   IS
   BEGIN
      DELETE FROM swiftaccounts
            WHERE valute = v_valute;

      INSERT INTO swiftaccounts
                  (valute, acc_id)
           VALUES (v_valute, v_acc_id);

      COMMIT;
   END;

   --GET REFERENCE
   FUNCTION getreference (vcurrency VARCHAR2)
      RETURN VARCHAR2
   IS
      nextnumber   INTEGER;
      result       VARCHAR2 (16);
   BEGIN
      SELECT swift_reference.NEXTVAL
        INTO nextnumber
        FROM DUAL;

      result :=
                  TO_CHAR (SYSDATE, 'YYMMDD')
               || UPPER (vcurrency)
               || nextnumber;
      RETURN result;
   END;

   --GENERATE FILE FOR SWIFT
   FUNCTION generatefile (v_reference VARCHAR, v_opercode VARCHAR)
      RETURN BOOLEAN
   IS
   BEGIN
      DBMS_OUTPUT.put_line (' ');
   END;

   --INSERT INTO SWIFT OUT (CREATE NEW MESSAGE)
   PROCEDURE swift_out_insert (
      v_sendertype          swift_out.sendertype%TYPE,
      v_senderbic           swift_out.senderbic%TYPE,
      v_senderlt            swift_out.senderlt%TYPE,
