      v_f32a_amount         swift_out.f32a_amount%TYPE,
      v_f33b_curr           swift_out.f33b_curr%TYPE,
      v_f33b_amount         swift_out.f33b_amount%TYPE,
      v_f36                 swift_out.f36%TYPE,
      v_f50                 swift_out.f50%TYPE,
