      v_f50_bic             swift_out.f50_bic%TYPE,
      v_f50_name_address    swift_out.f50_name_address%TYPE,
      v_f51a                swift_out.f51a%TYPE,
      v_f51a_a              swift_out.f51a_a%TYPE,
      v_f51a_b              swift_out.f51a_b%TYPE,
      v_f52                 swift_out.f52%TYPE,
