-- Start of DDL Script for Package AV.TM_MANAGE
-- Generated 24-Aug-2008 19:23:11 from AV@T

CREATE OR REPLACE 
PACKAGE tm_manage

 AUTHID CURRENT_USER
 is
   procedure changestatus(ticketid number, stat number);
   function getgrantsadv(advgrant varchar, user_name varchar2 default user)
     return number;
  procedure deleteticket(tid in number);
  procedure committicket (aid number, tdesc varchar, tinfo varchar, tnam1 varchar, tnam2 varchar);
end;
/


CREATE OR REPLACE 
PACKAGE BODY             tm_manage
is
   procedure committicket (aid number, tdesc varchar, tinfo varchar, tnam1 varchar, tnam2 varchar)
   is
      stat      number;
      batchid   number;

      cursor c_tm
      is
         select r.*, a.id accid, a.val_acc
           from sba_tm_archive r, smart.account a
          where dacc_no = a.acc_no and r.id = aid;

      tm        c_tm%rowtype;
      adesc     varchar2 (144);
      ainfo     varchar2 (108);
      Client_INN_   xs_Batchs.client_inn%type;
   begin
      select status,DACCINN
        into stat,client_INN_
        from tm_archive
       where id = aid;
       
      if stat = 5
      then
         open c_tm;

         fetch c_tm
          into tm;

         close c_tm;
         tm.description := tdesc;
         tm.information := tinfo;
         adesc :=
               substr (tm.description, 1, 35)
            || '|'
            || substr (tm.description, 36, 35)
            || '|'
            || substr (tm.description, 71, 35)
            || '|'
            || substr (tm.description, 106, 35)
            || '|';
         ainfo :=
               substr (tm.information, 1, 35)
            || '|'
            || substr (tm.information, 36, 35)
            || '|'
            || substr (tm.information, 71, 35)
            || '|';
           -- raise_application_error(-20001, adesc);
         batchid :=
            xs_control.xs_batchs_insert ('CREDIT',
                                         tm.accid,
                                         tnam1,
                                         '/',
                                         xs_control.getnewbatchrefrence (0),
                                         tm.ammount,
                                         tm.val_acc,
                                         null
                                        );
          --  raise_application_error(-20009,'d');
         xs_control.xs_beneficiary_insert
                                       (batchid,
                                        tm.kbankfilial,
                                        tm.kbanksubkacc,
                                        tm.kacc_no,
                                        tnam2,
                                        '/',
                                        tm.kaccinn,
                                        adesc, --tm.description,
                                        900,
                                        ainfo, --tm.information,
                                        tm.val_acc,
                                        xs_control.getnewbeneficiaryreference,
                                        tm.ammount,
                                        1
                                       );

         update xs_Batchs
            set client_inn = client_INN_
          where id=batchid;
      end if;

      update tm_archive
         set status = status + 1
       where status <= 5 and id = aid;

      commit;
   end;

   procedure changestatus (ticketid number, stat number)
   is
   begin
      update tm_archive
         set status = stat
       where id = ticketid;
   end;

   function getgrantsadv (advgrant varchar, user_name varchar2 default user)
      return number
   is
      obj   number;
   begin
      select advancedgrantid
        into obj
        from sba_usergrants_advanced
       where username = upper (user_name)
         and advancedgrantid = (select id
                                  from sba_advanced_grants
                                 where grantname = upper (advgrant));

      return obj;
   exception
      when no_data_found
      then
         return 0;
   end;

   procedure deleteticket (tid in number)
   is
   begin
      delete from tm_archive
            where id = tid;

      commit;
   end;
end;
/


-- End of DDL Script for Package AV.TM_MANAGE

