CREATE OR REPLACE 
PACKAGE BODY xs_control
IS
   
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
PROCEDURE SetIncomingTransaction (v_id NUMBER)
IS
  transactionid    NUMBER;
  accountval_kod   NUMBER;
  v_commisionid    NUMBER;
  v_debitid        NUMBER;
  v_creditid       NUMBER;
  v_amount         NUMBER;
  v_valute         NUMBER;
  v_trname         VARCHAR2 (255);
  Credit_ID        Number;
  accountclosed    NUMBER;
  v_Filial         Number;
  v_CorAccount     Number;
  Indikator        number;
  VREC_CLIENT_NAME      VarChar2(140);
BEGIN
  v_valute :=0; /*** LVPCSS works only with AZM ***/
  
  select 
   Rec_Client_Acc_ID,Amount,Sen_Name,REC_CLIENT_NAME, Filial
    into
   v_CreditID,     v_Amount,v_TrName,VREC_CLIENT_NAME,v_Filial
    from XS_Incoming
     where ID = v_ID; 
     
  select  CommisionID,  CorAccount
   into v_CommisionID,v_CorAccount 
   from XS_Config;
   
  select Acc_ID
    into v_DebitID
    from XS_Accounts
     where (valute = v_valute) and (BranchID = v_Filial);

      --Check for closed account 
      SELECT id
        INTO accountclosed
        FROM ACCOUNT
       WHERE (id = v_creditid) AND (close_dat IS NULL);

      --check credit account
     
  /***if account belongs to branch, then 1052--->2801***/
  if v_CorAccount <> v_DebitID then
  select AccID 
    into Credit_ID
    from XS_BranchAccount
   where (valute = v_valute) and (BranchID = v_Filial);
   IF  (v_creditid > 0) AND (accountclosed > 0)
   THEN        
  TransactionID :=
   SB_Transaction.Transaction_Add (
      DebitID         => v_CorAccount,
      CreditID        => Credit_ID,
      DebitAmount     => v_Amount,
      CreditAmount    => null,
      LAmount         => null,
      DebitRate       => null,
      CreditRate      => null,
      TrName          => v_TrName || ' - ' ||VREC_CLIENT_NAME,
      Flags           => 0,
      ParentID        => null,
      OperationType   => 15,
      TransactionDate => GetDefaultDate);
      Indikator:=1;
    end if;
  end if;/***if account belongs to branch***/
     
 
  IF  (v_creditid > 0) AND (accountclosed > 0)
   THEN        
         
         transactionid :=
               sb_transaction.transaction_add (
                  debitid=> v_debitid,
                  creditid=> v_creditid,
                  debitamount=> v_amount,
                  creditamount=> NULL,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=>    v_TrName || ' - ' ||VREC_CLIENT_NAME,
                  flags => 0,
                  parentid=> NULL,
                  
--                               inbalancechar => 0,
--                               outbalancechar => 0,
--                               transactionid => null,
--                               parentid => null,
--                               tempid => null,
                  operationtype=> 15,
                  transactiondate=> getdefaultdate
               );
         -- CHANGE ICON to accept                     
         xs_incoming_ChangeStatus (v_id, 1);
         Indikator:=2;
      ELSE
         -- CHANGE ICON to reject                                             
         xs_incoming_ChangeStatus (v_id, 2);
         Indikator:=0;
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         xs_incoming_ChangeStatus (v_id, 2);
         DBMS_OUTPUT.put_line (
            SUBSTR (   'Error '
                    || TO_CHAR (SQLCODE)
                    || ': '
                    || SQLERRM, 1, 255)
         );
     if indikator=2 then 
        COMMIT;
     else
        rollback;
     end if;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE SetBatchsTransaction (v_id NUMBER)
   IS
      CURSOR creditmessages
      IS
         SELECT *
           FROM xs_beneficiary
          WHERE BatchID = v_id;

      messages           creditmessages%ROWTYPE;
      transactionid      NUMBER;
      v_debitid          NUMBER;
      v_creditid         NUMBER;
      v_commisionid      NUMBER;
      accountval_kod     NUMBER;
      debit_id           NUMBER;
      curs               NUMBER (22, 2);
      iconresult         NUMBER;
      customersid        INTEGER;
      reject_commision   INTEGER;
      bal_cn             INTEGER;
      TransactionsDate   DATE;
      ClientAccount      INTEGER;
      TransName          VARCHAR (250);
   BEGIN
      OPEN creditmessages;

      LOOP
         FETCH creditmessages INTO messages;
         EXIT WHEN creditmessages%NOTFOUND;

         SELECT Acc_ID
           INTO v_DebitID
           FROM XS_BATCHS
          WHERE ID = v_ID;

         SELECT Acc_ID
           INTO v_CreditID
           FROM XS_ACCOUNTS
          WHERE (Valute = Messages.Val_Cod)
            AND (BranchID IN (SELECT FILIAL
                                FROM XS_BATCHS
                               WHERE ID = V_ID)
                );

         SELECT CommisionID
           INTO v_CommisionID
           FROM XS_CONFIG;

         SELECT acc_id
           INTO debit_id
           FROM XS_BATCHS
          WHERE (id = messages.BatchID);

         SELECT val_acc
           INTO accountval_kod
           FROM ACCOUNT
          WHERE (id = debit_id);

         SELECT ostat
           INTO curs
           FROM operkurs
          WHERE (val_kod = accountval_kod) AND (dat = sbop.get_date);

         --Bank daxili hesablardan commisiya 
         SELECT bal_cn1
           INTO bal_cn
           FROM ACCOUNT
          WHERE (id = debit_id) AND (close_dat IS NULL);

         IF ((bal_cn >= 3300) AND (bal_cn <= 3999))
         THEN
            CLIENTACCOUNT := 1;
            TransName :=    'К?чц?мя - '
                         || TO_CHAR (messages.amount);
         ELSE
            CLIENTACCOUNT := 0;
            TransName :=    'К?чц?мя - '
                         || messages.client_name;
         END IF;

         TransactionsDate := GetDefaultDate;
         TransName:=Replace(Messages.REMIT_INF,'|') ;
         Transactionid :=
               sb_transaction.transaction_add (
                  debitid=> v_debitid,
                  creditid=> v_creditid,
                  debitamount=> NULL,
                  creditamount=> messages.amount,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=> TransName,
                  flags => 0,
                  -- inbalancechar => 0,
                  -- outbalancechar => 0,
                  -- transactionid => null,
                  -- parentid => null,
                  -- tempid => null
                  parentid=> NULL,
                  operationtype=> 15,
                  transactiondate=> TransactionsDate
               );

         --Set Transaction ID
         UPDATE XS_BENEFICIARY
            SET transaction_id = transactionid
          WHERE (BatchID = v_id) AND (id = messages.id);

         --CHILD TRANSACTION
				 IF CLIENTACCOUNT = 1
         THEN
            sb_complex_transactions.settransactions (
               v_commisionid,
               v_debitid,
               v_creditid,
               messages.amount,
               messages.amount,
               TransactionsDate
            );
         END IF;
         
        --  2801--->1052  --
        select AccID into v_DebitID from XS_BranchAccount
         where (Valute = Messages.Val_Cod)
           and (BranchID in (select Filial
                               from XS_BATCHS
                              where ID = v_ID));
        select CorAccount into v_CreditID from XS_Config;                      
        
        if v_DebitID > 0 then   
        TransName :=    'К?чц?мя - '
                         || messages.client_name;
                            
         TransactionID :=
               SB_Transaction.Transaction_Add (
                  DebitID=> v_DebitID,
                  CreditID=> v_CreditID,
                  DebitAmount=> NULL,
                  CreditAmount=> Messages.Amount,
                  Lamount=> NULL,
                  DebitRate=> NULL,
                  CreditRate=> NULL,
                  TrName=> TransName,
                  Flags => 0,
                  -- inbalancechar => 0,
                  -- outbalancechar => 0,
                  -- transactionid => null,
                  -- parentid => null,
                  -- tempid => null
                  ParentID=> NULL,
                  OperationType=> 15,
                  TransactionDate=> TransactionsDate
               );
           end if; --if v_DebitID > 0    
      END LOOP;

      CLOSE CreditMessages;

      --APPLY TRANSID                                                  
      UPDATE XS_BATCHS
         SET send = 0
       WHERE id = v_id;
   EXCEPTION
      WHEN OTHERS
      THEN
         BEGIN
            ROLLBACK WORK;
           /* iconresult := xs_Batchs_ChangeStatus (v_id, 0);
            RAISE_APPLICATION_ERROR (
               -20998,
               SUBSTR (
                     'Error '
                  || TO_CHAR (SQLCODE)
                  || ': '
                  || SQLERRM,
                  1,
                  255
               )
            );*/
            raise;
         END;

         COMMIT WORK;
   END;

