   FUNCTION GetNewBatchRefrence (v_valute INTEGER)
      RETURN VARCHAR2
   IS
      nw       INTEGER;
      result   VARCHAR2 (36);
      cur      VARCHAR (3);
   BEGIN
      SELECT XS_BATCHS_REFERENCE_GEN.NEXTVAL
        INTO nw
        FROM DUAL;

      SELECT val_name
        INTO cur
        FROM avalute
       WHERE valute = v_valute;

      result :=    TO_CHAR (nw)
                || cur
                || TO_CHAR (SYSDATE, 'YYMMDD');
      RETURN result;
   END;

   
