--------------------------------------------------------------------------------
   FUNCTION xs_Batchs_ChangeStatus (v_id NUMBER, v_status NUMBER)
      RETURN INTEGER
   IS
      result         INTEGER;
      v_accept       INTEGER;
      messagecount   INTEGER;
   BEGIN
      --If message no commited
      IF v_status = 0
      THEN
         UPDATE XS_BATCHS
            SET status = v_status
          WHERE id = v_id;

         result := 1;
         COMMIT;
      END IF;

      IF v_status = 1
      THEN
         SELECT COUNT (*)
           INTO v_accept
           FROM XS_BENEFICIARY
          WHERE (status = 1) AND (BatchID = v_id);

         SELECT COUNT (*)
           INTO messagecount
           FROM XS_BENEFICIARY
          WHERE (BatchID = v_id);

         IF (v_accept = messagecount)
         THEN
            UPDATE XS_BATCHS
               SET status = v_status
             WHERE id = v_id;

            result := 1;
            COMMIT;
         ELSE
            result := 0;
         END IF;
      END IF;

      IF v_status = 2
      THEN
         UPDATE XS_BATCHS
            SET status = v_status
          WHERE id = v_id;

         result := 1;
         COMMIT;
      END IF;

      RETURN result;
   END;

   
