   PROCEDURE xs_transtype_code_change (
      v_id     INTEGER,
      v_name   VARCHAR2,
      v_code   INTEGER
   )
   IS
      fn   INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO fn
        FROM xs_transtype_code
       WHERE code = v_code;

      IF fn = 0
      THEN
         INSERT INTO xs_transtype_code
                     (nameid, NAME, code)
              VALUES (v_id, v_name, v_code);
      ELSE
         UPDATE xs_transtype_code
            SET nameid = v_id,
                NAME = v_name,
                code = v_code;
      END IF;

      COMMIT;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE xs_transtype_name_change (
      v_id     INTEGER,
      v_name   VARCHAR2,
      ins      INTEGER
   )
   IS
   BEGIN
      IF ins = 1
      THEN
         INSERT INTO xs_transtype_name
                     (NAME)
              VALUES (v_name);
      ELSIF ins = 0
      THEN
         BEGIN
            DELETE FROM xs_transtype_code
                  WHERE nameid = v_id;

            DELETE FROM xs_transtype_name
                  WHERE id = v_id;
         END;
      END IF;

      COMMIT;
   END;

   
