   PROCEDURE xs_config_change (oper INTEGER, v_value VARCHAR2)
   IS
   BEGIN
      IF oper = 1
      THEN
         UPDATE xs_config
            SET ACCOUNT = v_value;
      END IF;

      IF oper = 2
      THEN
         UPDATE xs_config
            SET amount_limit = TO_NUMBER (v_value);
      END IF;

      IF oper = 3
      THEN
         UPDATE xs_config
            SET in_dir = v_value;
      END IF;

      IF oper = 4
      THEN
         UPDATE xs_config
            SET out_dir = v_value;
      END IF;

      IF oper = 5
      THEN
         UPDATE xs_config
            SET archive_dir = v_value;
      END IF;

      COMMIT;
   END;

   
