   FUNCTION CheckReadingBatch (v_id INTEGER, v_status INTEGER)
      RETURN INTEGER
   IS
      result         INTEGER;
      noaccept       INTEGER;
      messagecount   INTEGER;
      globalaccept   INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO noaccept
        FROM xs_beneficiary
       WHERE (NOT (status = v_status)) AND (BatchID = v_id);

      SELECT COUNT (*)
        INTO globalaccept
        FROM xs_beneficiary
       WHERE (transaction_id NOT IN
                          (SELECT id
                             FROM provdoc
                            WHERE dat = GetDefaultDate)
             )
         AND (BatchID = v_id);

      IF  (noaccept = 0) AND (globalaccept = 0)
      THEN
         result := 1;
      ELSE
         result := 0;
      END IF;

      RETURN result;
   END;

   
