   PROCEDURE BatchToReadyBatchs (v_id INTEGER DEFAULT NULL, SendAll INTEGER)
   IS
      maxamount   NUMBER (22, 2);
   BEGIN
      SELECT Amount_limit
        INTO maxamount
        FROM XS_CONFIG;

      IF SendAll = 0
      THEN
         UPDATE XS_SendingBatchs
            SET send = 0
          WHERE id = v_id;
      ELSIF SendAll = 1
      THEN
         UPDATE XS_SendingBatchs
            SET send = 0;
      END IF;

      COMMIT;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE BatchToSendingBatchs (v_id INTEGER DEFAULT NULL, SendAll INTEGER)
   IS
   BEGIN
      IF SendAll = 0
      THEN
         UPDATE xs_readybatchs
            SET send = 1
          WHERE (id = v_id);
      ELSIF SendAll = 1
      THEN
         UPDATE xs_readybatchs
            SET send = 1;
      END IF;

      COMMIT;
   END;

   
