--------------------------------------------------------------------------------
   FUNCTION GetDefaultDate
      RETURN DATE
   IS
      v_usebankdate   INTEGER;
      result          DATE;
      v_NewDate       DATE;
   BEGIN
      SELECT usebankdate
        INTO v_usebankdate
        FROM xs_config;
        
     SELECT New_Date
        INTO v_NewDate
        FROM xs_config;
        
      IF v_usebankdate = 1
      THEN
         result := sbop.get_date;
      ELSE
         result := TRUNC (SYSDATE);
      END IF;
      IF Result < v_NewDate then Result :=v_NewDate;
      END IF;
      RETURN result;
   END;

   
