   PROCEDURE BANKM_ADDINFO
   IS
      CURSOR C_BANKM
      IS
         SELECT *
           FROM BANKM;

      R_BANKM    C_BANKM%ROWTYPE;
      TEMPSTR    VARCHAR2 (20);
      TEMPSTR1   VARCHAR2 (20);
   BEGIN
      OPEN C_BANKM;

      LOOP
         FETCH C_BANKM INTO R_BANKM;
         EXIT WHEN C_BANKM%NOTFOUND;
         TEMPSTR1 := TO_CHAR (R_BANKM.KRNO);
         TEMPSTR := CONCAT (
                          '0'
                       || SUBSTR (TEMPSTR1, 0, 5)
                       || '3',
                       SUBSTR (TEMPSTR1, 7, 7)
                    );

         
--  dbms_output.put_line(TEMPSTR);
         UPDATE BANKM
            SET SUBKRNO = TEMPSTR
          WHERE ID = R_BANKM.ID;
      END LOOP;

      CLOSE C_BANKM;
      COMMIT WORK;
   END;

   
