CREATE OR REPLACE 
PACKAGE BODY       zsd_1
IS
   FUNCTION check_unique (bk IN VARCHAR2, si IN VARCHAR2, param IN VARCHAR2)
      RETURN BOOLEAN
   IS
      summa      INTEGER;
      c_count    INTEGER;
      pc_count   INTEGER;
      dc_count   INTEGER;
      kc_count   INTEGER;
      ok         BOOLEAN;
   BEGIN
      SELECT COUNT (*)
        INTO c_count
        FROM cell c
       WHERE (    (c.book_caption = bk AND c.sheet_id = si)
              AND (   c.sell = param
                   OR c.debet = param
                   OR c.kredit = param
                   OR c.lcell = param
                  )
             );

      SELECT COUNT (*)
        INTO pc_count
        FROM provcell pc
       WHERE (    (pc.book_caption = bk AND pc.sheet_id = si)
              AND (pc.deb_val = param OR pc.kre_val = param OR pc.ekv = param
                  )
             );

      SELECT COUNT (*)
        INTO dc_count
        FROM depcell dc
       WHERE (    (dc.book_caption = bk AND dc.sheet_id = si)
              AND (   dc.brest = param
                   OR dc.brest_ekv = param
                   OR dc.brestin = param
                   OR dc.brestin_ekv = param
                   OR dc.tramt = param
                   OR dc.tramt_ekv = param
                   OR dc.payamt = param
                   OR dc.payamt_ekv = param
                   OR dc.payintamt = param
                   OR dc.payintamt_ekv = param
                   OR dc.erest = param
                   OR dc.erest_ekv = param
                   OR dc.eintrest = param
                   OR dc.eintrest_ekv = param
                  )
             );

      SELECT COUNT (*)
        INTO kc_count
        FROM krecell kc
       WHERE (    (kc.book_caption = bk AND kc.sheet_id = si)
              AND (   kc.deq = param
                   OR kc.deq_ekv = param
                   OR kc.deqin = param
                   OR kc.deqin_ekv = param
                   OR kc.deok = param
                   OR kc.deok_ekv = param
                   OR kc.deokin = param
                   OR kc.deokin_ekv = param
                   OR kc.devk = param
                   OR kc.devk_ekv = param
                   OR kc.dsk = param
                   OR kc.dsk_ekv = param
                   OR kc.dskin = param
                   OR kc.dskin_ekv = param
                   OR kc.vkk = param
                   OR kc.vkk_ekv = param
                  )
             );

      summa := c_count + pc_count + dc_count + kc_count;

      IF summa = 0
      THEN
         ok := TRUE;
      ELSE
         ok := FALSE;
      END IF;

      RETURN ok;
   END;

   FUNCTION check_for_trial
      RETURN DATE
   IS
      RESULT   DATE;
   BEGIN
      SELECT tek_dat
        INTO RESULT
        FROM sysdat;

      RETURN RESULT;
   END;
   ------------------------------------------
   FUNCTION get_ostat (p_id IN INTEGER, p_dat IN DATE)
      RETURN NUMBER
   IS
      result   NUMBER;
   BEGIN
      SELECT ostat
        INTO result
        FROM operkurs
       WHERE dat = (select max(dat) from operkurs where dat <= p_dat)
         AND val_kod = (SELECT currency
                          FROM cm_portfolio
                         WHERE id = p_id);

      RETURN result;
   END;
