   FUNCTION calc_by_balcn (begdat IN DATE, enddat IN DATE, balcn IN varchar)
      RETURN varchar
   IS
      RESULT   varchar(200);
   BEGIN
      SELECT SUM (pok_ostat) AS sums
        INTO RESULT
        FROM archost ar, ACCOUNT acc
       WHERE datdate BETWEEN begdat AND enddat
         AND ar.acc_id = acc.ID
         AND bal_cn1 IN (balcn);

      RETURN RESULT;
      COMMIT;
   END;
   ------------------------------------
   function calc_by_acc_(begdat in date,enddat in date,
accno in varchar)
return varchar
is
vaccno varchar(20);
vdate varchar(200);
Result varchar(4000);
begin
if vaccno is not null then
vaccno :=' acc.acc_no=' || '''' || TO_CHAR (accno) || '''' || '';
end if;

      vdate :=
            ' and acc.datdate between '''
         || begdat
         || ''' and '''
         || enddat
         || ''' ';
      RESULT :=
            ' select ar.* from archost ar where ar.acc_id in (select acc.id from account acc where '||vaccno||vdate;
      RETURN RESULT;
   END;

------------------------------------
   FUNCTION cal_by_acc_balcn (
      begdat   IN   DATE,
      enddat   IN   DATE,
      accid    IN   varchar,
      balcn    IN   varchar
   )
      RETURN NUMBER
   IS
      sums   NUMBER;
   BEGIN
      sums :=
           calc_by_acc (begdat, enddat, accid)
         + calc_by_balcn (begdat, enddat, balcn);
      RETURN sums;
      COMMIT;
   END;

   FUNCTION calc_by_acc (begdat IN DATE, enddat IN DATE, accid IN varchar)
      RETURN varchar
   IS
      RESULT   varchar(20);
    BEGIN
   SELECT SUM (pok_ostat) AS sums
        INTO RESULT
        FROM archost ar, ACCOUNT acc
       WHERE datdate BETWEEN begdat AND enddat and ar.acc_id=acc.id and
          acc_id in (select id from account where  acc_no IN (accid));
      RETURN RESULT;
      COMMIT;
   END;

