   FUNCTION check_adm_user
      RETURN BOOLEAN
   IS
      RESULT   BOOLEAN;
      ct       INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO ct
        FROM dba_role_privs
       WHERE grantee = USER AND granted_role = 'DBA';

      IF ct > 0
      THEN
         RESULT := TRUE;
      ELSE
         RESULT := FALSE;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION full_account (accno IN VARCHAR2)
      RETURN VARCHAR2
   IS
      c_ount    INTEGER;
      end_pos   INTEGER          := 1;
      beg_pos   INTEGER          := 1;
      t_dest    VARCHAR2 (32000);
      x         VARCHAR2 (32000);
      y         VARCHAR2 (32000);
   BEGIN
      IF LENGTH (accno) > 0
      THEN
         LOOP
            end_pos := INSTR (accno, ',', beg_pos);

            IF end_pos = 0
            THEN
               x := SUBSTR (accno, beg_pos, LENGTH (accno) - beg_pos + 1);

               IF LENGTH (x) > 0
               THEN
                  SELECT COUNT (*)
                    INTO c_ount
                    FROM ACCOUNT
                   WHERE acc_no = x;

                  IF c_ount = 0
                  THEN
                     t_dest := t_dest || x || '*,';
                  ELSE
                     t_dest := t_dest || x || ',';
                  END IF;
               END IF;
            ELSE
               y := SUBSTR (accno, beg_pos, end_pos - beg_pos);

               IF LENGTH (y) > 0
               THEN
                  SELECT COUNT (*)
                    INTO c_ount
                    FROM ACCOUNT
                   WHERE acc_no = y;

                  IF c_ount = 0
                  THEN
                     t_dest := t_dest || y || '*,';
                  ELSE
                     t_dest := t_dest || y || ',';
                  END IF;
               END IF;
            END IF;

            beg_pos := end_pos + 1;
            EXIT WHEN end_pos = 0;
         END LOOP;
      END IF;

      RETURN SUBSTR (t_dest, 1, LENGTH (t_dest) - 1);
   END;

