      t_dest    VARCHAR2 (32000);
      x         VARCHAR2 (32000);
      y         VARCHAR2 (32000);
   BEGIN
      IF LENGTH (balno) > 0
      THEN
         LOOP
            end_pos := INSTR (balno, ',', beg_pos);

            IF end_pos = 0
            THEN
               x := SUBSTR (balno, beg_pos, LENGTH (balno) - beg_pos + 1);

               IF LENGTH (x) > 0
               THEN
                  SELECT COUNT (*)
                    INTO c_ount
                    FROM ACCOUNT
                   WHERE bal_cn1 = x;

                  IF c_ount = 0
                  THEN
                     t_dest := t_dest || x || '*,';
                  ELSE
                     t_dest := t_dest || x || ',';
                  END IF;
               END IF;
            ELSE
               y := SUBSTR (balno, beg_pos, end_pos - beg_pos);

               IF LENGTH (y) > 0
               THEN
                  SELECT COUNT (*)
                    INTO c_ount
                    FROM ACCOUNT
                   WHERE bal_cn1 = y;

                  IF c_ount = 0
