   FUNCTION get_per (s_id IN INTEGER, s_bdat IN DATE)                 --period
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (50);
      p        INTEGER;
      cm       NUMBER;

      CURSOR c_p
      IS
         SELECT bperiod, eperiod, NAME
           FROM sbcm_periods;
   BEGIN
      SELECT (closedate - s_bdat)
        INTO cm
        FROM sbcm_contracts
       WHERE ID = s_id;

      FOR pr IN c_p
      LOOP
         IF (cm >= pr.bperiod) AND (cm <= pr.eperiod)
         THEN
            RESULT := pr.NAME;
            EXIT;
         END IF;
      END LOOP;

      RETURN RESULT;
   END;

   FUNCTION get_opdate (s_id IN INTEGER)                      --achilma tarixi
      RETURN DATE
