        INTO RESULT
        FROM sbcm_contracts
       WHERE ID = s_id;

      RETURN RESULT;
   END;

   FUNCTION get_cldate (s_id IN INTEGER)                    --baghlanma tarixi
      RETURN DATE
   IS
      RESULT   DATE;
   BEGIN
