        INTO RESULT
        FROM sbcm_contracts
       WHERE ID = s_id;

      RETURN RESULT;
   END;

   FUNCTION get_bd_ost (s_id IN INTEGER, s_bdat IN DATE)
      --dovrun evveline  qaliq
   RETURN NUMBER
   IS
      RESULT   NUMBER;
      curdat   DATE;
   BEGIN
      SELECT tek_dat
        INTO curdat
        FROM sysdat;

      IF s_bdat = curdat          --begin tarix system tarixina berabar olarsa
      THEN
         BEGIN
            SELECT facticaldebt
              INTO RESULT
              FROM sbcm_contract_state
             WHERE id# = s_id;
         END;
      END IF;

      IF s_bdat <> curdat    --begin  tarixi system tarixina berabar olarmazsa
      THEN
         BEGIN
            SELECT facticaldebt
              INTO RESULT
              FROM sbcm_contract_state_history
             WHERE id# = s_id AND hdate = (SELECT MAX (hdate)
                                             FROM sbcm_contract_state_history
                                            WHERE hdate <= s_bdat);
         END;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION get_bd_ost_all (
      s_bdat      IN   DATE,
      s_balno     IN   VARCHAR2,
      s_accno     IN   VARCHAR2,
      s_valyuta   IN   VARCHAR2,
      s_rez       IN   NUMBER,
      s_fil       IN   VARCHAR2
   )
      RETURN NUMBER
   IS
      RESULT   NUMBER;
      curdat   DATE;
      b_pos    INTEGER       := 1;
      e_pos    INTEGER       := 1;
      x        VARCHAR2 (50);
      summa    NUMBER;
   BEGIN
      SELECT tek_dat                              -- system tarixini gotururuk
        INTO curdat
        FROM sysdat;

      LOOP
         e_pos := INSTR (s_balno, ',', b_pos);

         IF e_pos = 0
         THEN
            x := SUBSTR (s_balno, b_pos, LENGTH (s_balno) - b_pos + 1);
         ELSE
            x := SUBSTR (s_balno, b_pos, e_pos - b_pos);
         END IF;

         IF s_bdat = curdat       --begin tarix system tarixina berabar olarsa
         THEN
            BEGIN
               SELECT SUM (facticaldebt)
                 INTO RESULT
                 FROM sbcm_contract_state cts, sbcm_contract_accounts sbac
                WHERE cts.id# = sbac.id#
                  AND sbac.contractaccid IN (
                         SELECT ID
                           FROM ACCOUNT
                          WHERE bal_cn1 IN x
                            AND acc_no IN NVL (s_accno, NULL)
                            AND val_acc IN (
                                    SELECT valute
                                      FROM avalute
                                     WHERE val_name =
                                                     NVL (s_valyuta, val_name))
                            AND kli_id IN (
                                    SELECT ID
                                      FROM customers
                                     WHERE nerezident =
                                                       NVL (s_rez, nerezident))
                            AND filial IN (SELECT ID
                                             FROM filial_t
                                            WHERE NAME = NVL (s_fil, NAME)));
            END;
         END IF;

         IF s_bdat <> curdat --begin  tarixi system tarixina berabar olarmazsa
         THEN
            BEGIN
               SELECT SUM (facticaldebt)
                 INTO RESULT
                 FROM sbcm_contract_state_history ctsh,
                      sbcm_contract_accounts sbac
                WHERE hdate = (SELECT MAX (hdate)
                                 FROM sbcm_contract_state_history
                                WHERE hdate <= s_bdat)
                  AND sbac.contractaccid IN (
                         SELECT ID
                           FROM ACCOUNT
                          WHERE bal_cn1 IN NVL (s_balno, bal_cn1)
                            AND acc_no IN NVL (s_accno, acc_no)
                            AND val_acc IN (
                                    SELECT valute
                                      FROM avalute
                                     WHERE val_name =
                                                     NVL (s_valyuta, val_name))
                            AND kli_id IN (
                                    SELECT ID
                                      FROM customers
                                     WHERE nerezident =
                                                       NVL (s_rez, nerezident))
                            AND filial IN (SELECT ID
                                             FROM filial_t
                                            WHERE NAME = NVL (s_fil, NAME)));
            END;
         END IF;

         summa := summa + RESULT;
         b_pos := e_pos + 1;
         EXIT WHEN e_pos = 0;
      END LOOP;

      RETURN summa;
   END;

   FUNCTION get_bd_in_ost (s_id IN INTEGER, s_bdat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
      curdat   DATE;
   BEGIN
      SELECT tek_dat
        INTO curdat
        FROM sysdat;

      IF s_bdat = curdat
      THEN
         BEGIN
            SELECT facticalinterestdebt
              INTO RESULT
              FROM sbcm_contract_state
             WHERE id# = s_id;
         END;
      END IF;

      IF s_bdat <> curdat
      THEN
         BEGIN
            SELECT facticalinterestdebt
              INTO RESULT
              FROM sbcm_contract_state_history
             WHERE id# = s_id AND hdate = (SELECT MAX (hdate)
                                             FROM sbcm_contract_state_history
                                            WHERE hdate <= s_bdat);
         END;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION get_bd_ost_ekv (s_id IN INTEGER, s_bdat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
      curdat   DATE;
   BEGIN
      SELECT tek_dat
        INTO curdat
        FROM sysdat;

      IF s_bdat = curdat
      THEN
         BEGIN
            SELECT facticaldebt * get_currency_ostat (s_id, s_bdat)
              INTO RESULT
              FROM sbcm_contract_state;
         END;
      END IF;

      IF s_bdat <> curdat
      THEN
         BEGIN
            SELECT facticaldebt * get_currency_ostat (s_id, s_bdat)
              INTO RESULT
              FROM sbcm_contract_state_history
             WHERE hdate = (SELECT MAX (hdate)
                              FROM sbcm_contract_state_history
                             WHERE hdate <= s_bdat);
         END;
      END IF;

      RETURN RESULT;
   END;

