                                              FROM sbcm_contract_state_history
                                             WHERE hdate <= s_bdat);
         END;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION get_bd_in_ost_ekv (s_id IN INTEGER, s_bdat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
      curdat   DATE;
   BEGIN
      SELECT tek_dat
        INTO curdat
        FROM sysdat;

      IF s_bdat = curdat
      THEN
         BEGIN
            SELECT facticalinterestdebt * get_currency_ostat (cts.id#, s_bdat)
