         BEGIN
            SELECT facticalinterestdebt * get_currency_ostat (cn.ID, s_bdat)
              INTO RESULT
              FROM sbcm_contract_state_history, sbcm_contracts cn
             WHERE id# = s_id AND hdate = (SELECT MAX (hdate)
                                             FROM sbcm_contract_state_history
                                            WHERE hdate <= s_bdat);
         END;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION get_ed_ost (s_id IN INTEGER, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
      curdat   DATE;
   BEGIN
      SELECT tek_dat
        INTO curdat
        FROM sysdat;

      IF s_edat = curdat
      THEN
         BEGIN
            SELECT facticaldebt
              INTO RESULT
              FROM sbcm_contract_state
             WHERE id# = s_id;
         END;
      END IF;

      IF s_edat <> curdat
      THEN
         BEGIN
            SELECT facticaldebt
              INTO RESULT
              FROM sbcm_contract_state_history
             WHERE id# = s_id AND hdate = (SELECT MAX (hdate)
                                             FROM sbcm_contract_state_history
                                            WHERE hdate <= s_edat);
         END;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION get_ed_in_ost (s_id IN INTEGER, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
      curdat   DATE;
   BEGIN
      IF s_edat = curdat
      THEN
         BEGIN
            SELECT facticalinterestdebt
              INTO RESULT
              FROM sbcm_contract_state
             WHERE id# = s_id;
         END;
      END IF;

      IF s_edat <> curdat
      THEN
         BEGIN
            SELECT facticalinterestdebt
              INTO RESULT
              FROM sbcm_contract_state_history
             WHERE id# = s_id AND hdate = (SELECT MAX (hdate)
                                             FROM sbcm_contract_state_history
                                            WHERE hdate <= s_edat);
         END;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION get_ed_in_ost_ekv (s_id IN INTEGER, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
      curdat   DATE;
   BEGIN
      SELECT tek_dat
        INTO curdat
        FROM sysdat;

      IF s_edat = curdat
      THEN
         BEGIN
            SELECT facticalinterestdebt * get_currency_ostat (cts.id#, s_edat)
              INTO RESULT
              FROM sbcm_contract_state cts
             WHERE id# = s_id;
         END;
      END IF;

      IF s_edat <> curdat
      THEN
         BEGIN
            SELECT   facticalinterestdebt
                   * get_currency_ostat (sbcm_contract_state_history.id#,
                                         sbcm_contract_state_history.hdate
                                        )
              INTO RESULT
              FROM sbcm_contract_state_history
             WHERE id# = s_id AND hdate = (SELECT MAX (hdate)
                                             FROM sbcm_contract_state_history
                                            WHERE hdate <= s_edat);
         END;
      END IF;

      RETURN RESULT;
   END;

