   FUNCTION get_tram (s_id IN INTEGER, s_bdat IN DATE, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT SUM (total)
        INTO RESULT
        FROM sbcm_tranches
       WHERE id# = s_id AND hdate BETWEEN s_bdat AND s_edat;

      RETURN RESULT;
   END;

   FUNCTION get_tram_all (s_bdat IN DATE, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT SUM (total)
        INTO RESULT
        FROM sbcm_tranches tr, sbcm_contracts cn
       WHERE tr.id# = cn.ID AND tr.hdate BETWEEN s_bdat AND s_edat;

      RETURN RESULT;
   END;

   FUNCTION get_tram_ekv (s_id IN INTEGER, s_bdat IN DATE, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT SUM (total * get_currency_ostat (cm.id#, sbcm_tranches.hdate))
        INTO RESULT
        FROM sbcm_tranches, sbcm_contract_state_history cm
       WHERE cm.id# = s_id AND cm.hdate BETWEEN s_bdat AND s_edat;

      RETURN RESULT;
   END;

   FUNCTION get_pay (s_id IN INTEGER, s_bdat IN DATE, s_edat IN DATE)
      --odenilmish mebleq
   RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT SUM (facticaldebt)
        INTO RESULT
        FROM sbcm_payments
       WHERE id# = s_id AND hdate BETWEEN s_bdat AND s_edat;

      RETURN RESULT;
   END;

   FUNCTION get_pay_ekv (s_id IN INTEGER, s_bdat IN DATE, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT SUM (cm.facticaldebt * get_currency_ostat (cm.id#, cm.hdate))
        INTO RESULT
        FROM sbcm_payments, sbcm_contract_state_history cm
       WHERE cm.id# = s_id AND cm.hdate BETWEEN s_bdat AND s_edat;

      RETURN RESULT;
   END;

   FUNCTION get_payin (s_id IN INTEGER, s_bdat IN DATE, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT SUM (interestdebt)
        INTO RESULT
        FROM sbcm_payments
       WHERE id# = s_id AND hdate BETWEEN s_bdat AND s_edat;

      RETURN RESULT;
   END;

   FUNCTION get_payin_ekv (s_id IN INTEGER, s_bdat IN DATE, s_edat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT SUM (interestdebt
                  * get_currency_ostat (s_id, sbcm_payments.hdate)
                 )
        INTO RESULT
        FROM sbcm_payments
       WHERE id# = s_id AND hdate BETWEEN s_bdat AND s_edat;

      RETURN RESULT;
   END;

   FUNCTION get_fil (s_id IN INTEGER)
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (30);
   BEGIN
      SELECT NAME
        INTO RESULT
        FROM filial
       WHERE ID = (SELECT p.branchid
                     FROM cm_portfolio p
                    WHERE p.ID = s_id);

      RETURN RESULT;
   END;

   FUNCTION get_katname (s_id IN INTEGER)                     --kategoriya adi
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (50);
   BEGIN
      SELECT CATEGORY
        INTO RESULT
        FROM sbcm_categories
       WHERE ID = (SELECT clienttype
                     FROM sbcm_contracts
                    WHERE ID = s_id);

      RETURN RESULT;
   END;

   FUNCTION get_currency_ostat (s_id IN INTEGER, p_dat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT ostat
        INTO RESULT
        FROM operkurs
       WHERE val_kod = (SELECT val_acc
                          FROM ACCOUNT
                         WHERE ID = (SELECT contractaccid
                                       FROM sbcm_contract_accounts a
                                      WHERE a.id# = s_id))
         AND dat = (SELECT MAX (dat)
                      FROM operkurs
                     WHERE dat <= p_dat);

      RETURN RESULT;
   END;

   FUNCTION get_currency_ostat_kre (s_id IN INTEGER, p_dat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT ostat
        INTO RESULT
        FROM operkurs
       WHERE val_kod = (SELECT currency
                          FROM cm_portfolio b
                         WHERE b.ID = s_id) AND dat = (SELECT MAX (dat)
                                                         FROM operkurs
                                                        WHERE dat <= p_dat);

      RETURN RESULT;
   END;

   FUNCTION get_currency_ostat_all (p_dat IN DATE)
      RETURN NUMBER
   IS
      RESULT   NUMBER;
   BEGIN
      SELECT ostat
        INTO RESULT
        FROM operkurs
       WHERE val_kod =
                (SELECT val_acc
                   FROM ACCOUNT
                  WHERE ID =
                            (SELECT contractaccid
                               FROM sbcm_contract_accounts a,
                                    sbcm_contracts b
                              WHERE a.id# = b.ID))
         AND dat = (SELECT MAX (dat)
                      FROM operkurs
                     WHERE dat <= '08-sep-2006');

      RETURN RESULT;
   END;

   FUNCTION get_tekdat (s_bdate IN DATE)
      RETURN BOOLEAN
   IS
      dat      DATE;
      RESULT   BOOLEAN;
   BEGIN
      SELECT tek_dat
        INTO dat
        FROM sysdat;

      IF dat = s_bdate
      THEN
         RESULT := TRUE;
      ELSE
         RESULT := FALSE;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION get_user_name
      RETURN VARCHAR2
   IS
      RESULT   VARCHAR2 (50);
   BEGIN
      SELECT grantee
        INTO RESULT
        FROM dba_role_privs
       WHERE grantee = USER AND granted_role <> 'DBA';

      RETURN RESULT;
   END;
END;
